export class Action_Animation extends VE_ActionBehaviour {

    public get ID(): string {
        return "Animation|动画控制";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '动画控制，组001_2，true，0，100，true，true';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=882';
    }
    public get className(): string {
        return "Action_Animation";
    }

    public get type(): ActionType {
        return ActionType.Animation;
    }
    private _blueGameobject: VeryGameObject = new VeryGameObject();
    private autoAnimate: VeryBool = new VeryBool();
    private autoAnimateFrom: VeryNumber = new VeryNumber();
    private autoAnimateTo: VeryNumber = new VeryNumber();
    private autoAnimateLoop: VeryBool = new VeryBool();
    //参数6：设置子物体
    private _setChildren: VeryBool = new VeryBool();

    public active(): void {
        if (this._blueGameobject.value !== null) {
            var tmpTransformNode = (this._blueGameobject.value.transform.mesh !== null) ? this._blueGameobject.value.transform.mesh : this._blueGameobject.value.transform.transformNode;
            this.Recursion_Add(tmpTransformNode, this.autoAnimate.value, this.autoAnimateFrom.value, this.autoAnimateTo.value, this.autoAnimateLoop.value, 1.0, this._setChildren.value);
        }
    }

    private Recursion_Add(obj: BABYLON.TransformNode, autoAnimate: boolean, autoAnimateFrom: number, autoAnimateTo: number, autoAnimateLoop: boolean, speed: number, setChild: boolean = false) {
        if (this.autoAnimate.value) {
            this.scene.beginAnimation(obj, this.autoAnimateFrom.value, this.autoAnimateTo.value, this.autoAnimateLoop.value, 1.0);
        }
        else {
            this.scene.beginAnimation(obj, 0, 0, this.autoAnimateLoop.value, 1.0);
            this.scene.stopAnimation(obj);
        }
        if (setChild) {
            if (obj.getChildTransformNodes().length > 0) {
                for (var i = 0; i < obj.getChildTransformNodes().length; i++) {
                    this.Recursion_Add(obj.getChildTransformNodes()[i], autoAnimate, autoAnimateFrom, autoAnimateTo, autoAnimateLoop, speed, setChild);
                }
            }
        }
    }

    public onUpdate(): void {
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 5, 6)) {
            return false;
        } else {

            // 第1个参数：
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0], this.nodeID)) {
                return false;
            }
            this._blueGameobject = para0.gameObject;
            // var tmpMesh = this._blueGameobject.value?.mesh;
            // if (tmpMesh == null || tmpMesh == undefined) {
            //     VE_ErrorManager.Add(new VE_Error('', this.ID + " 响应 传入参数格式可能有误，传入参数：" + para_array[0] + "，该物体不具有Mesh，请检查！", '', Severity.Error));
            //     return false;
            // }

            // 参数2：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[1])) {
                return false;
            }
            this.autoAnimate = para1.bool;

            // 参数3：
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[2])) {
                return false;
            }
            this.autoAnimateFrom = para2.number;

            // 参数4：
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[3])) {
                return false;
            }
            this.autoAnimateTo = para3.number;

            // 参数5：
            let para4: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para4, para_array[4])) {
                return false;
            }
            this.autoAnimateLoop = para4.bool;

            // 参数6：是否设置子物体
            this._setChildren.value = true;
            if (para_array.length > 5) {
                let para5: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para5, para_array[5])) {
                    return false;
                }
                this._setChildren = para5.bool;
            }


            return true;
        }
    }
    public destroy(): void {

    }
}
