export class Action_SkeletonAnimation_RangeName extends VE_ActionBehaviour {

    public get ID(): string {
        return "Skeleton_Animation_Name|骨骼动画名控制";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '骨骼动画名控制，mixamorig:Skin，YBot_Run，true';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=884';
    }
    public get className(): string {
        return "Action_SkeletonAnimation_RangeName";
    }

    public get type(): ActionType {
        return ActionType.Animation;
    }
    private _blueGameobject: VeryGameObject = new VeryGameObject();
    private rangeName: VeryString = new VeryString();
    private autoAnimateLoop: VeryBool = new VeryBool();
    //参数6：设置子物体
    private _setChildren: VeryBool = new VeryBool();

    public active(): void {
        if (this._blueGameobject.value !== null) {
            var tmpTransformNode = (this._blueGameobject.value.transform.mesh !== null) ? this._blueGameobject.value.transform.mesh : this._blueGameobject.value.transform.transformNode;
            this.Recursion_Add(tmpTransformNode, this.rangeName.value, this.autoAnimateLoop.value, 1.0, this._setChildren.value);
        }
    }
    private Recursion_Add(obj: BABYLON.TransformNode, rangeName: string, autoAnimateLoop: boolean, speed: number, setChild: boolean = false) {
        if (obj instanceof BABYLON.AbstractMesh) {
            var tmpSkeleton = obj.skeleton;
            if (tmpSkeleton) {
                //DO_20220420:骨骼动画,glb文件导出babylon文件解析
                //多动画之间过渡
                var tmpRanges = tmpSkeleton.getAnimationRanges();
                if (tmpRanges.length > 1) {
                    let tmpThis = this;
                    let onBeforeAnimation = function () {
                        // Increment the weight of the current override animation
                        if (currentAni) {
                            currentAni.weight = BABYLON.Scalar.Clamp(currentAni.weight + 0.01, 0, 1);
                        }
                        for (var i = 0; i < GameGlobal.meshAnimatables[meshID].length; i++) {
                            var tmpAni = GameGlobal.meshAnimatables[meshID][i];
                            if (currentAni !== tmpAni) {
                                tmpAni.weight = BABYLON.Scalar.Clamp(tmpAni.weight - 0.01, 0, 1);
                            }
                        }
                        for (var i = 0; i < GameGlobal.meshAnimatables[meshID].length; i++) {
                            var tmpAni = GameGlobal.meshAnimatables[meshID][i];
                            //DO_20230313:五代修改
                            //骨骼动画：多动画之间过渡                            
                            tmpAni.loopAnimation = autoAnimateLoop;
                        }
                        // Remove the callback the current animation weight reaches 1 or
                        // when all override animations reach 0 when current is undefined
                        var allWeightZero = true;
                        for (var i = 0; i < GameGlobal.meshAnimatables[meshID].length; i++) {
                            var tmpAni = GameGlobal.meshAnimatables[meshID][i];
                            if (tmpAni.weight !== 0) {
                                allWeightZero = false;
                                break;
                            }
                        }
                        if ((currentAni && currentAni.weight === 1) || allWeightZero) {
                            tmpThis.scene.onBeforeAnimationsObservable.removeCallback(onBeforeAnimation);
                        }
                    };

                    let meshID = obj.id;
                    let previousIndex = -1;
                    let currentIndex = -1;
                    for (var i = 0; i < tmpRanges.length; i++) {
                        var tmpAnimationRange = tmpRanges[i];
                        if (tmpAnimationRange && tmpAnimationRange.name === rangeName) {
                            currentIndex = i;
                            break;
                        }
                    }
                    if (GameGlobal.meshAnimatables[meshID]) {
                        for (var i = 0; i < GameGlobal.meshAnimatables[meshID].length; i++) {
                            var tmpAni = GameGlobal.meshAnimatables[meshID][i];
                            if (tmpAni.weight === 1) {
                                previousIndex = i;
                                break;
                            }
                        }
                    }
                    console.warn(meshID + '--' + obj.name + '--skeletonRangeIndex--' + previousIndex + '--' + currentIndex);
                    if (previousIndex === currentIndex) {
                        return;
                    }
                    let previousAni = (previousIndex >= 0) ? GameGlobal.meshAnimatables[meshID][previousIndex] : undefined;
                    let currentAni = (currentIndex >= 0) ? GameGlobal.meshAnimatables[meshID][currentIndex] : undefined;

                    if (currentAni === undefined) {
                        // Restart animation observer
                        this.scene.onBeforeAnimationsObservable.removeCallback(onBeforeAnimation);
                        this.scene.onBeforeAnimationsObservable.add(onBeforeAnimation);
                    }
                    else {
                        // Do nothing if run is already the current animation
                        if (previousAni === currentAni) {
                            return;
                        }
                        // Synchronize animations
                        if (previousAni) {
                            currentAni.syncWith(null);
                            previousAni.syncWith(currentAni);
                        }
                        // Restart animation observer with run set to current
                        this.scene.onBeforeAnimationsObservable.removeCallback(onBeforeAnimation);
                        //previousAni = currentAni;
                        this.scene.onBeforeAnimationsObservable.add(onBeforeAnimation);
                    }
                }
                else {
                    if (rangeName.toLocaleLowerCase() !== 'null' && rangeName.toLocaleLowerCase() !== 'none') {
                        var autoAnimateFrom = 0, autoAnimateTo = 0;
                        var selectedRange = false;
                        for (var i = 0; i < tmpRanges.length; i++) {
                            var tmpAnimationRange = tmpRanges[i];
                            if (tmpAnimationRange && tmpAnimationRange.name === rangeName) {
                                autoAnimateFrom = tmpAnimationRange.from;
                                autoAnimateTo = tmpAnimationRange.to;
                                selectedRange = true;
                                break;
                            }
                        }
                        if (selectedRange) {
                            this.scene.beginAnimation(tmpSkeleton, autoAnimateFrom, autoAnimateTo, autoAnimateLoop, 1.0);
                        }
                        else {
                            console.error('骨骼动画动画名填写错误--' + rangeName);
                        }
                    }
                    else {
                        this.scene.beginAnimation(tmpSkeleton, 0, 0, autoAnimateLoop, 1.0);
                    }
                }
            }
        }
        if (setChild) {
            if (obj.getChildTransformNodes().length > 0) {
                for (var i = 0; i < obj.getChildTransformNodes().length; i++) {
                    this.Recursion_Add(obj.getChildTransformNodes()[i], rangeName, autoAnimateLoop, speed, setChild);
                }
            }
        }
    }

    public onUpdate(): void {
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3, 4)) {
            return false;
        } else {

            // 第1个参数：
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0], this.nodeID)) {
                return false;
            }
            this._blueGameobject = para0.gameObject;
            // var tmpMesh = this._blueGameobject.value?.mesh;
            // if (tmpMesh == null || tmpMesh == undefined) {
            //     VE_ErrorManager.Add(new VE_Error('', this.ID + " 响应 传入参数格式可能有误，传入参数：" + para_array[0] + "，该物体不具有Mesh，请检查！", '', Severity.Error));
            //     return false;
            // }

            // 参数2：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[1])) {
                return false;
            }
            this.rangeName = para1.string;

            // 参数3：
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[2])) {
                return false;
            }
            this.autoAnimateLoop = para2.bool;

            // 参数4：是否设置子物体
            this._setChildren.value = true;
            if (para_array.length > 3) {
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[3])) {
                    return false;
                }
                this._setChildren = para3.bool;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}


