    public static unloadById(node_id: string): void {
        if (VEObjects._objectsByNodeId.has(node_id)) {
            const ve_object = VEObjects._objectsByNodeId.get(node_id);
            if (ve_object) {
                UIManager.removeGUIObject(ve_object.entity);
                // VEObjects._objectsByName.delete(ve_object.NodeName);
                const index = VEObjects._objects.indexOf(ve_object);
                if (index > -1) {
                    VEObjects._objects.splice(index);
                }
                VEObjects._objectsByNodeId.delete(node_id);
            }
        } else if (VEObjects._clonesByNodeId.has(node_id)) {
            const ve_object = VEObjects._clonesByNodeId.get(node_id);
            if (ve_object) {
                UIManager.removeGUIObject(ve_object.entity);
                // VEObjects._clonesByName.delete(ve_object.NodeName);
                const index = VEObjects._clones.indexOf(ve_object);
                if (index > -1) {
                    VEObjects._clones.splice(index);
                }
                VEObjects._clonesByNodeId.delete(node_id);
            }
        }
    }

