import { IExpression, VE_Expressions } from "../expression";
import { VE_FsmData, VE_StateActionData, VE_StateData, VE_StateTriggerData } from "../dataSource";
import { VE_Error, VE_ErrorManager } from "../global";
import { StateConst, VE_AssociatedState, VE_Fsm, VE_State, VE_StateAction } from "../state";
import { ErrorInfo } from "../utility";
import { IVeryVar, VeryList, VeryString, VarTools, VeryBool, VEVarManager } from "../variables";
import { AssignmentParser } from "./assignment-parser";
import { StateActionType } from "../enum";
import { Trigger_Custom } from "../library/trigger";
import { VEObjects, VEObject } from "../object";
import { VE_TriggerBehaviour, VE_CustomTriggerManager, VE_Triggers } from "../trigger";
import { VE_ActionBehaviour, VE_Actions } from "../action";

export class InstanceParser {

    private assignmentParser: AssignmentParser = new AssignmentParser();


    public constructor() {


    }


    // 1、一般局部变量
    public parsingVariable(ve_object: VEObject): boolean {
        // console.error(ve_object);

        let successful: boolean = true;

        const objectID: string = ve_object.NodeName;
        const varLen = ve_object.varData.count;
        for (let k: number = 0; k < varLen; k++) {
            // (1). 局部变量
            const varID: string = ve_object.varData.getVariableID(k);
            const varPara: string[] = ve_object.varData.getVariableParas(varID);
            // console.log(`varPara[0]: ${varPara[0]}`);
            // 判断，1.普通变量；2.公式
            // 1.公式
            if (
                varPara[0] === "公式" ||
                varPara[0].toLowerCase().trim() === "expression"
            ) {
                continue;
            }
            // 2.普通IVeryVar变量
            else if (VEVarManager.hasVarType(varPara[0])) {
                const errorInfo: ErrorInfo = new ErrorInfo();
                let newVar: Nullable<IVeryVar> = VEVarManager.createVariable(
                    varID,
                    varPara[0],
                    varPara[1],
                    errorInfo
                );
                // TODO: List或者Dictionary处理
                //TODO_20210125:List多种方式定义
                //console.log(varID + "--" + newVar);
                if (errorInfo.isRight && newVar !== null && newVar.varType === "List") {
                    (<VeryList>newVar).SetChildValue(objectID, errorInfo, ve_object.NodeID);
                }
                if (newVar === null || !errorInfo.isRight) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(
                        VE_Error.error(
                            ve_object.varData.getPos(varID),
                            "{{对象}}：" +
                            objectID +
                            "，{{局部变量}}：" +
                            varID +
                            "，" +
                            varPara[0] +
                            "，" +
                            varPara[1] +
                            "，{{局部变量创建失败}}，{{失败原因}}：" +
                            errorInfo.message +
                            "，{{请检查}}！",
                            "",
                            objectID
                        )
                    );
                    successful = false;
                } else {
                    ve_object.addVariable(varID, newVar);
                }
            }
            // 3.对象（类）变量 TOODO
            else if (VEObjects.isNodeNameLoaded(varPara[0], ve_object.NodeID)) {
                ve_object.addClone(varID, VEObjects.getByName(varPara[0], ve_object.NodeID));
            }
            // 未知错误
            else {
                console.warn(`varPara[0]: ${varPara[0]}, ve_object.NodeID: ${ve_object.NodeID}`);
                console.warn(ve_object);
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(
                    VE_Error.error(
                        ve_object.varData.getPos(varID),
                        "{{对象}}：" +
                        objectID +
                        "，{{局部变量}}：" +
                        varID +
                        "," +
                        varPara[0] +
                        "," +
                        varPara[1] +
                        "，{{局部变量创建失败}}，{{当前变量类型不存在}}，{{请检查}}！",
                        "",
                        objectID
                    )
                );
                successful = false;
            }
        }

        return successful;
    }


    // 2、状态变量与状态机
    public parsingFSMState(ve_object: VEObject): boolean {

        let successful: boolean = true;

        const objectID: string = ve_object.NodeName;
        const fsmLen = ve_object.dataSource.fsmCount;
        for (let k: number = 0; k < fsmLen; k++) {
            const fsmID: string = ve_object.dataSource.getFsmID(k);
            const fsmData: VE_FsmData = ve_object.dataSource.getFsmData(fsmID);
            // 创建状态变量，目前默认为string变量
            const newVar: VeryString = new VeryString();
            newVar.setValue(fsmData.initialValStr);
            // 状态机
            const fsm: VE_Fsm = new VE_Fsm(
                objectID,
                ve_object.NodeID,
                fsmID,
                newVar
            );
            ve_object.addFsm(fsmID, fsm);
        }

        return successful;
    }


    // 3、公式变量
    public parsingExpression(ve_object: VEObject): boolean {

        let successful: boolean = true;

        const objectID: string = ve_object.NodeName;
        const varLen = ve_object.varData.count;
        for (let k: number = 0; k < varLen; k++) {
            // (1). 局部变量
            const varID: string = ve_object.varData.getVariableID(k);
            const varPara: string[] = ve_object.varData.getVariableParas(varID);
            // 判断，1.普通变量；2.公式；3.模板变量；
            // 1.公式
            if (
                varPara[0] === "公式" ||
                varPara[0].toLowerCase().trim() === "expression"
            ) {
                // 公式之间以从前到后的解析顺序变异，若前面的公式引用了后面的公式，会直接报错
                let errorInfo: ErrorInfo = new ErrorInfo();
                // TOODO
                let newVar: IExpression = VE_Expressions.createLocalExpression(
                    varID,
                    varPara[1],
                    objectID,
                    errorInfo,
                    ve_object.NodeID
                );
                if (!errorInfo.isRight || newVar === null) {
                    VE_ErrorManager.Add(
                        VE_Error.error(
                            ve_object.varData.getPos(varID),
                            "{{对象}}：" +
                            objectID +
                            "，{{局部变量}}：" +
                            varID +
                            "," +
                            varPara[0] +
                            "," +
                            varPara[1] +
                            "，{{局部变量创建失败}}，{{公式创建错误}}：\n" +
                            errorInfo.message,
                            "",
                            objectID
                        )
                    );
                    successful = false;
                }
                ve_object.addExpression(varID, newVar);
            } else {
                continue;
            }
        }

        return successful;
    }


    // 4、触发——触发创建
    public parsingTrigger(ve_object: VEObject): boolean {

        let successful: boolean = true;

        const objectID: string = ve_object.NodeName;
        const triggerLen = ve_object.dataSource.triggerCount;
        for (let k: number = 0; k < triggerLen; k++) {
            const triggerID: string = ve_object.dataSource.getTriggerID(k);
            // Debug.Log("触发ID：" + triggerID);
            const triggerPara: string[] = ve_object.dataSource.getTriggerPara(triggerID);

            if (!VE_Triggers.hasTrigger(triggerPara[0])) {
                VE_ErrorManager.Add(
                    VE_Error.error(
                        ve_object.dataSource.getTriggerPos(triggerID),
                        "{{对象}}：" +
                        objectID +
                        "，{{触发}}：" +
                        triggerID +
                        "，{{触发类型}}：" +
                        triggerPara[0] +
                        "，{{当前系统中不存在该触发类型}}，{{请检查}}！",
                        "",
                        objectID
                    )
                );
                successful = false;
            } else {
                // 初始化Trigger
                const errorInfo: ErrorInfo = new ErrorInfo();
                const trigger: Nullable<VE_TriggerBehaviour> = VE_Triggers.createTrigger(
                    ve_object,
                    triggerID,
                    triggerPara[0],
                    triggerPara.slice(1),
                    errorInfo
                );

                if (!errorInfo.isRight || trigger === null) {
                    VE_ErrorManager.Add(
                        VE_Error.error(
                            ve_object.dataSource.getTriggerPos(triggerID),
                            "{{对象}}：" +
                            objectID +
                            "，{{触发}}：" +
                            triggerID +
                            "，{{触发创建错误}}，{{原因}}：" +
                            errorInfo.message +
                            "，{{请检查}}！",
                            "",
                            objectID
                        )
                    );
                    successful = false;
                }
                else {
                    // 自定义触发特殊处理
                    if (trigger.className === "Trigger_Custom") {
                        VE_CustomTriggerManager.AddTriggerEvent(
                            objectID,
                            triggerID,
                            (<Trigger_Custom>trigger).customEvent.bind(trigger)
                        );
                    }
                    ve_object.addTrigger(triggerID, trigger!);
                }

            }

        }

        return successful;
    }

    // 5、响应——响应创建
    public parsingAction(ve_object: VEObject): boolean {

        let successful: boolean = true;

        const objectID: string = ve_object.NodeName;
        const actionLen = ve_object.dataSource.actionCount;
        for (let k: number = 0; k < actionLen; k++) {
            const actionID: string = ve_object.dataSource.getActionID(k);
            const actionPara: string[] = ve_object.dataSource.getActionPara(
                actionID
            );
            // console.log(actionID);
            // console.log(actionPara);
            if (!VE_Actions.hasAction(actionPara[0])) {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(
                    VE_Error.error(
                        ve_object.dataSource.getActionPos(actionID),
                        "{{对象}}：" +
                        objectID +
                        "，{{响应}}：" +
                        actionID +
                        "，{{响应类型}}：" +
                        actionPara[0] +
                        "，{{当前系统中不存在该响应类型}}，{{请检查}}！",
                        "",
                        objectID
                    )
                );
                successful = false;
            } else {
                // 初始化Action
                const errorInfo: ErrorInfo = new ErrorInfo();
                let action: Nullable<VE_ActionBehaviour> = VE_Actions.createAction(
                    ve_object,
                    actionID,
                    actionPara[0],
                    actionPara.slice(1),
                    ve_object.dataSource.getActionInitVal(actionID),
                    errorInfo
                );

                if (!errorInfo.isRight || action === null) {
                    VE_ErrorManager.Add(
                        VE_Error.error(
                            ve_object.dataSource.getActionPos(actionID),
                            "{{对象}}：" +
                            objectID +
                            "，{{响应}}：" +
                            actionID +
                            "，{{响应创建错误}}，{{原因}}：" +
                            errorInfo.message +
                            "，{{请检查}}！",
                            "",
                            objectID
                        )
                    );
                    successful = false;
                }
                ve_object.addAction(actionID, action!);
            }
        }

        return successful;
    }


    // 6、状态机 —— 状态机信息关联：触发关联 + 响应关联 + 状态赋值
    public parsingFsmLink(ve_object: VEObject): boolean {

        let successful: boolean = true;

        const objectID: string = ve_object.NodeName;
        const fsmLen = ve_object.dataSource.fsmCount;
        for (let k: number = 0; k < fsmLen; k++) {
            const fsmID: string = ve_object.dataSource.getFsmID(k);
            const fsmData: VE_FsmData = ve_object.dataSource.getFsmData(fsmID);
            // 状态机
            const fsm: VE_Fsm = ve_object.getFsm(fsmID);
            // 状态信息关联：触发激活条件，触发，逻辑表达式，状态值计算公式，响应，关联状态
            for (let p: number = 0; p < fsmData.count; p++) {
                const stateData: VE_StateData = fsmData.getStateData(p);
                if (fsm.hasStateValue(stateData.ValStr)) {
                    VE_ErrorManager.Add(
                        VE_Error.error(
                            "（" + stateData.rowIndex + "，E）",
                            "{{对象}}：" +
                            objectID +
                            "，{{状态}}：" +
                            fsmID +
                            "，{{当前状态值重复}}，{{同一个状态的值不允许重复}}，{{请检查}}！",
                            "",
                            objectID
                        )
                    );
                    successful = false;
                }
                // 状态值，判断状态值不能重复，状态值为常量字符串
                const state: VE_State = new VE_State(fsm, fsm.count + 1);
                state.setConstValue(stateData.ValStr);

                // 响应是否顺序运行
                if (stateData.isSequence) {
                    state.setSequence();
                }

                // 关联状态条件
                if (stateData.logicalExp !== "") {
                    const errorInfo: ErrorInfo = new ErrorInfo();
                    // TOODO
                    const logicalExp: IExpression = VE_Expressions.createFsmExpression(
                        "",
                        stateData.logicalExp,
                        objectID,
                        fsmID,
                        errorInfo,
                        ve_object.NodeID
                    );
                    if (!errorInfo.isRight || logicalExp === null) {
                        VE_ErrorManager.Add(
                            VE_Error.error(
                                "（" + stateData.rowIndex.toString() + "，D）",
                                "{{对象}}：" +
                                objectID +
                                "，{{状态}}：" +
                                fsmID +
                                "，{{状态逻辑表达式}}：" +
                                stateData.logicalExp +
                                "，{{逻辑表达式创建失败}}，{{公式创建错误}}：\n" +
                                errorInfo.message,
                                "",
                                objectID
                            )
                        );
                        successful = false;
                    }
                    state.logicalAssociated = logicalExp;
                }

                // 触发信息关联
                for (let s: number = 0; s < stateData.triggerCount; s++) {

                    const triggerData: VE_StateTriggerData = stateData.getTrigger(s);
                    const triggerPos: string = stateData.getTriggerPos(s);
                    // 可能为当前对象，也可能是其他对象上的触发
                    const trigger: Nullable<VE_TriggerBehaviour> = VE_Triggers.getTrigger(
                        ve_object,
                        triggerData.triggerID
                    );
                    if (trigger === null) {
                        // console.error(trigger);
                        //DO_20221228:表格编辑器,自动检测,中英文
                        VE_ErrorManager.Add(
                            VE_Error.error(
                                triggerPos,
                                "{{对象}}：" +
                                objectID +
                                "，{{状态}}：" +
                                fsmID +
                                "，{{触发}}：" +
                                triggerData.triggerID +
                                "，{{当前触发无法在系统中查找到}}，{{请检查}}！",
                                "",
                                objectID
                            )
                        );
                        successful = false;
                    } else {
                        // 逻辑条件
                        let logicalExp: Nullable<IExpression> = null;
                        // Debug.LogWarning("逻辑表达式：" + triggerData.LogicalExp);
                        if (triggerData.logicalExp !== "") {
                            // 状态逻辑表达式
                            const errorInfo: ErrorInfo = new ErrorInfo();
                            // TOODO
                            logicalExp = VE_Expressions.createFsmExpression(
                                "",
                                triggerData.logicalExp,
                                objectID,
                                fsmID,
                                errorInfo,
                                ve_object.NodeID
                            );
                            // Debug.LogWarning(logicalExp);
                            if (!errorInfo.isRight || logicalExp === null) {
                                //DO_20221228:表格编辑器,自动检测,中英文
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        triggerPos,
                                        "{{对象}}：" +
                                        objectID +
                                        "，{{状态}}：" +
                                        fsmID +
                                        "，{{状态逻辑表达式}}：" +
                                        triggerData.logicalExp +
                                        "，{{逻辑表达式创建失败}}，{{公式创建错误}}：\n" +
                                        errorInfo.message,
                                        "",
                                        objectID
                                    )
                                );
                                successful = false;
                            }
                        }
                        // console.log(state);
                        // console.error(trigger);
                        trigger.addTriggerTarget(logicalExp, state);
                        // 触发启动条件
                        if (triggerData.logicalSwitch !== "") {
                            // 触发启动条件
                            const errorInfo: ErrorInfo = new ErrorInfo();
                            // TOODO
                            const logicalSwitch: IExpression = VE_Expressions.createFsmExpression(
                                "",
                                triggerData.logicalSwitch,
                                objectID,
                                fsmID,
                                errorInfo,
                                ve_object.NodeID
                            );
                            if (!errorInfo.isRight || logicalSwitch === null || logicalSwitch === undefined) {
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        triggerPos,
                                        "{{对象}}：" +
                                        objectID +
                                        "，{{状态}}：" +
                                        fsmID +
                                        "，{{触发启动条件}}：" +
                                        triggerData.logicalSwitch +
                                        "，{{触发启动条件创建失败}}，{{公式创建错误}}：\n" +
                                        errorInfo.message,
                                        "",
                                        objectID
                                    )
                                );
                                successful = false;
                            }
                            trigger.addLogicalSwitch(logicalSwitch);
                        }
                    }
                }

                // 响应信息关联
                for (let s: number = 0; s < stateData.actionCount; s++) {

                    const actionData: VE_StateActionData = stateData.getAction(s);
                    const actionPos: string = stateData.getActionPos(s);
                    // 正常响应
                    if (actionData.type === StateActionType.Action) {
                        // 可能为当前对象，也可能是其他对象上的响应
                        let action: Nullable<VE_ActionBehaviour> = VE_Actions.getAction(
                            ve_object,
                            actionData.actionID
                        );
                        if (action === null) {
                            //DO_20221228:表格编辑器,自动检测,中英文
                            VE_ErrorManager.Add(
                                VE_Error.error(
                                    actionPos,
                                    "{{对象}}：" +
                                    objectID +
                                    "，{{状态}}：" +
                                    fsmID +
                                    "，{{响应}}：" +
                                    actionData.actionID +
                                    "，{{当前响应无法在系统中查找到}}，{{请检查}}！",
                                    "",
                                    objectID
                                )
                            );
                            successful = false;
                        }
                        else {
                            // 响应参数，目前默认只支持常量（两个bool值理论上可以为常量或者变量和公式值引用）
                            // 启动标志
                            const errorInfo: ErrorInfo = new ErrorInfo();
                            let enableVar: Nullable<IVeryVar> = null;
                            const enableStr: string = actionData.enabled.trim().toLowerCase();
                            if (enableStr === 'false' || enableStr === '关' || enableStr === '否' || enableStr === '假') {
                                enableVar = new VeryBool();
                                enableVar.setValue(false);
                            } else if (enableStr === "true" || enableStr === '开' || enableStr === '是' || enableStr === '真') {
                                enableVar = new VeryBool();
                                enableVar.setValue(true);
                            } else {
                                // 支持变量：（1）*变量名；（2）对象名.*变量名；注意：必须返回boolean
                                if (
                                    actionData.enabled.indexOf(StateConst.VARIABLE_SYMBOL) > -1
                                ) {
                                    errorInfo.clear();
                                    // TOODO
                                    enableVar = VarTools.GetVeryVarWithExpression(
                                        objectID,
                                        actionData.enabled,
                                        errorInfo,
                                        ve_object.NodeID
                                    );
                                    if (!errorInfo.isRight || enableVar === null || enableVar === undefined) {
                                        VE_ErrorManager.Add(
                                            VE_Error.error(
                                                actionPos,
                                                "{{对象}}：" +
                                                objectID +
                                                "，{{状态}}：" +
                                                fsmID +
                                                "，{{响应}}：" +
                                                actionData.actionID +
                                                "，{{参数}}：" +
                                                actionData.enabled +
                                                "，{{响应启动参数格式不正确}}，{{错误信息}}：" +
                                                errorInfo.message,
                                                "",
                                                objectID
                                            )
                                        );
                                        successful = false;
                                    }
                                    else {
                                        if (enableVar.varType !== "bool") {
                                            VE_ErrorManager.Add(
                                                VE_Error.error(
                                                    actionPos,
                                                    "{{对象}}：" +
                                                    objectID +
                                                    "，{{状态}}：" +
                                                    fsmID +
                                                    "，{{响应}}：" +
                                                    actionData.actionID +
                                                    "，{{参数}}：" +
                                                    actionData.enabled +
                                                    "，{{响应启动参数变量必须返回bool值类型}}，{{当前变量类型}}：" +
                                                    enableVar.varType,
                                                    "",
                                                    objectID
                                                )
                                            );
                                            successful = false;
                                        }
                                    }
                                } else {
                                    VE_ErrorManager.Add(
                                        VE_Error.error(
                                            actionPos,
                                            "{{对象}}：" +
                                            objectID +
                                            "，{{状态}}：" +
                                            fsmID +
                                            "，{{响应}}：" +
                                            actionData.actionID +
                                            "，{{参数}}：" +
                                            actionData.enabled +
                                            "，{{响应启动参数允许填写格式为：“启动/true”、“停止/false”、“*变量名”、“对象名.*变量名”，且变量不能为模板变量，且变量返回值必须为bool值，当前参数不符合}}，{{请检查}}！",
                                            "",
                                            objectID
                                        )
                                    );
                                    successful = false;
                                }
                            }

                            // 每帧运行
                            let everyFrameVar: Nullable<IVeryVar> = null;
                            const everyFrameStr: string = actionData.everyFrame
                                .trim()
                                .toLowerCase();
                            if (everyFrameStr === 'false' || everyFrameStr === '关' || everyFrameStr === '否' || everyFrameStr === '假') {
                                everyFrameVar = new VeryBool();
                                everyFrameVar.setValue(false);
                            } else if (everyFrameStr === 'true' || everyFrameStr === '开' || everyFrameStr === '是' || everyFrameStr === '真') {
                                everyFrameVar = new VeryBool();
                                everyFrameVar.setValue(true);
                            } else {
                                // 支持变量：（1）*变量名；（2）对象名.*变量名；注意：必须返回boolean
                                if (
                                    actionData.everyFrame.indexOf(StateConst.VARIABLE_SYMBOL) > -1
                                ) {
                                    errorInfo.clear();
                                    // TOODO
                                    everyFrameVar = VarTools.GetVeryVarWithExpression(
                                        objectID,
                                        actionData.everyFrame,
                                        errorInfo,
                                        ve_object.NodeID
                                    );
                                    if (!errorInfo.isRight || everyFrameVar === null || everyFrameVar === undefined) {
                                        VE_ErrorManager.Add(
                                            VE_Error.error(
                                                actionPos,
                                                "{{对象}}：" +
                                                objectID +
                                                "，{{状态}}：" +
                                                fsmID +
                                                "，{{响应}}：" +
                                                actionData.actionID +
                                                "，{{参数}}：" +
                                                actionData.everyFrame +
                                                "，{{响应帧循环参数格式不正确}}，{{错误信息}}：" +
                                                errorInfo.message,
                                                ""
                                            )
                                        );
                                        successful = false;
                                    }
                                    else {
                                        if (everyFrameVar.varType !== "bool") {
                                            VE_ErrorManager.Add(
                                                VE_Error.error(
                                                    actionPos,
                                                    "{{对象}}：" +
                                                    objectID +
                                                    "，{{状态}}：" +
                                                    fsmID +
                                                    "，{{响应}}：" +
                                                    actionData.actionID +
                                                    "，{{参数}}：" +
                                                    actionData.everyFrame +
                                                    "，{{响应帧循环参数变量必须返回bool值类型}}，{{当前变量类型}}：" +
                                                    everyFrameVar.varType,
                                                    "",
                                                    objectID
                                                )
                                            );
                                            successful = false;
                                        }
                                    }
                                } else {
                                    VE_ErrorManager.Add(
                                        VE_Error.error(
                                            actionPos,
                                            "{{对象}}：" +
                                            objectID +
                                            "，{{状态}}：" +
                                            fsmID +
                                            "，{{响应}}：" +
                                            actionData.actionID +
                                            "，{{参数}}：" +
                                            actionData.everyFrame +
                                            "，{{响应帧循环参数允许填写格式为：“持续/true”、“一次/false”、“*变量名”、“对象名.*变量名”，且变量不能为模板变量，且变量返回值必须为bool值，当前参数不符合}}，{{请检查}}！",
                                            "",
                                            objectID
                                        )
                                    );
                                    successful = false;
                                }
                            }

                            // 顺序运行
                            const isSequenceStr: string = actionData.isSequence
                                .trim()
                                .toLowerCase();
                            let isSequence: boolean = false;
                            if (isSequenceStr === 'false' || isSequenceStr === '关' || isSequenceStr === '否' || isSequenceStr === '假') {
                                isSequence = false;
                            } else if (isSequenceStr === 'true' || isSequenceStr === '开' || isSequenceStr === '是' || isSequenceStr === '真') {
                                isSequence = true;
                            } else {
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        actionPos,
                                        "{{对象}}：" +
                                        objectID +
                                        "，{{状态}}：" +
                                        fsmID +
                                        "，{{响应}}：" +
                                        actionData.actionID +
                                        "，{{参数}}：" +
                                        actionData.isSequence +
                                        "，{{响应依次运行状态允许填写格式为：“同时：false/关/否/假”、“依次：true/开/是/真”，不允许填写变量}}，{{请检查}}！",
                                        "",
                                        objectID
                                    )
                                );
                                successful = false;
                            }

                            // 创建状态响应
                            let stateAction: VE_StateAction = new VE_StateAction();
                            stateAction.setAction(
                                action,
                                enableVar,
                                everyFrameVar,
                                isSequence
                            );
                            state.addAction(stateAction);
                        }
                    }
                    // 赋值
                    else {
                        if (!this.assignmentParser.assignmentAction(objectID, fsmID, ve_object, actionData, state)) {
                            successful = false;
                        }
                    }
                }

                fsm.addState(state);
            }
        }

        return successful;
    }


    // 7、状态机 —— 状态机信息关联：关联状态信息关联
    public parsingAssociatedState(ve_object: VEObject): boolean {

        let successful: boolean = true;

        const objectID: string = ve_object.NodeName;
        const fsmLen = ve_object.dataSource.fsmCount;
        for (let k: number = 0; k < fsmLen; k++) {
            const fsmID: string = ve_object.dataSource.getFsmID(k);
            const fsmData: VE_FsmData = ve_object.dataSource.getFsmData(fsmID);
            // 状态机
            const fsm: VE_Fsm = ve_object.getFsm(fsmID);
            // 状态信息关联：触发激活条件，触发，逻辑表达式，状态值计算公式，响应，关联状态
            for (let p: number = 0; p < fsmData.count; p++) {
                const stateData: VE_StateData = fsmData.getStateData(p);
                const state: Nullable<VE_State> = fsm.getStateInSequence(p);
                // 关联状态信息关联
                for (let s: number = 0; s < stateData.associatedStateCount; s++) {
                    let associatedStateInfo: string = stateData.getAssociatedState(s);
                    const associatedPos: string = stateData.getAssociatedStatePos(s);
                    const associatedState: VE_AssociatedState = new VE_AssociatedState(
                        state!
                    );
                    const multipleAssociatedState: string[] = associatedStateInfo.split(
                        /,|，/
                    );

                    for (let w: number = 0; w < multipleAssociatedState.length; w++) {
                        associatedStateInfo = multipleAssociatedState[w].trim();
                        // let stateIndex: number = StateConst.STATE_INDEX;

                        let stateValue: string = StateConst.STATE_VALUE;

                        const strArray: string[] = associatedStateInfo.split("=");
                        if (strArray.length === 1) {
                        } else if (strArray.length === 2) {
                            stateValue = strArray[1].trim();
                        } else {
                            VE_ErrorManager.Add(
                                VE_Error.error(
                                    associatedPos,
                                    "{{对象}}：" +
                                    objectID +
                                    "，{{状态}}：" +
                                    fsmID +
                                    "，{{关联状态}}：" +
                                    associatedStateInfo +
                                    "，{{当前关联状态格式错误}}，{{应为“状态名 = 状态值”的形式}}，{{请检查}}！",
                                    ""
                                )
                            );
                            successful = false;
                        }

                        // 1. 状态名
                        // 2. 对象名.状态名
                        // 3. *模板变量.状态名
                        // 4. 对象名.*模板变量.状态名
                        let aFsmID: string = strArray[0].trim();
                        if (aFsmID.indexOf(StateConst.STATE_SEPARATOR) > -1) {
                            const stateArray: string[] = aFsmID.split(
                                StateConst.STATE_SEPARATOR
                            );
                            for (let q: number = 0; q < stateArray.length; q++) {
                                stateArray[q] = stateArray[q].trim();
                            }

                            // 对象名.*模板变量.状态名
                            if (stateArray.length === 3) {
                                if (VEObjects.isNodeNameLoaded(stateArray[0], ve_object.NodeID)) {
                                    const aObject: VEObject = VEObjects.getByName(stateArray[0], ve_object.NodeID);
                                    if (stateArray[1].startsWith(StateConst.VARIABLE_SYMBOL)) {
                                        const varID: string = stateArray[1].substring(1);
                                        if (aObject.isCreatedClone(varID)) {
                                            const clone = aObject.getClone(varID);
                                            if (clone.parent && clone.parent.dataSource.isCreatedFsm(stateArray[2])) {
                                                associatedState.addClone(
                                                    clone,
                                                    stateArray[2],
                                                    stateValue,
                                                    associatedPos
                                                );
                                            } else {
                                                VE_ErrorManager.Add(
                                                    VE_Error.error(
                                                        associatedPos,
                                                        "{{对象}}：" +
                                                        objectID +
                                                        "，{{状态}}：" +
                                                        fsmID +
                                                        "，{{关联状态}}：" +
                                                        associatedStateInfo +
                                                        "，{{当前关联状态填写格式为“对象名.*模板变量.状态名”}}，{{在当前对象的该模板变量中无法查找到对应状态名}}，{{请检查}}！",
                                                        "",
                                                        objectID
                                                    )
                                                );
                                                successful = false;
                                            }
                                        } else {
                                            VE_ErrorManager.Add(
                                                VE_Error.error(
                                                    associatedPos,
                                                    "{{对象}}：" +
                                                    objectID +
                                                    "，{{状态}}：" +
                                                    fsmID +
                                                    "，{{关联状态}}：" +
                                                    associatedStateInfo +
                                                    "，{{当前关联状态填写格式为“对象名.*模板变量.状态名”}}，{{在当前对象中无法查找到该模板变量}}，{{请检查}}！",
                                                    "",
                                                    objectID
                                                )
                                            );
                                            successful = false;
                                        }

                                    } else {
                                        VE_ErrorManager.Add(
                                            VE_Error.error(
                                                associatedPos,
                                                "{{对象}}：" +
                                                objectID +
                                                "，{{状态}}：" +
                                                fsmID +
                                                "，{{关联状态}}：" +
                                                associatedStateInfo +
                                                "，{{当前关联状态填写格式为“对象名.*模板变量.状态名”}}，{{模板变量填写格式不正确}}，{{请检查}}！",
                                                "",
                                                objectID
                                            )
                                        );
                                        successful = false;
                                    }
                                } else {
                                    VE_ErrorManager.Add(
                                        VE_Error.error(
                                            associatedPos,
                                            "{{对象}}：" +
                                            objectID +
                                            "，{{状态}}：" +
                                            fsmID +
                                            "，{{关联状态}}：" +
                                            associatedStateInfo +
                                            "，{{当前关联状态填写格式为“对象名.*模板变量.状态名”}}，{{无法查找到该对象}}，{{请检查}}！",
                                            "",
                                            objectID
                                        )
                                    );
                                    successful = false;
                                }
                            } else if (stateArray.length === 2) {
                                // 对象名.状态名
                                // *模板变量.状态名

                                let aObjectID: string = stateArray[0].trim();
                                aFsmID = stateArray[1].trim();
                                // *模板变量.状态名
                                if (aObjectID.startsWith(StateConst.VARIABLE_SYMBOL)) {
                                    aObjectID = aObjectID.substring(1);
                                    if (ve_object.isCreatedClone(aObjectID)) {
                                        const clone = ve_object.getClone(aObjectID);
                                        if (clone.parent && clone.parent.dataSource.isCreatedFsm(stateArray[1])) {
                                            associatedState.addClone(
                                                clone,
                                                stateArray[1],
                                                stateValue,
                                                associatedPos
                                            );
                                        } else {
                                            VE_ErrorManager.Add(
                                                VE_Error.error(
                                                    associatedPos,
                                                    "{{对象}}：" +
                                                    objectID +
                                                    "，{{状态}}：" +
                                                    fsmID +
                                                    "，{{关联状态}}：" +
                                                    associatedStateInfo +
                                                    "，{{当前关联状态填写格式为“*模板变量.状态名”}}，{{在当前模板变量中无法查找到对应状态名}}，{{请检查}}！",
                                                    "",
                                                    objectID
                                                )
                                            );
                                            successful = false;
                                        }
                                    } else {
                                        VE_ErrorManager.Add(
                                            VE_Error.error(
                                                associatedPos,
                                                "{{对象}}：" +
                                                objectID +
                                                "，{{状态}}：" +
                                                fsmID +
                                                "，{{关联状态}}：" +
                                                associatedStateInfo +
                                                "，{{当前关联状态填写格式为“*模板变量.状态名”}}，{{在当前系统中无法查找到该模板变量}}，{{请检查}}！",
                                                "",
                                                objectID
                                            )
                                        );
                                        successful = false;
                                    }

                                }
                                // 对象名.状态名
                                else {
                                    const aObject: VEObject = VEObjects.getByName(aObjectID, ve_object.NodeID);
                                    if (aObject === null || aObject === undefined) {
                                        VE_ErrorManager.Add(
                                            VE_Error.error(
                                                associatedPos,
                                                "{{对象}}：" +
                                                objectID +
                                                "，{{状态}}：" +
                                                fsmID +
                                                "，{{关联状态}}：" +
                                                associatedStateInfo +
                                                "，{{当前关联状态填写格式为“对象名.状态名”}}，{{当前系统中无法查找到该对象名}}，{{请检查}}！",
                                                "",
                                                objectID
                                            )
                                        );
                                        successful = false;
                                    } else {
                                        const aFsm: VE_Fsm = aObject.getFsm(aFsmID);
                                        if (aFsm === null || aFsm === undefined) {
                                            VE_ErrorManager.Add(
                                                VE_Error.error(
                                                    associatedPos,
                                                    "{{对象}}：" +
                                                    objectID +
                                                    "，{{状态}}：" +
                                                    fsmID +
                                                    "，{{关联状态}}：" +
                                                    associatedStateInfo +
                                                    "，{{当前关联状态填写格式为“对象名.状态名”}}，{{当前对象名所对应的对象中无法查找到该状态名}}，{{请检查}}！",
                                                    "",
                                                    objectID
                                                )
                                            );
                                            successful = false;
                                        }
                                        const toState: Nullable<VE_State> = aFsm.getState(stateValue);
                                        if (toState === null || toState === undefined) {
                                            VE_ErrorManager.Add(
                                                VE_Error.error(
                                                    associatedPos,
                                                    "{{对象}}：" +
                                                    objectID +
                                                    "，{{状态}}：" +
                                                    fsmID +
                                                    "，{{关联状态}}：" +
                                                    associatedStateInfo +
                                                    "，{{当前关联状态填写格式为“对象名.状态名”}}，{{当前关联状态序号超出对应状态序号范围}}，{{请检查}}！",
                                                    "",
                                                    objectID
                                                )
                                            );
                                            successful = false;
                                        }
                                        associatedState.add(toState, stateValue, associatedPos);
                                        // VE_AssociatedState associatedState = new VE_AssociatedState(state, toState);
                                        // state.AddAssociatedState(associatedState);
                                    }
                                }
                            } else {
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        associatedPos,
                                        "{{对象}}：" +
                                        objectID +
                                        "，{{状态}}：" +
                                        fsmID +
                                        "，{{关联状态}}：" +
                                        associatedStateInfo +
                                        "，{{状态名填写错误}}，{{无法查找到对应状态}}，{{请检查}}！",
                                        ""
                                    )
                                );
                                successful = false;
                            }
                        }
                        //状态名
                        else {
                            const aFsm: VE_Fsm = ve_object.getFsm(aFsmID);
                            if (aFsm === null || aFsm === undefined) {
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        associatedPos,
                                        "{{对象}}：" +
                                        objectID +
                                        "，{{状态}}：" +
                                        fsmID +
                                        "，{{关联状态}}：" +
                                        associatedStateInfo +
                                        "，{{状态名填写错误}}，{{可以查找到对象}}，{{但是对象上无法查找到该状态}}，{{请检查}}！",
                                        ""
                                    )
                                );
                                successful = false;
                            } else {
                                const toState: Nullable<VE_State> = aFsm.getState(stateValue);
                                if (toState === null || toState === undefined) {
                                    VE_ErrorManager.Add(
                                        VE_Error.error(
                                            associatedPos,
                                            "{{对象}}：" +
                                            objectID +
                                            "，{{状态}}：" +
                                            fsmID +
                                            "，{{关联状态}}：" +
                                            associatedStateInfo +
                                            "，{{状态名填写错误}}，{{可以查找到对象和状态}}，{{但是状态序号超出范围}}，{{请检查}}！",
                                            "",
                                            objectID
                                        )
                                    );
                                    successful = false;
                                } else {
                                    associatedState.add(toState, stateValue, associatedPos);
                                }
                            }
                        }
                    }
                    state!.addAssociatedState(associatedState);
                }
            }
        }

        return successful;
    }
}