export class Action_To_String extends VE_ActionBehaviour {

    public get ID(): string {
        return "To_String|转字符串";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '转字符串，*任意变量，*string变量';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=691';
    }
    public get className(): string {
        return "Action_To_String";
    }

    private _isBlueVar = false;
    private _str = "";
    private _iBlueVar: Nullable<IVeryVar> = null;
    private _blueString: VeryString = new VeryString();

    //DO_20211221:number转字符串的时候,保存小数点位数
    private _decimalPoint: VeryNumber = new VeryNumber();
    private toDecimal(str: string, decimal: number): any {
        var f = parseFloat(str);
        if (isNaN(f)) {
            return NaN;
        }
        if (decimal === 0) {
            return Math.round(f);
        }
        var tmpValue = f;
        var tmpDivide = 1;
        for (var i = 0; i < decimal; i++) {
            tmpValue = tmpValue * 10;
            tmpDivide = tmpDivide * 10;
        }
        tmpValue = Math.round(tmpValue);
        var f = tmpValue / tmpDivide;
        var s = f.toString();
        var rs = s.indexOf('.');
        if (rs < 0) {
            rs = s.length;
            s += '.';
        }
        while (s.length <= (rs + decimal)) {
            s += '0';
        }
        return s;
    }

    public active(): void {

    }

    public onUpdate(): void {
        if (this._isBlueVar && this._iBlueVar != null) {
            this._blueString.value = this._iBlueVar.getValue();
        }
        else {
            this._blueString.value = this._str;
        }

        //DO_20211221:number转字符串的时候,保存小数点位数
        if (this._decimalPoint.value >= 0) {
            var finalDecimalPoint = parseInt(this._decimalPoint.value.toString());
            var finalValue = this.toDecimal(this._blueString.value, finalDecimalPoint);
            //DO_20221228:表格编辑器,自动检测
            if (!isNaN(finalValue)) {
                this._blueString.value = finalValue;
            }
            else {
                console.error(this.ID + " 响应传入参数格式错误： " + this._blueString.value + "，请检查填入数据！");
            }
        }
    }

    public paraParser(para_array: string[]): boolean {
        //DO_20211221:number转字符串的时候,保存小数点位数
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2, 3)) {
            return false;
        } else {
            // 参数1：
            if (VarTools.IsVarID(para_array[0])) {
                this._isBlueVar = true;
                let errorInfo: ErrorInfo = new ErrorInfo();
                let veryVar: Nullable<IVeryVar> = VarTools.GetVeryVarWithExpression(this.objectID, para_array[0], errorInfo, this.nodeID);
                if (veryVar == null) {
                    // console.error(this.ID + " 响应 传入参数错误，变量：" + para_array[0] + "，" + errorInfo);
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[0] + "，{{传入参数错误}}，{{无法查找到该变量}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
                else {
                    this._iBlueVar = veryVar;
                }
            }
            else {
                this._str = para_array[0];
                this._isBlueVar = false;
            }

            // 参数2：字符串
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringPara(this.objectID, this.ID, ParaType.Action, para1, para_array[1])) {
                return false;
            }
            this._blueString = para1.string;

            //DO_20211221:number转字符串的时候,保存小数点位数
            this._decimalPoint.value = -1;
            if (para_array.length > 2) {
                // 参数3：小数点位数
                let para2: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[2])) {
                    return false;
                }
                this._decimalPoint = para2.number;
            }

            return true;
        }
    }

    public destroy(): void {

    }
}

