export class Action_Minimap extends VE_ActionBehaviour {

    public get ID(): string {
        return 'Minimap|圆形画中画';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '圆形画中画，*画中画显示，主相机，画中画相机，(0，0，0)，1';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=838';
    }
    public get className(): string {
        return 'Action_Minimap';
    }

    //控制显示
    private _switch: VeryBool = new VeryBool();

    //DO_20210930:漫游相机,画中画显示修改
    private _mainCamera: VeryCamera = new VeryCamera();
    private _minimapCamera: VeryCamera = new VeryCamera();

    //画中画物体
    private _minimapOBJ: Nullable<BABYLON.Mesh> = null;
    //画中画位置
    private _posVec: VeryVector3 = new VeryVector3();
    private _isVec: boolean = false;
    private _x: VeryNumber = new VeryNumber();
    private _y: VeryNumber = new VeryNumber();
    private _z: VeryNumber = new VeryNumber();
    //画中画大小
    private _size: VeryNumber = new VeryNumber();
    //画中画定位方式
    private _posStyle: string = "居中";

    public active(): void {
        var scene = this.scene;
        //DO_20210930:漫游相机,画中画显示修改
        //位置，大小
        var posVec3 = this._posVec.value;
        if (!this._isVec) {
            posVec3 = new BABYLON.Vector3(this._x.value, this._y.value, this._z.value);
        }
        if (this._minimapOBJ == null) {
            var size = this._size.value;
            //RenderTargetTexture
            var rendertargetTexture = new BABYLON.RenderTargetTexture("minimapRenderTargetTexture", { width: BabylonEngine.Canvas.width, height: BabylonEngine.Canvas.height }, scene, true, false);
            scene.customRenderTargets.push(rendertargetTexture);
            //DO_20220519:圆形画中画,背景颜色
            if (GameGlobal.cameraClearcolors[this._minimapCamera.value.name]) {
                rendertargetTexture.clearColor = GameGlobal.cameraClearcolors[this._minimapCamera.value.name];
            }
            rendertargetTexture.activeCamera = this._minimapCamera.value;
            rendertargetTexture.renderList = scene.meshes;
            //相机背景色
            GameGlobal.minimapTextureData[this._minimapCamera.name] = rendertargetTexture;
            //画中画物体:厚度基本为0的圆柱体
            this._minimapOBJ = BABYLON.Mesh.CreateCylinder("minimapOBJ", 0.001, 0.4 * size, 0.4 * size, 24, 1, scene);
            this._minimapOBJ.position = posVec3;
            this._minimapOBJ.rotation = new BABYLON.Vector3(270 / 180 * Math.PI, 0, 0);

            //画中画显示材质
            var minimapMat = new BABYLON.StandardMaterial("minimapMat", scene);
            var tmpSize = (BabylonEngine.Canvas.width > BabylonEngine.Canvas.height) ? BabylonEngine.Canvas.height : BabylonEngine.Canvas.width;
            rendertargetTexture.resize(tmpSize);
            minimapMat.diffuseColor = new BABYLON.Color3(1, 1, 1);
            minimapMat.diffuseTexture = rendertargetTexture;
            minimapMat.diffuseTexture.level = 1.2; // intensity
            minimapMat.specularColor = BABYLON.Color3.Black();
            minimapMat.emissiveColor = new BABYLON.Color3(1, 1, 1); // backlight

            this._minimapOBJ.material = minimapMat;
        }
        //当前显示相机
        this._minimapOBJ.parent = this._mainCamera.value;
        this._minimapOBJ.layerMask = 1;
        //位置大小调整
        var tmpScreenPoint = posVec3;
        var sWidth = scene.getEngine().getRenderWidth();
        var sHeight = scene.getEngine().getRenderHeight();
        var zDis = 0.04;
        if (this._posStyle == "居中") {
            tmpScreenPoint = new BABYLON.Vector3(tmpScreenPoint.x + sWidth / 2, tmpScreenPoint.y + sHeight / 2, zDis);
        }
        var tmpVec3 = BABYLON.Vector3.Unproject(tmpScreenPoint, sWidth, sHeight, BABYLON.Matrix.Identity(), this._mainCamera.value.getViewMatrix(), scene.getProjectionMatrix());
        this._minimapOBJ.setAbsolutePosition(tmpVec3);
        this._minimapOBJ.setEnabled(this._switch.value);
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 5, 6)) {
            return false;
        } else {
            //是否显示
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._switch = para1.bool;

            //DO_20210930:漫游相机,画中画显示修改 
            // 主相机
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.CameraPara(this.objectID, this.ID, ParaType.Action, para2, para_array[1], this.nodeID)) {
                return false;
            }
            this._mainCamera = para2.camera;
            // 画中画相机
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.CameraPara(this.objectID, this.ID, ParaType.Action, para3, para_array[2], this.nodeID)) {
                return false;
            }
            this._minimapCamera = para3.camera;

            //画中画位置
            let para4: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para4, para_array[3])) {
                return false;
            }
            this._isVec = para4.isVec;
            this._posVec = para4.vector3;
            this._x = para4.vecNumbers[0];
            this._y = para4.vecNumbers[1];
            this._z = para4.vecNumbers[2];

            //画中画大小
            let para5: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para5, para_array[4])) {
                return false;
            }
            this._size = para5.number;

            //画中画定位方式
            this._posStyle = '居中';
            if (para_array.length > 5) {
                if (para_array[5] == '左上' || para_array[5] == '左下' || para_array[5] == '右上' || para_array[5] == '右下') {
                    this._posStyle = para_array[5];
                }
            }

            return true;
        }

    }

    public destroy(): void {

    }

}
