    public paraParser(para_array: string[]): boolean {
        //DO_20221202:方形画中画,添加颜色参数,添加边框宽度
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 4, 5, 6)) {
            return false;
        } else {
            //是否显示
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._switch = para1.bool;

            //DO_20210930:漫游相机,画中画显示修改 
            // 主相机
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.CameraPara(this.objectID, this.ID, ParaType.Action, para2, para_array[1], this.nodeID)) {
                return false;
            }
            this._mainCamera = para2.camera;
            // 画中画相机
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.CameraPara(this.objectID, this.ID, ParaType.Action, para3, para_array[2], this.nodeID)) {
                return false;
            }
            this._minimapCamera = para3.camera;

            //画中画位置
            let para4: VeryParas = new VeryParas();
            if (!ParaParserUtility.RectOrNumberPara(this.objectID, this.ID, ParaType.Action, para4, para_array[3])) {
                return false;
            }
            this._isVec = para4.isRect;
            this._vec4 = para4.rect;
            this._vecNumbers = para4.rectNumbers;

            //DO_20221202:方形画中画,添加颜色参数,添加边框宽度
            this._isColor = true;
            this._blueColor.value = new BABYLON.Vector3(0, 255, 0);
            if (para_array.length > 4) {
                // 参数2：
                let para5: VeryParas = new VeryParas();
                if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Trigger, para5, para_array[4])) {
                    return false;
                }
                this._isColor = para5.isVec;
                this._blueColor = para5.vector3;
                this._colorFloat = para5.vecNumbers;
            }
            this._thickness.value = 2;
            if (para_array.length > 5) {
                let para6: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para6, para_array[5])) {
                    return false;
                }
                this._thickness = para6.number;
            }

            return true;
        }

    }

    public destroy(): void {

    }

