export class Action_Set_Active extends VE_ActionBehaviour {

    public get ID(): string {
        return "Set_Active|设置激活";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '设置激活，true，立方体，true';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=566';
    }
    public get className(): string {
        return "Action_Set_Active";
    }

    private _obj: VeryGameObject = new VeryGameObject();
    private _isActive: VeryBool = new VeryBool();
    private _childActive: VeryBool = new VeryBool();

    //DO_20221125:node材质重新激活后node材质刷新,记录node材质初始状态
    private serializationObject = {};

    public active(): void {
        if (this._obj.value != null) {
            if (this._childActive.value) {
                this.ActiveRecursion(this._obj.value.transform.transformNode, this._isActive.value);
            }
            else {
                this._obj.value.transform.transformNode?.setEnabled(this._isActive.value);

                //DO_20221125:粒子系统重新激活后粒子系统刷新,node材质重新激活后node材质刷新
                var tmpMesh = <BABYLON.AbstractMesh>this._obj.value.transform.transformNode;
                if (tmpMesh && this._isActive.value) {
                    //粒子系统重新激活后粒子系统刷新
                    for (var i = 0; i < this.scene.particleSystems.length; i++) {
                        if (this.scene.particleSystems[i].emitter === tmpMesh) {
                            this.scene.particleSystems[i].reset();
                            this.scene.particleSystems[i].start();
                        }
                    }
                    //node材质重新激活后node材质刷新,创建新材质恢复到node材质初始状态
                    var tmpMaterial = tmpMesh.material;
                    if (tmpMaterial && (tmpMaterial instanceof BABYLON.NodeMaterial)) {
                        let store = BABYLON.NodeMaterial.IgnoreTexturesAtLoadTime;
                        BABYLON.NodeMaterial.IgnoreTexturesAtLoadTime = false;
                        let nodeMaterial = BABYLON.SerializationHelper.Parse(() => new BABYLON.NodeMaterial('newMat', this.scene), this.serializationObject[tmpMesh.uniqueId], this.scene, '');
                        nodeMaterial.loadFromSerialization(this.serializationObject[tmpMesh.uniqueId]);
                        nodeMaterial.build();
                        tmpMesh.material = nodeMaterial;
                        tmpMaterial.dispose();
                        BABYLON.NodeMaterial.IgnoreTexturesAtLoadTime = store;
                    }
                }

            }
        }
    }
    private ActiveRecursion(obj: BABYLON.Nullable<BABYLON.TransformNode>, active: boolean) {
        obj?.setEnabled(active);

        //DO_20221125:粒子系统重新激活后粒子系统刷新,node材质重新激活后node材质刷新
        var tmpMesh = <BABYLON.AbstractMesh>obj;
        if (tmpMesh && active) {
            //粒子系统重新激活后粒子系统刷新
            for (var i = 0; i < this.scene.particleSystems.length; i++) {
                if (this.scene.particleSystems[i].emitter === tmpMesh) {
                    this.scene.particleSystems[i].reset();
                    this.scene.particleSystems[i].start();
                }
            }
            var tmpMaterial = tmpMesh.material;
            if (tmpMaterial && (tmpMaterial instanceof BABYLON.NodeMaterial)) {
                let store = BABYLON.NodeMaterial.IgnoreTexturesAtLoadTime;
                BABYLON.NodeMaterial.IgnoreTexturesAtLoadTime = false;
                let nodeMaterial = BABYLON.SerializationHelper.Parse(() => new BABYLON.NodeMaterial('newMat', this.scene), this.serializationObject[tmpMesh.uniqueId], this.scene, '');
                nodeMaterial.loadFromSerialization(this.serializationObject[tmpMesh.uniqueId]);
                nodeMaterial.build();
                tmpMesh.material = nodeMaterial;
                tmpMaterial.dispose();
                BABYLON.NodeMaterial.IgnoreTexturesAtLoadTime = store;
            }
        }
        if (obj != null && obj.getChildTransformNodes().length > 0) {
            for (var i = 0; i < obj.getChildTransformNodes().length; i++) {
                this.ActiveRecursion(obj.getChildTransformNodes()[i], active);
            }
        }
    }

    //DO_20221125:node材质重新激活后node材质刷新,遍历子物体获取node材质初始状态
    private ActiveRecursion_RecordNodeMaterial(obj: BABYLON.Nullable<BABYLON.TransformNode>, active: boolean) {
        var tmpMesh = <BABYLON.AbstractMesh>obj;
        if (tmpMesh) {
            var tmpMaterial = tmpMesh.material;
            var count = 20;
            let that = this;
            var scrllFunc = function () {
                if (count > 0 && (tmpMaterial === null)) {
                    tmpMaterial = tmpMesh.material;
                    if (tmpMaterial && (tmpMaterial instanceof BABYLON.NodeMaterial)) {
                        that.serializationObject[tmpMesh.uniqueId] = tmpMaterial.serialize();
                    }
                    count--;
                    setTimeout(() => {
                        scrllFunc();
                    }, 500);
                }
            }
            setTimeout(() => {
                scrllFunc();
            }, 500);
            if (tmpMaterial && (tmpMaterial instanceof BABYLON.NodeMaterial)) {
                this.serializationObject[tmpMesh.uniqueId] = tmpMaterial.serialize();
            }
        }
        if (obj != null && obj.getChildTransformNodes().length > 0) {
            for (var i = 0; i < obj.getChildTransformNodes().length; i++) {
                this.ActiveRecursion_RecordNodeMaterial(obj.getChildTransformNodes()[i], active);
            }
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2, 3)) {
            return false;
        } else {
            // 参数1：是否激活
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._isActive = para1.bool;

            // 参数2：物体
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para2, para_array[1], this.nodeID)) {
                return false;
            }
            this._obj = para2.gameObject;

            //参数3：是否设置子物体
            if (para_array.length > 2) {
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                    return false;
                }
                this._childActive = para3.bool;
            }

            //DO_20221125:node材质重新激活后node材质刷新,遍历子物体获取node材质初始状态
            //DO_20230613:表格编辑器,自动检测
            if (!VeryEngine.enableLuckySheet) {
                this.ActiveRecursion_RecordNodeMaterial(this._obj.value.transform.transformNode, this._childActive.value);
            }
            return true;
        }
    }

    public destroy(): void {

    }
}

