export class Action_Create_Empty extends VE_ActionBehaviour {

    public get ID(): string {
        return "Create_Empty|创建空物体";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '创建空物体，空物体，null，(10，10，10)';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=569';
    }
    public get className(): string {
        return "Action_Create_Empty";
    }

    private _objName: VeryString = new VeryString();
    private _blueObj: VeryGameObject = new VeryGameObject();
    private _refObj: VeryGameObject = new VeryGameObject();

    private _pos: VeryVector3 = new VeryVector3();
    private _posIsVec: boolean = true;
    private _posNumbers: VeryNumber[] = [];

    private _angle: VeryVector3 = new VeryVector3();
    private _angleIsVec: boolean = true;
    private _angleNumbers: VeryNumber[] = [];

    public active(): void {

        this._blueObj.value = new GameObject(this._objName.value);
        if (this._refObj.value) {
            this._blueObj.value.transform.parent = this._refObj.value.transform;
        }
        this._blueObj.value.transform.localPosition = this._posIsVec ? BABYLON.Vector3.Zero().copyFrom(this._pos.value) : BABYLON.Vector3.Zero().copyFromFloats(this._posNumbers[0].value, this._posNumbers[1].value, this._posNumbers[2].value);
        this._blueObj.value.transform.localEulerAngles = this._angleIsVec ? BABYLON.Vector3.Zero().copyFrom(this._angle.value) : BABYLON.Vector3.Zero().copyFromFloats(this._angleNumbers[0].value, this._angleNumbers[1].value, this._angleNumbers[2].value);
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 1, 2, 3, 4)) {
            return false;
        } else {
            // 参数1：物体名
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._objName = para1.string;

            // 参数2: 位置
            if (para_array.length > 1) {
                if (para_array[1].toLowerCase() === 'null' || para_array[1].toLowerCase() === 'none') {
                    this._posIsVec = true;
                    this._pos.value = BABYLON.Vector3.Zero();
                } else {
                    let para2: VeryParas = new VeryParas();
                    if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                        return false;
                    }
                    this._posIsVec = para2.isVec;
                    this._pos = para2.vector3;
                    this._posNumbers = para2.vecNumbers;
                }
            }

            // 参数3: 角度
            if (para_array.length > 2) {
                if (para_array[2].toLowerCase() === 'null' || para_array[2].toLowerCase() === 'none') {
                    this._angleIsVec = true;
                    this._angle.value = BABYLON.Vector3.Zero();
                } else {
                    let para3: VeryParas = new VeryParas();
                    if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                        return false;
                    }
                    this._angleIsVec = para3.isVec;
                    this._angle = para3.vector3;
                    this._angleNumbers = para3.vecNumbers;
                }
            }

            // 参数4: 参考物体
            if (para_array.length > 3) {
                if (para_array[3].toLowerCase() === 'null' || para_array[3].toLowerCase() === 'none') {
                    this._refObj.value = null;
                } else {
                    let para4: VeryParas = new VeryParas();
                    if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para4, para_array[3], this.nodeID)) {
                        return false;
                    }
                    this._refObj = para4.gameObject;
                }
            }

            return true;
        }
    }

    public destroy(): void {

    }
}

export class Action_OutlineHighlight extends VE_ActionBehaviour {

    public get ID(): string {
        return "OutlineHighlight|物体轮廓高亮";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '物体轮廓高亮，*高亮控制，立方体，(255，0，0)，(0，255，0)，0.5，false';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=840';
    }
    public get className(): string {
        return "Action_OutlineHighlight";
    }

    // 参数1：高亮控制
    private _switch: VeryBool = new VeryBool();
    // 参数2：物体
    private _blueObj: VeryGameObject = new VeryGameObject();
    // 参数3：起始颜色
    private _startIsVec: boolean = false;
    private _startColor: VeryVector3 = new VeryVector3();
    private _startColor2: VeryNumber[] = [];
    //参数4：终止颜色
    private _endIsVec: boolean = false;
    private _endColor: VeryVector3 = new VeryVector3();
    private _endColor2: VeryNumber[] = [];
    //参数5：间隔时间
    private _spaceTime: VeryNumber = new VeryNumber();
    //参数6：设置子物体
    private _setChildren: VeryBool = new VeryBool();
    //DO_20220824:物体轮廓高亮,增加一个参数高亮持续时间
    //参数7：高亮持续时间
    private _highlightCurrentTime: number = 0;
    private _highlightTime: VeryNumber = new VeryNumber();

    private _recordMeshs: { [key: string]: BABYLON.AbstractMesh } = {};
    private _currentTime: number = 0;
    //DO_20220217:轮廓高亮中其他未高亮物体被高亮影响
    private static _highlightLayer: Nullable<BABYLON.HighlightLayer> = null;
    private static _initialed: boolean = false;
    private startColor = new BABYLON.Vector3(0, 0, 0);
    private endColor = new BABYLON.Vector3(0, 0, 0);

    //DO_20220831:物体轮廓高亮，轮廓高亮被遮挡时处理
    private static maxUniqueId = 0;

    public active(): void {

        //DO_20220217:轮廓高亮中其他未高亮物体被高亮影响
        if (Action_OutlineHighlight._highlightLayer == null) {
            Action_OutlineHighlight._highlightLayer = new BABYLON.HighlightLayer("hightlight", this.scene);
        }
        if (!Action_OutlineHighlight._initialed) {
            //DO_20220831:物体轮廓高亮，轮廓高亮被遮挡时处理
            //DO_20220720:轮廓高亮被遮挡时处理
            //this.scene.setRenderingAutoClearDepthStencil(1, false);
            for (var i = 0; i < this.scene.meshes.length; i++) {
                // DO_20220221:picoVR轮廓高亮报错
                var mesh = <BABYLON.Mesh>this.scene.meshes[i];
                if (mesh && mesh.onBeforeBindObservable) {
                    //DO_20220831:物体轮廓高亮，轮廓高亮被遮挡时处理
                    //DO_20220720:轮廓高亮被遮挡时处理
                    //mesh.renderingGroupId = 1;
                    if (mesh.material) {
                        if (mesh.material.uniqueId > Action_OutlineHighlight.maxUniqueId) {
                            Action_OutlineHighlight.maxUniqueId = mesh.material.uniqueId;
                        }
                    }
                    Action_OutlineHighlight._highlightLayer.addExcludedMesh(mesh);

                }
            }
            //DO_20220831:物体轮廓高亮，轮廓高亮被遮挡时处理
            for (var i = 0; i < VR.BabylonEngine.Scene.meshes.length; i++) {
                var mesh = <BABYLON.Mesh>VR.BabylonEngine.Scene.meshes[i];
                if (mesh.material) {
                    if (mesh.material.uniqueId <= Action_OutlineHighlight.maxUniqueId) {
                        mesh.material.uniqueId = mesh.material.uniqueId + Action_OutlineHighlight.maxUniqueId;
                    }
                }
            }
            Action_OutlineHighlight._initialed = true;
        }

        this.startColor = this._startColor.value;
        if (!this._startIsVec) {
            this.startColor = new BABYLON.Vector3(this._startColor2[0].value, this._startColor2[1].value, this._startColor2[2].value);
        }
        this.endColor = this._endColor.value;
        if (!this._endIsVec) {
            this.endColor = new BABYLON.Vector3(this._endColor2[0].value, this._endColor2[1].value, this._endColor2[2].value);
        }
    }

    public onUpdate(): void {

        //DO_20220217:轮廓高亮中其他未高亮物体被高亮影响
        //DO_20211213:循环遍历处理空物体
        if (this._blueObj.value != null && Action_OutlineHighlight._highlightLayer != null) {
            //记录旧的材质
            var tmpTransformNode = (this._blueObj.value.transform.mesh !== null) ? this._blueObj.value.transform.mesh : this._blueObj.value.transform.transformNode;
            this.Recursion_Add(tmpTransformNode, this._setChildren.value);

            //DO_20220217:轮廓高亮中其他未高亮物体被高亮影响
            for (let key in this._recordMeshs) {
                //DO_20220221:picoVR轮廓高亮报错
                var mesh = <BABYLON.Mesh>this._recordMeshs[key];
                if (mesh && mesh.onBeforeBindObservable) {
                    //DO_20220901:物体轮廓高亮, material为空处理
                    //DO_20220831:物体轮廓高亮，轮廓高亮被遮挡时处理
                    if (mesh.material) {
                        if (mesh.material.uniqueId > Action_OutlineHighlight.maxUniqueId) {
                            mesh.material.uniqueId = mesh.material.uniqueId - Action_OutlineHighlight.maxUniqueId;
                        }
                    }
                    //DO_20220720:轮廓高亮被遮挡时处理
                    //mesh.renderingGroupId = 0;
                    Action_OutlineHighlight._highlightLayer.removeExcludedMesh(mesh);
                }
            }

            if (this._switch.value) {
                this._currentTime += Time.deltaTime;
                if (this._currentTime >= this._spaceTime.value * 2) {
                    this._currentTime = 0;
                }
                for (let key in this._recordMeshs) {
                    //DO_20220221:picoVR轮廓高亮报错
                    var mesh = <BABYLON.Mesh>this._recordMeshs[key];
                    if (mesh && mesh.onBeforeBindObservable) {

                        if (Action_OutlineHighlight._highlightLayer.hasMesh(mesh)) {
                            Action_OutlineHighlight._highlightLayer.removeMesh(mesh);
                        }
                        //TODO_20210308:物体轮廓高亮
                        if (this._currentTime >= this._spaceTime.value) {
                            Action_OutlineHighlight._highlightLayer.addMesh(mesh, new BABYLON.Color3(this.startColor.x / 255, this.startColor.y / 255, this.startColor.z / 255));
                        }
                        else {
                            Action_OutlineHighlight._highlightLayer.addMesh(mesh, new BABYLON.Color3(this.endColor.x / 255, this.endColor.y / 255, this.endColor.z / 255));
                        }

                    }
                }

                //DO_20220824:物体轮廓高亮,增加一个参数高亮持续时间
                if (this._highlightTime.value > 0) {
                    this._highlightCurrentTime += Time.deltaTime;
                    if (this._highlightCurrentTime >= this._highlightTime.value) {
                        this._switch.value = false;
                        this._highlightCurrentTime = 0;
                    }
                }
            }
            else {
                for (let key in this._recordMeshs) {
                    //DO_20220221:picoVR轮廓高亮报错
                    var mesh = <BABYLON.Mesh>this._recordMeshs[key];
                    if (mesh && mesh.onBeforeBindObservable) {
                        //TODO_20210308:物体轮廓高亮
                        Action_OutlineHighlight._highlightLayer.removeMesh(mesh);

                        //DO_20220831:物体轮廓高亮，轮廓高亮物体相互遮挡时切换高亮物体处理
                        Action_OutlineHighlight._highlightLayer.addExcludedMesh(mesh);
                        //DO_20220901:物体轮廓高亮, material为空处理
                        //DO_20220831:物体轮廓高亮，轮廓高亮被遮挡时处理
                        if (mesh.material) {
                            if (mesh.material.uniqueId <= Action_OutlineHighlight.maxUniqueId) {
                                mesh.material.uniqueId = mesh.material.uniqueId + Action_OutlineHighlight.maxUniqueId;
                            }
                        }

                    }
                }
                //DO_20220706:轮廓高亮,使用物体变量时切换物体调用处理
                this._recordMeshs = {};
            }
        }

    }

    //DO_20211213:循环遍历处理空物体
    private Recursion_Add(obj: BABYLON.TransformNode, setChild: boolean = false) {
        if (this._recordMeshs[obj.name] == undefined) {
            if (obj instanceof BABYLON.AbstractMesh)
                this._recordMeshs[obj.name] = obj;
            if (setChild) {
                if (obj.getChildTransformNodes().length > 0) {
                    for (var i = 0; i < obj.getChildTransformNodes().length; i++) {
                        this.Recursion_Add(obj.getChildTransformNodes()[i], setChild);
                    }
                }
            }
        }
    }

    //DO_20220325:轮廓高亮支持响应为false时，关闭高亮
    public onDisable(): void {
        this._switch.value = false;
        for (let key in this._recordMeshs) {
            var mesh = <BABYLON.Mesh>this._recordMeshs[key];
            if (mesh && mesh.onBeforeBindObservable) {
                Action_OutlineHighlight._highlightLayer.removeMesh(mesh);

                //DO_20220831:物体轮廓高亮，轮廓高亮物体相互遮挡时切换高亮物体处理,
                Action_OutlineHighlight._highlightLayer.addExcludedMesh(mesh);
                //DO_20220901:物体轮廓高亮, material为空处理
                //DO_20220831:物体轮廓高亮，轮廓高亮被遮挡时处理
                if (mesh.material) {
                    if (mesh.material.uniqueId <= Action_OutlineHighlight.maxUniqueId) {
                        mesh.material.uniqueId = mesh.material.uniqueId + Action_OutlineHighlight.maxUniqueId;
                    }
                }
            }
        }
        //DO_20220706:轮廓高亮,使用物体变量时切换物体调用处理
        this._recordMeshs = {};
    }

    public paraParser(para_array: string[]): boolean {
        //DO_20220824:物体轮廓高亮,增加一个参数高亮持续时间
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 5, 6, 7)) {
            return false;
        } else {
            // 参数1：高亮控制
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._switch = para0.bool;

            // 参数2：物体
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para1, para_array[1], this.nodeID)) {
                return false;
            }
            this._blueObj = para1.gameObject;

            // 参数3：起始颜色
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[2])) {
                return false;
            }
            this._startIsVec = para2.isVec;
            this._startColor = para2.vector3;
            this._startColor2 = para2.vecNumbers;

            // 参数4：终止颜色
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[3])) {
                return false;
            }
            this._endIsVec = para3.isVec;
            this._endColor = para3.vector3;
            this._endColor2 = para3.vecNumbers;

            // 参数5：间隔时间
            let para4: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para4, para_array[4])) {
                return false;
            }
            this._spaceTime = para4.number;

            // 参数6：是否设置子物体
            if (para_array.length > 5) {
                let para5: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para5, para_array[5])) {
                    return false;
                }
                this._setChildren = para5.bool;
            }

            //DO_20220824:物体轮廓高亮,增加一个参数高亮持续时间
            // 参数7：持续时间
            this._highlightTime.value = 0;
            this._highlightCurrentTime = 0;
            if (para_array.length > 6) {
                let para6: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para6, para_array[6])) {
                    return false;
                }
                this._highlightTime = para6.number;
            }


            return true;
        }
    }

    public destroy(): void {

    }
}

//DO_20210929:物体组合
export class Action_GameObject_Combination extends VE_ActionBehaviour {

    public get ID(): string {
        return "GameObject_Combination|物体组合|物体控制";
    }
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '物体组合，*keyStr，1：Cube.Cube2.Cube13，(2：Cube.Cube2.Cube14，Cube.Cube2.Cube15)';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=587';
    }
    public get className(): string {
        return "Action_GameObject_Combination";
    }

    //控制字符串
    private _controlStr: VeryString = new VeryString();

    //记录ID及对应的物体
    private _panelModule: { [key: string]: BABYLON.Node[] } = {};
    // 记录上次操作 父层对应的子层       如：112 =>  <11,112>
    private _currentLevelID: { [key: string]: string } = {};
    //从0变成非0时使用，记录是物体消失前的状态   父层----子层
    private _zeroNotesID: { [key: string]: string } = {};
    //当前完整的ID
    private _currentTotalID: string = "";
    //最大个数,最小个数用于循环
    private _max: { [key: string]: number } = {};
    private _min: { [key: string]: number } = {};
    //标准ID的长度
    private _length: number = -1;
    //导航条 情况没有分析完全，暂不处理，待补充
    private _navigationInf: string[] = [];
    private _navigationPoint: number = 0;
    private _switch: string = "";

    //DO_20221213:支持变量控制物体组合全显示
    private _allShow: VeryBool = new VeryBool();

    public active(): void {
        this._switch = this._controlStr.getValue().toString();
        let loopNumber: number;
        let isSpecial: boolean;
        let para = {
            state_input: this._switch,
            number: 0,
            is_special: true
        }
        if (!this.DealInputRequirements(para)) {
            console.error(this.ID + " 响应，状态表里，使响应值变成" + this._switch + "，发生错误，长度不符合要求或者循环增量不符合要求！");
            return;
        }
        this._switch = para.state_input;
        loopNumber = para.number;
        isSpecial = para.is_special;
        let tagString = this._switch.substring(0, this._length - 1);
        let lastNumber = this._switch[this._length - 1];
        //DO_20221213:支持变量控制物体组合全显示
        for (var key in this._panelModule) {
            this.SetActive(this._panelModule[key], false);
        }
        if (lastNumber === '=') {
            if (this._currentLevelID[tagString]) {
                this.SetActive(this._panelModule[this._currentTotalID], false);
                this._currentTotalID = this._currentLevelID[tagString];
                this.SetActive(this._panelModule[this._currentTotalID], true);
            }
        }

        else if (lastNumber === '<') {
            if (this._currentLevelID[tagString] && this._currentLevelID[tagString][this._length - 1] === '0') {
                this.SetActive(this._panelModule[this._currentTotalID], false);
                this._currentLevelID[tagString] = this._zeroNotesID[tagString];
                this._currentTotalID = this._zeroNotesID[tagString];
                this.RecordNavigationInf(this._currentTotalID);
                this.SetActive(this._panelModule[this._currentTotalID], true);
            }
        }

        else if (lastNumber === '+') {
            this.SetActive(this._panelModule[this._currentTotalID], false);
            this._currentTotalID = this.PlusLoop(this._currentTotalID, loopNumber);
            this.RecordNavigationInf(this._currentTotalID);
            this._currentLevelID[tagString] = this._currentTotalID;
            this.SetActive(this._panelModule[this._currentTotalID], true);

        }
        else if (lastNumber === '-') {
            this.SetActive(this._panelModule[this._currentTotalID], false);
            this._currentTotalID = this.MinusLoop(this._currentTotalID, loopNumber);
            this.RecordNavigationInf(this._currentTotalID);
            this._currentLevelID[tagString] = this._currentTotalID;
            this.SetActive(this._panelModule[this._currentTotalID], true);
        }
        else if (lastNumber === ')') {
            if (this._navigationPoint < this._navigationInf.length - 1) {
                this.SetActive(this._panelModule[this._currentTotalID], false);
                let oldID = this._currentTotalID;
                this._navigationPoint++;
                this._currentTotalID = this._navigationInf[this._navigationPoint];
                this._currentLevelID[this._currentTotalID.substring(0, this._length - 1)] = this._currentTotalID;
                if (this._currentTotalID[this._length - 1] === '0' && oldID.startsWith(this._currentTotalID.substring(0, this._length - 1)))
                    this._zeroNotesID[this._currentTotalID.substring(0, this._length - 1)] = this._currentTotalID;
                this.SetActive(this._panelModule[this._currentTotalID], true);
            }
        }
        else if (lastNumber === '(') {
            if (this._navigationPoint !== 0) {
                this.SetActive(this._panelModule[this._currentTotalID], false);
                let oldID = this._currentTotalID;
                this._navigationPoint--;
                this._currentTotalID = this._navigationInf[this._navigationPoint];
                this._currentLevelID[this._currentTotalID.substring(0, this._length - 1)] = this._currentTotalID;
                if (this._currentTotalID[this._length - 1] === '0' && oldID.startsWith(this._currentTotalID.substring(0, this._length - 1)))
                    this._zeroNotesID[this._currentTotalID.substring(0, this._length - 1)] = this._currentTotalID;
                this.SetActive(this._panelModule[this._currentTotalID], true);
            }
        } else {
            //DO_20221213:支持变量控制物体组合全显示
            //if (this.PanelContainsKey(this._switch) && this._switch !== this._currentTotalID) {
            if (this.PanelContainsKey(this._switch)) {
                if (isSpecial) {
                    this._currentLevelID[tagString] = this._switch;
                } else {
                    this.SetActive(this._panelModule[this._currentTotalID], false);
                    this._currentLevelID[tagString] = this._switch;
                    this.RecordNavigationInf(this._currentTotalID);
                    if (lastNumber === '0' && this._currentTotalID.startsWith(tagString))
                        this._zeroNotesID[tagString] = this._currentTotalID;
                    this._currentTotalID = this._switch;
                    this.SetActive(this._panelModule[this._currentTotalID], true);
                }
            }
        }
        //DO_20221213:支持变量控制物体组合全显示
        if (this._allShow.value) {
            for (var key in this._panelModule) {
                this.SetActive(this._panelModule[key], true);
            }
        }
        this._controlStr.setValue(this._currentTotalID);
    }

    private DealInputRequirements(data: any): boolean {
        data.number = 1;
        data.is_special = false;
        if (data.state_input === ")" || data.state_input === "(") {
            for (let i = 0; i < this._length - 1; i++) {
                data.state_input = "0" + data.state_input;
            }
            return true;
        } else if (data.state_input.length > this._length) {
            if (data.state_input.startsWith("@")) {
                data.is_special = true;
                data.state_input = data.state_input.substring(1);
            }
            else if (data.state_input[this._length - 1] === '+' || data.state_input[this._length - 1] === '-') {
                let numberStr = data.state_input.substring(this._length);
                var n = parseInt(numberStr);
                if (isNaN(n)) {
                    return false;
                }
                data.number = n;
                data.state_input = data.state_input.substring(0, this._length);
                return true;
            }
            else
                return false;
        }
        if (data.state_input.length === this._length)
            return true;
        else
            return false;
    }

    private RecordNavigationInf(current_id: string): void {
        if (this._navigationPoint < this._navigationInf.length - 1) {
            for (let i = this._navigationPoint + 1; i < this._navigationInf.length; i++) {
                this._navigationInf.splice(this._navigationPoint + 1, 1);
            }
        }
        this._navigationInf.push(current_id);
        this._navigationPoint = this._navigationInf.length - 1;
    }

    private PanelContainsKey(current_id: string): boolean {
        return this._panelModule[current_id] ? true : false;
    }

    public paraParser(para_array: string[]): boolean {
        if (para_array.length < 2) {
            //DO_20221228:表格编辑器,自动检测,中英文
            VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{需要大于等于2个传入参数}}，{{当前参数个数为}}" + para_array.length.toString() + "，{{请检查}}！", '', Severity.Error));
            return false;
        } else {

            // 第1个参数转化  GUI组控制string变量
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._controlStr = para1.string;

            // 其他参数转化  UGUI分组
            // 后面参数转化
            for (let i = 1, len = para_array.length; i < len; i++) {
                // 去掉Excel表的回车键
                para_array[i] = para_array[i].replace(/\n/g, '');
                let panelID = para_array[i].split(/:|：/);
                //DO_20221213:支持变量控制物体组合全显示
                if (i === (len - 1) && panelID.length === 1) {
                    let para2: VeryParas = new VeryParas();
                    if (ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[i])) {
                        this._allShow = para2.bool;
                        break;
                    }
                }
                if (panelID.length !== 2) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + ' {{响应传入参数格式错误}}，{{物体元素键值}}： ' + para_array[i] + '，{{应为（id：物体元素1，物体元素2，...）的形式}}！', '', Severity.Error));
                    return false;
                }

                // 判断字符串是否为数字和字母组合  
                var condition1 = /^[0-9a-zA-Z]*$/;
                if (!condition1.test(panelID[0])) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + ' {{响应传入参数格式错误}}: ' + para_array[i] + "{{的ID}}：" + panelID[0] + "，{{应只包含数字或者字母}}！", '', Severity.Error));
                    return false;
                }

                // Panel 的id识别（111的识别）
                if (!this._panelModule[panelID[0]]) {
                    this._panelModule[panelID[0]] = [];

                    // Debug.Log(panelStr[0]);
                    if (this._length === -1) {
                        this._length = panelID[0].length;
                    }
                    else if (this._length != panelID[0].length) {
                        //DO_20221228:表格编辑器,自动检测,中英文
                        VE_ErrorManager.Add(new VE_Error('', this.ID + ' {{响应传入参数格式错误}}: ' + panelID[0] + "，{{字符串长度与之前不一致}}！", '', Severity.Error));
                        return false;
                    }
                    // 去掉最后一个数字的标记字符串
                    let tagString = panelID[0].substring(0, this._length - 1);
                    let lastNumber = this.ConversionCharToIndex(panelID[0][this._length - 1]);  // 将最后一个字符转化为ASCII码int值
                    if (!this._panelModule[tagString + "0"])
                        this._panelModule[tagString + "0"] = [];

                    // 获取最大数值，用于循环处理
                    if (!this._max[tagString])
                        this._max[tagString] = lastNumber;
                    else if (this._max[tagString] < lastNumber)
                        this._max[tagString] = lastNumber;
                    // 获取最小数值，用于设置默认状态
                    if (!this._min[tagString]) {
                        if (lastNumber != 0) {
                            this._zeroNotesID[tagString] = tagString + this.ConversionIndexToStr(lastNumber);
                            this._min[tagString] = lastNumber;
                        }
                        if (!this._currentLevelID[tagString])
                            this._currentLevelID[tagString] = tagString + this.ConversionIndexToStr(lastNumber);
                    }

                    else if (this._min[tagString] > lastNumber) {
                        if (lastNumber != 0) {
                            this._min[tagString] = lastNumber;
                            this._zeroNotesID[tagString] = tagString + this.ConversionIndexToStr(lastNumber);
                        }
                        this._currentLevelID[tagString] = tagString + this.ConversionIndexToStr(lastNumber);
                    }
                } else {
                    // 考虑要不要报错，同时写了2个一样的
                    console.warn(this.ID + " 响应传入参数错误：" + panelID[0] + "，该ID已存在,不允许重复命名！");
                    continue;
                }
                let panelStr = panelID[1].split(/,|，/);

                // 找到Gameobject进行匹配记录
                for (let j = 0; j < panelStr.length; j++) {
                    if (panelStr[j] === "")
                        continue;
                    let panelObj: Nullable<BABYLON.Node> = null;
                    let isSingleName = (panelStr[j].split('.').length === 1);
                    if (isSingleName) {
                        panelObj = this.scene.getNodeByName(panelStr[j]);
                    }
                    else {
                        panelObj = this.GetFullNameNode(panelStr[j]);
                    }
                    if (panelObj !== null) {
                        this._panelModule[panelID[0]].push(panelObj);
                        break;
                    }
                    //DO_20221228:表格编辑器,自动检测
                    if (panelObj === null && !VeryEngine.enableLuckySheet) {
                        //DO_20221228:表格编辑器,自动检测,中英文
                        VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + panelStr[j] + "，{{物体在场景中无法找到}}，{{请检查}}！", '', Severity.Error));
                        return false;
                    }
                }
            }

            // 初始化
            this._currentTotalID = this._controlStr.value;
            this._currentLevelID[this._currentTotalID.substring(0, this._length - 1)] = this._currentTotalID;
            for (let key in this._panelModule) {
                if (this._currentTotalID != key)
                    this.SetActive(this._panelModule[key], false);
            }
            if (this._panelModule[this._currentTotalID]) {
                this.SetActive(this._panelModule[this._currentTotalID], true);
            }
            //DO_20221213:支持变量控制物体组合全显示
            if (this._allShow.value) {
                for (var key in this._panelModule) {
                    this.SetActive(this._panelModule[key], true);
                }
            }

            return true;
        }
    }

    private GetFullNameNode(fullName: string): BABYLON.Nullable<BABYLON.Node> {
        var tmpNode: BABYLON.Nullable<BABYLON.Node> = null;
        var tmpParent: BABYLON.Nullable<BABYLON.Node> = null;
        var tmpArray = fullName.split('.');
        var notFound = true;
        for (var i = 0; i < this.scene.rootNodes.length; i++) {
            if (tmpArray[0] === this.scene.rootNodes[i].name) {
                tmpParent = this.scene.rootNodes[i];
                tmpNode = this.scene.rootNodes[i];
                notFound = false;
                break;
            }
        }
        if (notFound) {
            return null;
        }
        for (var i = 1; i < tmpArray.length; i++) {
            notFound = true;
            for (var j = 0; j < tmpParent.getChildren().length; j++) {
                if (tmpArray[i] === tmpParent.getChildren()[j].name) {
                    tmpNode = tmpParent.getChildren()[j];
                    tmpParent = tmpParent.getChildren()[j];
                    notFound = false;
                    break;
                }
            }
            if (notFound) {
                return null;
            }
        }
        return tmpNode;
    }

    private SetActive(panel_objs: BABYLON.Node[], is_show: boolean): void {
        for (let i = 0; i < panel_objs.length; i++) {
            panel_objs[i].setEnabled(is_show);
        }
    }

    private PlusLoop(current_id: string, plus_number: number = 1): string {
        let lastNumber = this.ConversionCharToIndex(current_id[this._length - 1]);
        let lastNumberStr = "";
        if (lastNumber === 0)
            return current_id;
        current_id = current_id.substring(0, this._length - 1);
        while (true) {
            lastNumber += plus_number;
            if (lastNumber > this._max[current_id])
                lastNumber = this._min[current_id] + lastNumber - this._max[current_id] - 1;
            lastNumberStr = this.ConversionIndexToStr(lastNumber);
            if (this.PanelContainsKey(current_id + lastNumberStr))
                break;
        }
        return current_id + lastNumberStr;
    }

    private MinusLoop(current_id: string, minus_number: number = 1): string {
        let lastNumber = this.ConversionCharToIndex(current_id[this._length - 1]);
        let lastNumberStr = "";
        if (lastNumber === 0)
            return current_id;
        current_id = current_id.substring(0, this._length - 1);
        while (true) {
            lastNumber -= minus_number;
            if (lastNumber < this._min[current_id])
                lastNumber = this._max[current_id] - (this._min[current_id] - lastNumber - 1);
            lastNumberStr = this.ConversionIndexToStr(lastNumber);
            if (this.PanelContainsKey(current_id + lastNumberStr))
                break;
        }
        return current_id + lastNumberStr;
    }

    private ConversionIndexToStr(index: number): string {
        if (index < 10)
            return index.toString();
        else if (index < 36)
            return String.fromCharCode(index + 87);  // 'a' ((char)(index + 87)).ToString();
        else if (index < 62)
            return String.fromCharCode(index + 29);  // ((char)(index + 29)).ToString();
        else {
            console.warn(this.ID + " 响应，输入下标超出范围，请与程序猿联系！");
            return "null";
        }
    }

    private ConversionCharToIndex(char_index: string): number {
        let index = char_index.charCodeAt(0);
        if (96 < index && index < 123) {
            return index - 87;
        } else if (index > 64 && index < 91) {
            return index - 29;
        } else {
            return index - 48;
        }
    }

    public destroy(): void {

    }
}

