import { VEObject } from "../object";
import { VE_FsmData, VE_StateActionData, VE_StateData, VE_StateTriggerData } from "../dataSource";
import { StateConst } from "../state";
import { VE_StringFormat } from "../utility";
import { VE_Error, VE_ErrorManager } from "../global";
import { VeryTable } from "../../verytable";

export class TableParser {

    private _lastFsmID: string = '';
    // private _lastObjectID: string = '';
    private _activeFsmData: Nullable<VE_FsmData> = null;
    private _activeStateData: Nullable<VE_StateData> = null;
    private _emptyLine: boolean = false;



    public constructor() {

    }


    public parsing(ve_object: VEObject, table: VeryTable): boolean {

        this._activeFsmData = null;
        this._activeStateData = null;

        let successful: boolean = true;

        const rowCount = table.RowCount;
        for (let i: number = 1; i < rowCount; i++) {
            // console.log(`行号: ${i+1}, 内容: ${table.getData(i, 0)}`);
            // 注释行, 直接跳过
            if (table.getData(i, 0).startsWith('//')) {
                continue;
            }
            // 空行
            if (table.getRow(i)!.isEmpty()) {
                // console.log('空行: ' + (i + 1));
                // TODO: 空行直接分隔状态；
                this._emptyLine = true;
                continue;
            }

            // （1）变量或者单独的状态
            else if (table.getData(i, 4) !== "" && table.getData(i, 0) === "" && table.getData(i, 1) === "" && table.getData(i, 2) === "" && table.getData(i, 3) === "" && table.getData(i, 5) === "" && table.getData(i, 6) === "" && table.getData(i, 7) === "") {
                const paraData: string = table.getData(i, 4);

                // 状态赋值或者局部公式变量
                let isVariable: boolean = true;
                if (paraData.indexOf('=') > -1) {
                    const paraArray: string[] = paraData.split('=');
                    // 状态赋值
                    // 目前暂不考虑赋值公式中有等号的情况, 赋值公式后面只能是常量或者已创建的变量
                    if (paraArray.length === 2 && paraArray[0].trim() === this._lastFsmID) {
                        this._emptyLine = false;
                        isVariable = false;
                        if (this._activeFsmData === null) {
                            VE_ErrorManager.Add(VE_Error.error(table.pos(i, 4), "{{状态赋值}}: " + table.getData(i, 4) + ", {{当前状态书写格式错误}}, {{请检查}}！", table.ID, ve_object.NodeName));
                            successful = false;
                        } else {
                            const stateData: VE_StateData = new VE_StateData(this._activeFsmData, paraArray[1].trim(), false);
                            stateData.rowIndex = i;
                            this._activeFsmData.addState(stateData);
                            this._activeStateData = stateData;
                        }
                    }
                }

                // 一般变量或者公式变量
                if (isVariable) {
                    this._emptyLine = true;
                    const varArray: string[] = VE_StringFormat.paraSegment(paraData);
                    if (varArray.length === 2 || varArray.length === 3) {
                        let varID: string = varArray[0].trim();
                        if (!VE_StringFormat.isIDLegal(varID)) {
                            VE_ErrorManager.Add(VE_Error.error(table.pos(i, 4), "{{变量}}: " + table.getData(i, 4) + ", {{当前变量名不合法}}, {{包含非法字符}}, {{请检查}}！", table.ID, ve_object.NodeName));
                            successful = false;
                        }

                        const paraArray: string[] = [varArray[1].trim()];
                        if (varArray.length === 2) {
                            paraArray.push('');
                        } else {
                            paraArray.push(varArray[2].trim());
                        }
                        // 注意: 局部变量名与状态名也不能重合
                        if (ve_object.varData.isCreatedVariable(varID)) {
                            VE_ErrorManager.Add(VE_Error.error(table.pos(i, 4), "{{对象名}}: " + ve_object.NodeName + ", {{局部变量}}: " + table.getData(i, 4) + ", {{当前局部变量名已创建}}, {{请检查}}！", table.ID, ve_object.NodeName));
                            successful = false;
                        }
                        else if (ve_object.dataSource.isCreatedFsm(varID)) {
                            VE_ErrorManager.Add(VE_Error.error(table.pos(i, 4), "{{对象名}}: " + ve_object.NodeName + ", {{局部变量}}: " + table.getData(i, 4) + ", {{局部变量名不能与状态名相同}}, {{当前状态已创建}}, {{请检查}}！", table.ID, ve_object.NodeName));
                            successful = false;
                        }
                        else {
                            ve_object.varData.addVariable(varID, paraArray, table.pos(i, 4));
                        }
                    } else {
                        VE_ErrorManager.Add(VE_Error.error(table.pos(i, 4), "{{局部变量}}: " + table.getData(i, 4) + ", {{当前局部变量格式不正确}}, {{请检查}}！", table.ID, ve_object.NodeName));
                        successful = false;
                    }
                }
            }
            // （2）状态 + 触发 + 条件 + 响应 + 关联状态，多种复合情况
            else {
                // 1）状态解析
                let hasState: boolean = false;
                let paraData: string = table.getData(i, 4);
                if (paraData !== '') {
                    hasState = true;
                    this._emptyLine = false;
                }
                // 空行分隔新状态
                else {
                    if (this._emptyLine) {
                        this._emptyLine = false;
                        hasState = true;
                        paraData = (ve_object.NodeName + '_空状态_' + StateConst.StateCount++) + ',' + StateConst.STATE_VALUE;
                    }
                }
                // 状态解析，状态值只能为string字符串，非空行，且状态为空，跳过状态解析
                if (hasState) {
                    // 状态赋值
                    if (paraData.indexOf('=') > -1) {
                        const stateArray: string[] = paraData.split('=');
                        const fsmID: string = stateArray[0].trim();
                        // 状态
                        if (stateArray.length === 2) {
                            if (fsmID === this._lastFsmID) {
                                if (this._activeFsmData === null) {
                                    VE_ErrorManager.Add(VE_Error.error(table.pos(i, 4), "{{状态赋值}}: " + table.getData(i, 4) + ", {{当前状态不属于任何对象和模板对象}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                    successful = false;
                                } else {
                                    // let stateIndex: number = StateConst.STATE_INDEX;
                                    const stateData: VE_StateData = new VE_StateData(this._activeFsmData, stateArray[1].trim(), false);
                                    stateData.rowIndex = i;
                                    this._activeFsmData.addState(stateData);
                                    this._activeStateData = stateData;
                                }
                            } else {
                                VE_ErrorManager.Add(VE_Error.error(table.pos(i, 4), "{{状态赋值}}：" + table.getData(i, 4) + "，{{状态名}}：" + fsmID + "，{{当前状态未定义}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                successful = false;
                            }
                        } else {
                            VE_ErrorManager.Add(VE_Error.error(table.pos(i, 4), "{{状态赋值}}：" + table.getData(i, 4) + "，{{当前状态格式不正确}}，{{应为“状态名=状态值”的形式}}，{{请检查}}！", table.ID, ve_object.NodeName));
                            successful = false;
                        }
                    }
                    // 创建状态机
                    else {
                        const varArray: string[] = VE_StringFormat.paraSegment(paraData);
                        if (varArray.length === 2) {
                            const fsmID: string = varArray[0].trim();
                            if (!VE_StringFormat.isIDLegal(fsmID)) {
                                VE_ErrorManager.Add(VE_Error.error(table.pos(i, 4), "{{状态名}}：" + table.getData(i, 4) + "，{{当前状态名不合法}}，{{包含非法字符}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                successful = false;
                            }
                            varArray[1] = varArray[1].trim();
                            this._lastFsmID = fsmID;
                            // 状态名与变量名不可重名
                            if (ve_object.varData.isCreatedVariable(fsmID)) {
                                VE_ErrorManager.Add(VE_Error.error(table.pos(i, 4), "{{对象名}}：" + ve_object.NodeName + "，{{状态名}}：" + fsmID + "，{{状态名与局部变量名不能相同}}，{{当前局部变量已创建}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                successful = false;
                            }
                            else if (ve_object.dataSource.isCreatedFsm(fsmID)) {
                                VE_ErrorManager.Add(VE_Error.error(table.pos(i, 4), "{{对象名}}：" + ve_object.NodeName + "，{{状态名}}：" + fsmID + "，{{当前状态已创建}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                successful = false;
                            } else {
                                // 创建状态机数据
                                ve_object.dataSource.createFsm(fsmID, table.pos(i, 4));
                                this._activeFsmData = ve_object.dataSource.getFsmData(fsmID);
                                // 初始化状态机
                                this._activeFsmData.initFsm('string', varArray[1]);
                                // 创建具体状态
                                const stateData: VE_StateData = new VE_StateData(this._activeFsmData, varArray[1], true);
                                stateData.rowIndex = i;
                                this._activeFsmData.addState(stateData);
                                this._activeStateData = stateData;
                            }
                        } else {
                            VE_ErrorManager.Add(VE_Error.error(table.pos(i, 4), "{{状态定义}}：" + table.getData(i, 4) + "，{{当前状态格式不正确}}，{{应为“状态名, 状态值”的形式}}，{{请检查}}！", table.ID, ve_object.NodeName));
                            successful = false;
                        }
                    }
                }

                // 2）触发解析
                if (table.getData(i, 1) !== '' || table.getData(i, 2) !== '') {
                    if (this._activeFsmData === null || this._activeStateData === null) {
                        VE_ErrorManager.Add(VE_Error.error(table.pos(i, 1), "{{触发}}：" + table.getData(i, 1) + "，{{当前触发书写格式不属于任何对象}}，{{请检查}}！", table.ID, ve_object.NodeName));
                        successful = false;
                    }

                    // 触发定义不为空，则加入到DataSource中，并且判断重复性
                    let triggerID: string = table.getData(i, 1);
                    if (table.getData(i, 1) === '') {
                        triggerID = ve_object.NodeName + '_' + this._lastFsmID + '_空触发_' + StateConst.TriggerCount++;
                    }
                    let idTemp: string = triggerID.replace(/./g, '');
                    if (!VE_StringFormat.isIDLegal(idTemp)) {
                        VE_ErrorManager.Add(VE_Error.error(table.pos(i, 1), "{{触发名}}：" + table.getData(i, 1) + "，{{当前触发名不合法}}，{{包含非法字符}}，{{请检查}}！", table.ID, ve_object.NodeName));
                        successful = false;
                    }

                    if (table.getData(i, 2) !== '') {
                        if (!this._activeFsmData!.dataSource.isCreatedTrigger(triggerID)) {
                            this._activeFsmData!.dataSource.addTrigger(triggerID, VE_StringFormat.paraSegment(table.getData(i, 2)), table.pos(i, 2));
                        } else {
                            VE_ErrorManager.Add(VE_Error.error(table.pos(i, 1), "{{触发}}：" + table.getData(i, 1) + "，{{当前触发已在该对象中定义}}，{{请勿重复定义}}，{{请检查}}！", table.ID, ve_object.NodeName));
                            successful = false;
                        }
                    }

                    // 触发数据加入StateData中
                    let triggerData: VE_StateTriggerData = new VE_StateTriggerData(triggerID);
                    this._activeStateData.addTrigger(triggerData, table.pos(i, 1));

                    // 触发启动条件
                    if (table.getData(i, 0) !== '') {
                        triggerData.logicalSwitch = table.getData(i, 0);
                    }

                    // 触发逻辑条件
                    if (table.getData(i, 3) !== '') {
                        triggerData.logicalExp = table.getData(i, 3);
                    }

                } else {
                    // 触发启动条件
                    if (table.getData(i, 0) !== '') {
                        VE_ErrorManager.Add(VE_Error.error(table.pos(i, 0), "{{触发启动条件}}：" + table.getData(i, 0) + "，{{当前无触发}}，{{请勿定义触发启动条件}}，{{请检查}}！", table.ID, ve_object.NodeName));
                        successful = false;
                    }

                    // 关联状态逻辑条件
                    if (table.getData(i, 3) !== '') {
                        if (this._activeFsmData === null || this._activeStateData === null) {
                            VE_ErrorManager.Add(VE_Error.error(table.pos(i, 3), "{{状态逻辑条件}}：" + table.getData(i, 3) + "，{{当前状态逻辑条件不属于任何对象}}，{{请检查}}！", table.ID, ve_object.NodeName));
                            successful = false;
                        }

                        if (this._activeStateData.logicalExp !== '') {
                            VE_ErrorManager.Add(VE_Error.error(table.pos(i, 3), "{{状态逻辑条件}}：" + table.getData(i, 3) + "，{{在状态的某个值中，无触发的状态逻辑条件只能填写1个，作为关联状态的逻辑条件，此处为第2个，不符合规则}}，{{请检查}}！", table.ID, ve_object.NodeName));
                            successful = false;
                        } else {
                            this._activeStateData.logicalExp = table.getData(i, 3);
                        }
                    }
                }

                // 3）响应解析
                if (table.getData(i, 5) !== '' || table.getData(i, 6) !== '') {
                    if (this._activeFsmData === null || this._activeStateData === null) {
                        VE_ErrorManager.Add(VE_Error.error(table.pos(i, 5), "{{响应}}：" + table.getData(i, 5) + "，{{当前响应不属于任何对象}}，{{请检查}}！", table.ID, ve_object.NodeName));
                        successful = false;
                    } else {
                        // 分3种类型，合成2种
                        if (table.getData(i, 6) !== '') {
                            // 响应定义（有响应名或为空）、变量赋值、log调试；
                            const tempStr: string = table.getData(i, 6).toLowerCase();
                            if (tempStr.startsWith('log(') || tempStr.startsWith('log（') || tempStr.startsWith('调试（') || tempStr.startsWith('调试(')) {
                                const newActionID: string = ve_object.NodeName + '__log__' + StateConst.LogCount++;
                                const actionData: VE_StateActionData = new VE_StateActionData(newActionID, 'true', 'false');
                                this._activeStateData.addAction(actionData, table.pos(i, 6));
                                let actionPara: string = table.getData(i, 6).substring(4);
                                if (tempStr.startsWith('调试')) {
                                    actionPara = table.getData(i, 6).substring(3);
                                }
                                this._activeFsmData.dataSource.addAction(newActionID, ['调试', '调试', actionPara.substring(0, actionPara.length - 1)], ['true', 'false'], table.pos(i, 6));
                                if (table.getData(i, 5) !== '') {
                                    VE_ErrorManager.Add(VE_Error.warning(table.pos(i, 5), "{{响应名}}：" + table.getData(i, 5) + "，{{该处不应该再有响应定义}}，{{但是填写了响应名}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                    successful = false;
                                }
                            }
                            else if (tempStr.startsWith('error(') || tempStr.startsWith('error（') || tempStr.startsWith('错误（') || tempStr.startsWith('错误(')) {
                                let newActionID: string = ve_object.NodeName + '__log__' + StateConst.LogCount++;
                                let actionData: VE_StateActionData = new VE_StateActionData(newActionID, 'true', 'false');
                                this._activeStateData.addAction(actionData, table.pos(i, 6));
                                let actionPara: string = table.getData(i, 6).substring(6);
                                if (tempStr.startsWith('错误')) {
                                    actionPara = table.getData(i, 6).substring(3);
                                }
                                this._activeFsmData.dataSource.addAction(newActionID, ['调试', '错误', actionPara.substring(0, actionPara.length - 1)], ['true', 'false'], table.pos(i, 6));
                                if (table.getData(i, 5) !== '') {
                                    VE_ErrorManager.Add(VE_Error.warning(table.pos(i, 5), "{{响应名}}：" + table.getData(i, 5) + "，{{该处不应该再有响应定义}}，{{但是填写了响应名}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                    successful = false;
                                }
                            }
                            else if (tempStr.startsWith('warn(') || tempStr.startsWith('warn（') || tempStr.startsWith('警告（') || tempStr.startsWith('警告(')) {
                                let newActionID: string = ve_object.NodeName + '__log__' + StateConst.LogCount++;
                                let actionData: VE_StateActionData = new VE_StateActionData(newActionID, 'true', 'false');
                                this._activeStateData.addAction(actionData, table.pos(i, 6));
                                let actionPara: string = table.getData(i, 6).substring(5);
                                if (tempStr.startsWith('警告')) {
                                    actionPara = table.getData(i, 6).substring(3);
                                }
                                this._activeFsmData.dataSource.addAction(newActionID, ['调试', '警告', actionPara.substring(0, actionPara.length - 1)], ['true', 'false'], table.pos(i, 6));
                                if (table.getData(i, 5) !== '') {
                                    VE_ErrorManager.Add(VE_Error.warning(table.pos(i, 5), "{{响应名}}：" + table.getData(i, 5) + "，{{该处不应该再有响应定义}}，{{但是填写了响应名}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                    successful = false;
                                }
                            } else {
                                // 响应ID
                                const actionArray: string[] = VE_StringFormat.paraSegment(table.getData(i, 6));
                                // TODO：分辨是变量赋值 还是 响应参数
                                // 允许“=”后面直接赋值 公式
                                if (actionArray.length === 1 && actionArray[0].indexOf('=') > -1) {
                                    if (table.getData(i, 5) !== '') {
                                        VE_ErrorManager.Add(VE_Error.warning(table.pos(i, 5), "{{响应名}}：" + table.getData(i, 5) + "，{{该处不应该再有响应定义}}，{{但是填写了响应名}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                        successful = false;
                                    }

                                    // 允许“=”后面直接赋值 公式
                                    const equalIndex: number = table.getData(i, 6).indexOf('=');
                                    const actionData: VE_StateActionData = new VE_StateActionData('');
                                    actionData.setAssignmentAction(table.getData(i, 6), table.getData(i, 6).substring(0, equalIndex).trim(), table.getData(i, 6).substring(equalIndex + 1).trim());
                                    this._activeStateData.addAction(actionData, table.pos(i, 6));
                                } else {
                                    let actionNames: string[];
                                    if (table.getData(i, 5) !== '') {
                                        actionNames = VE_StringFormat.paraSegment(table.getData(i, 5));
                                    } else {
                                        actionNames = [ve_object.NodeName + '_' + this._lastFsmID + '_空响应_' + StateConst.ActionCount++, 'true', 'false', 'false'];
                                    }

                                    // console.log(actionArray);
                                    if (actionNames.length === 2 || actionNames.length === 3 || actionNames.length === 4) {
                                        let actionData: VE_StateActionData;
                                        if (actionNames.length === 2) {
                                            actionData = new VE_StateActionData(actionNames[0], actionNames[1]);
                                        } else if (actionNames.length === 3) {
                                            actionData = new VE_StateActionData(actionNames[0], actionNames[1], actionNames[2]);
                                        } else {
                                            actionData = new VE_StateActionData(actionNames[0], actionNames[1], actionNames[2], actionNames[3]);
                                        }
                                        this._activeStateData.addAction(actionData, table.pos(i, 5));
                                    } else {
                                        VE_ErrorManager.Add(VE_Error.error(table.pos(i, 5), "{{响应}}：" + table.getData(i, 5) + "，{{响应格式不正确，应为“响应ID，启动标志（bool），每帧运行标志（bool）”的形式}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                        successful = false;
                                    }

                                    // 响应定义
                                    if (!VE_StringFormat.isIDLegal(actionNames[0])) {
                                        VE_ErrorManager.Add(VE_Error.error(table.pos(i, 5), "{{响应名}}：" + table.getData(i, 5) + "，{{当前响应名不合法}}，{{包含非法字符}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                        successful = false;
                                    }
                                    if (!this._activeFsmData.dataSource.isCreatedAction(actionNames[0])) {
                                        if (actionNames.length == 2) {
                                            this._activeFsmData.dataSource.addAction(actionNames[0], VE_StringFormat.paraSegment(table.getData(i, 6)), [actionNames[1], 'false'], table.pos(i, 6));
                                        } else {
                                            this._activeFsmData.dataSource.addAction(actionNames[0], VE_StringFormat.paraSegment(table.getData(i, 6)), [actionNames[1], actionNames[2]], table.pos(i, 6));
                                        }
                                    } else {
                                        VE_ErrorManager.Add(VE_Error.error(table.pos(i, 5), "{{响应}}：" + table.getData(i, 5) + "，{{当前响应已在该对象中定义}}，{{请勿重复定义}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                        successful = false;
                                    }

                                }
                            }
                        } else {
                            // 响应名引用；
                            let actionArray: string[] = VE_StringFormat.paraSegment(table.getData(i, 5));
                            // console.log(actionArray);
                            if (actionArray.length === 2 || actionArray.length === 3 || actionArray.length === 4) {
                                let actionData: VE_StateActionData;
                                if (actionArray.length === 2) {
                                    actionData = new VE_StateActionData(actionArray[0], actionArray[1]);
                                } else if (actionArray.length === 3) {
                                    actionData = new VE_StateActionData(actionArray[0], actionArray[1], actionArray[2]);
                                } else {
                                    actionData = new VE_StateActionData(actionArray[0], actionArray[1], actionArray[2], actionArray[3]);
                                }
                                this._activeStateData.addAction(actionData, table.pos(i, 5));
                            } else {
                                //DO_20221228:表格编辑器,自动检测,中英文
                                VE_ErrorManager.Add(VE_Error.error(table.pos(i, 5), "{{响应}}：" + table.getData(i, 5) + "，{{响应格式不正确，应为“响应ID，启动标志（bool），每帧运行标志（bool）”的形式}}，{{请检查}}！", table.ID, ve_object.NodeName));
                                successful = false;
                            }
                        }
                    }
                }

                // 4）关联状态解析
                if (table.getData(i, 7) !== '') {
                    if (this._activeFsmData === null || this._activeStateData === null) {
                        VE_ErrorManager.Add(VE_Error.error(table.pos(i, 7), "{{关联状态}}：" + table.getData(i, 7) + "，{{当前关联状态不属于任何对象}}，{{请检查}}！", table.ID, ve_object.NodeName));
                        successful = false;
                    }
                    else {
                        this._activeStateData!.addAssociatedState(table.getData(i, 7), table.pos(i, 7));
                    }
                }

            }

        }

        return successful;
    }





}