import { Compiler } from "../../../veryengine/compiler";
import { GameObject, ParaType, Severity, VEObjects, VE_Actions, VE_Error, VE_ErrorManager, VarTools, VeryBool, VeryGameObject, VeryNumber, VeryString, VeryVector3 } from "../../../veryengine";
import { VEClone } from "../../../veryengine/template";
import { VE_ActionBehaviour } from "../../action";
import { ParaParserUtility, VeryParas, ErrorInfo } from "../../utility";

export class Action_CloneObject extends VE_ActionBehaviour {

    public get ID(): string {
        return '克隆对象|Clone_Object';
    };

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '克隆对象，*球对象，null，(0，-6，0)，(0，0，90)，false';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=784';
    }
    public get className(): string {
        return 'Action_CloneObject';
    };


    private _template: Nullable<VEClone> = null;
    private _templateVarID: string = '';
    private _ref: VeryGameObject = new VeryGameObject();

    private _position: VeryVector3 = new VeryVector3();
    private _posX: VeryNumber = new VeryNumber();
    private _posY: VeryNumber = new VeryNumber();
    private _posZ: VeryNumber = new VeryNumber();
    private _isPositionVec: boolean = true;

    private _angle: VeryVector3 = new VeryVector3();
    private _angleX: VeryNumber = new VeryNumber();
    private _angleY: VeryNumber = new VeryNumber();
    private _angleZ: VeryNumber = new VeryNumber();
    private _isAngleVec: boolean = true;

    private _destoryOnCreateNew: VeryBool = new VeryBool();
    private _withChild: VeryBool = new VeryBool();



    public active(): void {
        if (this._template === null) return;

        setTimeout(this.createClone.bind(this), 0);

    }


    private async createClone() {
        const errorInfo: ErrorInfo = new ErrorInfo();
        await this._template.create(this._destoryOnCreateNew.value, this._withChild.value);

        if (this._template.instance === null) {
            console.error(this.ID + " 响应 克隆对象错误，错误原因：" + errorInfo.message);
            return;
        }
        if (this._ref.value !== null) {
            if (this._isPositionVec) {
                this._template.instance.gameObject.transform.position = this._ref.value.transform.transformPosition(this._position.value);
            }
            else {
                this._template.instance.gameObject.transform.position = this._ref.value.transform.transformPosition(new BABYLON.Vector3(this._posX.value, this._posY.value, this._posZ.value));
            }

            const emptyAngle: GameObject = new GameObject("Angle__Empty");
            emptyAngle.transform.parent = this._ref.value.transform;
            if (this._isAngleVec) {
                emptyAngle.transform.localEulerAngles = this._angle.value;
            }
            else {
                emptyAngle.transform.localEulerAngles = new BABYLON.Vector3(this._angleX.value, this._angleY.value, this._angleZ.value);
            }
            this._template.instance.gameObject.transform.eulerAngles = emptyAngle.transform.eulerAngles;
            GameObject.Destroy(emptyAngle);
        }
        else {
            if (this._isPositionVec) {
                this._template.instance.gameObject.transform.position = this._position.value;
            }
            else {
                this._template.instance.gameObject.transform.position = new BABYLON.Vector3(this._posX.value, this._posY.value, this._posZ.value);
            }

            if (this._isAngleVec) {
                this._template.instance.gameObject.transform.eulerAngles = this._angle.value;
            }
            else {
                this._template.instance.gameObject.transform.eulerAngles = new BABYLON.Vector3(this._angleX.value, this._angleY.value, this._angleZ.value);
            }
        }
    }

    // 1.变量
    // 2.参考系
    // 3.位置
    // 4.角度
    // 5.是否销毁旧实例
    // 6.是否克隆子物体
    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 4, 5, 6)) {
            return false;
        } else {

            // 参数1：模板变量（1）*模板变量；（2）对象名.*模板变量；
            const errorInfo: ErrorInfo = new ErrorInfo();
            this._templateVarID = para_array[0];

            this._template = VarTools.GetClone(this.objectID, this._templateVarID, errorInfo, this.nodeID);
            if (this._template === null) {
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式错误}}，{{克隆对象错误}}，{{对象变量}}：" + para_array[0] + "，{{错误原因}}： " + errorInfo.message, '', Severity.Error));
                return false;
            }

            // 参数2： 参考物体
            let para4: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para4, para_array[1], this.nodeID)) {
                return false;
            }
            this._ref = para4.gameObject;

            // 参数3： 位置
            let para5: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para5, para_array[2])) {
                return false;
            }
            this._isPositionVec = para5.isVec;
            this._position = para5.vector3;
            this._posX = para5.vecNumbers[0];
            this._posY = para5.vecNumbers[1];
            this._posZ = para5.vecNumbers[2];

            // 参数4： 角度
            let para6: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para6, para_array[3])) {
                return false;
            }
            this._isAngleVec = para6.isVec;
            this._angle = para6.vector3;
            this._angleX = para6.vecNumbers[0];
            this._angleY = para6.vecNumbers[1];
            this._angleZ = para6.vecNumbers[2];

            // 参数5： 是否销毁旧实例
            if (para_array.length > 4) {
                let para7: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para7, para_array[4])) {
                    return false;
                }
                this._destoryOnCreateNew = para7.bool;
            } else {
                this._destoryOnCreateNew.value = true;
            }

            // 参数6： 是否克隆子物体
            if (para_array.length > 5) {
                let para8: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para8, para_array[5])) {
                    return false;
                }
                this._withChild = para8.bool;
            } else {
                this._withChild.value = false;
            }

            return true;
        }
    }


    public destroy(): void {

    }

}
VE_Actions.addAction(Action_CloneObject);

export class Action_CloneObjectCustomPara extends VE_ActionBehaviour {

    public get ID(): string {
        return '克隆对象自定义参数|Clone_Object_Custom_Para';
    };

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '克隆对象自定义参数，*球对象，true, false, ({"position": [0,0,0]})';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=1166';
    }
    public get className(): string {
        return 'Action_CloneObjectCustomPara';
    };

    private _template: Nullable<VEClone> = null;
    private _templateVarID: string = '';

    private _destoryOnCreateNew: VeryBool = new VeryBool();
    private _withChild: VeryBool = new VeryBool();

    private _paras: VeryString = new VeryString();

    public active(): void {
        if (this._template === null) return;

        setTimeout(this.createClone.bind(this), 0);
    }

    private async createClone() {

        const errorInfo: ErrorInfo = new ErrorInfo();
        let p: any;
        try {
            p = JSON.parse(this._paras.value);
        } catch (e) {
            console.error(this._paras.value);
            console.error(this.ID + " 响应 自定义参数错误，错误原因：" + e.message);
            return;
        }
        await this._template.create(this._destoryOnCreateNew.value, this._withChild.value, p);
        if (this._template.instance === null) {
            console.error(this.ID + " 响应 克隆对象错误，错误原因：" + errorInfo.message);
            return;
        }
    }

    // 1.变量
    // 2.是否销毁旧实例
    // 3.是否克隆子物体
    // 4.参数
    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 4)) {
            return false;
        } else {

            // 参数1：模板变量（1）*模板变量；（2）对象名.*模板变量；
            const errorInfo: ErrorInfo = new ErrorInfo();
            this._templateVarID = para_array[0];

            this._template = VarTools.GetClone(this.objectID, this._templateVarID, errorInfo, this.nodeID);
            if (this._template === null) {
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式错误}}，{{克隆对象错误}}，{{对象变量}}：" + para_array[0] + "，{{错误原因}}： " + errorInfo.message, '', Severity.Error));
                return false;
            }

            // 参数2： 是否销毁旧实例
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._destoryOnCreateNew = para2.bool;


            // 参数3： 是否克隆子物体
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                return false;
            }
            this._withChild = para3.bool;

            // 参数4： 参数
            let para4: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para4, para_array[3])) {
                return false;
            }
            this._paras = para4.string;

            return true;
        }
    }


    public destroy(): void {

    }

}
VE_Actions.addAction(Action_CloneObjectCustomPara);


export class Action_DestoryCloneObject extends VE_ActionBehaviour {

    public get ID(): string {
        return '销毁克隆对象|Destory_Clone_Object';
    };

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '销毁克隆对象, 对象变量, true, false';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=785';
    }
    public get className(): string {
        return 'Action_DestoryCloneObject';
    };

    private _cloneVar: string = '';
    // private _deleteObject: VeryBool = new VeryBool();
    private _deleteAll: VeryBool = new VeryBool();
    private _errorInfo: ErrorInfo = new ErrorInfo();

    public active(): void {

        const clone = VarTools.GetClone(this.objectID, this._cloneVar, this._errorInfo, this.nodeID);
        if (this._errorInfo.isRight && clone) {
            clone.unload(this._deleteAll.value);
        } else {
            console.error(this.ID + " {{响应}} {{无法在系统中查找到该对象变量}}，{{对象变量名：}}：" + this._cloneVar + '，请检查！');
        }

    }


    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2, 1)) {
            return false;
        } else {
            // 参数1：待卸载对象
            this._cloneVar = para_array[0];

            // if (para_array.length > 1) {
            //     // 参数2： 是否删除模板对象之前所创建的所有实例
            //     let para2: VeryParas = new VeryParas();
            //     if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
            //         return false;
            //     }
            //     this._deleteObject = para2.bool;
            // } else {
            //     this._deleteObject.value = true;
            // }

            if (para_array.length > 1) {
                // 参数3： 是否删除当前对象的所有克隆体
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[1])) {
                    return false;
                }
                this._deleteAll = para3.bool;
            } else {
                this._deleteAll.value = false;
            }

            return true;
        }
    }


    public destroy(): void {

    }

}
VE_Actions.addAction(Action_DestoryCloneObject);


export class Action_UnloadVEObject extends VE_ActionBehaviour {

    public get ID(): string {
        return '卸载对象|Unload_Object';
    };

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '卸载对象, 对象名, true';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=1167';
    }
    public get className(): string {
        return 'Action_UnloadVEObject';
    };

    private _isThis: boolean = false;
    private _name: VeryString = new VeryString();
    private _deleteObject: VeryBool = new VeryBool();

    public active(): void {
        if (this._isThis) {
            Compiler.unloadTableByName(this.objectID, this.nodeID, this._deleteObject.value);
        } else {
            if (VEObjects.isNodeNameLoaded(this._name.value, this.nodeID)) {
                Compiler.unloadTableByName(this._name.value, this.nodeID, this._deleteObject.value);
            } else {
                console.error(this.ID + " {{响应}} {{无法在系统中查找到该对象}}，{{对象ID：}}：" + this._name.value + '，请检查！');
            }
        }
    }


    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2, 1)) {
            return false;
        } else {
            // 参数1：待卸载对象
            if (para_array[0].toLowerCase() === "this") {
                this._isThis = true;
            }
            else {
                // 参数2： 待卸载对象
                let para1: VeryParas = new VeryParas();
                if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                    return false;
                }
                this._name = para1.string;
            }

            if (para_array.length > 1) {
                // 参数2： 是否删除模板对象之前所创建的所有实例
                let para2: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                    return false;
                }
                this._deleteObject = para2.bool;
            } else {
                this._deleteObject.value = true;
            }

            return true;
        }
    }


    public destroy(): void {

    }

}
VE_Actions.addAction(Action_UnloadVEObject);