import { GameGlobal } from "../global";
// import { VeryEngine } from "../veryEngine";

export class Resources {

    /**
     * 根据项目资源ID加载项目资源；
     * @param asset_id 项目资源ID；
     * @returns 若成功，返回资源string；若失败，则返回错误信息；
     */
    public static async LoadAsset(asset_id: string): Promise<string> {
        return new Promise<string>((resolve, reject) => {
            if (GameGlobal.assetsData.assets && GameGlobal.assetsData.assets[asset_id]) {
                let assetData = GameGlobal.assetsData.assets[asset_id];
                ossfile.getJsonAsset(GameGlobal.projectID, asset_id, assetData.name, assetData.file.hash).then(response => {
                    resolve(response);
                }).catch(err => {
                    reject('资源ID：' + asset_id + '，项目资源中找不到此资源，请检查ID填写是否正确！');
                });
            } else {
                reject('资源ID：' + asset_id + '，项目资源中找不到此资源，请检查ID填写是否正确！');
            }
        });
    }


    /**
     * 根据项目资源ID加载该资源url；
     * @param asset_id 项目资源ID；
     * @returns 若成功，返回资源url；若失败，则返回错误信息；
     */
    public static async GetUrl(asset_id: string): Promise<string> {
        return new Promise<string>((resolve, reject) => {
            if (GameGlobal.assetsData.assets && GameGlobal.assetsData.assets[asset_id]) {
                let assetData = GameGlobal.assetsData.assets[asset_id];
                ossfile.getUrl(GameGlobal.projectID, asset_id, assetData.name, assetData.file.hash).then(response => {
                    resolve(response);
                }).catch(err => {
                    reject('资源ID：' + asset_id + '，项目资源中找不到此资源，请检查ID填写是否正确！');
                });
            } else {
                reject('资源ID：' + asset_id + '，项目资源中找不到此资源，请检查ID填写是否正确！');
            }
        });
    }


}
