export class VeryBool implements IVeryVar {
    public get varType(): string {
        return "bool";
    }

    public get className(): string {
        return "VeryBool";
    }

    public get ID(): string {
        return 'bool|开关';
    }
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return 'bool，false';
    }

    public name: string = '';

    private _isExpression: boolean = false;
    private _expression: Nullable<VeryExpression> = null;

    public get value(): boolean {
        if (this._isExpression) {
            return this._expression!.value.evaluate();
        }
        return this._value;
    }
    public set value(val: boolean) {
        this._value = val;
    }
    private _value: boolean = false;

    constructor() {
        this._value = false;
    }

    public setValue(val: any): void {
        this._value = val;
    }

    public getValue(): any {
        if (this._isExpression) {
            return this._expression!.value.evaluate();
        }
        return this._value;
    }

    public setExpression(expression: VeryExpression): void {
        this._expression = expression;
        this._isExpression = true;
    }

    public initValue(value_str: string, error_info: ErrorInfo): any {
        value_str = value_str.trim();
        if (value_str.toLowerCase() === 'false' || value_str === '关' || value_str === '否' || value_str === '假') {
            return false;
        } else if (value_str.toLowerCase() === 'true' || value_str === '开' || value_str === '是' || value_str === '真') {
            return true;
        } else if (
            value_str === "" ||
            value_str.toLowerCase() === "null" ||
            value_str.toLowerCase() === "none"
        ) {
            return false;
        } else {
            error_info.isRight = false;
            //DO_20221228:表格编辑器,自动检测,中英文
            error_info.message =
                "{{类型}}: " +
                this.varType +
                "，{{值}}：" +
                value_str +
                "，{{该变量值和类型不匹配}}，{{转化错误}}，{{请检查}}！";
            return null;
        }
    }

    public clone(): IVeryVar {
        const varClone: VeryBool = new VeryBool();
        varClone.setValue(this._value);
        return varClone;
    }

    public getBytes(): ByteBuffer {
        const buf = ByteBuffer.Allocate(1);
        buf.WriteBoolean(this._value);
        return buf;
    }

    public setBytes(buf: ByteBuffer): void {
        this._value = buf.ReadBoolean()
    }
}

