export class VeryList implements IVeryVar {

    public get varType(): string {
        return "List";
    }

    public get className(): string {
        return "VeryList";
    }

    public get ID(): string {
        return 'list|数组';
    }
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return 'list，(number，[10])';
    }
    public name: string = '';

    private _isExpression: boolean = false;
    private _expression: Nullable<VeryExpression> = null;

    public get value(): IVeryVar[] {
        if (this._isExpression && this._expression) {
            return this._expression.value.evaluate();
        }
        return this._value;
    }
    public set value(val: IVeryVar[]) {
        this._value = val;
    }
    private _value: IVeryVar[] = [];

    constructor() {
        this._value = [];
    }

    public getValue(): any {
        if (this._isExpression && this._expression) {
            return this._expression.value.evaluate();
        }
        return this._value;
    }

    public setValue(val: any) {
        if (val == "") {
            this._value = [];
        }
        else {
            this._value = val;
        }
    }

    public setExpression(expression: VeryExpression): void {
        this._isExpression = true;
        this._expression = expression;
    }

    public clone(): IVeryVar {
        const varClone: VeryList = new VeryList();
        for (let i = 0; i < this._value.length; i++) {
            varClone.value[varClone.value.length] = this._value[i].clone();
        }
        return varClone;
    }

    //特殊处理
    public childType: string = '';
    public GetValue(i: number, blue_var: IVeryVar, clone: boolean = false) {
        if (i < 0 || i >= this._value.length) {
            console.error("从数组中获取元素的下标:" + i + ",超出范围!\n数组总共单元" + this._value.length + "个。");
            return;
        }
        if (clone) {
            blue_var.setValue(this._value[i].getValue());
        }
        else {
            blue_var.setValue(this._value[i].getValue());
            this._value[i] = blue_var;
        }
    }

    public SetValue(i: number, blue_var: IVeryVar) {
        this._value[i] = blue_var;
    }

    public Add(blue_var: IVeryVar, need_clone: boolean = true) {
        if (need_clone) {
            const tmpBlue = blue_var.clone();
            this._value[this._value.length] = tmpBlue;
        }
        else {
            this._value[this._value.length] = blue_var;
        }
    }

    public Insert(i: number, blue_var: IVeryVar, need_clone: boolean = true) {
        if (i < 0 || i >= this._value.length) {
            console.error("在数组中插入元素的下标:" + i + ",超出范围!");
            return;
        }
        if (need_clone) {
            const tmpBlue = blue_var.clone();
            const tmpLength = this._value.length;
            for (let j = tmpLength - 1; j >= i; j--) {
                this._value[j + 1] = this._value[j];
            }
            this._value[i] = tmpBlue;
        }
        else {
            const tmpLength = this._value.length;
            for (let j = tmpLength - 1; j >= i; j--) {
                this._value[j + 1] = this._value[j];
            }
            this._value[i] = blue_var;
        }
    }

    public RemoveAt(i: number) {
        if (i < 0 || i >= this._value.length) {
            console.error("在数组中删除元素的下标:" + i + ",超出范围!");
            return;
        }
        const tmpList: VeryList = <VeryList>this.clone();
        this._value = [];
        for (let j = 0; j < i; j++) {
            this._value[j] = tmpList._value[j];
        }
        for (let j = i + 1; j < tmpList._value.length; j++) {
            this._value[j - 1] = tmpList._value[j];
        }
    }

    public ValueInit(initType: Nullable<IVeryVar>, index: number[], init_value: string) {
        if (initType != null) {
            const error_info = new ErrorInfo();
            const value = initType.initValue(init_value, error_info);
            initType.setValue(value);

            if (error_info.isRight) {
                if (index.length == 1) {
                    this.childType = initType.varType;

                    const linearValue = new VeryList();
                    for (let j = 0; j < index[0]; j++) {
                        linearValue.value[j] = (initType.clone());
                    }
                    this.value = linearValue.value;
                }
                if (index.length >= 2) {
                    this.childType = "List";

                    for (let i = index.length - 1; i >= 0; i--) {
                        const linearValue = new VeryList();
                        for (let j = 0; j < index[i]; j++) {
                            linearValue.value[j] = (initType.clone());
                        }

                        if (i != 0) {
                            initType = linearValue;
                        }
                        else {
                            this.value = linearValue.value;
                        }
                    }
                }
            }
        }
    }

    //TODO_20210125:List多种方式定义
    private strSplit: string[] = [];
    private _t = null;
    public initValue(value_str: string, error_info: ErrorInfo): any {
        this.strSplit = VE_StringFormat.strSubsection(value_str);
        if (this.strSplit.length < 1) {
            error_info.isRight = false;
            //DO_20221228:表格编辑器,自动检测,中英文
            error_info.message = (value_str + ",{{不存在参数}}!");
            return null;
        }
        this._t = VEVarManager.getVarType(this.strSplit[0]);
        if (this._t == null) {
            error_info.isRight = false;
            //DO_20221228:表格编辑器,自动检测,中英文
            error_info.message = (value_str + ",{{该Type类型不存在}}!");
            return null;
        }
        //DO_20211231:数组初始化的时候，子变量使用中文名类型
        this.childType = this._t.prototype.varType;
        //this.childType = this.strSplit[0];
        return [];
    }

    public SetChildValue(object_id: string, error_info: ErrorInfo, host_node_id: string): void {
        if (this.strSplit.length > 1) {
            if (this.strSplit[1].startsWith("[") || this.strSplit[1].startsWith("【")) {
                const endIndex = this.strSplit.length - 1;
                if (this.strSplit[endIndex].endsWith("]") || this.strSplit[endIndex].endsWith("】")) {
                    this.strSplit[1] = this.strSplit[1].substring(1);
                    this.strSplit[endIndex] = this.strSplit[endIndex].substring(0, this.strSplit[endIndex].length - 1);
                    let veryVar: (Nullable<IVeryVar>) = VEVarManager.createVariable('', this.childType, "", error_info);
                    if (veryVar != null) {
                        const value = veryVar.initValue("", error_info);
                        if (error_info.isRight && veryVar != null) {
                            veryVar.setValue(value);
                            for (let i = this.strSplit.length - 1; i > 0; i--) {
                                let linear = 0;
                                linear = VE_TypeConvert.intConvert(this.strSplit[i], error_info);
                                if (error_info.isRight) {
                                    const linearValue = [];
                                    for (let j = 0; j < linear; j++) {
                                        linearValue[linearValue.length] = veryVar.clone();
                                    }
                                    if (i != 1) {
                                        veryVar = new VeryList();
                                        veryVar.setValue(linearValue);
                                    }
                                    else {
                                        this._value = linearValue;
                                    }
                                }
                                else {
                                    //DO_20221228:表格编辑器,自动检测,中英文
                                    error_info.message += this.strSplit[i] + ",{{该内容代表数组某个维度的个数}}，{{其值必须为int类型}}!";
                                    error_info.isRight = false;
                                    break;
                                }
                            }
                        }
                        if (this.strSplit.length > 2) {
                            this.childType = "List";
                        }
                    }
                    this.strSplit = [];
                    return;
                }
            }
        }
        for (let i = 1; i < this.strSplit.length; i++) {
            if (this.strSplit[i].indexOf("*") != -1 && this.strSplit[i].indexOf(",") == -1 && this.strSplit[i].indexOf("，") == -1) {
                const veryVar2 = VarTools.GetVeryVar(object_id, this.strSplit[i], error_info, host_node_id);
                if (veryVar2 !== null) {
                    const id = veryVar2.ID.toLowerCase();  // 类型名可能有多个
                    if (id.indexOf(this.childType.toLowerCase()) >= 0) {
                        this._value[this.value.length] = (veryVar2);
                    }
                    else {
                        //DO_20221228:表格编辑器,自动检测,中英文
                        error_info.message += (this.strSplit[i] + "，{{该Type为}}" + veryVar2.varType + "，{{不符合要求}}，{{应该是}}" + this.childType + "{{类型}}!");
                        error_info.isRight = false;
                    }
                }
            }
            else {
                const veryVar3: (Nullable<IVeryVar>) = VEVarManager.createVariable("", this.childType, this.strSplit[i], error_info);
                if (error_info.isRight) {
                    if (this.childType === this.varType) {
                        (<VeryList>veryVar3).SetChildValue(object_id, error_info, host_node_id);
                    }
                    //TODO_20210125:Dictionary处理
                    //else if (_t == VeryDictionary._varType) {
                    //((VeryDictionary)veryVar).SetChildValue(object_id, error_info);
                    //}
                    this._value[this.value.length] = (veryVar3);
                }
            }
        }
        this.strSplit = [];
    }

    public Clear() {
        this._value = [];
    }

    public getBytes(): ByteBuffer {
        const buf = ByteBuffer.Allocate(400);
        for (let i = 0; i < this._value.length; i++) {
            buf.Write(this._value[i].getBytes());
        }
        return buf;
    }

    public setBytes(buf: ByteBuffer): void {
        let i = 0;
        const count = this._value.length;
        while (buf.ReadableBytes() > 0) {
            const length = buf.ReadInt();
            const childBuf = buf.ReadRetainedSlice(length);
            if (i < count) {
                this._value[i].setBytes(childBuf);
            }
            else {
                const error_info = new ErrorInfo();
                const tmpBlue = VEVarManager.createVariable('', this.childType, "", error_info);
                tmpBlue.setBytes(childBuf);
                this._value.push(tmpBlue);
            }
            i++;
        }
        for (; i < count; i++) {
            this._value.pop();
        }
    }
}


//DO_20220408:UI变量
export class VeryUI implements IVeryVar {
    public get varType(): string {
        return "UI";
    }

    public get className(): string {
        return "VeryUI";
    }

    public get ID(): string {
        return 'ui';
    }
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return 'ui，2D画布.容器.按钮';
    }
    public name: string = '';

    public get value(): Nullable<VREdit.GUI> {
        return this._value;
    }
    public set value(val: Nullable<VREdit.GUI>) {
        this._value = val;
    }
    private _value: Nullable<VREdit.GUI> = null;

    constructor() {

    }

    public setValue(val: any) {
        this._value = val;
    }
    public getValue(): any {
        return this._value;
    }

    public initValue(value_str: string, error_info: ErrorInfo): any {

        if (value_str === '' || value_str.toLowerCase() === 'null' || value_str.toLowerCase() === 'none') {
            return null;
        } else {
            const rValue = this.GetUI(BabylonEngine.Scene, value_str);

            //DO_20221228:表格编辑器,自动检测
            if (rValue === null && !VeryEngine.enableLuckySheet) {
                error_info.isRight = false;
                //DO_20221228:表格编辑器,自动检测,中英文
                error_info.message =
                    "{{类型}}: " +
                    this.varType +
                    "，{{值}}：" +
                    value_str +
                    "，{{在场景中找不到指定对象}}，{{请检查}}！";
            }
            return rValue;
        }
    }

    public GetUI(scene: BABYLON.Scene, buttonName: string): BABYLON.Nullable<VREdit.GUI> {
        return ParaParserUtility.GetUI(scene, buttonName, '');
    }

    public clone(): IVeryVar {
        const varClone: VeryUI = new VeryUI();
        varClone.setValue(this._value);
        return varClone;
    }

    public getBytes(): ByteBuffer {
        const fullName = this.getUIFullName(this.value);
        const buf = ByteBuffer.Allocate(500);
        buf.WriteString(fullName);
        return buf;

    }
    private getUIFullName(control: BABYLON.Nullable<VREdit.IEDEntity>, name?: string) {
        if (control != null) {
            if (control.parent == null) {
                return control.name + "." + name;
            } else {
                if (name) {
                    name = control.name + "." + name;
                } else {
                    name = control.name;
                }
                return this.getUIFullName(control.parent, name)
            }
        } else {
            return control.name + "." + name;
        }
    }

    public setBytes(buf: ByteBuffer): void {
        const fullName = buf.ReadString();
        this._value = this.GetUI(BabylonEngine.Scene, fullName);
    }
}

