import { VE_ActionBehaviour, VE_Actions } from '../../action';
import { VeryGameObject, VeryBool, VeryVector3, VeryNumber, VeryString } from '../../variables';
import { ParaParserUtility, VeryParas } from '../../utility';
import { ParaType, Severity } from '../../enum';
import { VE_ErrorManager, VE_Error, GameGlobal } from '../../global';
import { BabylonEngine, Time } from "../../babylon";

export class Action_ScreenShot extends VE_ActionBehaviour {

    public get ID(): string {
        return "ScreenShot|截屏";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '截屏，第一张，0，0，200，200';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=948';
    }
    public get className(): string {
        return "Action_ScreenShot";
    }

    //js加载
    public static _jsLoaded: boolean = false;
    //存储信息
    public static _screenShotData = {};
    public static _screenShotWidth = {};
    public static _screenShotHeight = {};
    //DO_20220622:截屏输出到实验报告
    public static _screenShotPage = {}
    public static _screenShotPosX = {};
    public static _screenShotPosY = {};

    //pdf名字
    private _picName: VeryString = new VeryString();
    //截图位置和大小
    private _posX: VeryNumber = new VeryNumber();
    private _posY: VeryNumber = new VeryNumber();
    private _sizeX: VeryNumber = new VeryNumber();
    private _sizeY: VeryNumber = new VeryNumber();

    public active(): void {
        //TODO_20210923:截屏,位置大小    
        let picName = this._picName.value;
        let sizeX = this._sizeX.value;
        let sizeY = this._sizeY.value;
        let posX = this._posX.value;
        let posY = this._posY.value;

        var htmlDom = document.getElementById('renderCanvas');
        //调用html2canvas插件
        html2canvas(htmlDom, {
            logging: false, //日志开关，便于查看html2canvas的内部执行流程
            width: htmlDom.clientWidth, //dom 原始宽度
            height: htmlDom.clientHeight,
            scrollY: 0,
            scrollX: 0,
            useCORS: true // 【重要】开启跨域配置
        }).then(function (newCanvas) {
            var image = Canvas2Image.convertToImage(newCanvas, BabylonEngine.Canvas.width, BabylonEngine.Canvas.height, undefined);
            image.onload = function () {
                var retCanvas = document.createElement('canvas');
                var retCtx = retCanvas.getContext('2d');
                if (sizeX === 0 && sizeY === 0) {
                    retCanvas.width = BabylonEngine.Canvas.width;
                    retCanvas.height = BabylonEngine.Canvas.height;
                    retCanvas.style.background = "#ffffff";
                    retCtx.drawImage(image, 0, 0, retCanvas.width, retCanvas.height, 0, 0, retCanvas.width, retCanvas.height);

                    //记录图片
                    Action_ScreenShot._screenShotData[picName] = retCanvas.toDataURL("png", 1.0)
                    //console.log(Action_ScreenShot._screenShotData[picName]);
                    Action_ScreenShot._screenShotWidth[picName] = retCanvas.width;
                    Action_ScreenShot._screenShotHeight[picName] = retCanvas.height;
                }
                else {
                    retCanvas.width = sizeX;
                    retCanvas.height = sizeY;
                    retCanvas.style.background = "#ffffff";
                    retCtx.drawImage(image, posX + (BabylonEngine.Canvas.width - sizeX) / 2, posY + (BabylonEngine.Canvas.height - sizeY) / 2, sizeX, sizeY, 0, 0, sizeX, sizeY);

                    //记录图片
                    Action_ScreenShot._screenShotData[picName] = retCanvas.toDataURL("png", 1.0);;
                    //console.log(Action_ScreenShot._screenShotData[picName]);
                    Action_ScreenShot._screenShotWidth[picName] = sizeX;
                    Action_ScreenShot._screenShotHeight[picName] = sizeY;
                }
            };
        });
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        //DO_20221110:截屏导出到PDF,新增页数和PDF中位置
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 5, 8)) {
            return false;
        } else {
            //图片名
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0], false)) {
                return false;
            }
            this._picName = para1.string;

            //截图位置X
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para2, para_array[1], false)) {
                return false;
            }
            this._posX = para2.number;

            //截图位置Y
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para3, para_array[2], false)) {
                return false;
            }
            this._posY = para3.number;

            //截图大小宽度
            let para4: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para4, para_array[3], false)) {
                return false;
            }
            this._sizeX = para4.number;

            //截图大小高度
            let para5: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para5, para_array[4], false)) {
                return false;
            }
            this._sizeY = para5.number;

            //DO_20221110:截屏导出到PDF,新增页数和PDF中位置
            Action_ScreenShot._screenShotPage[this._picName.value] = 0;
            if (para_array.length > 5) {
                Action_ScreenShot._screenShotPage[this._picName.value] = Number(para_array[5]);
            }
            Action_ScreenShot._screenShotPosX[this._picName.value] = 5;
            if (para_array.length > 6) {
                Action_ScreenShot._screenShotPosX[this._picName.value] = Number(para_array[6]);
            }
            Action_ScreenShot._screenShotPosY[this._picName.value] = 5;
            if (para_array.length > 7) {
                Action_ScreenShot._screenShotPosY[this._picName.value] = Number(para_array[7]);
            }

            return true;
        }
    }
    public destroy(): void {

    }
}

export class Action_ScreenShotToPDF extends VE_ActionBehaviour {

    public get ID(): string {
        return "ScreenShotToPDF|截屏导出到PDF";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '截屏导出到PDF，成绩单';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=949';
    }
    public get className(): string {
        return "Action_ScreenShotToPDF";
    }

    //pdf名字
    private _pdfName: VeryString = new VeryString();

    public active(): void {
        //下载pdf
        var pdf = new jspdf.jsPDF(undefined, 'pt', 'a0')// 三个参数，第一个方向，第二个单位，第三个尺寸格式
        //DO_20221110:截屏导出到PDF,新增页数和PDF中位置
        //自动增加页数
        var autoPage = false;
        //最大页数
        var maxPage = 1;
        for (var key in Action_ScreenShot._screenShotData) {
            if (Action_ScreenShot._screenShotPage[key] === 0) {
                autoPage = true;
                break;
            }
            if (Action_ScreenShot._screenShotPage[key] > maxPage) {
                maxPage = Action_ScreenShot._screenShotPage[key];
            }
        }
        //console.log(autoPage + '--' + maxPage);
        //自动增加页数
        if (autoPage) {
            var i = 0;
            for (var key in Action_ScreenShot._screenShotData) {
                if (i !== 0)
                    pdf.addPage();
                pdf.addImage(Action_ScreenShot._screenShotData[key], 'PNG', 5, 5, Action_ScreenShot._screenShotWidth[key], Action_ScreenShot._screenShotHeight[key])
                i++;
            }
        }
        //最大页数
        else {
            for (var i = 0; i < (maxPage - 1); i++) {
                pdf.addPage();
            }
            for (var key in Action_ScreenShot._screenShotData) {
                pdf.setPage(Action_ScreenShot._screenShotPage[key]);
                pdf.addImage(Action_ScreenShot._screenShotData[key], 'PNG', Action_ScreenShot._screenShotPosX[key], Action_ScreenShot._screenShotPosY[key], Action_ScreenShot._screenShotWidth[key], Action_ScreenShot._screenShotHeight[key])
            }
        }
        pdf.save(this._pdfName.value + '.pdf');
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 1)) {
            return false;
        } else {
            //pdf名字
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0], false)) {
                return false;
            }
            this._pdfName = para1.string;

            //判断js是否加载
            if (!Action_ScreenShot._jsLoaded) {
                let head = document.getElementsByTagName('head').item(0);
                ossfile.getStandardUI(GameGlobal.projectID, 'js/jspdf.umd.min.js').then(response => {
                    console.log(response);
                    var myscript = document.createElement('script');
                    myscript.src = response;
                    myscript.type = 'text/javascript';
                    head.appendChild(myscript);
                });
                ossfile.getStandardUI(GameGlobal.projectID, 'js/html2canvas.min.js').then(response => {
                    console.log(response);
                    var myscript = document.createElement('script');
                    myscript.src = response;
                    myscript.type = 'text/javascript';
                    head.appendChild(myscript);
                });
                ossfile.getStandardUI(GameGlobal.projectID, 'js/canvas2image.js').then(response => {
                    console.log(response);
                    var myscript = document.createElement('script');
                    myscript.src = response;
                    myscript.type = 'text/javascript';
                    head.appendChild(myscript);
                });
                Action_ScreenShot._jsLoaded = true;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}
