import { VE_TriggerBehaviour, VE_Triggers } from "../../trigger";
import { ParaParserUtility, VE_KeyboardMap, VeryParas } from '../../utility';
import { ParaType, Severity } from '../../enum';
import { VE_ErrorManager, VE_Error } from '../../global';
// import { GameObject } from "../../babylon/babylonVariables";
// import { VeryGameObject, VeryBool, VeryNumber, VeryString } from "../../variables";

import { Action_XR_Enable } from "../action";

export class Trigger_VR_Button extends VE_TriggerBehaviour {

    public get ID(): string {
        return 'VR_Button|VR手柄按钮';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return 'VR手柄按钮，trigger,VR手柄按钮，squeeze,VR手柄按钮，a,VR手柄按钮，b,VR手柄按钮，x,VR手柄按钮，y,VR手柄按钮，前,VR手柄按钮，后,VR手柄按钮，左,VR手柄按钮，右';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=893';
    }
    public get className(): string {
        return 'Trigger_VR_Button';
    }

    //手柄按钮名
    private _buttonName: string = '';
    //手柄摇杆方向
    private _axesName: string = '前';

    //触发初始化
    private _initialed: boolean = false;

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 1, 2)) {
            return false;
        } else {
            //参数1
            if (para_array[0].toLowerCase() == "trigger" || para_array[0].toLowerCase() == "squeeze" || para_array[0].toLowerCase() == "thumbstick" || para_array[0].toLowerCase() == "a" || para_array[0].toLowerCase() == "b" || para_array[0].toLowerCase() == "x" || para_array[0].toLowerCase() == "y") {
                this._buttonName = para_array[0].toLowerCase();
            }
            else {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{触发}} {{传入参数格式错误}}：" + para_array[0] + "，{{参数应为trigger或者squeeze或者thumbstick或者a或者b或者x或者y}}，{{此处填写错误}}，{{请检查}}！", '', Severity.Error));
                return false;
            }

            //DO_20220830:触发响应中参数支持中英文
            //参数2
            if (para_array.length > 1) {
                if (para_array[1] === '前' || para_array[1].toLowerCase() == 'forward') {
                    this._axesName = '前';
                }
                else if (para_array[1] === '后' || para_array[1].toLowerCase() == 'back') {
                    this._axesName = "后";
                }
                else if (para_array[1] === '左' || para_array[1].toLowerCase() == 'left') {
                    this._axesName = '左';
                }
                else if (para_array[1] === '右' || para_array[1].toLowerCase() == 'right') {
                    this._axesName = '右';
                }
                else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{触发}} {{传入参数格式错误}}：" + para_array[1] + "{{参数应为}}前|forward、后|back、左|left、右|right，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }


            return true;
        }

    }

    public onUpdate(): void {
        if (Action_XR_Enable._xrHelper) {
            if (!this._initialed) {
                console.warn('VR手柄按钮 初始化--' + (Action_XR_Enable._xrHelper !== null));
                var XRHelper = Action_XR_Enable._xrHelper;

                XRHelper.input.onControllerAddedObservable.add((controller) => {
                    controller.onMotionControllerInitObservable.add((motionController) => {
                        if (motionController.handness === 'left') {
                            const xr_ids = motionController.getComponentIds();
                            let triggerComponent = motionController.getComponent(xr_ids[0]);//xr-standard-trigger
                            triggerComponent.onButtonStateChangedObservable.add(() => {
                                //console.log('left xr-standard-trigger');
                                if (triggerComponent.pressed) {
                                    if (this._buttonName === 'trigger') {
                                        this.sendEvent();
                                    }
                                } else {

                                }
                            });
                            let squeezeComponent = motionController.getComponent(xr_ids[1]);//xr-standard-squeeze
                            squeezeComponent.onButtonStateChangedObservable.add(() => {
                                //console.log('left xr-standard-squeeze');
                                if (squeezeComponent.pressed) {
                                    if (this._buttonName === 'squeeze') {
                                        this.sendEvent();
                                    }
                                } else {
                                }
                            });
                            let thumbstickComponent = motionController.getComponent(xr_ids[2]);//xr-standard-thumbstick
                            thumbstickComponent.onButtonStateChangedObservable.add(() => {
                                //console.log('left xr-standard-thumbstick');
                            });
                            thumbstickComponent.onAxisValueChangedObservable.add((axes) => {
                                //console.log('right xr-standard-thumbstick--' + axes.x + '--' + axes.y);
                                if (this._buttonName === 'thumbstick') {
                                    if (axes.y < 0 && this._axesName === '前') {
                                        this.sendEvent();
                                    }
                                    if (axes.y > 0 && this._axesName === '后') {
                                        this.sendEvent();
                                    }
                                    if (axes.x < 0 && this._axesName === '左') {
                                        this.sendEvent();
                                    }
                                    if (axes.x > 0 && this._axesName === '右') {
                                        this.sendEvent();
                                    }
                                }
                            });
                            let xbuttonComponent = motionController.getComponent(xr_ids[3]);//x-button
                            //DO_20220606:VR修改,匹配旧版本HTC硬件
                            if (xbuttonComponent !== undefined) {
                                xbuttonComponent.onButtonStateChangedObservable.add(() => {
                                    //console.log('left x-button');
                                    if (xbuttonComponent.pressed) {
                                        if (this._buttonName === 'x') {
                                            this.sendEvent();
                                        }
                                    } else {
                                    }
                                });
                            }

                            let ybuttonComponent = motionController.getComponent(xr_ids[4]);//y-button
                            //DO_20220606:VR修改,匹配旧版本HTC硬件
                            if (ybuttonComponent !== undefined) {
                                ybuttonComponent.onButtonStateChangedObservable.add(() => {
                                    //console.log('left y-button');
                                    if (ybuttonComponent.pressed) {
                                        if (this._buttonName === 'y') {
                                            this.sendEvent();
                                        }
                                    } else {
                                    }
                                });
                            }
                        }
                        if (motionController.handness === 'right') {
                            const xr_ids = motionController.getComponentIds();
                            let triggerComponent = motionController.getComponent(xr_ids[0]);//xr-standard-trigger
                            triggerComponent.onButtonStateChangedObservable.add(() => {
                                //console.log('right xr-standard-trigger');
                                if (triggerComponent.pressed) {
                                    if (this._buttonName === 'trigger') {
                                        this.sendEvent();
                                    }
                                } else {
                                }
                            });
                            let squeezeComponent = motionController.getComponent(xr_ids[1]);//xr-standard-squeeze
                            squeezeComponent.onButtonStateChangedObservable.add(() => {
                                //console.log('right xr-standard-squeeze');
                                if (squeezeComponent.pressed) {
                                    if (this._buttonName === 'squeeze') {
                                        this.sendEvent();
                                    }
                                } else {
                                }
                            });
                            let thumbstickComponent = motionController.getComponent(xr_ids[2]);//xr-standard-thumbstick
                            thumbstickComponent.onButtonStateChangedObservable.add(() => {
                                //console.log('right xr-standard-thumbstick');
                            });
                            thumbstickComponent.onAxisValueChangedObservable.add((axes) => {
                                //console.log('right xr-standard-thumbstick--' + axes.x + '--' + axes.y);
                                if (this._buttonName === 'thumbstick') {
                                    if (axes.y < 0 && this._axesName === '前') {
                                        this.sendEvent();
                                    }
                                    if (axes.y > 0 && this._axesName === '后') {
                                        this.sendEvent();
                                    }
                                    if (axes.x < 0 && this._axesName === '左') {
                                        this.sendEvent();
                                    }
                                    if (axes.x > 0 && this._axesName === '右') {
                                        this.sendEvent();
                                    }
                                }
                            });

                            let abuttonComponent = motionController.getComponent(xr_ids[3]);//a-button
                            //DO_20220606:VR修改,匹配旧版本HTC硬件
                            if (abuttonComponent !== undefined) {
                                abuttonComponent.onButtonStateChangedObservable.add(() => {
                                    //console.log('right a-button');
                                    if (abuttonComponent.pressed) {
                                        if (this._buttonName === 'a') {
                                            this.sendEvent();
                                        }
                                    } else {
                                    }
                                });
                            }
                            let bbuttonComponent = motionController.getComponent(xr_ids[4]);//b-button
                            //DO_20220606:VR修改,匹配旧版本HTC硬件
                            if (bbuttonComponent !== undefined) {
                                bbuttonComponent.onButtonStateChangedObservable.add(() => {
                                    //console.log('right b-button');
                                    if (bbuttonComponent.pressed) {
                                        if (this._buttonName === 'b') {
                                            this.sendEvent();
                                        }
                                    } else {
                                    }
                                });
                            }

                        }

                    })

                });

                this._initialed = true;
            }
        }
    }

    public destroy(): void {

    }

}

//DO_20211220:VR
VE_Triggers.addTrigger(Trigger_VR_Button);