export class Action_Get_List_Value extends VE_ActionBehaviour {

    public get ID(): string {
        return "Get_List_Value|获取数组单元";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '获取数组单元，*list1，0，*acceptValue，false';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=754';
    }
    public get className(): string {
        return "Action_Get_List_Value";
    }

    public get type(): ActionType {
        return ActionType.Animation;
    }

    //数组
    private _blueList: VeryList = new VeryList();
    //索引
    private _blueNumber: VeryNumber = new VeryNumber();
    //元素
    private _blueValue: Nullable<IVeryVar> = null;
    //是否独立于数组
    private _blueBool: VeryBool = new VeryBool();

    public active(): void {
        if (this._blueValue != null) {
            this._blueList.GetValue(this._blueNumber.value, this._blueValue, this._blueBool.value);
        }
    }
    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3, 4)) {
            return false;
        } else {
            // 参数1：数组
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.ListPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._blueList = para1.list;

            // 参数2：元素索引
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._blueNumber = para2.number;

            //参数3:获取元素
            if (VarTools.IsVarID(para_array[2])) {
                let errorInfo: ErrorInfo = new ErrorInfo();
                this._blueValue = VarTools.GetVeryVar(this.objectID, para_array[2], errorInfo, this.nodeID);
                if (this._blueValue == null) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[2] + "，{{无法查找到该变量}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
                else if (this._blueValue.varType != this._blueList.childType) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[2] + "，{{该变量类型不吻合}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }
            else {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[2] + "，{{应为Very变量}}，{{不能为常量}}，{{请检查}}！", '', Severity.Error));
                return false;
            }

            //第四个参数:是否独立于数组
            //TODO_20210610:BUG修改
            this._blueBool.value = true;
            if (para_array.length > 3) {
                let para4: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolPara(this.objectID, this.ID, ParaType.Action, para4, para_array[3])) {
                    return false;
                }
                this._blueBool = para4.bool;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}

export class Action_List_Add extends VE_ActionBehaviour {

    public get ID(): string {
        return "List_Add|数组添加单元";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '数组添加单元，*list，*添加值，0，false';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=755';
    }
    public get className(): string {
        return "Action_List_Add";
    }

    public get type(): ActionType {
        return ActionType.Animation;
    }

    // 参数1：数组
    private _blueList: VeryList = new VeryList();
    //参数2：添加的元素
    private _blueValue: Nullable<IVeryVar> = null;
    //第3个参数：何处添加元素，默认在尾部
    private _blueNumber: VeryNumber = new VeryNumber();
    //是否独立于数组
    private _blueBool: VeryBool = new VeryBool();

    public active(): void {
        if (this._blueValue != null) {
            if (this._blueNumber.value < 0) {
                this._blueList.Add(this._blueValue, this._blueBool.value);
            }
            else {
                this._blueList.Insert(this._blueNumber.value, this._blueValue, this._blueBool.value);
            }
        }
    }
    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2, 3, 4)) {
            return false;
        } else {
            // 参数1：数组
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.ListPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._blueList = para1.list;

            //参数2：添加的元素
            if (VarTools.IsVarID(para_array[1])) {
                let errorInfo: ErrorInfo = new ErrorInfo();
                this._blueValue = VarTools.GetVeryVar(this.objectID, para_array[1], errorInfo, this.nodeID);
                if (this._blueValue == null) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[1] + "，{{无法查找到该变量}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
                else if (this._blueValue.varType != this._blueList.childType) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[1] + "，{{该变量类型不吻合}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }
            else {
                //TODO:常量根据list子类型新建新变量
                let errorInfo: ErrorInfo = new ErrorInfo();
                this._blueValue = VEVarManager.createVariable(this._blueList.name + "_tmp_" + Math.random(), this._blueList.childType, para_array[1], errorInfo);
                if (!errorInfo.isRight) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[1] + "，{{该变量创建失败失败信息}}：" + errorInfo.message, '', Severity.Error));
                    return false;
                }
            }

            //第3个参数：何处添加元素，默认在尾部
            this._blueNumber.value = -1;
            if (para_array.length > 2) {
                let para2: VeryParas = new VeryParas();
                //TODO_20210610:BUG修改
                if (!ParaParserUtility.NumberParaOnlyVar(this.objectID, this.ID, ParaType.Action, para2, para_array[2])) {
                    return false;
                }
                this._blueNumber = para2.number;
            }

            //第四个参数:是否独立于数组
            //TODO_20210610:BUG修改
            this._blueBool.value = true;
            if (para_array.length > 3) {
                let para4: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolPara(this.objectID, this.ID, ParaType.Action, para4, para_array[3])) {
                    return false;
                }
                this._blueBool = para4.bool;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}
export class Action_List_AddRange extends VE_ActionBehaviour {

    public get ID(): string {
        return "List_AddRange|数组叠加";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '数组叠加，*listA，*listB，*listC';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=756';
    }
    public get className(): string {
        return "Action_List_AddRange";
    }

    public get type(): ActionType {
        return ActionType.Animation;
    }

    // 参数1：数组
    private _blueList: VeryList = new VeryList();
    // 参数2：数组2
    private _blueList2: VeryList = new VeryList();
    // 参数3：数组3
    private _acceptList: VeryList = new VeryList();
    //参数4：插入索引
    private _blueNumber: VeryNumber = new VeryNumber();

    public active(): void {
        this._acceptList.setValue(this._blueList.value);
        if (this._blueNumber.value < 0) {
            for (var i = 0; i < this._blueList2.value.length; i++) {
                this._acceptList.Add(this._blueList2.value[i]);
            }
        }
        else {
            if (this._blueNumber.value < 0 || this._blueNumber.value >= this._blueList.value.length) {
                console.error("数组叠加中插入元素的下标:" + this._blueNumber.value + ",超出范围!");
                return;
            }
            let tmpLength = this._blueList.value.length;
            let tmpLength2 = this._blueList2.value.length;
            for (var j = 0; j < tmpLength2; j++) {
                this._acceptList.value[j + this._blueNumber.value] = this._blueList2.value[j];
            }
            for (var j = this._blueNumber.value; j < tmpLength; j++) {
                this._acceptList.value[j + tmpLength2] = this._blueList.value[j];
            }
        }
    }
    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3, 4)) {
            return false;
        } else {
            // 参数1：数组
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.ListPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._blueList = para1.list;

            // 参数2：数组2
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.ListPara(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._blueList2 = para2.list;

            // 参数3：数组3
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.ListPara(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                return false;
            }
            this._acceptList = para3.list;

            // 参数4：索引
            this._blueNumber.value = -1;
            if (para_array.length > 3) {
                let para4: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para4, para_array[3])) {
                    return false;
                }
                this._blueNumber = para4.number;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}
