export class Action_String_Split_To_List extends VE_ActionBehaviour {

    public get ID(): string {
        return "String_Split_To_List|字符串分割为数组";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '字符串分割为数组，a+b+c+d，+，*accpetList';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=761';
    }
    public get className(): string {
        return "Action_String_Split_To_List";
    }

    public get type(): ActionType {
        return ActionType.Animation;
    }

    // 参数1：字符串
    private _blueString: VeryString = new VeryString();
    // 参数2：字符
    private _splitChar: string = "";
    // 参数3：数组
    private _blueList: VeryList = new VeryList();

    public active(): void {
        var tmpSplte = this._blueString.value.split(this._splitChar);
        this._blueList.Clear();
        for (var i = 0; i < tmpSplte.length; i++) {
            var tmpString = new VeryString();
            tmpString.value = tmpSplte[i];
            this._blueList.Add(tmpString);
        }
    }
    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3)) {
            return false;
        } else {
            // 参数1：字符串
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._blueString = para1.string;

            //参数2：字符
            if (para_array[1] == "空格")
                para_array[1] = " ";
            else if (para_array[1] == "逗号")
                para_array[1] = ",";
            if (para_array[1].length != 1) {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[1] + "，{{字符串长度不为1}}，{{请检查}}！", '', Severity.Error));
                return false;
            }
            this._splitChar = para_array[1][0];

            // 参数3：数组
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.ListPara(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                return false;
            }
            this._blueList = para3.list;

            return true;
        }
    }
    public destroy(): void {

    }
}

export class Action_List_Contains extends VE_ActionBehaviour {

    public get ID(): string {
        return "List_Contains|数组包含单元";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '数组包含单元，*list，10，*result';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=763';
    }
    public get className(): string {
        return "Action_List_Contains";
    }

    public get type(): ActionType {
        return ActionType.Animation;
    }

    // 参数1：数组
    private _blueList: VeryList = new VeryList();
    //参数2：元素
    private _blueValue: Nullable<IVeryVar> = null;
    //参数3：是否包含
    private _blueBool: VeryBool = new VeryBool();

    public active(): void {
        if (this._blueValue != null) {
            this._blueBool.value = false;
            for (var i = 0; i < this._blueList.value.length; i++) {
                //DO_20230613:数组单元值比较修改
                if (this._blueList.value[i].getValue() === (this._blueValue.getValue())) {
                    //if (this._blueList.value[i].getValue().Equals(this._blueValue.getValue())) {
                    this._blueBool.value = true;
                    break;
                }
            }
        }
    }
    public onUpdate(): void {
        if (this._blueValue != null) {
            this._blueBool.value = false;
            for (var i = 0; i < this._blueList.value.length; i++) {
                //DO_20230613:数组单元值比较修改
                if (this._blueList.value[i].getValue() === (this._blueValue.getValue())) {
                    //if (this._blueList.value[i].getValue().Equals(this._blueValue.getValue())) {
                    this._blueBool.value = true;
                    break;
                }
            }
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3)) {
            return false;
        } else {
            // 参数1：数组
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.ListPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._blueList = para1.list;

            //参数2：添加的元素
            if (VarTools.IsVarID(para_array[1])) {
                let errorInfo: ErrorInfo = new ErrorInfo();
                this._blueValue = VarTools.GetVeryVar(this.objectID, para_array[1], errorInfo, this.nodeID);
                if (this._blueValue == null) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[1] + "，{{无法查找到该变量}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
                else if (this._blueValue.varType != this._blueList.childType) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[1] + "，{{该变量类型不吻合}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }
            else {
                //TODO:常量根据list子类型新建新变量
                let errorInfo: ErrorInfo = new ErrorInfo();
                this._blueValue = VEVarManager.createVariable(this._blueList.name + "_tmp_" + Math.random(), this._blueList.childType, para_array[1], errorInfo);
                if (!errorInfo.isRight) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[1] + "，{{该变量创建失败}}，{{失败信息}}：" + errorInfo.message, '', Severity.Error));
                    return false;
                }
            }

            //第3个参数:是否包含
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaOnlyVar(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                return false;
            }
            this._blueBool = para3.bool;

            return true;
        }
    }
    public destroy(): void {

    }
}
