export class Action_List_Random extends VE_ActionBehaviour {

    public get ID(): string {
        return "List_Random|数组随机排序";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '数组随机排序，*list，5';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=764';
    }
    public get className(): string {
        return "Action_List_Random";
    }

    public get type(): ActionType {
        return ActionType.Animation;
    }

    // 参数1：数组
    private _blueList: VeryList = new VeryList();
    //参数2：个数
    private _blueNumber: VeryNumber = new VeryNumber();
    //参数3：接收数组
    private _blueValue: VeryList = new VeryList();
    private _tag: boolean = false;

    public active(): void {
        if (this._tag) {
            this._blueValue.Clear();
            for (var i = 0; i < this._blueList.value.length; i++) {
                this._blueValue.Add(this._blueList.value[i]);
            }
        }
        else {
            this._blueValue = this._blueList;
        }
        var count = Math.min(this._blueNumber.value, this._blueList.value.length);
        for (var i = 0; i < count; i++) {
            var random = Math.floor(Math.random() * (this._blueValue.value.length - i) + i);
            var veryVar = this._blueValue.value[random];
            this._blueValue.value[random] = this._blueValue.value[i];
            this._blueValue.value[i] = veryVar;
        }
        var sub = this._blueValue.value.length - count;
        for (var i = 0; i < sub; i++) {
            this._blueValue.RemoveAt(count);
        }
    }
    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2, 3)) {
            return false;
        } else {
            // 参数1：数组
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.ListPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._blueList = para1.list;

            //第2个参数:个数
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._blueNumber = para2.number;

            //参数3：数组2
            if (para_array.length > 2) {
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.ListPara(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                    return false;
                }
                this._blueValue = para3.list;

                this._tag = true;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}

export class Action_List_Init extends VE_ActionBehaviour {

    public get ID(): string {
        return "List_Init|数组初始化";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '数组初始化，*list，number，(10，20，30)';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=762';
    }
    public get className(): string {
        return "Action_List_Init";
    }

    public get type(): ActionType {
        return ActionType.Animation;
    }

    // 参数1：数组
    private _blueList: VeryList = new VeryList();
    //参数2：类型
    private _rootUnitType: Nullable<IVeryVar> = null;
    //参数3：维度
    private _dimensional: VeryNumber[] = [];
    //参数4：默认初始值
    private _intValue: VeryString = new VeryString();

    public active(): void {
        var tmpListInt: number[] = [];
        for (var i = 0; i < this._dimensional.values.length; i++) {
            tmpListInt[i] = (this._dimensional[i].value);
        }
        this._blueList.ValueInit(this._rootUnitType, tmpListInt, this._intValue.value);
    }
    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3, 4)) {
            return false;
        } else {
            // 参数1：数组
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.ListPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._blueList = para1.list;

            //参数2：类型
            this._rootUnitType = VEVarManager.getVarType(para_array[1]);

            //参数3：维度
            var strSplit = para_array[2].split(/,|，/);
            for (var i = 0; i < strSplit.length; i++) {
                var veryInt = new VeryNumber();
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para3, strSplit[i])) {
                    return false;
                }
                veryInt = para3.number;
                this._dimensional[this._dimensional.length] = veryInt;
            }

            //第4个参数 初始值
            if (para_array.length > 3) {
                let para4: VeryParas = new VeryParas();
                if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para4, para_array[3])) {
                    return false;
                }
                this._intValue = para4.string;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}

