export class Action_List_SetGameobjectActive extends VE_ActionBehaviour {

    public get ID(): string {
        return "List_SetGameobjectActive|设置物体数组激活";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '设置物体数组激活，*list，true';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=966';
    }
    public get className(): string {
        return "Action_List_SetGameobjectActive";
    }

    public get type(): ActionType {
        return ActionType.Animation;
    }

    // 参数1：数组
    private _blueList: VeryList = new VeryList();
    // 参数2：物体数组激活
    private _blueBool: VeryBool = new VeryBool();
    //参数3:是否设置子物体
    private _childActive: VeryBool = new VeryBool();

    public active(): void {
        for (var i = 0; i < this._blueList.value.length; i++) {
            var tmpVeryGameobject = <VeryGameObject>this._blueList.value[i];
            if (tmpVeryGameobject.value != null) {
                if (this._childActive.value) {
                    this.ActiveRecursion(tmpVeryGameobject.value.transform.transformNode, this._blueBool.value);
                }
                else {
                    tmpVeryGameobject.value.transform.transformNode?.setEnabled(this._blueBool.value);
                }
            }
        }
    }
    private ActiveRecursion(obj: BABYLON.Nullable<BABYLON.TransformNode>, active: boolean) {
        obj?.setEnabled(active);
        if (obj != null && obj.getChildTransformNodes().length > 0) {
            for (var i = 0; i < obj.getChildTransformNodes().length; i++) {
                this.ActiveRecursion(obj.getChildTransformNodes()[i], active);
            }
        }
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2, 3)) {
            return false;
        } else {
            // 参数1：数组
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.ListPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._blueList = para1.list;
            //判断数组的单元类型是否是gameobject
            if (this._blueList.childType !== 'GameObject') {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[0] + "，{{List中单元类型不为gameobject}}，{{请检查}}！", '', Severity.Error));
                return false;
            }

            // 参数2：数组个数
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._blueBool = para2.bool;

            //参数3：是否设置子物体
            if (para_array.length > 2) {
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                    return false;
                }
                this._childActive = para3.bool;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}

