export class Action_Sprite_Animation extends VE_ActionBehaviour {

    public get ID(): string {
        return "Sprite_Animation|Sprite动画";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return 'Sprite动画，Sprite，0，40，true，100';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=871';
    }
    public get className(): string {
        return "Action_Sprite_Animation";
    }

    private _spriteName: VeryString = new VeryString();
    private _startCell: VeryNumber = new VeryNumber();
    private _endCell: VeryNumber = new VeryNumber();
    private _loop: VeryBool = new VeryBool();
    private _delay: VeryNumber = new VeryNumber();

    public active(): void {
        if (GameGlobal.sceneSpriteDic[this._spriteName.value]) {
            (<BABYLON.Sprite>GameGlobal.sceneSpriteDic[this._spriteName.value]).playAnimation(this._startCell.value, this._endCell.value, this._loop.value, this._delay.value, null);
        }
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 5)) {
            return false;
        } else {
            //参数1:sprite名字
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._spriteName = para0.string;
            //DO_20221228:表格编辑器,自动检测
            if (!VeryEngine.enableLuckySheet) {
                if (GameGlobal.sceneSpriteDic[this._spriteName.value] === undefined) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " Sprite{{在场景中不存在}}" + para_array[0] + "，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }

            //参数2:起始索引
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para1, para_array[1])) {
                return false;
            }
            this._startCell = para1.number;

            //参数3:终止索引
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para2, para_array[2])) {
                return false;
            }
            this._endCell = para2.number;

            //参数4:循环
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolPara(this.objectID, this.ID, ParaType.Action, para3, para_array[3])) {
                return false;
            }
            this._loop = para3.bool;

            //参数5:帧间隔
            let para4: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para4, para_array[4])) {
                return false;
            }
            this._delay = para4.number;

            return true;
        }
    }
    public destroy(): void {

    }
}
export class Action_Sprite_SetPosition extends VE_ActionBehaviour {


    public get ID(): string {
        return 'Sprite_SetPosition|Sprite设置位置';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return 'Sprite设置位置，Sprite，vector3，(0，0，0)';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=872';
    }
    public get className(): string {
        return 'Action_Sprite_SetPosition';
    }


    private _posvalue: VeryNumber = new VeryNumber();
    private _posVec: VeryVector3 = new VeryVector3();
    private _isVec: boolean = false;
    private _x: VeryNumber = new VeryNumber();
    private _y: VeryNumber = new VeryNumber();
    private _z: VeryNumber = new VeryNumber();
    private _axis: number = 0;

    private _spriteName: VeryString = new VeryString();

    public active(): void {

    }

    public onUpdate(): void {

        if (GameGlobal.sceneSpriteDic[this._spriteName.value]) {
            var tmpSprite = (<BABYLON.Sprite>GameGlobal.sceneSpriteDic[this._spriteName.value]);
            if (this._axis === 0) {
                tmpSprite.position = new BABYLON.Vector3(this._posvalue.value, tmpSprite.position.y, tmpSprite.position.z);
            }
            else if (this._axis === 1) {
                tmpSprite.position = new BABYLON.Vector3(tmpSprite.position.x, this._posvalue.value, tmpSprite.position.z);
            }
            else if (this._axis === 2) {
                tmpSprite.position = new BABYLON.Vector3(tmpSprite.position.x, tmpSprite.position.y, this._posvalue.value);
            }
            else {
                if (this._isVec) {
                    tmpSprite.position = this._posVec.value;
                }
                else {
                    tmpSprite.position = new BABYLON.Vector3(this._x.value, this._y.value, this._z.value);
                }
            }
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3)) {
            return false;
        } else {
            //参数1:sprite名字
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._spriteName = para0.string;
            //DO_20221228:表格编辑器,自动检测
            if (!VeryEngine.enableLuckySheet) {
                if (GameGlobal.sceneSpriteDic[this._spriteName.value] === undefined) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " Sprite{{在场景中不存在}}" + para_array[0] + "，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }

            // 参数2：设置目标
            if (para_array[1].toLowerCase() === "x") {
                this._axis = 0;
            }
            else if (para_array[1].toLowerCase() === "y") {
                this._axis = 1;
            }
            else if (para_array[1].toLowerCase() === "z") {
                this._axis = 2;
            }
            else if (para_array[1].toLowerCase() === "vector3") {
                this._axis = 3;
            }
            else {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数格式错误}}，{{轴参数应为x、y、z、vector3}}，{{当前为}}：" + para_array[1] + "，{{请检查}}！", '', Severity.Error));
                return false;
            }

            // 参数3：位置坐标
            if (this._axis === 3) {
                let para4: VeryParas = new VeryParas();
                if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para4, para_array[2])) {
                    return false;
                }
                this._isVec = para4.isVec;
                this._posVec = para4.vector3;
                this._x = para4.vecNumbers[0];
                this._y = para4.vecNumbers[1];
                this._z = para4.vecNumbers[2];
            }
            else {
                let para4: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para4, para_array[2])) {
                    return false;
                }
                this._posvalue = para4.number;
            }

            return true;
        }
    }

    public destroy(): void {

    }
}
