import { VEObject, VEObjects } from "../object";
import { VE_Error, VE_ErrorManager } from "../global";
import { InstanceParser } from "./instance-parser";
import { TableParser } from "./table-parser";
import { GameObject } from "../babylon";
import { UIManager } from "./uiManager";
import { VEFinder } from "../utility";
import { VeryTable } from "../../verytable";

export class LoadCenter {

    public tableParser: TableParser = new TableParser();
    public instanceParser: InstanceParser = new InstanceParser();

    private todoObjects: VEObject[] = [];

    public constructor() {

    }


    public hasLoaded(node_id: string): boolean {
        if (VEObjects.isNodeIdLoaded(node_id)) {
            return true;
        }
        // if (VEObjects.isNodeNameLoaded(node_name)) {
        //     return true;
        // }
        return false;
    }


    public loadTable(node_id: string, table_name: string, node_name: string, table: VeryTable, entity: VREdit.IEDEntity): boolean {
        // create object
        let gameObject = GameObject.FindByNodeId(node_id);

        if (!gameObject) {
            if (entity) {
                gameObject = new GameObject(entity.name);
                gameObject.setNull();
                gameObject.id = entity.id;
            } else {
                VE_ErrorManager.Add(
                    VE_Error.error(
                        "",
                        `物体名：${node_name}，物体ID：${node_id}，表格名：${table_name}，当前表格解析失败，无法在场景中找到该物体！`,
                        "",
                        node_name
                    )
                );
                return false;
            }
        }
        gameObject.entity = entity;
        // console.warn(gameObject);
        // console.error(entity.enabled);
        const object = new VEObject(node_id, node_name, gameObject, table);
        // object.entity = VEFinder.FindEntity(node_id);
        object.entity = entity;
        VEObjects.add(node_id, object);

        const successful = this.tableParser.parsing(object, table);
        this.todoObjects.push(object);
        return successful;
    }

    public loadEnd(): boolean {
        let successful: boolean = true;

        // 1、普通变量创建
        const len = this.todoObjects.length;
        for (let i = 0; i < len; i++) {
            const object = this.todoObjects[i];
            if (!this.instanceParser.parsingVariable(object)) {
                successful = false;
            }
        }

        // 2、状态变量与状态机创建
        for (let i = 0; i < len; i++) {
            const object = this.todoObjects[i];
            if (!this.instanceParser.parsingFSMState(object)) {
                successful = false;
            }
        }

        // 3、公式变量创建
        for (let i = 0; i < len; i++) {
            const object = this.todoObjects[i];
            if (!this.instanceParser.parsingExpression(object)) {
                successful = false;
            }
        }

        // 4、触发——触发创建
        for (let i = 0; i < len; i++) {
            const object = this.todoObjects[i];
            if (!this.instanceParser.parsingTrigger(object)) {
                successful = false;
            }
        }

        // 5、响应——响应创建
        for (let i = 0; i < len; i++) {
            const object = this.todoObjects[i];
            if (!this.instanceParser.parsingAction(object)) {
                successful = false;
            }
        }

        // 6、状态机 —— 状态机信息关联：触发关联 + 响应关联 + 状态赋值
        for (let i = 0; i < len; i++) {
            const object = this.todoObjects[i];
            if (!this.instanceParser.parsingFsmLink(object)) {
                successful = false;
            }
        }

        // 7、状态机 —— 状态机信息关联：关联状态信息关联
        for (let i = 0; i < len; i++) {
            const object = this.todoObjects[i];
            if (!this.instanceParser.parsingAssociatedState(object)) {
                successful = false;
            }
        }

        // UI
        UIManager.init();

        this.todoObjects = [];

        return successful;
    }

    public clone(ve_object: VEObject): void {

        // 1、普通变量创建
        this.instanceParser.parsingVariable(ve_object);

        // 2、状态变量与状态机创建
        this.instanceParser.parsingFSMState(ve_object);

        // 3、公式变量创建
        this.instanceParser.parsingExpression(ve_object);

        // 4、触发——触发创建
        this.instanceParser.parsingTrigger(ve_object);

        // 5、响应——响应创建
        this.instanceParser.parsingAction(ve_object);

        // 6、状态机 —— 状态机信息关联：触发关联 + 响应关联 + 状态赋值
        this.instanceParser.parsingFsmLink(ve_object);

        // 7、状态机 —— 状态机信息关联：关联状态信息关联
        this.instanceParser.parsingAssociatedState(ve_object);

        // UI
        UIManager.init();

        VE_ErrorManager.Print();
    }

    // TOODO
    public unloadTableById(node_id: string, delete_object: boolean = true): void {
        if (VEObjects.isNodeIdLoaded(node_id)) {
            const ve_object = VEObjects.getByNodeId(node_id);
            ve_object.unload(delete_object);
            VEObjects.unloadById(node_id);
        } else {
            console.error('卸载对象错误，无法在系统中查找到该对象（对象Id）：' + node_id);
        }
    }

    // TOODO
    public unloadTableByName(node_name: string, host_node_id: string, delete_object: boolean = true): void {
        // console.log(node_name);
        if (VEObjects.isNodeNameLoaded(node_name, host_node_id)) {
            const ve_object = VEObjects.getByName(node_name, host_node_id);
            // console.warn(ve_object);
            ve_object.unload(delete_object);
            VEObjects.unloadById(ve_object.NodeID);
        } else {
            console.error('卸载对象错误，无法在系统中查找到该对象（对象名）：' + node_name);
        }
    }



}