import { Severity } from "../enum";
import { GameGlobal, VE_Error, VE_ErrorManager } from "../global";
import { StateConst } from "../state";
import { ErrorInfo } from "../utility";
import { MonoBehaviourMessageCenter } from "../veryNetty/MonoBehaviourMessageCenter";
import { IVeryVar } from "./IVeryVar";

export class VEVarManager {


    private static _veryVarFunctions: { [key: string]: Function } = {};


    public static hasVarType(var_type: string): boolean {
        var_type = var_type.toLowerCase();
        if (VEVarManager._veryVarFunctions[var_type]) {
            return true;
        } else {
            return false;
        }
    }

    public static addVarType(var_function: Function): void {
        // 平台只加载一次，避免重复加载
        if (!GameGlobal.PlatformLoaded) {
            const tempVar: any = new var_function.prototype.constructor();
            // console.log(`变量ID：  ${tempVar.ID}， 变量名： ${tempVar.className} `);
            const ids: string[] = tempVar.ID.split('|');
            for (let i: number = 0; i < ids.length; i++) {
                const id: string = ids[i].trim().toLowerCase();
                if (VEVarManager._veryVarFunctions[id]) {
                    VE_ErrorManager.Add(new VE_Error('', `{{变量类型重复}}，{{当前变量类型}}：${id}，{{重复变量}}：${tempVar.className}，{{请为当前变量重新分配变量类型}}！`, '', Severity.Error));
                } else {
                    VEVarManager._veryVarFunctions[id] = var_function;
                }
            }
        }
    }

    public static createVariable(var_id: string, var_type: string, value: string, error_info: ErrorInfo): Nullable<IVeryVar> {
        var_type = var_type.toLowerCase();
        if (!VEVarManager._veryVarFunctions[var_type]) {
            error_info.isRight = false;
            //DO_20221228:表格编辑器,自动检测,中英文
            error_info.message = `{{变量创建错误}}：{{当前变量类型在平台中不存在}}，{{请检查}}！{{变量类型}}：` + var_type;
            return null;
        }

        let variable: any;
        try {
            // variable = Object.create(VEVarManager.getVarType(var_type));
            // new方式创建响应，Object.create方式创建因为prototype的关系，引用变量是唯一的，所有创建的响应共享，不合适
            variable = new VEVarManager._veryVarFunctions[var_type].prototype.constructor();

            if (!variable) {
                error_info.isRight = false;
                //DO_20221228:表格编辑器,自动检测,中英文
                error_info.message = '{{变量创建错误}}：{{当前类型在平台中不存在}}，{{请检查}}！{{类型名}}：' + var_type;
                return null;
            }
            const result: any = (<IVeryVar>variable).initValue(value, error_info);
            if (error_info.isRight) {
                (<IVeryVar>variable).setValue(result);
                (<IVeryVar>variable).name = var_id;
                //网络添加
                if (var_id.startsWith(StateConst.NET_SENDMODE_ALL))
                    MonoBehaviourMessageCenter.Instance.AddVeryEngineVeryVarEvent(variable, (<IVeryVar>variable).setBytes.bind(variable));
                return <IVeryVar>variable;
            } else {
                return null;
            }
        } catch (error) {
            console.log(`变量创建错误：${error.message}`);
            error_info.isRight = false;
            //DO_20221228:表格编辑器,自动检测,中英文
            error_info.message = '{{变量创建错误}}：{{当前类型在平台中不存在}}，{{请检查}}！{{类型名}}：' + var_type + '，{{错误原因}}：' + error.message;
            return null;
        }
    }

    public static getVarType(var_type: string): any {
        var_type = var_type.toLowerCase();
        if (VEVarManager._veryVarFunctions && VEVarManager._veryVarFunctions[var_type]) {
            return VEVarManager._veryVarFunctions[var_type];
        }
        return null;
    }


    public static remove(var_type: string): void {
        var_type = var_type.toLowerCase();
        delete VEVarManager._veryVarFunctions[var_type];
    }


}