export class Action_SketchMotion_SimpleMove extends VE_ActionBehaviour {

    public get ID(): string {
        return "SketchMotion_SimpleMove|一代平移运动";
    }
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '一代平移运动，立方体，(20，0，0)，10，自身';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=823';
    }
    public get className(): string {
        return "Action_SketchMotion_SimpleMove";
    }

    //TODO_20210209:支持动画响应
    public get type(): ActionType {
        return ActionType.Animation;
    }


    //物体
    private _blueObj: VeryGameObject = new VeryGameObject();
    //方向
    private _isVec3: boolean = false;
    private _directionVec: VeryVector3 = new VeryVector3();
    private _directionX: VeryNumber = new VeryNumber();
    private _directionY: VeryNumber = new VeryNumber();
    private _directionZ: VeryNumber = new VeryNumber();
    //速度
    private _speed: VeryNumber = new VeryNumber();
    //模式
    private _space: BABYLON.Space = BABYLON.Space.LOCAL;
    private _ref: VeryGameObject = new VeryGameObject();

    //一代平台——添加时间
    private _started = false;
    private _isInitialed = false;
    private _currentTime = 0;
    private _stantardTime = 0;
    //起始信息
    private StartPos = new BABYLON.Vector3(0, 0, 0);
    private StartEurler = new BABYLON.Vector3(0, 0, 0);
    //终止信息
    private EndPos = new BABYLON.Vector3(0, 0, 0);
    private EndEurler = new BABYLON.Vector3(0, 0, 0);

    //TODO_20210602:一代平移位置修正
    private NewRotationQuaternion: BABYLON.Nullable<BABYLON.Quaternion> = null;

    public active(): void {
        this._started = true;
    }

    public onUpdate(): void {
        //TODO:
        if (this._blueObj !== null && this._blueObj.value !== null && this._started) {

            if (!this._isInitialed) {
                // 2、位置修正
                this.StartPos = this._blueObj.value.transform.position;
                this.StartEurler = this._blueObj.value.transform.eulerAngles;//终止信息记录
                var emptyOBJ = BABYLON.MeshBuilder.CreateBox("move_empty", { size: 50 }, this.scene);
                var empty = new GameObject("move_empty", emptyOBJ);
                //TODO_20210630:设置父物体导致rotationQuaternion变化
                //DO_20221209:响应中设置父子关系后，一代运动角度修正
                var tmpParent = null;
                if (this._blueObj.value.transform.mesh) {
                    tmpParent = this._blueObj.value.transform.mesh.parent;
                }
                else if (this._blueObj.value.transform.transformNode) {
                    tmpParent = this._blueObj.value.transform.transformNode.parent;
                }
                emptyOBJ.setParent(tmpParent);
                //empty.transform.parent = (this._blueObj.value.transform.parent);
                empty.transform.position = this.StartPos;
                empty.transform.eulerAngles = this.StartEurler;
                // TODO:角度修正,rotationQuaternion优先于rotation
                var tmpTransformNode = empty.transform.transformNode;
                if (this._blueObj.value.transform.transformNode!.rotationQuaternion != null && tmpTransformNode != null) {
                    //TODO_20210602:一代旋转最终角度修正
                    if (tmpTransformNode.rotationQuaternion == null) {
                        tmpTransformNode.rotationQuaternion = new BABYLON.Quaternion(0, 0, 0, 1);
                    }
                    tmpTransformNode.rotationQuaternion!.copyFrom(this._blueObj.value.transform.transformNode!.rotationQuaternion);
                }
                //TODO_20210618:缩放比例导致位置修正错误
                empty.transform.localScale = this._blueObj.value.transform.localScale;
                // 模拟运动过程
                var tmpDirection = this._directionVec.value;
                if (!this._isVec3) {
                    tmpDirection = new BABYLON.Vector3(this._directionX.value, this._directionY.value, this._directionZ.value);
                }
                if (this._blueObj.value.transform.parent !== null) {

                }
                if (this._space === BABYLON.Space.LOCAL) {
                    //1、self
                    empty.transform.translate(tmpDirection, BABYLON.Space.LOCAL);
                }
                else if (this._space === BABYLON.Space.WORLD) {
                    //2.world
                    empty.transform.translate(tmpDirection, BABYLON.Space.WORLD);
                }
                else {
                    if (this._ref && this._ref.value) {
                        empty.transform.translateRelativeTo(tmpDirection, this._ref.value.transform);
                    }
                }
                //修改成相对路径
                this.EndPos = empty.transform.localPosition;
                this.EndEurler = empty.transform.localEulerAngles;
                //EndPos = empty.transform.position;
                //EndEurler = empty.transform.eulerAngles;
                if (empty.transform.transformNode != null && empty.transform.transformNode.rotationQuaternion != null) {
                    //console.log('2--' + empty.transform.transformNode.rotationQuaternion);
                    this.NewRotationQuaternion = new BABYLON.Quaternion(0, 0, 0, 1);
                    this.NewRotationQuaternion.copyFrom(empty.transform.transformNode.rotationQuaternion);
                }
                GameObject.Destroy(empty);

                //一代平台——添加时间,添加后处理位置修正
                //1、运行时间
                this._currentTime = 0;
                if (this._isVec3)
                    this._stantardTime = tmpDirection.length() / this._speed.value;
                else
                    this._stantardTime = tmpDirection.length() / this._speed.value;

                this._isInitialed = true;
            }
            else {
                var tmpDirection = this._directionVec.value;
                if (!this._isVec3) {
                    tmpDirection = new BABYLON.Vector3(this._directionX.value, this._directionY.value, this._directionZ.value);
                }

                if (this._space === BABYLON.Space.LOCAL) {
                    this._blueObj.value.transform.translate(tmpDirection.normalize().scale(this._speed.value * Time.deltaTime), BABYLON.Space.LOCAL);
                }
                else if (this._space === BABYLON.Space.WORLD) {
                    this._blueObj.value.transform.translate(tmpDirection.normalize().scale(this._speed.value * Time.deltaTime), BABYLON.Space.WORLD);
                }
                else {
                    if (this._ref && this._ref.value) {
                        this._blueObj.value.transform.translateRelativeTo(tmpDirection.normalize().scale(this._speed.value * Time.deltaTime), this._ref.value.transform);
                    }
                }

                //一代平台——添加时间
                this._currentTime += Time.deltaTime;
                if (this._currentTime >= this._stantardTime) {
                    this.PostProcess();
                }
            }
        }
    }

    //TODO_20210209:支持动画响应
    public pause(): void {
        this._started = false;
        super.pause();
    }
    public resume(): void {
        this._started = true;
        super.resume();
    }
    public stop(): void {
        this.PostProcess();
        super.stop();
    }

    //一代平台——后处理
    public PostProcess(): void {
        this._started = false;
        this._isInitialed = false;
        this._currentTime = 0;

        //一代平台——位置修正
        //修改成相对路径
        if (this._blueObj.value != null) {
            this._blueObj.value.transform.localPosition = this.EndPos;

            //TODO_20210602:一代旋转最终角度修正
            //TODO:角度修正,rotationQuaternion优先于rotation
            //console.log('3--' + this._blueObj.value.transform.transformNode.rotationQuaternion);
            //console.log('4--' + this.NewRotationQuaternion);
            if (this.NewRotationQuaternion != null && this._blueObj.value.transform.transformNode != null) {
                if (this._blueObj.value.transform.transformNode.rotationQuaternion == null) {
                    this._blueObj.value.transform.transformNode.rotationQuaternion = new BABYLON.Quaternion(0, 0, 0, 1);
                }
                this._blueObj.value.transform.transformNode.rotationQuaternion.copyFrom(this.NewRotationQuaternion);
                //DO_20220829:一代旋转rotationQuaternion导致获取角度错误
                //console.warn('角度修正--');
                this._blueObj.value.transform.transformNode.rotation = this._blueObj.value.transform.transformNode.rotationQuaternion.toEulerAngles();
                this._blueObj.value.transform.transformNode.rotationQuaternion = null;
            }
        }

        //TODO_20210209:支持动画响应
        this.finish();
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 4)) {
            return false;
        } else {
            //第一个参数:物体
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0], this.nodeID)) {
                return false;
            }
            this._blueObj = para1.gameObject;

            // 参数2：方向
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Trigger, para2, para_array[1])) {
                return false;
            }
            this._isVec3 = para2.isVec;
            this._directionVec = para2.vector3;
            this._directionX = para2.vecNumbers[0];
            this._directionY = para2.vecNumbers[1];
            this._directionZ = para2.vecNumbers[2];

            //参数3:速度
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Trigger, para3, para_array[2])) {
                return false;
            }
            this._speed = para3.number;

            //参数4：移动模式
            if (para_array[3].toLowerCase() === "self" || para_array[3] === "自身") {
                this._space = BABYLON.Space.LOCAL;
            }
            else if (para_array[3].toLowerCase() === "world" || para_array[3] === "世界") {
                this._space = BABYLON.Space.WORLD;
            }
            else {
                this._space = BABYLON.Space.BONE;
                let para4: VeryParas = new VeryParas();
                if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para4, para_array[3], this.nodeID)) {
                    return false;
                }
                this._ref = para4.gameObject;
                //DO_20221228:表格编辑器,自动检测
                if (!VeryEngine.enableLuckySheet) {
                    if (this._ref.value === null) {
                        //DO_20221228:表格编辑器,自动检测,中英文
                        VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应传入参数}} {{参考物体}}： " + para_array[3] + "，{{该参考物体在场景中无法找到}}！", '', Severity.Error));
                        return false;
                    }
                }
            }

            return true;
        }
    }

    public destroy(): void {

    }
}

