    //旋转速度
    private _rotateSpeed: VeryNumber = new VeryNumber();
    //参考物体
    private _referenceObj: VeryGameObject = new VeryGameObject();
    //最终位置
    private _isVec3: boolean = false;
    private _PosVec: VeryVector3 = new VeryVector3();
    private _PosX: VeryNumber = new VeryNumber();
    private _PosY: VeryNumber = new VeryNumber();
    private _PosZ: VeryNumber = new VeryNumber();
    //最终角度
    private _AngleIsVec3: boolean = false;
    private _AngleVec: VeryVector3 = new VeryVector3();
    private _AngleX: VeryNumber = new VeryNumber();
    private _AngleY: VeryNumber = new VeryNumber();
    private _AngleZ: VeryNumber = new VeryNumber();

    //一代平台——添加时间
    private _started = false;
    private _isInitialed = false;
    private _currentTime = 0;
    private _stantardTime = 0;
    //起始信息
    private StartPos = new BABYLON.Vector3(0, 0, 0);
    private StartEurler = new BABYLON.Vector3(0, 0, 0);
    //终止信息
    private EndPos = new BABYLON.Vector3(0, 0, 0);
    private EndEurler = new BABYLON.Vector3(0, 0, 0);
    //最终速度
    private SpeedVector = new BABYLON.Vector3(0, 0, 0);
    private AngleVector = new BABYLON.Vector3(0, 0, 0);

    public active(): void {
        this._started = true;
    }

    public onUpdate(): void {
        //TODO:
        if (this._blueObj !== null && this._blueObj.value !== null && this._referenceObj !== null && this._referenceObj.value !== null && this._started) {

            if (!this._isInitialed) {
                //2、位置修正
                this.StartPos = this._blueObj.value.transform.position;
                this.StartEurler = this._blueObj.value.transform.eulerAngles;//终止信息记录
                var emptyOBJ = BABYLON.MeshBuilder.CreateBox("random-move_empty-", { size: 1 }, this.scene);
                var empty = new GameObject("random-move_empty-", emptyOBJ);
                //模拟运动
                var tmpPos = this._PosVec.value;
                if (!this._isVec3) {
                    tmpPos = new BABYLON.Vector3(this._PosX.value, this._PosY.value, this._PosZ.value);
                }
                var tmpAngle = this._AngleVec.value;
                if (!this._AngleIsVec3) {
                    tmpAngle = new BABYLON.Vector3(this._AngleX.value, this._AngleY.value, this._AngleZ.value);
                }
                //DO_20221209:响应中设置父子关系后，一代运动角度修正
                var tmpParent = null;
                if (this._referenceObj.value.transform.mesh) {
                    tmpParent = this._referenceObj.value.transform.mesh;
                }
                else if (this._referenceObj.value.transform.transformNode) {
                    tmpParent = this._referenceObj.value.transform.transformNode;
                }
                emptyOBJ.setParent(tmpParent);
                //empty.transform.parent = this._referenceObj.value.transform;
                empty.transform.localScale = this._blueObj.value.transform.localScale;
                empty.transform.localPosition = tmpPos;
                empty.transform.localEulerAngles = tmpAngle;
                this.EndPos = empty.transform.position;
                this.EndEurler = empty.transform.eulerAngles;
                GameObject.Destroy(empty);

                //时间计算
                var motionVec = this.EndPos.subtract(this.StartPos);
                //TODO:计算角度差值
                var angleVec = this.EndEurler.subtract(this.StartEurler);
                //DO_20220701:角度特殊处理
                if (Math.abs(angleVec.x) === 360) {
                    angleVec.x = 0;
                }
                if (Math.abs(angleVec.y) === 360) {
                    angleVec.y = 0;
                }
                if (Math.abs(angleVec.z) === 360) {
                    angleVec.z = 0;
                }
                var moveTime = 0;
                var rotateTime = 0;
                if (motionVec.length() != 0 && this._moveSpeed.value != 0) {
                    moveTime = motionVec.length() / this._moveSpeed.value;
                }
                if (angleVec.length() != 0 && this._rotateSpeed.value != 0) {
                    rotateTime = angleVec.length() / this._rotateSpeed.value;
                }
                if (moveTime == 0 && rotateTime == 0) {
                    return;
                }
                if (moveTime > rotateTime) {
                    this._stantardTime = moveTime;
                }
                else {
                    this._stantardTime = rotateTime;
                }
                this.AngleVector = angleVec.scale(1 / this._stantardTime);
                this.SpeedVector = motionVec.scale(1 / this._stantardTime);

                this._isInitialed = true;
            }
            else {
                if (this.SpeedVector != BABYLON.Vector3.Zero())
                    this._blueObj.value.transform.position = this.StartPos.add(this.SpeedVector.scale(this._currentTime));
                if (this.AngleVector != BABYLON.Vector3.Zero())
                    this._blueObj.value.transform.eulerAngles = this.StartEurler.add(this.AngleVector.scale(this._currentTime));

                //一代平台——添加时间
                this._currentTime += Time.deltaTime;
                if (this._currentTime >= this._stantardTime) {
                    this.PostProcess();
                }
            }
        }
    }

