//TODO_20210702:世界坐标点转屏幕坐标点
export class Action_World_To_Screen_Point extends VE_ActionBehaviour {

    public get ID(): string {
        return "World_To_Screen_Point|世界坐标点转屏幕坐标点";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '世界坐标点转屏幕坐标点，*world_point，主相机，*pos';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=674';
    }
    public get className(): string {
        return "Action_World_To_Screen_Point";
    }

    //世界坐标
    private _worldPoint: VeryVector3 = new VeryVector3();

    //DO_20210930:漫游相机,相机变量
    private _camera1: VeryCamera = new VeryCamera();

    //接收屏幕坐标
    private _screenPoint: VeryVector2 = new VeryVector2();
    private _screenPointX: VeryNumber = new VeryNumber();
    private _screenPointY: VeryNumber = new VeryNumber();

    public active(): void {

    }

    public onUpdate(): void {
        //DO_20210930:漫游相机,相机变量
        if (this._camera1.value) {
            var startpoint1 = BABYLON.Vector3.Project(this._worldPoint.value, BABYLON.Matrix.Identity(), this.scene.getTransformMatrix(), this._camera1.value.viewport.toGlobal(this.scene.getEngine().getRenderWidth(), this.scene.getEngine().getRenderHeight()));
            this._screenPoint.value = new BABYLON.Vector2(startpoint1.x, startpoint1.y);
            this._screenPointX.value = startpoint1.x;
            this._screenPointY.value = startpoint1.y;
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3, 4)) {
            return false;
        } else {
            //参数1:世界坐标点
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3ParaWithExpression(this.objectID, this.ID, ParaType.Trigger, para1, para_array[0])) {
                return false;
            }
            this._worldPoint = para1.vector3;

            //DO_20210930:漫游相机,相机变量 
            // 参数2
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.CameraPara(this.objectID, this.ID, ParaType.Action, para2, para_array[1], this.nodeID)) {
                return false;
            }
            this._camera1 = para2.camera;
            //DO_20221228:表格编辑器,自动检测
            if (this._camera1.value === null && !VeryEngine.enableLuckySheet) return false;

            //参数3
            if (para_array.length == 3) {
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.Vector2Para(this.objectID, this.ID, ParaType.Trigger, para3, para_array[2])) {
                    return false;
                }
                this._screenPoint = para3.vector2;
            }
            else {
                let para4: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Trigger, para4, para_array[2])) {
                    return false;
                }
                this._screenPointX = para4.number;

                let para5: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Trigger, para5, para_array[3])) {
                    return false;
                }
                this._screenPointY = para5.number;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}

