export class Action_Set_Camera_Background_Color extends VE_ActionBehaviour {

    public get ID(): string {
        return "Set_Camera_Background_Color|设置相机背景颜色";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '设置相机背景颜色，主相机，（255，0，0）';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=678';
    }
    public get className(): string {
        return "Action_Set_Camera_Background_Color";
    }

    //DO_20210930:漫游相机,相机变量
    private _camera1: VeryCamera = new VeryCamera();

    private _isColor: boolean = false;
    private _blueColor: VeryVector3 = new VeryVector3();
    private _colorFloat: VeryNumber[] = []

    public active(): void {
        //DO_20210930:漫游相机,相机变量
        if (this._camera1.value) {
            if (!this._isColor) {
                let temp = GameGlobal.getCamera(this._camera1.value);
                if (temp) {
                    temp.clearColor = new BABYLON.Color4(this._colorFloat[0].value / 255, this._colorFloat[1].value / 255, this._colorFloat[2].value / 255);
                }
            }
            else {
                let temp = GameGlobal.getCamera(this._camera1.value);
                if (temp) {
                    temp.clearColor = new BABYLON.Color4(this._blueColor.value.x / 255, this._blueColor.value.y / 255, this._blueColor.value.z / 255);
                }

            }
        }
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2)) {
            return false;
        } else {
            //DO_20210930:漫游相机,相机变量 
            // 参数1：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.CameraPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0], this.nodeID)) {
                return false;
            }
            this._camera1 = para1.camera;
            //DO_20221228:表格编辑器,自动检测
            if (this._camera1.value === null && !VeryEngine.enableLuckySheet) return false;

            //参数2
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Trigger, para2, para_array[1])) {
                return false;
            }
            this._isColor = para2.isVec;
            this._blueColor = para2.vector3;
            this._colorFloat = para2.vecNumbers;

            return true;
        }
    }
    public destroy(): void {

    }
}

