export class Action_Set_CameraSpeed extends VE_ActionBehaviour {

    public get ID(): string {
        return "Set_CameraSpeed|设置漫游相机速度";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '设置漫游相机速度，漫游相机，50，5';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=927';
    }
    public get className(): string {
        return "Action_Set_CameraSpeed";
    }

    //漫游相机,相机变量
    private _camera1: VeryCamera = new VeryCamera();
    //移动速度
    private _moveSpeed: VeryNumber = new VeryNumber();
    //漫游速度
    private _rotateSpeed: VeryNumber = new VeryNumber();

    public active(): void {
        //漫游相机,相机变量
        if (this._camera1.value && (<BABYLON.FreeCamera>this._camera1.value)) {
            (<BABYLON.FreeCamera>this._camera1.value).speed = this._moveSpeed.value;
            (<BABYLON.FreeCamera>this._camera1.value).angularSensibility = 2000 / this._rotateSpeed.value;
        }
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3)) {
            return false;
        } else {
            // 参数1：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.CameraPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0], this.nodeID)) {
                return false;
            }
            this._camera1 = para1.camera;
            //DO_20230613:表格编辑器,自动检测
            if (this._camera1.value === null && !VeryEngine.enableLuckySheet) return false;

            //参数2
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Trigger, para2, para_array[1])) {
                return false;
            }
            this._moveSpeed = para2.number;

            //参数3
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Trigger, para3, para_array[2])) {
                return false;
            }
            this._rotateSpeed = para3.number;

            return true;
        }
    }
    public destroy(): void {

    }
}



