export class Camera_Tools {
    /*
      获取UI
    */
    public static GetCamera(scene: BABYLON.Scene, name: string, id: string): BABYLON.Nullable<BABYLON.Camera> {
        if (!name.endsWith('-Camera')) {
            name += '-Camera';
        }
        for (var i = 0; i < scene.cameras.length; i++) {
            if (name === scene.cameras[i].name) {
                return scene.cameras[i];
            }
        }
        console.error(id + "--响应参数出错--" + name);
        return null;
    }


    //DO_20221228:表格编辑器,自动检测
    public static GetChildCamera(name: string, host_node_id: string, ID: string, log: boolean = true): BABYLON.Nullable<BABYLON.Camera> {
        let camera: BABYLON.Nullable<BABYLON.Camera> = null;
        let obj = GameObject.FindByName(name, host_node_id);
        if (obj !== null && obj.transform.transformNode !== null) {
            let children = obj.transform.transformNode.getChildren();
            if (children.length > 0) {
                if (children[0] instanceof BABYLON.Camera) {
                    camera = <BABYLON.Camera>children[0];
                    return camera;
                } else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    if (log && !VeryEngine.enableLuckySheet) VE_ErrorManager.Add(new VE_Error('', ID + " {{响应}} {{传入参数格式错误}}，{{相机名}}： " + name + "，{{该相机无法在场景中找到}}！", '', Severity.Error));
                    return camera;
                }
            } else {
                //DO_20221228:表格编辑器,自动检测,中英文
                if (log && !VeryEngine.enableLuckySheet) VE_ErrorManager.Add(new VE_Error('', ID + " {{响应}} {{传入参数格式错误}}，{{相机名}}： " + name + "，{{该相机无法在场景中找到}}！", '', Severity.Error));
                return camera;
            }
        } else {
            //DO_20221228:表格编辑器,自动检测,中英文
            if (log && !VeryEngine.enableLuckySheet) VE_ErrorManager.Add(new VE_Error('', ID + " {{响应}} {{传入参数格式错误}}，{{相机名}}： " + name + "，{{该相机无法在场景中找到}}！", '', Severity.Error));
            return camera;
        }
    }
}