    public onDisable(): void {
        if (this._started) {
            this.PostProcess();
            super.stop();
        }
    }

    public pause(): void {
        this._started = false;
        super.pause();
    }
    public resume(): void {
        this._started = true;
        super.resume();
    }
    public stop(): void {
        this.PostProcess();
        super.stop();
    }
