export class Action_GUI_Image_SetColor extends VE_ActionBehaviour {

    public get ID(): string {
        return "GUI_Image_SetColor|设置GUI贴图颜色";
    }
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '设置GUI贴图颜色，2D画布3.按钮，(255，0，0)';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=889';
    }
    public get className(): string {
        return "Action_GUI_Image_SetColor";
    }

    //DO_20220408:UI变量
    private _controlVar: VeryUI = new VeryUI();
    private _Image: BABYLON.GUI.Image | HTMLImageElement;
    //颜色
    private _isColor: boolean = false;
    private _blueColor: VeryVector3 = new VeryVector3();
    private _colorFloat: VeryNumber[] = [];

    public active(): void {
        //DO_20220408:UI变量
        if (this._controlVar.value) {
            var color = new BABYLON.Vector3(this._blueColor.value.x, this._blueColor.value.y, this._blueColor.value.z);
            if (!this._isColor) {
                color = new BABYLON.Vector3(this._colorFloat[0].value, this._colorFloat[1].value, this._colorFloat[2].value);
            }

            if (this._controlVar.value.sceneObj instanceof BABYLON.GUI.Image) {
                this._Image = <BABYLON.GUI.Image>this._controlVar.value.sceneObj;
            }
            else if (this._controlVar.value.sceneObj instanceof BABYLON.GUI.Button) {
                var _Button = <BABYLON.GUI.Button>this._controlVar.value.sceneObj;
                if (_Button.image !== null) {
                    this._Image = _Button.image;
                }
            } else if (this._controlVar.value.sceneObj instanceof HTMLImageElement) {
                this._Image = this._controlVar.value.sceneObj;
            }
            else {
                return;
            }
            let source = (this._Image instanceof BABYLON.GUI.Image) ? this._Image.source : this._Image.src;
            if (source) {
                let img = new Image();
                img.src = source!;
                img.onload = () => {
                    let canvas = document.createElement('canvas');
                    let context = canvas.getContext('2d');
                    // console.warn(canvas);
                    // console.warn(img);
                    canvas.width = img.width;
                    canvas.height = img.height;
                    context!.drawImage(img, 0, 0);
                    let data = context!.getImageData(0, 0, img.width, img.height);
                    //console.warn(this._Image);
                    //console.warn(data);
                    //console.warn(data.data.length);
                    for (var i = 0; i < data.data.length; i += 4) {
                        data.data[i + 0] = color.x;
                        data.data[i + 1] = color.y;
                        data.data[i + 2] = color.z;
                    }
                    context!.putImageData(data, 0, 0);
                    const dataUrl: string = canvas.toDataURL("image/png");
                    (this._Image instanceof BABYLON.GUI.Image) ? this._Image.source = dataUrl : this._Image.src = dataUrl;
                    //console.warn(dataUrl);
                }
            }
        }
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2)) {
            return false;
        } else {
            //DO_20220408:UI变量
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.UIControlPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._controlVar = para0.uiControl;

            // 参数2：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Trigger, para1, para_array[1])) {
                return false;
            }
            this._isColor = para1.isVec;
            this._blueColor = para1.vector3;
            this._colorFloat = para1.vecNumbers;

            return true;
        }
    }
    public destroy(): void {

    }
}

