// //DO_20221124:下拉菜单,获取下拉列表选择项
export class Action_GUI_Get_Dropdown extends VE_ActionBehaviour {

    public get ID(): string {
        return "GUI_Get_Dropdown|获取下拉列表选择项";
    }

    public get className(): string {
        return "Action_GUI_Get_Dropdown";
    }

    public get Example(): string {
        return '获取下拉列表选择项，2D画布.下拉列表，*下拉列表内容，*下拉列表索引';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12/988';
    }

    //下拉菜单UI
    private _controlVar: VeryUI = new VeryUI();
    //下拉菜单选择项的内容
    private _blueString: VeryString = new VeryString();
    //下拉菜单选择项的索引
    private _blueNumber: VeryNumber = new VeryNumber();

    public active(): void {

    }

    public onUpdate(): void {
        if (this._controlVar.value) {
            this._blueNumber.value = parseFloat(this._controlVar.value.get("gui.selectedIndex"));
            let split = this._controlVar.value.get("gui.options").split("~");
            this._blueString.value = split[this._blueNumber.value];
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3)) {
            return false;
        } else {
            //UI变量
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.UIControlPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._controlVar = para0.uiControl;

            // 参数2：接收string变量
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaOnlyVar(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._blueString = para2.string;

            // 参数3：接收string变量
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaOnlyVar(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                return false;
            }
            this._blueNumber = para3.number;

            return true;
        }
    }
    public destroy(): void {

    }
}

