export class Trigger_On_Mouse_DoubleClick extends VE_TriggerBehaviour {

    public get ID(): string {
        return 'On_Mouse_DoubleClick|碰撞体鼠标双击';
    };

    public get className(): string {
        return 'Trigger_On_Mouse_DoubleClick';
    };
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '碰撞体鼠标双击，立方体';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=946';
    }

    private _target: VeryGameObject = new VeryGameObject();
    private _mouse: VeryNumber = new VeryNumber();

    private _observer: Nullable<BABYLON.Observer<BABYLON.PointerInfo>> = null;


    public paraParser(para_array: string[]): boolean {

        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 0, 1, 2)) {
            return false;
        }
        else {

            if (para_array.length > 0) {
                // 参数1： 指定碰撞物体
                let para1: VeryParas = new VeryParas();
                if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Trigger, para1, para_array[0], this.nodeID)) {
                    return false;
                }
                this._target = para1.gameObject;
            } else {
                // 默认为当前对象所在物体
                this._target.value = this.gameObject;
            }

            //DO_20221228:表格编辑器,自动检测
            if (!VeryEngine.enableLuckySheet) {
                if (this._target.value === null) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{触发}} {{传入参数格式错误}}：" + para_array[0] + "，{{请检查}}！", '', Severity.Error));
                    return false;
                } else {
                    if (this._target.value.transform.mesh === null) {

                    } else {
                        // 允许鼠标移动时获取碰撞信息
                        this._target.value.transform.mesh.enablePointerMoveEvents = true;
                    }
                }
            }

            // 参数2： 鼠标键位
            this._mouse.setValue(0);
            if (para_array.length > 1) {
                let para2: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Trigger, para2, para_array[1])) {
                    return false;
                }
                this._mouse = para2.number;
            }

            this._observer = this.scene.onPointerObservable.add((pointInfo: BABYLON.PointerInfo) => {
                if (pointInfo.type === BABYLON.PointerEventTypes.POINTERDOUBLETAP) {
                    if (pointInfo.pickInfo !== null && pointInfo.pickInfo.pickedMesh !== null && this._target.value) {
                        if (pointInfo.event.button === this._mouse.value && pointInfo.pickInfo.pickedMesh === this._target.value.transform.mesh) {
                            this.sendEvent();
                        }
                    }
                }
            });

            return true;
        }
    }

    public destroy(): void {
        if (this._observer) {
            this._scene.onPointerObservable.remove(this._observer);
        }
        this._observer = null;
    }
}

