    public static hsvString2rgba(hsv: string): number[] {
        var colorChange = [];
        for (var i = 1; i < hsv.length; i += 2) {
            colorChange.push(parseInt('0x' + hsv.slice(i, i + 2)));
        }
        colorChange = Tools.toSmallrgba(colorChange);
        return colorChange;
    }

    public static to255rgba(rgba: number[]): number[] {
        let rgba255: number[] = [];
        rgba.forEach((element: number) => {
            rgba255.push(element * 255);
        });
        return rgba255;
    }

    public static toSmallrgba(rgba: number[]): number[] {
        let rgbaSmall: number[] = [];
        rgba.forEach((element: number) => {
            rgbaSmall.push(element / 255.0);
        });
        return rgbaSmall;
    }


    public static getMultiMaterialByID(id: string, scene: BABYLON.Scene): BABYLON.Nullable<BABYLON.MultiMaterial> {
        for (var index = 0; index < scene.multiMaterials.length; index++) {
            if (scene.multiMaterials[index].id === id) {
                return scene.multiMaterials[index];
            }
        }

        return null;
    }

    private static _specialExtension: string[] = ['tif', 'tiff', 'tga', 'dds', 'hdr', 'exr', 'env', 'targa', 'psd'];

    public static textureUrlFormat(url: string): string {
        for (let i = 0, length = Tools._specialExtension.length; i < length; i++) {
            let index = url.indexOf(Tools._specialExtension[i]);
            if (index >= 0) {
                return url.substr(0, index + Tools._specialExtension[i].length);
            }
        }
        return url;
    }

