// import { BabylonEngine } from "../babylon";
import { IVeryVar, VeryString, VarTools, VeryBool } from "../variables";
import { VE_Reset } from "../manager";


export class UIUpdate {
    //TexBlock
    private static _updateText: { [key: string]: { [key: string]: BABYLON.GUI.TextBlock } } = {};
    private static _veryVar: { [key: string]: { [key: string]: IVeryVar } } = {};
    private static _stringBackup: { [key: string]: { [key: string]: string } } = {};

    //InputText
    private static _updateInputField: { [key: string]: { [key: string]: BABYLON.GUI.InputText } } = {};
    private static _veryVarInputField: { [key: string]: { [key: string]: IVeryVar } } = {};
    private static _stringBackupInputField: { [key: string]: { [key: string]: string } } = {};

    //DO_20211115:GUI和变量关联
    //slider
    private static _updateSlider: { [key: string]: { [key: string]: BABYLON.GUI.BaseSlider } } = {};
    private static _veryVarSlider: { [key: string]: { [key: string]: IVeryVar } } = {};
    private static _numberBackupSlider: { [key: string]: { [key: string]: number } } = {};
    //checkbox
    private static _updateCheckbox: { [key: string]: { [key: string]: BABYLON.GUI.Checkbox } } = {};
    private static _veryVarCheckbox: { [key: string]: { [key: string]: IVeryVar } } = {};
    private static _numberBackupCheckbox: { [key: string]: { [key: string]: boolean } } = {};

    constructor() {
        //清空关联
        VE_Reset.addClear(UIUpdate.Clear);
        VE_Reset.addProjectClear(UIUpdate.ClearProject);
    }

    /// <summary>
    /// 卸载清除所有相关数据；
    /// </summary>
    public static Clear(): void {
        this._updateText = {};
        this._veryVar = {};
        this._stringBackup = {};

        this._updateInputField = {};
        this._veryVarInputField = {};
        this._stringBackupInputField = {};

        //DO_20211115:GUI和变量关联
        //slider
        this._updateSlider = {};
        this._veryVarSlider = {};
        this._numberBackupSlider = {};
        //checkbox
        this._updateCheckbox = {};
        this._veryVarCheckbox = {};
        this._numberBackupCheckbox = {};
    }
    /// <summary>
    /// 卸载当前项目清除相关数据；
    /// </summary>
    /// <param name="project_name">项目名；</param>
    public static ClearProject(project_name: string): void {
        this._updateText[project_name] = {};
        this._veryVar[project_name] = {};
        this._stringBackup[project_name] = {};

        this._updateInputField[project_name] = {};
        this._veryVarInputField[project_name] = {};
        this._stringBackupInputField[project_name] = {};

        //DO_20211115:GUI和变量关联
        //slider
        this._updateSlider[project_name] = {};
        this._veryVarSlider[project_name] = {};
        this._numberBackupSlider[project_name] = {};
        //checkbox
        this._updateCheckbox[project_name] = {};
        this._veryVarCheckbox[project_name] = {};
        this._numberBackupCheckbox[project_name] = {};
    }

    //TODO:根据变量值实时刷新UI数据,效率比较低
    public static Update(): void {
        for (let project_name in this._updateText) {
            for (let full_name in this._updateText[project_name]) {
                if (this._veryVar[project_name][full_name] != undefined) {
                    //IVeryVar类型变量
                    if (this._stringBackup[project_name][full_name] != this._veryVar[project_name][full_name].getValue().toString()) {
                        this._stringBackup[project_name][full_name] = this._veryVar[project_name][full_name].getValue().toString();
                        this._updateText[project_name][full_name].text = this._stringBackup[project_name][full_name];
                    }
                }
            }
        }

        //TODO: 当变量同时在Text和InputField中被引用时
        for (let project_name in this._updateInputField) {
            for (let full_name in this._updateInputField[project_name]) {
                if (this._veryVarInputField[project_name][full_name] != undefined) {
                    //IVeryVar类型变量
                    if (this._stringBackupInputField[project_name][full_name] != this._veryVarInputField[project_name][full_name].getValue().toString()) {
                        this._stringBackupInputField[project_name][full_name] = this._veryVarInputField[project_name][full_name].getValue().toString();
                        this._updateInputField[project_name][full_name].text = this._stringBackupInputField[project_name][full_name];
                    }
                }
            }
        }

        //DO_20211115:GUI和变量关联
        //slider
        for (let project_name in this._updateSlider) {
            for (let full_name in this._updateSlider[project_name]) {
                if (this._veryVarSlider[project_name][full_name] != undefined) {
                    //IVeryVar类型变量
                    if (this._numberBackupSlider[project_name][full_name] !== this._veryVarSlider[project_name][full_name].getValue()) {
                        this._numberBackupSlider[project_name][full_name] = this._veryVarSlider[project_name][full_name].getValue();
                        this._updateSlider[project_name][full_name].value = this._numberBackupSlider[project_name][full_name];
                    }
                }
            }
        }
        //checkbox
        for (let project_name in this._updateCheckbox) {
            for (let full_name in this._updateCheckbox[project_name]) {
                if (this._veryVarCheckbox[project_name][full_name] != undefined) {
                    //IVeryVar类型变量
                    if (this._numberBackupCheckbox[project_name][full_name] !== this._veryVarCheckbox[project_name][full_name].getValue()) {
                        this._numberBackupCheckbox[project_name][full_name] = this._veryVarCheckbox[project_name][full_name].getValue();
                        this._updateCheckbox[project_name][full_name].isChecked = this._numberBackupCheckbox[project_name][full_name];
                    }
                }
            }
        }
    }

    /// <summary>
    /// 添加VeryVar关联数据；
    /// </summary>
    /// <param name="project_name">项目名；</param>
    /// <param name="full_name">变量完整名字；</param>
    /// <param name="current_text">当前Text组件；</param>
    /// <param name="very_var">对应的VeryVar变量；</param>
    /// <param name="init_value">初始string值；</param>
    public static AddText(project_name: string, full_name: string, current_text: BABYLON.GUI.TextBlock, very_var: IVeryVar, init_value: string): void {
        try {
            if ((this._updateText[project_name] === undefined)) {
                this._updateText[project_name] = {};
                if (this._veryVar[project_name] === undefined) {
                    this._veryVar[project_name] = {};
                    this._stringBackup[project_name] = {};
                }
            }
            if ((this._updateText[project_name][full_name] === undefined)) {
                this._updateText[project_name][full_name] = current_text;
                if (this._veryVar[project_name][full_name] === undefined) {
                    this._veryVar[project_name][full_name] = very_var;
                    this._stringBackup[project_name][full_name] = init_value;
                }
            }
        }
        catch (e) {
            console.error(e);
        }
    }

    /// <summary>
    /// 添加VeryVar关联数据；
    /// </summary>
    /// <param name="project_name">项目名；</param>
    /// <param name="full_name">变量完整名字；</param>
    /// <param name="current_text">当前InputField组件；</param>
    /// <param name="very_var">对应的VeryVar变量；</param>
    /// <param name="init_value">初始string值；</param>
    public static AddInputText(project_name: string, full_name: string, current_text: BABYLON.GUI.InputText, very_var: IVeryVar, init_value: string): void {
        if ((this._updateInputField[project_name] === undefined)) {
            this._updateInputField[project_name] = {};
            if (this._veryVarInputField[project_name] === undefined) {
                this._veryVarInputField[project_name] = {};
                this._stringBackupInputField[project_name] = {};
            }
        }
        if ((this._updateInputField[project_name][full_name] === undefined)) {
            this._updateInputField[project_name][full_name] = current_text;
            if (this._veryVarInputField[project_name][full_name] === undefined) {
                this._veryVarInputField[project_name][full_name] = very_var;
                this._stringBackupInputField[project_name][full_name] = init_value;
            }
        }
    }

    //DO_20211115:GUI和变量关联
    /// <summary>
    /// 添加VeryVar关联数据；
    /// </summary>
    /// <param name="project_name">项目名；</param>
    /// <param name="full_name">变量完整名字；</param>
    /// <param name="current_slider">当前Slider组件；</param>
    /// <param name="very_var">对应的VeryVar变量；</param>
    /// <param name="init_value">初始number值；</param>
    public static AddSlider(project_name: string, full_name: string, current_slider: BABYLON.GUI.BaseSlider, very_var: IVeryVar, init_value: number): void {

        try {
            if ((this._updateSlider[project_name] === undefined)) {
                this._updateSlider[project_name] = {};
                if (this._veryVarSlider[project_name] === undefined) {
                    this._veryVarSlider[project_name] = {};
                    this._numberBackupSlider[project_name] = {};
                }
            }
            if ((this._updateSlider[project_name][full_name] === undefined)) {
                this._updateSlider[project_name][full_name] = current_slider;
                if (this._veryVarSlider[project_name][full_name] === undefined) {
                    this._veryVarSlider[project_name][full_name] = very_var;
                    this._numberBackupSlider[project_name][full_name] = init_value;
                }
            }
        }
        catch (e) {
            console.error(e);
        }
    }
    /// <summary>
    /// 添加VeryVar关联数据；
    /// </summary>
    /// <param name="project_name">项目名；</param>
    /// <param name="full_name">变量完整名字；</param>
    /// <param name="current_checkbox">当前Checkbox组件；</param>
    /// <param name="very_var">对应的VeryVar变量；</param>
    /// <param name="init_value">初始boolean值；</param>
    public static AddCheckbox(project_name: string, full_name: string, current_checkbox: BABYLON.GUI.Checkbox, very_var: IVeryVar, init_value: boolean): void {

        try {
            if ((this._updateCheckbox[project_name] === undefined)) {
                this._updateCheckbox[project_name] = {};
                if (this._veryVarCheckbox[project_name] === undefined) {
                    this._veryVarCheckbox[project_name] = {};
                    this._numberBackupCheckbox[project_name] = {};
                }
            }
            if ((this._updateCheckbox[project_name][full_name] === undefined)) {
                this._updateCheckbox[project_name][full_name] = current_checkbox;
                if (this._veryVarCheckbox[project_name][full_name] === undefined) {
                    this._veryVarCheckbox[project_name][full_name] = very_var;
                    this._numberBackupCheckbox[project_name][full_name] = init_value;
                }
            }
        }
        catch (e) {
            console.error(e);
        }
    }
}