import { VE_ActionBehaviour, VE_Actions } from "../../action";
import { ParaParserUtility, VeryParas } from '../../utility';
import { ParaType, Severity } from '../../enum';
import { VE_ErrorManager, VE_Error } from '../../global';
import { VeryGameObject, VeryBool, VeryNumber, VeryString, VeryRect, VeryVector3, VeryVector2, VeryMaterial } from "../../variables";

//DO_20220812:网页视频播放,视频播放界面大小支持视窗宽度百分比和是窗口高度百分比
import { BabylonEngine } from "../../babylon";

//DO_20230313:五代修改
//资源加载方式修改
import { BabylonLoader } from "../../../veryengine/loader";

//DO_20221228:表格编辑器,自动检测
import { VeryEngine } from "../../veryEngine";

export class Action_VideoPlayOnOBJ extends VE_ActionBehaviour {

    public get ID(): string {
        return 'VideoPlayOnOBJ|物体上视频播放';
    }
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '物体上视频播放，*播放控制，立方体，1624026882-87e00edf，false，1';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=753';
    }
    public get className(): string {
        return 'Action_VideoPlayOnOBJ';
    }

    //是否开启
    private _switch: VeryBool = new VeryBool();
    //物体
    private _blueOBJ: VeryGameObject = new VeryGameObject();
    //播放视频
    private _musicString: VeryString = new VeryString();
    //视频循环
    private _musicLoop: VeryBool = new VeryBool();
    //视频音乐大小
    private _musicVolume: VeryNumber = new VeryNumber();
    //DO_202220601:物体上视频播放,添加控制从头开始播放的变量
    private _musicRestart: VeryBool = new VeryBool();

    //视频
    private _video: BABYLON.Nullable<BABYLON.VideoTexture> = null;
    private _currentMesh: BABYLON.Nullable<BABYLON.AbstractMesh> = null;
    //物体原有材质
    private _oldMat: BABYLON.Nullable<BABYLON.Material> = null;
    private _newMat: BABYLON.Nullable<BABYLON.StandardMaterial> = null;

    //TODO_20210618:视频路径改成id
    private _url: string = '';
    //DO_20220518:物体上视频播放,支持视频ID为变量
    public static _videoDic: { [key: string]: BABYLON.VideoTexture } = {};

    //DO_20221011:播放开始时间,播放结束时间
    //播放开始时间
    private _startTime: VeryNumber = new VeryNumber();
    //多个视频切换，每个视频不同时间点切换
    private static _matDic: { [key: string]: BABYLON.StandardMaterial } = {};
    private static _vedioDic: { [key: string]: BABYLON.VideoTexture } = {};
    //播放终止时间
    private _endTime: VeryNumber = new VeryNumber();

    public active(): void {
        //console.log("Video--" + this._video?.isReady() + "--" + this._video?.video.readyState);
        //DO_20211223:VideoTexture只能用户触发才能创建
        if (this._currentMesh) {

            //DO_20221011:多个视频切换，每个视频不同时间点切换
            // 物体材质
            if (Action_VideoPlayOnOBJ._matDic[this._url] === undefined) {

                if (this._video === null) {
                    this._video = new BABYLON.VideoTexture("VideoAction", this._url, this.scene, true, false, BABYLON.Texture.TRILINEAR_SAMPLINGMODE, { autoPlay: true, autoUpdateTexture: true });
                }
                // console.log("Vedio--" + this._vedio.video.videoWidth + "--" + this._vedio.video.videoHeight);
                this._newMat = new BABYLON.StandardMaterial("videoActionMaterial", this.scene);
                this._newMat.diffuseTexture = this._video;
                //DO_20220106:视频在物体上播放亮度调节,不受光源影响
                this._newMat.roughness = 1;
                this._newMat.emissiveColor = BABYLON.Color3.White();
                this._newMat.specularColor = BABYLON.Color3.Black();
                this._newMat.diffuseColor = BABYLON.Color3.White();
                this._newMat.ambientColor = BABYLON.Color3.White();
                this._newMat.backFaceCulling = false;
                //this._newMat.roughness = 1;
                //this._newMat.emissiveColor = BABYLON.Color3.White();
                // 物体材质
                this._currentMesh.material = this._newMat;
                Action_VideoPlayOnOBJ._vedioDic[this._url] = this._video;
                Action_VideoPlayOnOBJ._matDic[this._url] = this._newMat;
            }
            else {
                this._currentMesh.material = Action_VideoPlayOnOBJ._matDic[this._url];
                this._video = Action_VideoPlayOnOBJ._vedioDic[this._url];
            }

            /*
            //DO_20220518:物体上视频播放,支持视频ID为变量
            // 物体材质
            if (this._newMat === null) {
                this._newMat = new BABYLON.StandardMaterial("videoActionMaterial", this.scene);
                //DO_20220106:视频在物体上播放亮度调节,不受光源影响
                this._newMat.roughness = 1;
                this._newMat.emissiveColor = BABYLON.Color3.White();
                this._newMat.specularColor = BABYLON.Color3.Black();
                this._newMat.diffuseColor = BABYLON.Color3.White();
                this._newMat.ambientColor = BABYLON.Color3.White();
                this._newMat.backFaceCulling = false;
                // 物体材质
                this._currentMesh.material = this._newMat;
            }
            */

            //视频贴图
            if (Action_VideoPlayOnOBJ._videoDic[this._musicString.value] === undefined) {
                setTimeout(this.AddNewVideo.bind(this), 0);
                return;
            }
            else {
                //DO_20220527:物体上视频播放,切换视频时音频未切换
                if (this._video) {
                    this._video.video.pause();
                }
                var changeVideo = (this._video !== Action_VideoPlayOnOBJ._videoDic[this._musicString.value]);
                this._video = Action_VideoPlayOnOBJ._videoDic[this._musicString.value];

                //DO_202220601:物体上视频播放,添加控制从头开始播放的变量
                if (changeVideo || (this._musicRestart.value && this._switch.value)) {
                    this._video.video.currentTime = 0;
                }
            }
            Action_VideoPlayOnOBJ._matDic[this._url].diffuseTexture = this._video;

            if (this._video) {
                if (this._switch.value) {
                    this._video.video.loop = this._musicLoop.value;
                    this._video.video.volume = (this._musicVolume.value);

                    this._video.video.play();

                    //DO_20221011:播放开始时间,播放结束时间
                    if (this._startTime.value !== 0) {
                        this._video.video.currentTime = this._startTime.value;
                    }

                } else {
                    this._video.video.loop = this._musicLoop.value;
                    this._video.video.volume = (this._musicVolume.value);
                    this._video.video.pause();
                    // 物体材质
                    // this._currentMesh.material = this._oldMat;
                }
            }

        }
    }

    public onUpdate(): void {
        //DO_20221011:播放开始时间,播放结束时间
        if (this._currentMesh) {
            if (this._video) {
                if (this._switch.value) {
                    if (this._endTime.value > 0 && this._endTime.value > this._startTime.value) {
                        //console.log('this._video.video.currentTime--' + this._video.video.currentTime + '--' + this._startTime.value + '--' + this._endTime.value);
                        if (this._video.video.currentTime < this._startTime.value) {
                            this._video.video.currentTime = this._startTime.value;
                        }
                        if (this._video.video.currentTime >= this._endTime.value) {
                            this._video.video.pause();
                            this._video.video.currentTime = this._endTime.value;
                            this._switch.value = false;
                        }
                    }
                }
            }
        }
    }

    //DO_20220518:物体上视频播放,支持视频ID为变量
    private async AddNewVideo() {
        let self = this;
        //DO_20230313:五代修改
        //资源加载方式修改
        self._url = await BabylonLoader.getAssetUrl(self._musicString.value);
        //self._url = await Resources.GetUrl(self._musicString.value);
        //DO_20211223:VideoTexture只能用户触发才能创建
        if (self._url === '') {
            console.error('物体上视频播放 视频信息获取失败，asset_id：' + self._musicString.value + '，无法在当前场景中查找到该ID，请检查！');
        }
        else {
            //DO_20220527:物体上视频播放,切换视频时音频未切换
            if (self._video) {
                self._video.video.pause();
            }
            Action_VideoPlayOnOBJ._videoDic[self._musicString.value] = new BABYLON.VideoTexture("VideoAction", self._url, self.scene, true, false, BABYLON.Texture.TRILINEAR_SAMPLINGMODE, { autoPlay: true, autoUpdateTexture: true });
            self._video = Action_VideoPlayOnOBJ._videoDic[self._musicString.value];

            self._newMat.diffuseTexture = self._video;
            if (self._video) {
                if (self._switch.value) {
                    self._video.video.loop = self._musicLoop.value;
                    self._video.video.volume = (self._musicVolume.value);

                    self._video.video.play();
                } else {
                    self._video.video.loop = self._musicLoop.value;
                    self._video.video.volume = (self._musicVolume.value);
                    self._video.video.pause();
                    // 物体材质
                    // this._currentMesh.material = this._oldMat;
                }
            }
        }
    }

    //DO_20220518:物体上视频播放,支持视频ID为变量
    //TODO_20210618:视频路径改成id
    private async initVideo() {
        let self = this;
        //DO_20230313:五代修改
        //资源加载方式修改
        self._url = await BabylonLoader.getAssetUrl(self._musicString.value);
        //self._url = await Resources.GetUrl(self._musicString.value);
        //DO_20211223:VideoTexture只能用户触发才能创建
        if (self._url === '') {
            console.warn('物体上视频播放 视频信息获取失败，asset_id：' + self._musicString.value + '，无法在当前场景中查找到该ID，请检查！');
        }
        else {
            //DO_20220527:物体上视频播放,切换视频时音频未切换
            Action_VideoPlayOnOBJ._videoDic[self._musicString.value] = new BABYLON.VideoTexture("VideoAction", self._url, self.scene, true, false, BABYLON.Texture.TRILINEAR_SAMPLINGMODE, { autoPlay: false, autoUpdateTexture: true });
            self._video = Action_VideoPlayOnOBJ._videoDic[self._musicString.value];
        }
    }

    public paraParser(para_array: string[]): boolean {
        //DO_20221011:播放开始时间,播放结束时间
        //DO_202220601:物体上视频播放,添加控制从头开始播放的变量
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 3, 4, 5, 6, 7, 8)) {
            return false;
        } else {
            // 第1个参数：
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._switch = para0.bool;

            // 第2个参数：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para1, para_array[1], this.nodeID)) {
                return false;
            }
            this._blueOBJ = para1.gameObject;
            //DO_20221228:表格编辑器,自动检测
            if (!VeryEngine.enableLuckySheet) {
                if (this._blueOBJ.value !== null) {
                    if (this._blueOBJ.value.mesh !== null) {
                        this._currentMesh = this._blueOBJ.value.mesh;
                        this._oldMat = this._blueOBJ.value.mesh.material;
                    } else {
                        //DO_20221228:表格编辑器,自动检测,中英文
                        VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[1] + "，{{视频播放物体不存在Mesh网格}}，{{请检查}}！", '', Severity.Error));
                        return false;
                    }
                } else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[1] + "，{{视频播放物体不存在}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }

            // 参数3
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[2])) {
                return false;
            }
            this._musicString = para2.string;
            setTimeout(this.initVideo.bind(this), 0);

            // 参数4
            this._musicLoop.value = true;
            if (para_array.length > 3) {
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[3])) {
                    return false;
                }
                this._musicLoop = para3.bool;
            }

            // 参数5
            this._musicVolume.value = 1;
            if (para_array.length > 4) {
                let para4: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para4, para_array[4])) {
                    return false;
                }
                this._musicVolume = para4.number;
            }

            //DO_202220601:物体上视频播放,添加控制从头开始播放的变量
            // 参数6
            this._musicRestart.value = false;
            if (para_array.length > 5) {
                let para5: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para5, para_array[5])) {
                    return false;
                }
                this._musicRestart = para5.bool;
            }

            //DO_20221011:播放开始时间,播放终止时间
            this._startTime.value = 0;
            if (para_array.length > 6) {
                let para5: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para5, para_array[6])) {
                    return false;
                }
                this._startTime = para5.number;
            }
            //播放终止时间
            this._endTime.value = 0;
            if (para_array.length > 7) {
                let para6: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para6, para_array[7])) {
                    return false;
                }
                this._endTime = para6.number;
            }

            return true;
        }

    }
    public destroy(): void {

    }
}


