export class Action_Open_URL extends VE_ActionBehaviour {

    public get ID(): string {
        return "Open_URL|打开网页";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '打开网页，https://www.baidu.com,打开网页，https://www.baidu.com，当前网页打开,打开网页，https://www.baidu.com，当前网页嵌入，1655959654-878ab54a，右上，(10，10，60，60)';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=669';
    }
    public get className(): string {
        return "Action_Open_URL";
    }

    private _URL: VeryString = new VeryString();
    //DO_20220623:打开网页，当前网页打开,当前网页嵌入
    private _openType: VeryString = new VeryString();
    //返回按钮ID
    private _buttonImage: VeryString = new VeryString();
    //返回按钮定位方式
    private _buttonPosType: VeryString = new VeryString();
    //返回按钮位置大小
    private _isRect: boolean = false;
    private _rect: VeryRect = new VeryRect();
    private _rectArray: VeryNumber[] = [];
    //iframe嵌入网页
    private _iframe: BABYLON.Nullable<HTMLIFrameElement> = null;
    private _button: BABYLON.Nullable<HTMLButtonElement> = null;

    public active(): void {
        let url = this._URL.value;
        let schema = window.location.search;
        if (url.indexOf("?") < 0) {
            if (schema.startsWith("?"))
                schema = schema.substring(1);
            if (schema.length > 0)
                url = url + "?" + schema;
        }
        //DO_20220623:打开网页，当前网页打开,当前网页嵌入
        if (this._openType.value.endsWith('新标签页打开')) {
            window.open(url);
        }
        else if (this._openType.value.endsWith('当前网页打开')) {
            window.open(url, '_self');
        }
        else if (this._openType.value.endsWith('当前网页嵌入')) {
            let that = this;
            //DO_20230313:五代修改
            //资源加载方式修改
            BabylonLoader.getAssetUrl(this._buttonImage.value).then(response => {
            // ossfile.getUrl(GameGlobal.projectID, this._buttonImage.value, GameGlobal.assetsData.assets[this._buttonImage.value].name, GameGlobal.assetsData.assets[this._buttonImage.value].file.hash).then(response => {
                //console.log(that._URL.value);
                //console.log(response);
                //console.log(that._buttonPosType.value);
                var tmpVec = that._rect.value;
                if (!that._isRect) {
                    tmpVec = new BABYLON.Vector4(that._rectArray[0].value, that._rectArray[1].value, that._rectArray[2].value, that._rectArray[3].value);
                }
                //console.log(tmpVec);
                if (that._iframe === null) {
                    that._iframe = document.createElement('iframe');
                    that._iframe.src = url;
                    document.body.appendChild(that._iframe);
                    that._iframe.style.cssText = 'position:absolute;top:0px;left:0px;width:100%;height:100%';
                    this._iframe.onload = function () {
                        if (that._button === null) {
                            that._button = document.createElement('button');
                            var image: HTMLImageElement = document.createElement('img');
                            image.src = response;
                            image.style.cssText = 'width:100%;height:100%';
                            that._button.appendChild(image);
                            document.body.appendChild(that._button);
                            var left = tmpVec.x + 'px';
                            var top = tmpVec.y + 'px';
                            if (that._buttonPosType.value === '右上') {
                                left = (window.innerWidth - tmpVec.x - tmpVec.z) + 'px';
                                top = (tmpVec.y) + 'px';
                            }
                            else if (that._buttonPosType.value === '居中') {
                                left = (window.innerWidth / 2 + tmpVec.x - tmpVec.z / 2) + 'px';
                                top = (window.innerHeight / 2 + tmpVec.y - tmpVec.w / 2) + 'px';
                            }
                            else if (that._buttonPosType.value === '左下') {
                                left = (tmpVec.x) + 'px';
                                top = (window.innerHeight - tmpVec.y - tmpVec.w) + 'px';
                            }
                            else if (that._buttonPosType.value === '右下') {
                                left = (window.innerWidth - tmpVec.x - tmpVec.z) + 'px';
                                top = (window.innerHeight - tmpVec.y - tmpVec.w) + 'px';
                            }
                            that._button.style.cssText = 'border:0px;padding:0px;background:transparent;position:absolute;top:' + top + ';left:' + left + ';width:' + tmpVec.z + 'px;height:' + tmpVec.w + 'px';
                            that._button.onclick = function () {
                                //网页清除
                                that._iframe.src = 'about:blank';
                                try {
                                    that._iframe.contentWindow.document.write('');
                                    that._iframe.contentWindow.document.clear();
                                }
                                catch (e) { }
                                that._iframe.parentNode.removeChild(that._iframe);
                                that._button.parentNode.removeChild(that._button);
                                //记录清除
                                that._iframe = null;
                                that._button = null;
                            };
                        }
                    };
                }
            });
        }
    }


    public paraParser(para_array: string[]): boolean {
        //DO_20220623:打开网页，当前网页打开,当前网页嵌入
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 1, 2, 5)) {
            return false;
        } else {
            // 参数1：字符串
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._URL = para1.string;

            //DO_20220623:打开网页，当前网页打开,当前网页嵌入
            this._openType.value = '新标签页打开';
            if (para_array.length > 1) {
                //DO_20220830:触发响应中参数支持中英文
                if (para_array[1] === "当前网页打开" || para_array[1].toLowerCase() == "replacecurrentpage") {
                    this._openType.value = "当前网页打开";
                }
                else if (para_array[1] === "当前网页嵌入" || para_array[1].toLowerCase() == "embedincurrentpage") {
                    this._openType.value = "当前网页嵌入";
                }
                else if (para_array[1] === "新标签页打开" || para_array[1].toLowerCase() == "newpage") {
                    this._openType.value = "新标签页打开";
                }
                else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', `${this.ID} {{响应传入参数错误}}，{{参数}}：${para_array[1]}，{{网页打开方式只能是}}新标签页打开|newpage,当前网页打开|replacecurrentpage,当前网页嵌入|embedincurrentpage{{这三种中的一种}}，{{请检查}}！`, '', Severity.Error));
                    return false;
                }
            }
            if (para_array.length > 2) {
                let para2: VeryParas = new VeryParas();
                if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[2])) {
                    return false;
                }
                this._buttonImage = para2.string;
            }
            //DO_20220830:触发响应中参数支持中英文
            this._buttonPosType.value = '右上';
            if (para_array.length > 3) {
                if (para_array[3] === '右上' || para_array[3].toLowerCase() == 'righttop') {
                    this._buttonPosType.value = '右上';
                }
                else if (para_array[3] === '右下' || para_array[3].toLowerCase() == 'rightbottom') {
                    this._buttonPosType.value = '右下';
                }
                else if (para_array[3] === '左上' || para_array[3].toLowerCase() == 'lefttop') {
                    this._buttonPosType.value = '左上';
                }
                else if (para_array[3] === '左下' || para_array[3].toLowerCase() == 'leftbottom') {
                    this._buttonPosType.value = '左下';
                }
                else if (para_array[3] === '居中' || para_array[3].toLowerCase() == 'center') {
                    this._buttonPosType.value = '居中';
                }
                else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', `${this.ID} {{响应传入参数错误}}，参数：${para_array[3]}，{{当前网页嵌入的返回按钮定位方式只能是}}右上|righttop，右下|rightbottom，左上|lefttop，左下|leftbottom，居中|center{{这5种中的一种}}，{{请检查}}！`, '', Severity.Error));
                    return false;
                }
            }
            if (para_array.length > 4) {
                // 第5个参数：显示区域
                let para5: VeryParas = new VeryParas();
                if (!ParaParserUtility.RectOrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para5, para_array[4])) {
                    return false;
                }
                this._isRect = para5.isRect;
                this._rect = para5.rect;
                this._rectArray = para5.rectNumbers;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}

