//DO_20220224:获取当前硬件平台信息
export class Action_GetHardware extends VE_ActionBehaviour {

    public get ID(): string {
        return "GetHardware|获取当前硬件平台信息";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '获取当前硬件平台信息，*硬件平台';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=902';
    }
    public get className(): string {
        return "Action_GetHardware";
    }

    private _hardwareName: VeryString = new VeryString();

    public active(): void {
        //console.warn('获取当前硬件平台');
        //console.log(navigator.userAgent.toLowerCase());
        var hasVR = false;
        if (Action_XR_Enable._xrHelper !== null) {
            //console.log(Action_XR_Enable._xrHelper.enterExitUI);
            //console.log(Action_XR_Enable._xrHelper.enterExitUI.overlay.clientHeight);
            hasVR = (Action_XR_Enable._xrHelper.enterExitUI.overlay.clientHeight !== 0);
        }
        var userAgent = navigator.userAgent.toLowerCase();
        var name = 'Unknown';
        var version = 'Unknown';
        if (userAgent.indexOf('win') > -1) {
            name = 'Windows';
            if (userAgent.indexOf('windows nt 5.0') > -1) {
                version = 'Windows 2000';
            } else if (userAgent.indexOf('windows nt 5.1') > -1 || userAgent.indexOf('windows nt 5.2') > -1) {
                version = 'Windows XP';
            } else if (userAgent.indexOf('windows nt 6.0') > -1) {
                version = 'Windows Vista';
            } else if (userAgent.indexOf('windows nt 6.1') > -1 || userAgent.indexOf('windows 7') > -1) {
                version = 'Windows 7';
            } else if (userAgent.indexOf('windows nt 6.2') > -1 || userAgent.indexOf('windows 8') > -1) {
                version = 'Windows 8';
            } else if (userAgent.indexOf('windows nt 6.3') > -1) {
                version = 'Windows 8.1';
            } else if (userAgent.indexOf('windows nt 6.2') > -1 || userAgent.indexOf('windows nt 10.0') > -1) {
                version = 'Windows 10';
            } else {
                version = 'Unknown';
            }
            this._hardwareName.value = "PC";
            //DO_20220224:获取当前硬件平台信息,PCVR
            if (hasVR) {
                this._hardwareName.value = "PCVR";
            }
        } else if (userAgent.indexOf('iphone') > -1) {
            name = 'Phone';
            this._hardwareName.value = "Phone";
        }
        else if (userAgent.indexOf('android') > -1) {
            name = 'Android';
            this._hardwareName.value = "Phone";
            //获取当前硬件平台,AndroidVR
            if (userAgent.indexOf('mobile vr')) {
                this._hardwareName.value = "AndroidVR";
            }
        }
        else if (userAgent.indexOf('mac') > -1) {
            name = 'Mac';
            this._hardwareName.value = "PC";
        } else if (userAgent.indexOf('x11') > -1 || userAgent.indexOf('unix') > -1 || userAgent.indexOf('sunname') > -1 || userAgent.indexOf('bsd') > -1) {
            name = 'Unix';
            this._hardwareName.value = "PC";
        } else if (userAgent.indexOf('linux') > -1) {
            name = 'Linux';
            this._hardwareName.value = "PC";
        }
        else {
            name = 'Unknown';
        }
        //console.log(this._hardwareName.value);
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 1)) {
            return false;
        } else {

            // 参数1：字符串
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._hardwareName = para1.string;

            return true;
        }
    }
    public destroy(): void {

    }
}

