    //DO_20230422:五代2D画布实现方式改变
    //检查点在Rect里面的位置：1234四个区域，-1表示不再区域里面
    private PointInRect(point: BABYLON.Vector2, rect: BABYLON.Vector4): number {
        if (point.x >= rect.x && point.x <= (rect.x + rect.z) && point.y >= rect.y && point.y <= (rect.y + rect.w)) {
            if (((point.x - rect.x) <= (rect.z / 2)) && ((point.y - rect.y) <= (rect.w / 2))) {
                return 1;
            }
            if (((point.x - rect.x) > (rect.z / 2)) && ((point.y - rect.y) <= (rect.w / 2))) {
                return 2;
            }
            if (((point.x - rect.x) <= (rect.z / 2)) && ((point.y - rect.y) > (rect.w / 2))) {
                return 3;
            }
            if (((point.x - rect.x) > (rect.z / 2)) && ((point.y - rect.y) > (rect.w / 2))) {
                return 4;
            }
        }
        return -1;
    }
    //添加引出线显示
    private AddLabel(tmpOBJ: Nullable<GameObject>, tmpLabel: string) {
        this.lineColor = this._lineColor.value;
        if (!this._colorIsVec) {
            this.lineColor = new BABYLON.Vector3(this._lineColor2[0].value, this._lineColor2[1].value, this._lineColor2[2].value);
        }
        var tmpCamera = this.scene.activeCamera;
        var lineLength = 50;
        var rect = new BABYLON.Vector4(0, 0, this.scene.getEngine().getRenderWidth(), this.scene.getEngine().getRenderHeight());
        if (tmpOBJ != null && tmpCamera != null) {
            var startpoint1 = BABYLON.Vector3.Project(tmpOBJ.transform.position, BABYLON.Matrix.Identity(), this.scene.getTransformMatrix(), tmpCamera.viewport.toGlobal(this.scene.getEngine().getRenderWidth(), this.scene.getEngine().getRenderHeight()));
            var startPoint = new BABYLON.Vector2(startpoint1.x, startpoint1.y);
            var pointPos = this.PointInRect(new BABYLON.Vector2(startPoint.x, startPoint.y), rect);
            //物体位置超出屏幕：在屏幕范围内渲染才能显示
            //TODO_20210729:物体在相机背面处理
            if (pointPos > 0 && startpoint1.z < 1) {
                var endpoint = new BABYLON.Vector2(startPoint.x + lineLength, startPoint.y - lineLength);
                var buttonLeft = endpoint.x;
                var buttonTop = endpoint.y;
                //TODO:计算显示名长度
                var tmpWidth = 150;
                if (tmpLabel.length > 3) {
                    tmpWidth = (tmpLabel.length * 20) + 90;

                    //TODO_20210630:小写字母和数字宽度减半
                    var count = 0
                    for (let i = 0; i < tmpLabel.length; i++) {
                        var char = tmpLabel.charCodeAt(i);
                        if (char >= 97 && char <= 122) {
                            count++;
                        }
                        if (char >= 48 && char <= 57) {
                            count++;
                        }
                    }
                    tmpWidth = tmpWidth - count * 10;
                }

                var tmpHeight = 54;
                //调节屏幕上需要显示的标注的显示位置
                if (pointPos == 1 || pointPos == 3) {
                    this._leftData[this._leftData.length] = new LabelData(tmpOBJ.name, startPoint, BABYLON.Vector2.Zero(), tmpLabel, new BABYLON.Vector4(buttonLeft, buttonTop, tmpWidth, tmpHeight));
                }
                else {
                    this._rightData[this._rightData.length] = new LabelData(tmpOBJ.name, startPoint, BABYLON.Vector2.Zero(), tmpLabel, new BABYLON.Vector4(buttonLeft, buttonTop, tmpWidth, tmpHeight));
                }
            }
        }
    }
