export class Action_MirrorTexture extends VE_ActionBehaviour {

    public get ID(): string {
        return "Set_MirrorTexture|设置镜面倒影";
    }

    public get className(): string {
        return "Action_MirrorTexture";
    }

    private _obj: VeryGameObject = new VeryGameObject();
    private _ratio: VeryNumber = new VeryNumber();
    private _level: VeryNumber = new VeryNumber();
    private _renderList: VeryGameObject[] = [];

    private _mirrorTexture: BABYLON.MirrorTexture;
    private _init: boolean = false;


    public active(): void {

        // console.log('active');

        if (!this._init) {
            this._init = true;
            if (this._obj.value && this._obj.value.mesh) {
                let glass = this._obj.value.mesh;

                //Ensure working with new values for glass by computing and obtaining its worldMatrix
                glass.computeWorldMatrix(true);
                var glass_worldMatrix = glass.getWorldMatrix();

                //Obtain normals for plane and assign one of them as the normal
                var glass_vertexData = glass.getVerticesData('normal');
                var glassNormal = new BABYLON.Vector3(glass_vertexData[0], glass_vertexData[1], glass_vertexData[2]);
                //Use worldMatrix to transform normal into its current value
                glassNormal = BABYLON.Vector3.TransformNormal(glassNormal, glass_worldMatrix)

                //Create reflecting surface for mirror surface
                var reflector = BABYLON.Plane.FromPositionAndNormal(glass.position, glassNormal.scale(-1));
                this._mirrorTexture.mirrorPlane = reflector;

                if (glass.material && glass.material !== this.scene.defaultMaterial) {
                    if (glass.material instanceof BABYLON.StandardMaterial) {
                        glass.material.reflectionTexture = this._mirrorTexture;
                    } else if (glass.material instanceof BABYLON.PBRMaterial) {
                        glass.material.reflectionTexture = this._mirrorTexture;
                    }
                } else {
                    let mirrorMaterial = new BABYLON.StandardMaterial('__mirror__', this.scene);
                    mirrorMaterial.reflectionTexture = this._mirrorTexture;
                    glass.material = mirrorMaterial;
                }
            }
        }


        // if (this._obj.value != null) {
        //     if (this._childActive.value) {
        //         this.ActiveRecursion(this._obj.value.transform.transformNode, this._isActive.value);
        //     }
        //     else {
        //         this._obj.value.transform.transformNode?.setEnabled(this._isActive.value);
        //     }
        // }
    }
    // private ActiveRecursion(obj: BABYLON.Nullable<BABYLON.TransformNode>, active: boolean) {
    //     obj?.setEnabled(active);
    //     if (obj != null && obj.getChildTransformNodes().length > 0) {
    //         for (var i = 0; i < obj.getChildTransformNodes().length; i++) {
    //             this.ActiveRecursion(obj.getChildTransformNodes()[i], active);
    //         }
    //     }
    // }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 4)) {
            return false;
        } else {
            // 参数1：平面物体
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0], this.nodeID)) {
                return false;
            }
            this._obj = para1.gameObject;

            // 参数2：分辨率
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._ratio = para2.number;

            // 参数3：level
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                return false;
            }
            this._level = para3.number;

            // 参数4：镜面物体
            let objList = para_array[3].split(/[,，]/);
            // console.warn(objList);
            if (objList && objList.length > 0) {
                for (let i = 0; i < objList.length; i++) {
                    objList[i] = objList[i].trim();
                    let para: VeryParas = new VeryParas();
                    if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para, objList[i], this.nodeID)) {
                        return false;
                    }
                    this._renderList.push(para.gameObject);
                }
            }
            // console.error(this._renderList);

            this._mirrorTexture = new BABYLON.MirrorTexture('__mirror__', this._ratio.value, this.scene, true);
            this._mirrorTexture.level = this._level.value;
            this._mirrorTexture.clearColor = new BABYLON.Color4(0, 0, 0, 1);

            const getChildren = (node: BABYLON.TransformNode | BABYLON.AbstractMesh, render_list: BABYLON.AbstractMesh[]) => {
                if (node instanceof BABYLON.AbstractMesh) {
                    render_list.push(node);
                }
                let children = node.getChildren();
                if (children && children.length > 0) {
                    for (let i = 0; i < children.length; i++) {
                        if (children[i] instanceof BABYLON.TransformNode || children[i] instanceof BABYLON.AbstractMesh) {
                            getChildren(<BABYLON.TransformNode>children[i], render_list);
                        }
                    }
                }
            }

            for (let i = 0; i < this._renderList.length; i++) {
                // TODO: 递归
                if (this._renderList[i].value.mesh) {
                    getChildren(this._renderList[i].value.mesh, this._mirrorTexture.renderList);
                } else if (this._renderList[i].value.transform.transformNode) {
                    getChildren(this._renderList[i].value.transform.transformNode, this._mirrorTexture.renderList);
                }
            }

            return true;
        }
    }

    public destroy(): void {

    }
}

VE_Actions.addAction(Action_MirrorTexture);



