export class Light_Tools {
    /*
      获取UI
    */
    public static GetLight(scene: BABYLON.Scene, name: string, id: string): BABYLON.Nullable<BABYLON.Light> {
        for (var i = 0; i < scene.lights.length; i++) {
            if (name == scene.lights[i].name) {
                return scene.lights[i];
            }
        }
        console.error(id + "--响应参数出错--" + name);
        return null;
    }

    //DO_20221228:表格编辑器,自动检测
    public static GetChildLight(name: string, host_node_id: string, ID: string, log: boolean = true): BABYLON.Nullable<BABYLON.Light> {
        let light: BABYLON.Nullable<BABYLON.Light> = null;
        let obj = GameObject.FindByName(name, host_node_id);
        if (obj !== null && obj.transform.transformNode !== null) {
            let children = obj.transform.transformNode.getChildren();
            if (children.length > 0) {
                if (children[0] instanceof BABYLON.Light) {
                    light = <BABYLON.Light>children[0];
                    return light;
                } else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    if (log && !VeryEngine.enableLuckySheet) VE_ErrorManager.Add(new VE_Error('', ID + " {{响应}} {{传入参数格式错误}}，{{灯光名}}： " + name + "，{{该灯光无法在场景中找到}}！", '', Severity.Error));
                    return light;
                }
            } else {
                //DO_20221228:表格编辑器,自动检测,中英文
                if (log && !VeryEngine.enableLuckySheet) VE_ErrorManager.Add(new VE_Error('', ID + " {{响应}} {{传入参数格式错误}}，{{灯光名}}： " + name + "，{{该灯光无法在场景中找到}}！", '', Severity.Error));
                return light;
            }
        } else {
            //DO_20221228:表格编辑器,自动检测,中英文
            if (log && !VeryEngine.enableLuckySheet) VE_ErrorManager.Add(new VE_Error('', ID + " {{响应}} {{传入参数格式错误}}，{{灯光名}}： " + name + "，{{该灯光无法在场景中找到}}！", '', Severity.Error));
            return light;
        }
    }
}