export class Action_Clock extends VE_ActionBehaviour {

    public get ID(): string {
        return "Clock|计时器";
    }
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '计时器，*时间字符串，*计时秒数，true';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=928';
    }
    public get className(): string {
        return "Action_Clock";
    }

    private _timeString: VeryString = new VeryString();
    private _secondsNumber: VeryNumber = new VeryNumber();
    private _restartBool: VeryBool = new VeryBool();

    private _currentTotalTime: number = 0;

    public active(): void {
        //console.log('active--' + this._restartBool.value);
        if (this._restartBool.value) {
            this._currentTotalTime = 0;
            this._secondsNumber.value = parseInt(this._currentTotalTime.toString());
            this._timeString.value = this.TimeConvert(this._secondsNumber.value);
        }
    }
    public onUpdate(): void {
        //console.log('onUpdate--');
        this._currentTotalTime += Time.deltaTime;
        this._secondsNumber.value = parseInt(this._currentTotalTime.toString());
        this._timeString.value = this.TimeConvert(this._secondsNumber.value);
    }
    public onDisable(): void {
        //console.log('onDisable--');
    }

    private TimeConvert(_currentTotalTime: number): string {
        var minutes = parseInt((_currentTotalTime / 60).toString());
        var seconds = parseInt((_currentTotalTime % 60).toString());
        return ((minutes < 10) ? ('0' + minutes.toString()) : minutes.toString()) + ":" + ((seconds < 10) ? ('0' + seconds.toString()) : seconds.toString());
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3)) {
            return false;
        } else {
            // 参数1：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaOnlyVar(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._timeString = para1.string;

            // 参数2：
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaOnlyVar(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._secondsNumber = para2.number;

            // 参数3：
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                return false;
            }
            this._restartBool = para3.bool;

            return true;
        }
    }
    public destroy(): void {

    }
}

