export class Action_Mouse_Pick extends VE_ActionBehaviour {

    public get ID(): string {
        return "Mouse_Pick|鼠标点选";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '鼠标点选，*result_bool，null，*result_vec，null';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=561';
    }
    public get className(): string {
        return "Action_Mouse_Pick";
    }

    private _blueBool: VeryBool = new VeryBool();
    private _isBool = false;

    private _blueGameObject: VeryGameObject = new VeryGameObject();
    private _isGameObject = false;

    private _blueVector3: VeryVector3 = new VeryVector3();
    private _isVector3 = false;

    private _blueFloat: VeryNumber = new VeryNumber();
    private _isFloat = false;

    private _observer: Nullable<BABYLON.Observer<BABYLON.PointerInfo>> = null;

    public active(): void {
        this._observer = this.scene.onPointerObservable.add((pointerInfo) => {
            switch (pointerInfo.type) {
                case BABYLON.PointerEventTypes.POINTERDOWN:
                    if (pointerInfo.pickInfo != null) {
                        if (this._isBool) {
                            this._blueBool.value = (pointerInfo.pickInfo.pickedMesh != null);
                        }
                        if (this._isGameObject) {
                            if (pointerInfo.pickInfo.pickedMesh != null) {
                                this._blueGameObject.setValue(pointerInfo.pickInfo.pickedMesh);
                            }
                            else {
                                this._blueGameObject.value = null;
                            }
                        }
                        if (this._isVector3) {
                            if (pointerInfo.pickInfo.pickedPoint != null) {
                                this._blueVector3.value = pointerInfo.pickInfo.pickedPoint;
                            }
                            else {
                                this._blueVector3.value = BABYLON.Vector3.Zero();
                            }
                        }
                        if (this._isFloat) {
                            this._blueFloat.value = pointerInfo.pickInfo.distance;
                        }
                    }
                    break;
            };
        });
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 4)) {
            return false;
        } else {
            //参数1
            if (para_array[0].toLowerCase() == "null" || para_array[0].toLowerCase() == "none") {

            }
            else {
                this._isBool = true;
                var para0 = new VeryParas();
                if (!ParaParserUtility.BoolParaOnlyVar(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                    return false;
                }
                this._blueBool = para0.bool;
            }

            //参数2
            if (para_array[1].toLowerCase() == "null" || para_array[1].toLowerCase() == "none") {

            }
            else {
                this._isGameObject = true;
                var para0 = new VeryParas();
                if (!ParaParserUtility.GameObjectParaOnlyVar(this.objectID, this.ID, ParaType.Action, para0, para_array[1])) {
                    return false;
                }
                this._blueGameObject = para0.gameObject;
            }

            //参数3
            if (para_array[2].toLowerCase() == "null" || para_array[2].toLowerCase() == "none") {

            }
            else {
                this._isVector3 = true;
                var para0 = new VeryParas();
                if (!ParaParserUtility.Vector3Para(this.objectID, this.ID, ParaType.Action, para0, para_array[2])) {
                    return false;
                }
                this._blueVector3 = para0.vector3;
            }

            //参数4
            if (para_array[3].toLowerCase() == "null" || para_array[3].toLowerCase() == "none") {

            }
            else {
                this._isFloat = true;
                var para0 = new VeryParas();
                if (!ParaParserUtility.NumberParaOnlyVar(this.objectID, this.ID, ParaType.Action, para0, para_array[3])) {
                    return false;
                }
                this._blueFloat = para0.number;
            }

            return true;
        }
    }
    public destroy(): void {
        if (this._observer) {
            this.scene.onPointerObservable.remove(this._observer);
        }
        this._observer = null;
    }
}

export class Action_MouseDrag extends VE_ActionBehaviour {

    public get ID(): string {
        return "MouseDrag|鼠标拖拽";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '鼠标拖拽，自由，left，X，物体名~包括，（Cube，Sphere）';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=562';
    }
    public get className(): string {
        return "Action_MouseDrag";
    }

    //拖拽方式
    private _choose = "";
    private _moveRef: BABYLON.Nullable<Transform> = null;
    //拖拽鼠标按钮
    private _mouseBtn = 0;
    private _isPlane = false;
    //拖拽轴
    private _move = "";
    //过滤条件
    private _filter = false;
    private _include = true;
    private _filterName: string[] = [];

    //拖拽
    private startingPoint: BABYLON.Nullable<BABYLON.Vector2> = null;
    private currentMesh: BABYLON.Nullable<BABYLON.AbstractMesh> = null;
    private EPSILON: number = 0.00001;

    private _observer: Nullable<BABYLON.Observer<BABYLON.PointerInfo>> = null;

    public active(): void {
        let self = this;
        this._observer = this.scene.onPointerObservable.add((pointerInfo) => {
            //DO_20211025:鼠标拖拽控制关闭
            if (!self.enabled) {
                return;
            }
            switch (pointerInfo.type) {
                case BABYLON.PointerEventTypes.POINTERDOWN:
                    if (pointerInfo.pickInfo && pointerInfo.pickInfo.pickedMesh && pointerInfo.event.button === this._mouseBtn) {
                        if (!this._filter) {
                            this.pointerDown(pointerInfo.pickInfo.pickedMesh)
                        }
                        else {
                            if (this._include) {
                                if (this._filterName.indexOf(pointerInfo.pickInfo.pickedMesh.name) != -1) {
                                    this.pointerDown(pointerInfo.pickInfo.pickedMesh)
                                }
                            }
                            else {
                                if (this._filterName.indexOf(pointerInfo.pickInfo.pickedMesh.name) == -1) {
                                    this.pointerDown(pointerInfo.pickInfo.pickedMesh)
                                }
                            }
                        }
                    }
                    break;
                case BABYLON.PointerEventTypes.POINTERUP:
                    if (pointerInfo.event.button === this._mouseBtn)
                        this.pointerUp();
                    break;
                case BABYLON.PointerEventTypes.POINTERMOVE:
                    this.pointerMove(pointerInfo);
                    break;
            }
        });
    }
    private getPosition(): BABYLON.Nullable<BABYLON.Vector2> {
        return new BABYLON.Vector2(this.scene.pointerX, this.scene.pointerY);
    }
    private pointerDown(mesh: BABYLON.AbstractMesh) {
        this.currentMesh = mesh;
        let tmpCamera = this.scene.activeCamera;
        this.startingPoint = this.getPosition();
        if (this.startingPoint) { // we need to disconnect camera from canvas
            setTimeout(function () {
                if (tmpCamera)
                    tmpCamera.detachControl(BabylonEngine.Canvas);
            }, 0);
        }
    }

    private pointerUp() {
        if (this.startingPoint) {
            let tmpCamera = this.scene.activeCamera;
            if (tmpCamera)
                tmpCamera.attachControl(BabylonEngine.Canvas, true);
            this.startingPoint = null;
            return;
        }
    }

    private pointerMove(pointerInfo: BABYLON.PointerInfo) {
        if (!this.startingPoint) {
            return;
        }
        var current = this.getPosition();
        if (!current) {
            return;
        }

        var diff = current.subtract(this.startingPoint);
        var tmpCamera = this.scene.activeCamera;
        //物体拖拽移动
        if (this.currentMesh && tmpCamera) {
            var startpoint1 = BABYLON.Vector3.Project(this.currentMesh.position, BABYLON.Matrix.Identity(), this.scene.getTransformMatrix(), tmpCamera.viewport.toGlobal(this.scene.getEngine().getRenderWidth(), this.scene.getEngine().getRenderHeight()));
            var tmpVec3 = BABYLON.Vector3.Unproject(new BABYLON.Vector3(this.startingPoint.x, this.startingPoint.y, startpoint1.z), this.scene.getEngine().getRenderWidth(), this.scene.getEngine().getRenderHeight(), BABYLON.Matrix.Identity(), tmpCamera.getViewMatrix(), this.scene.getProjectionMatrix());
            var offset = this.currentMesh.position.subtract(tmpVec3);
            //TODO_20210805:自由拖拽效果修改
            if (this._choose === 'free') {
                //鼠标当前屏幕坐标转化为世界坐标
                var curPosition = BABYLON.Vector3.Unproject(new BABYLON.Vector3(current.x, current.y, startpoint1.z), this.scene.getEngine().getRenderWidth(), this.scene.getEngine().getRenderHeight(), BABYLON.Matrix.Identity(), tmpCamera.getViewMatrix(), this.scene.getProjectionMatrix());
                this.currentMesh.position = curPosition.add(offset);
            }
            else if (this._choose === 'world') {
                if (!this._isPlane)  //轴移动
                {
                    var z = BABYLON.Vector3.Project(this.currentMesh.position, BABYLON.Matrix.Identity(), this.scene.getTransformMatrix(), tmpCamera.viewport.toGlobal(this.scene.getEngine().getRenderWidth(), this.scene.getEngine().getRenderHeight())).z;
                    //鼠标当前屏幕坐标转化为世界坐标
                    var curPosition = BABYLON.Vector3.Unproject(new BABYLON.Vector3(current.x, current.y, z), this.scene.getEngine().getRenderWidth(), this.scene.getEngine().getRenderHeight(), BABYLON.Matrix.Identity(), tmpCamera.getViewMatrix(), this.scene.getProjectionMatrix());
                    if (this._move === 'x') {
                        this.currentMesh.position = new BABYLON.Vector3(curPosition.x + offset.x, this.currentMesh.position.y, this.currentMesh.position.z);
                    }
                    else if (this._move === 'y') {
                        this.currentMesh.position = new BABYLON.Vector3(this.currentMesh.position.x, curPosition.y + offset.y, this.currentMesh.position.z);
                    }
                    else if (this._move === 'z') {
                        this.currentMesh.position = new BABYLON.Vector3(this.currentMesh.position.x, this.currentMesh.position.y, curPosition.z + offset.z);
                    }
                }
                else {
                    //鼠标当前屏幕坐标转化为世界坐标
                    var ray = pointerInfo.pickInfo.ray;
                    var t = 1;
                    if (this._move === 'xy' || this._move === 'yx') //求直线与z = 常量 平面的交点
                    {
                        if (Math.abs(ray.direction.z) > this.EPSILON) {
                            t = (this.currentMesh.position.z - ray.origin.z) / ray.direction.z;
                            this.currentMesh.position = new BABYLON.Vector3(ray.origin.x + ray.direction.x * t + offset.x, ray.origin.y + ray.direction.y * t + offset.y, this.currentMesh.position.z);
                        }
                    }
                    else if (this._move === 'xz' || this._move === 'zx') //求直线与y = 常量 平面的交点
                    {
                        if (Math.abs(ray.direction.y) > this.EPSILON) {
                            t = (this.currentMesh.position.y - ray.origin.y) / ray.direction.y;
                            this.currentMesh.position = new BABYLON.Vector3(ray.origin.x + ray.direction.x * t + offset.x, this.currentMesh.position.y, ray.origin.z + ray.direction.z * t + offset.z);
                        }
                    }
                    else //求直线与x = 常量 平面的交点
                    {
                        if (Math.abs(ray.direction.x) > this.EPSILON) {
                            t = (this.currentMesh.position.x - ray.origin.x) / ray.direction.x;
                            this.currentMesh.position = new BABYLON.Vector3(this.currentMesh.position.x, ray.origin.y + ray.direction.y * t + offset.y, ray.origin.z + ray.direction.z * t + offset.z);
                        }
                    }
                }
            }
            else if (this._choose === 'self') {
                if (!this._isPlane)  //轴移动
                {
                    var z = BABYLON.Vector3.Project(this.currentMesh.position, BABYLON.Matrix.Identity(), this.scene.getTransformMatrix(), tmpCamera.viewport.toGlobal(this.scene.getEngine().getRenderWidth(), this.scene.getEngine().getRenderHeight())).z;
                    //鼠标当前屏幕坐标转化为世界坐标                            
                    var curPosition = BABYLON.Vector3.Unproject(new BABYLON.Vector3(current.x, current.y, z), this.scene.getEngine().getRenderWidth(), this.scene.getEngine().getRenderHeight(), BABYLON.Matrix.Identity(), tmpCamera.getViewMatrix(), this.scene.getProjectionMatrix());

                    let matrix: BABYLON.Matrix = BABYLON.Matrix.Invert(this.currentMesh.computeWorldMatrix());
                    var localPosition = BABYLON.Vector3.TransformCoordinates(curPosition.add(offset), matrix);
                    if (this._move === 'x') {
                        const matrix = this.currentMesh.computeWorldMatrix(true);
                        const Pos = BABYLON.Vector3.TransformCoordinates(new BABYLON.Vector3(localPosition.x, 0, 0), matrix);
                        this.currentMesh.position = new BABYLON.Vector3(Pos.x, Pos.y, Pos.z);
                    }
                    else if (this._move === 'y') {
                        const matrix = this.currentMesh.computeWorldMatrix(true);
                        const Pos = BABYLON.Vector3.TransformCoordinates(new BABYLON.Vector3(0, localPosition.y, 0), matrix);
                        this.currentMesh.position = new BABYLON.Vector3(Pos.x, Pos.y, Pos.z);
                    }
                    else if (this._move === 'z') {
                        const matrix = this.currentMesh.computeWorldMatrix(true);
                        const Pos = BABYLON.Vector3.TransformCoordinates(new BABYLON.Vector3(0, 0, localPosition.z), matrix);
                        this.currentMesh.position = new BABYLON.Vector3(Pos.x, Pos.y, Pos.z);
                    }

                }
                else {
                    //鼠标当前屏幕坐标转化为世界坐标
                    var ray = pointerInfo.pickInfo.ray;
                    var t = 1;
                    let matrix: BABYLON.Matrix = BABYLON.Matrix.Invert(this.currentMesh.computeWorldMatrix());
                    let pointA: BABYLON.Vector3 = BABYLON.Vector3.TransformCoordinates(ray.direction, matrix);
                    let pointOrigin: BABYLON.Vector3 = BABYLON.Vector3.TransformCoordinates(BABYLON.Vector3.Zero(), matrix);
                    var transDirection = pointA.subtract(pointOrigin);
                    if (this._move === 'xy' || this._move === 'yx') //求直线与z = 常量 平面的交点
                    {
                        if (Math.abs(transDirection.z) > this.EPSILON) {
                            let matrix: BABYLON.Matrix = BABYLON.Matrix.Invert(this.currentMesh.computeWorldMatrix());
                            var point = BABYLON.Vector3.TransformCoordinates(ray.origin.add(offset), matrix);
                            var movePoint = BABYLON.Vector3.TransformCoordinates(this.currentMesh.position, matrix);;

                            t = (movePoint.z - point.z) / transDirection.z;
                            var localPoint = new BABYLON.Vector3(point.x + transDirection.x * t, point.y + transDirection.y * t, movePoint.z);
                            const matrix2 = this.currentMesh.computeWorldMatrix(true);
                            const Pos = BABYLON.Vector3.TransformCoordinates(localPoint, matrix2);
                            this.currentMesh.position = Pos;
                        }
                    }
                    else if (this._move === 'xz' || this._move === 'zx') //求直线与y = 常量 平面的交点
                    {
                        if (Math.abs(transDirection.y) > this.EPSILON) {
                            let matrix: BABYLON.Matrix = BABYLON.Matrix.Invert(this.currentMesh.computeWorldMatrix());
                            var point = BABYLON.Vector3.TransformCoordinates(ray.origin.add(offset), matrix);
                            var movePoint = BABYLON.Vector3.TransformCoordinates(this.currentMesh.position, matrix);;

                            t = (movePoint.y - point.y) / transDirection.y;
                            var localPoint = new BABYLON.Vector3(point.x + transDirection.x * t, movePoint.y, point.z + transDirection.z * t);
                            const matrix2 = this.currentMesh.computeWorldMatrix(true);
                            const Pos = BABYLON.Vector3.TransformCoordinates(localPoint, matrix2);
                            this.currentMesh.position = Pos;
                        }
                    }
                    else if (this._move === 'yz' || this._move === 'zy') //求直线与x = 常量 平面的交点
                    {
                        if (Math.abs(transDirection.x) > this.EPSILON) {
                            let matrix: BABYLON.Matrix = BABYLON.Matrix.Invert(this.currentMesh.computeWorldMatrix());
                            var point = BABYLON.Vector3.TransformCoordinates(ray.origin.add(offset), matrix);
                            var movePoint = BABYLON.Vector3.TransformCoordinates(this.currentMesh.position, matrix);;

                            t = (movePoint.x - point.x) / transDirection.x;
                            var localPoint = new BABYLON.Vector3(movePoint.x, point.y + transDirection.y * t, point.z + transDirection.z * t);
                            const matrix2 = this.currentMesh.computeWorldMatrix(true);
                            const Pos = BABYLON.Vector3.TransformCoordinates(localPoint, matrix2);
                            this.currentMesh.position = Pos;
                        }
                    }
                }
            }
            //TODO:物体模式未实现;x,y,z,xy,xz,yz轴6种模式未实现
            else if (this._choose == 'someObject') {

            }
        }
        this.startingPoint = current;
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3, 5)) {
            return false;
        } else {
            //参数1
            var firstStr = para_array[0].toLowerCase();
            if (firstStr === 'world' || firstStr === '世界') {
                this._choose = 'world';
            }
            else if (firstStr === 'self' || firstStr === '相对' || firstStr === '自身') {
                this._choose = 'self';
            }
            else if (firstStr === 'free' || firstStr === '自由') {
                this._choose = 'free';
            }
            else {
                var tempObj = new VeryGameObject();
                let para1 = new VeryParas();
                if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0], this.nodeID)) {
                    return false;
                }
                tempObj = para1.gameObject;
                //DO_20221228:表格编辑器,自动检测
                if (!VeryEngine.enableLuckySheet) {
                    if (tempObj.value === null) {
                        //DO_20221228:表格编辑器,自动检测,中英文
                        VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[0] + "，{{无法在场景中查找到该物体}}，{{请检查}}！", '', Severity.Error));
                        return false;
                    }
                    this._moveRef = tempObj.value.transform;
                    this._choose = "someObject";
                }
            }

            //参数2
            var secondStr = para_array[1].toLowerCase();
            if (secondStr === "0" || secondStr === "left" || secondStr === "左") {
                this._mouseBtn = 0;
            }
            else if (secondStr === "1" || secondStr === "right" || secondStr === "右") {
                this._mouseBtn = 2;
            }
            else if (secondStr === "2" || secondStr === "middle" || secondStr === "中") {
                this._mouseBtn = 1;
            }
            else {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[1] + "，{{鼠标参数格式为}}:  “0”、“left”、“左”{{表示鼠标左键拖拽}}，“1”、“right”、“右”{{表示鼠标右键拖拽}}，“2”、“middle”、“中”{{表示鼠标中键拖拽}}，{{请检查}}！", '', Severity.Error));
                return false;
            }

            //参数3
            var thirdStr = para_array[2].toLowerCase();
            if (thirdStr === 'x' || thirdStr === 'y' || thirdStr === 'z' || thirdStr === 'xy' || thirdStr === 'yx' || thirdStr === 'xz' || thirdStr === 'zx' || thirdStr === 'yz' || thirdStr === 'zy') {
                this._move = thirdStr;
                if (thirdStr === 'xy' || thirdStr === 'yx' || thirdStr === 'xz' || thirdStr === 'zx' || thirdStr === 'yz' || thirdStr === 'zy') {
                    this._isPlane = true;
                }
            }
            else {
                if (this._choose !== 'free') {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[2] + "，{{轴应该填}}“X”、“Y”、“Z”、“XY”、“XZ”、“YZ”，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }

            //参数4
            if (para_array.length > 3) {
                var tagArray = para_array[3].split('~');
                if (tagArray.length !== 2) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[3] + "，{{第4个参数应为}}“物体名~包括”|“Name~Include”、“物体名~排除”|“Name~Exclude”，{{表示过滤条件}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
                //物体名或者标签判断
                if (tagArray[0].trim() === "物体名" || tagArray[0].trim().toLowerCase() === "name") {
                }
                else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[3] + "，{{第4个参数应为}}“物体名~包括”|“Name~Include”、“物体名~排除”|“Name~Exclude”，{{表示过滤条件}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
                //排除或者包括判断
                if (tagArray[1].trim() === "包括" || tagArray[1].trim().toLowerCase() === "include") {
                    this._include = true;
                }
                else if (tagArray[1].trim() === "排除" || tagArray[1].trim().toLowerCase() === "exclude") {
                    this._include = false;
                }
                else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[3] + "，{{第4个参数应为}}“物体名~包括”|“Name~Include”、“物体名~排除”|“Name~Exclude”，{{表示过滤条件}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }
            else {
                this._filter = false;
                this._filterName = [];
            }

            //参数5
            if (para_array.length > 4) {
                var nameArray = para_array[4].split(/,|，/);
                for (var i = 0; i < nameArray.length; i++) {
                    nameArray[i] = nameArray[i].trim();
                    if (VarTools.IsVarID(nameArray[i])) {
                        var tempStr = new VeryString();
                        let para1 = new VeryParas();
                        if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, nameArray[i])) {
                            return false;
                        }
                        tempStr = para1.string;
                        if (tempStr.value !== "" && (this._filterName.indexOf(tempStr.value) == -1)) {
                            this._filterName[this._filterName.length] = (nameArray[i]);
                        }
                    }
                    else {
                        if (nameArray[i] !== "" && (this._filterName.indexOf(nameArray[i]) == -1)) {
                            this._filterName[this._filterName.length] = (nameArray[i]);
                        }
                    }
                }
                if (this._filterName.length > 0) {
                    this._filter = true;
                }
            }
            else {
                this._filter = false;
                this._filterName = [];
            }
            return true;
        }
    }
    public destroy(): void {
        if (this._observer) {
            this.scene.onPointerObservable.remove(this._observer);
        }
        this._observer = null;
    }
}

export class Action_MouseEnterHighlight extends VE_ActionBehaviour {

    public get ID(): string {
        return "MouseEnterHighlight|鼠标移入高亮";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '鼠标移入高亮，true，立方体，(255，0，0)，true';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=563';
    }
    public get className(): string {
        return "Action_MouseEnterHighlight";
    }

    //鼠标经过时改变物体颜色  
    private _isColor = true;
    private _newColor: VeryVector3 = new VeryVector3();
    private _colorFloat: VeryNumber[] = [];
    //是否处理子物体
    private _isRecursion = true;
    //是否开启高亮
    private _switch: VeryBool = new VeryBool();
    //高亮物体
    private _objArray: string[] = [];

    //当前操作Mesh
    private _currentMesh: BABYLON.Nullable<BABYLON.AbstractMesh> = null;
    private _oldMaterial: BABYLON.Nullable<BABYLON.Material> = null;
    private _oldMaterials: { [key: string]: BABYLON.Nullable<BABYLON.Material> } = {};

    private _observer: Nullable<BABYLON.Observer<BABYLON.PointerInfo>> = null;

    public active(): void {
        this._observer = this.scene.onPointerObservable.add((pointerInfo) => {
            switch (pointerInfo.type) {
                case BABYLON.PointerEventTypes.POINTERMOVE:
                    if (this._switch) {
                        var pickinfo = this.scene.pick(this.scene.pointerX, this.scene.pointerY);
                        if (pickinfo == null || pickinfo.pickedMesh == null) {
                            if (this._currentMesh != null) {
                                //console.log("Out--" + this._currentMesh + "--" + this._oldMaterial);
                                if (this._isRecursion) {
                                    this.RecursionRestore(this._currentMesh);
                                    this._oldMaterials = {};
                                }
                                this._currentMesh.material = this._oldMaterial;
                                this._currentMesh = null;
                            }
                        }
                        else {
                            if (this._currentMesh != pickinfo.pickedMesh) {
                                if (this._currentMesh != null) {
                                    if (this._isRecursion) {
                                        this.RecursionRestore(this._currentMesh);
                                        this._oldMaterials = {};
                                    }
                                    this._currentMesh.material = this._oldMaterial;
                                    this._currentMesh = null;
                                }

                                if (this._objArray.indexOf(pickinfo.pickedMesh.name) != -1) {
                                    this._oldMaterial = pickinfo.pickedMesh.material;
                                    var tmpMat = new BABYLON.StandardMaterial("tmpMat", this.scene);
                                    if (!this._isColor) {
                                        tmpMat.diffuseColor = new BABYLON.Color3(this._colorFloat[0].value / 255, this._colorFloat[1].value / 255, this._colorFloat[2].value / 255);
                                    }
                                    else {
                                        tmpMat.diffuseColor = new BABYLON.Color3(this._newColor.value.x / 255, this._newColor.value.y / 255, this._newColor.value.z / 255);
                                    }
                                    pickinfo.pickedMesh.material = tmpMat;
                                    this._currentMesh = pickinfo.pickedMesh;
                                    if (this._isRecursion) {
                                        this.RecursionRecord(this._currentMesh,);
                                    }
                                    //console.log("Enter--" + this._currentMesh + "--" + this._oldMaterial);
                                }
                            }
                        }
                    }
                    break;
            }
        });
    }

    private RecursionRecord(obj: BABYLON.AbstractMesh) {
        if (obj.getChildMeshes().length > 0) {
            for (var i = 0; i < obj.getChildMeshes().length; i++) {
                var tmpOldMat = obj.getChildMeshes()[i].material;
                var tmpMat = new BABYLON.StandardMaterial("tmpMat", this.scene);
                if (!this._isColor) {
                    tmpMat.diffuseColor = new BABYLON.Color3(this._colorFloat[0].value / 255, this._colorFloat[1].value / 255, this._colorFloat[2].value / 255);
                }
                else {
                    tmpMat.diffuseColor = new BABYLON.Color3(this._newColor.value.x / 255, this._newColor.value.y / 255, this._newColor.value.z / 255);
                }
                obj.getChildMeshes()[i].material = tmpMat;
                this._oldMaterials[obj.getChildMeshes()[i].name] = tmpOldMat;

                this.RecursionRecord(obj.getChildMeshes()[i]);
            }
        }
    }
    private RecursionRestore(obj: BABYLON.AbstractMesh) {
        if (obj.getChildMeshes().length > 0) {
            for (var i = 0; i < obj.getChildMeshes().length; i++) {
                obj.getChildMeshes()[i].material = this._oldMaterials[obj.getChildMeshes()[i].name];

                this.RecursionRestore(obj.getChildMeshes()[i]);
            }
        }
    }


    public onUpdate(): void {
        if (!this._switch) {
            if (this._currentMesh != null) {
                if (this._isRecursion) {
                    this.RecursionRestore(this._currentMesh);
                    this._oldMaterials = {};
                }
                this._currentMesh.material = this._oldMaterial;
                this._currentMesh = null;
            }
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3, 4)) {
            return false;
        } else {
            //参数1
            var para0 = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._switch = para0.bool;

            //参数3
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Trigger, para2, para_array[2])) {
                return false;
            }
            this._isColor = para2.isVec;
            this._newColor = para2.vector3;
            this._colorFloat = para2.vecNumbers;

            //参数4
            if (para_array.length > 3) {
                if (para_array[3].toLowerCase() === "false" || para_array[3].toLowerCase() === "关" || para_array[3].toLowerCase() === "否" || para_array[3].toLowerCase() === "假") {
                    this._isRecursion = false;
                }
                else if (para_array[3].toLowerCase() !== "true" || para_array[3].toLowerCase() === "开" || para_array[3].toLowerCase() === "是" || para_array[3].toLowerCase() === "真") {
                    console.warn(this.ID + " 响应传入参数格式错误，其值为： " + para_array[3] + "，应为true或者false，当前值两者都不是，此处默认true处理，自动给子物体也高亮！");
                }
            }

            //参数2
            var nameArray = para_array[1].split(/,|，/);
            for (var i = 0; i < nameArray.length; i++) {
                nameArray[i] = nameArray[i].trim();
                let para1: VeryParas = new VeryParas();
                var tempObj = new VeryGameObject();
                if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para1, nameArray[i], this.nodeID)) {
                    return false;
                }
                tempObj = para1.gameObject;
                //DO_20221228:表格编辑器,自动检测
                if (!VeryEngine.enableLuckySheet) {
                    if (tempObj.value == null) {
                        //DO_20221228:表格编辑器,自动检测,中英文
                        VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + nameArray[i] + "，{{无法在场景中查找到该物体}}，{{请检查}}！", '', Severity.Error));
                        return false;
                    }
                }
                this._objArray[this._objArray.length] = nameArray[i];
            }

            return true;
        }
    }
    public destroy(): void {
        if (this._observer) {
            this.scene.onPointerObservable.remove(this._observer);
        }
        this._observer = null;
    }
}

