//DO_20211029:获取轴
export class Action_GetAxis extends VE_ActionBehaviour {

    public get ID(): string {
        return "GetAxis|获取轴";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '获取轴，Mouse X，*resultNumber';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=558';
    }
    public get className(): string {
        return "Action_GetAxis";
    }

    //轴名字
    private _axisName: VeryString = new VeryString();
    //获取轴的值
    private _axisValue: VeryNumber = new VeryNumber();

    private _mousePos: BABYLON.Vector2 = BABYLON.Vector2.Zero();
    private _observer: Nullable<BABYLON.Observer<BABYLON.PointerInfo>> = null;
    private _keyboardObserver: Nullable<BABYLON.Observer<BABYLON.KeyboardInfo>> = null;

    //DO_20220427:获取轴，多表格同时调用获取鼠标滚动轴时只有最近调用的响应才有效的BUG解决
    private static _axisValueArray: VeryNumber[] = [];

    public active(): void {

        //DO_20220427:获取轴，多表格同时调用获取鼠标滚动轴时只有最近调用的响应才有效的BUG解决
        if (this._axisName.value === 'Mouse ScrollWheel') {
            if (Action_GetAxis._axisValueArray.indexOf(this._axisValue) === -1) {
                Action_GetAxis._axisValueArray.push(this._axisValue);
            }
            var scrllFunc = function (e) {
                e = e || window.event;
                if (e.wheelDelta) {
                    if (e.wheelDelta > 0) {
                        for (var i = 0; i < Action_GetAxis._axisValueArray.length; i++) {
                            let tmpVeryNumber = Action_GetAxis._axisValueArray[i]
                            tmpVeryNumber.value = 0.1;
                            setTimeout(() => {
                                tmpVeryNumber.value = 0;
                            }, 100);
                        }
                    }
                    if (e.wheelDelta < 0) {
                        for (var i = 0; i < Action_GetAxis._axisValueArray.length; i++) {
                            let tmpVeryNumber = Action_GetAxis._axisValueArray[i]
                            tmpVeryNumber.value = -0.1;
                            setTimeout(() => {
                                tmpVeryNumber.value = 0;
                            }, 100);
                        }
                    }
                }
                else if (e.detail) {
                    if (e.detail > 0) {
                        for (var i = 0; i < Action_GetAxis._axisValueArray.length; i++) {
                            let tmpVeryNumber = Action_GetAxis._axisValueArray[i]
                            tmpVeryNumber.value = 0.1;
                            setTimeout(() => {
                                tmpVeryNumber.value = 0;
                            }, 100);
                        }
                    }
                    if (e.detail < 0) {
                        for (var i = 0; i < Action_GetAxis._axisValueArray.length; i++) {
                            let tmpVeryNumber = Action_GetAxis._axisValueArray[i]
                            tmpVeryNumber.value = -0.1;
                            setTimeout(() => {
                                tmpVeryNumber.value = 0;
                            }, 100);
                        }
                    }
                }
            }
            document.addEventListener('DOMMouseScroll', scrllFunc, false);
            document.onwheel = scrllFunc;
        }

        this._keyboardObserver = this.scene.onKeyboardObservable.add((keyboardInfo) => {
            switch (keyboardInfo.type) {
                case BABYLON.KeyboardEventTypes.KEYDOWN:
                    if (this._axisName.value === 'Horizontal') {
                        if (keyboardInfo.event.keyCode === 37) {
                            this._axisValue.value = -1;
                        }
                        if (keyboardInfo.event.keyCode === 39) {
                            this._axisValue.value = 1;
                        }
                    }
                    else if (this._axisName.value === 'Vertical') {
                        if (keyboardInfo.event.keyCode === 38) {
                            this._axisValue.value = 1;

                        }
                        if (keyboardInfo.event.keyCode === 40) {
                            this._axisValue.value = -1;
                        }
                    }
                    break;
                case BABYLON.KeyboardEventTypes.KEYUP:
                    if (this._axisName.value === 'Horizontal') {
                        if (keyboardInfo.event.keyCode === 37) {
                            this._axisValue.value = 0;
                        }
                        if (keyboardInfo.event.keyCode === 39) {
                            this._axisValue.value = 0;
                        }
                    }
                    else if (this._axisName.value === 'Vertical') {
                        if (keyboardInfo.event.keyCode === 38) {
                            this._axisValue.value = 0;
                        }
                        if (keyboardInfo.event.keyCode === 40) {
                            this._axisValue.value = 0;
                        }
                    }
                    break;
            }
        });
    }

    public onUpdate(): void {
        if (this._axisName.value === 'Mouse X') {
            var newPos = new BABYLON.Vector2(this.scene.pointerX, BabylonEngine.Canvas.height - this.scene.pointerY);
            this._axisValue.value = (newPos.x - this._mousePos.x) / BabylonEngine.Canvas.width;
            if (this._axisValue.value !== 0) {
                //console.log(newPos + '--' + this._mousePos + '--' + this._axisValue.value);
            }
            this._mousePos = newPos;
        }
        if (this._axisName.value === 'Mouse Y') {
            var newPos = new BABYLON.Vector2(this.scene.pointerX, BabylonEngine.Canvas.height - this.scene.pointerY);
            this._axisValue.value = (newPos.y - this._mousePos.y) / BabylonEngine.Canvas.height;
            if (this._axisValue.value !== 0) {
                //console.log(newPos + '--' + this._mousePos + '--' + this._axisValue.value);
            }
            this._mousePos = newPos;
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2)) {
            return false;
        } else {
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._axisName = para0.string;
            if (para0.string.value !== 'Mouse X' && para0.string.value !== 'Mouse Y' && para0.string.value !== 'Horizontal' && para0.string.value !== 'Vertical' && para0.string.value !== 'Mouse ScrollWheel') {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[0] + "，{{当前轴参数填写错误}}，{{请检查}}！", '', Severity.Error));
                return false;
            }

            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaOnlyVar(this.objectID, this.ID, ParaType.Action, para1, para_array[1])) {
                return false;
            }
            this._axisValue = para1.number;

            return true;
        }
    }
    public destroy(): void {
        if (this._observer) {
            this.scene.onPointerObservable.remove(this._observer);
        }
        this._observer = null;
        if (this._keyboardObserver) {
            this.scene.onKeyboardObservable.remove(this._keyboardObserver);
        }
        this._keyboardObserver = null;
    }
}


