export class Action_Mouse_PickUI extends VE_ActionBehaviour {

    public get ID(): string {
        return "Mouse_PickUI|鼠标点选UI";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '鼠标点选UI，*UI变量';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=923';
    }
    public get className(): string {
        return "Action_Mouse_PickUI";
    }

    //接收UI变量
    private _blueUIControl: VeryUI = new VeryUI();

    //记录observable
    private _observerUI: BABYLON.GUI.Control[] = [];
    private _observer: BABYLON.Observer<BABYLON.GUI.Vector2WithInfo>[] = [];
    //点击时间,根据点击时间差获取实际点击UI
    private _pickTime: number = 0;

    public active(): void {
        var tmpTexture: BABYLON.GUI.AdvancedDynamicTexture
        // 2D GUI在单独的GUI scene中，但是3D GUI依然在普通场景中
        let allTexture: BABYLON.BaseTexture[] = [];
        if (BabylonEngine.GUIScene !== BabylonEngine.Scene) {
            for (var i = 0; i < BabylonEngine.GUIScene.textures.length; i++) {
                allTexture.push(BabylonEngine.GUIScene.textures[i]);
            }

            for (var i = 0; i < BabylonEngine.Scene.textures.length; i++) {
                allTexture.push(BabylonEngine.Scene.textures[i]);
            }
        } else {
            allTexture = BabylonEngine.Scene.textures;
        }

        for (var i = 0; i < allTexture.length; i++) {
            if (allTexture[i] instanceof BABYLON.GUI.AdvancedDynamicTexture) {
                tmpTexture = <BABYLON.GUI.AdvancedDynamicTexture>allTexture[i];
                var tmpContainer = tmpTexture.rootContainer;
                this.GetAllUI(tmpContainer);
            }
        }
    }

    public onDisable(): void {
        for (var i = 0; i < this._observer.length; i++) {
            this._observerUI[i].onPointerDownObservable.remove(this._observer[i]);
        }
        this._observerUI = [];
        this._observer = [];
    }


    private GetAllUI(tmpContainer: BABYLON.GUI.Container) {
        for (var i = 0; i < tmpContainer.children.length; i++) {
            let tmpControl = tmpContainer.children[i];
            this._observerUI[this._observerUI.length] = tmpControl;
            this._observer[this._observer.length] = tmpControl.onPointerDownObservable.add(() => {
                var myDateTime = new Date().getTime();
                if (this._pickTime === 0) {
                    this._pickTime = myDateTime;
                    this._blueUIControl.setValue(tmpControl);
                    console.warn('鼠标点选UI--' + tmpControl.name);
                }
                else {
                    //根据点击时间差获取实际点击UI
                    if ((myDateTime - this._pickTime) > 100) {
                        this._pickTime = myDateTime;
                        this._blueUIControl.setValue(tmpControl);
                        console.warn('鼠标点选UI--' + tmpControl.name);
                    }
                }
            });
            if (tmpControl instanceof BABYLON.GUI.Container) {
                this.GetAllUI(<BABYLON.GUI.Container>tmpControl);
            }
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 1)) {
            return false;
        } else {

            var para0 = new VeryParas();
            if (!ParaParserUtility.UIControlPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._blueUIControl = para0.uiControl;

            return true;
        }
    }
    public destroy(): void {

    }
}


