//DO_20211103:漫游相机,移动控制,旋转控制
export class Action_SceneCamera_Move extends VE_ActionBehaviour {

    public get ID(): string {
        return 'SceneCamera_Move|漫游相机移动';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '漫游相机移动，漫游相机，前,漫游相机移动，漫游相机，后,漫游相机移动，漫游相机，左,漫游相机移动，漫游相机，右';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=868';
    }
    public get className(): string {
        return 'Action_SceneCamera_Move';
    }

    private _cameraVariable: VeryCamera = new VeryCamera();
    private _moveType: string = '';

    //DO_20211213:速度设置可选参数
    private _speed: VeryNumber = new VeryNumber();

    public active(): void {

    }

    public onUpdate(): void {
        var camera = this._cameraVariable.value;
        if (camera instanceof BABYLON.FreeCamera) {
            //DO_20211213:速度设置可选参数
            var speed = camera._computeLocalCameraSpeed() * this._speed.value;
            if (this._moveType === '前') {
                camera._localDirection.copyFromFloats(0, 0, speed);
            }
            if (this._moveType === '后') {
                camera._localDirection.copyFromFloats(0, 0, -speed);
            }
            if (this._moveType === '左') {
                camera._localDirection.copyFromFloats(-speed, 0, 0);
            }
            if (this._moveType === '右') {
                camera._localDirection.copyFromFloats(speed, 0, 0);
            }

            if (camera.getScene().useRightHandedSystem) {
                camera._localDirection.z *= -1;
            }
            camera.getViewMatrix().invertToRef(camera._cameraTransformMatrix);
            BABYLON.Vector3.TransformNormalToRef(camera._localDirection, camera._cameraTransformMatrix, camera._transformedDirection);
            camera.cameraDirection.addInPlace(camera._transformedDirection);
        }
    }

    public paraParser(para_array: string[]): boolean {
        //DO_20211213:速度设置可选参数
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2, 3)) {
            return false;
        } else {
            // 参数1：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.CameraPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0], this.nodeID)) {
                return false;
            }
            this._cameraVariable = para1.camera;
            //DO_20230613:表格编辑器,自动检测
            if (this._cameraVariable.value === null && !VeryEngine.enableLuckySheet) return false;

            //DO_20220830:触发响应中参数支持中英文
            // 参数2：
            if (para_array[1] === '前' || para_array[1].toLowerCase() == 'forward') {
                this._moveType = '前';
            }
            else if (para_array[1] === '后' || para_array[1].toLowerCase() == 'back') {
                this._moveType = "后";
            }
            else if (para_array[1] === '左' || para_array[1].toLowerCase() == 'left') {
                this._moveType = '左';
            }
            else if (para_array[1] === '右' || para_array[1].toLowerCase() == 'right') {
                this._moveType = '右';
            }
            else {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[1] + "，{{漫游相机移动响应中移动方向填写错误}}，{{应为}}前|forward,后|back,左|left,右|right{{中的一种}}，{{请检查}}！", '', Severity.Error));
                return false;
            }

            //DO_20211213:速度设置可选参数
            // 参数3：
            this._speed.value = 1;
            if (para_array.length > 2) {
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                    return false;
                }
                this._speed = para3.number;
            }

            return true;
        }
    }

    public destroy(): void {
        // 
    }

}
