//DO_20221118:漫游相机设置位置和角度
export class Action_SceneCamera_SetPositionAndAngle extends VE_ActionBehaviour {

    public get ID(): string {
        return "SceneCamera_SetPositionAndAngle|漫游相机设置位置角度";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '漫游相机设置位置角度，漫游相机，(0，69，-631)，(0，0，0)';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=984';
    }
    public get className(): string {
        return "Action_SceneCamera_SetPositionAndAngle";
    }

    //相机
    private _camera1: VeryCamera = new VeryCamera();
    //位置
    private _isVec: boolean = false;
    private _posVec: VeryVector3 = new VeryVector3();
    private _x: VeryNumber = new VeryNumber();
    private _y: VeryNumber = new VeryNumber();
    private _z: VeryNumber = new VeryNumber();
    //角度
    private _isVec2: boolean = false;
    private _angleVec: VeryVector3 = new VeryVector3();
    private _x2: VeryNumber = new VeryNumber();
    private _y2: VeryNumber = new VeryNumber();
    private _z2: VeryNumber = new VeryNumber();

    public active(): void {
        if (this._camera1.value) {
            //位置
            var tmpParent = <BABYLON.TransformNode>this._camera1.value.parent;
            if (this._isVec) {
                tmpParent.position = this._posVec.value;
                this._camera1.value.position = BABYLON.Vector3.Zero();
            }
            else {
                tmpParent.position = new BABYLON.Vector3(this._x.value, this._y.value, this._z.value);
                this._camera1.value.position = BABYLON.Vector3.Zero();
            }
            //角度
            var tmpCamera = <BABYLON.TargetCamera>this._camera1.value;
            if (tmpCamera) {
                if (this._isVec2) {
                    tmpCamera.rotation = Tools.eulerAngleToRadian(this._angleVec.value);
                }
                else {
                    tmpCamera.rotation = Tools.eulerAngleToRadian(new BABYLON.Vector3(this._x2.value, this._y2.value, this._z2.value));
                }
            }
        }
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3)) {
            return false;
        } else {
            // 参数1：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.CameraPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0], this.nodeID)) {
                return false;
            }
            this._camera1 = para1.camera;
            //DO_20221228:表格编辑器,自动检测
            if (this._camera1.value === null && !VeryEngine.enableLuckySheet) return false;

            //参数2
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._isVec = para2.isVec;
            this._posVec = para2.vector3;
            this._x = para2.vecNumbers[0];
            this._y = para2.vecNumbers[1];
            this._z = para2.vecNumbers[2];

            //参数3
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                return false;
            }
            this._isVec2 = para3.isVec;
            this._angleVec = para3.vector3;
            this._x2 = para3.vecNumbers[0];
            this._y2 = para3.vecNumbers[1];
            this._z2 = para3.vecNumbers[2];

            return true;
        }
    }
    public destroy(): void {

    }
}


