import { ByteBuffer } from "./ByteBuffer";
import { SocketHandle,VeryEngineNode } from "./SocketBusiness";
import { MonoBehaviourMessageCenter, VerySendMode } from "./MonoBehaviourMessageCenter";
import { SocketManager } from "./SocketManager";
import { VeryNumber, VeryRect, VeryVector2, VeryVector3 } from "../variables/veryVariables";

export class MoveModel{
    public static allModel:{[key:number]:MoveModel}={};
    private _posInfoHeap:{time:number,dir:number[]}[]=[];
    private _currentTarget:{time:number,dir:number[]}|undefined;
    private _recordTarget:{time:number,dir:number[]}|undefined;
    private _lastTarget:{time:number,dir:number[]}|undefined;
    private  rTime=0;
    private _localMoveInfo=false;
    //正常移动
    public _moveState=false;
    //惯性移动
    private _moveState2=false;
    //预测移动
    private _moveCache=false;
    private mTime=0;
    private moveDiff:number[];
    private timesRevise=0;

    private justLogin:number[]=[];

    private showMove:number[];
    private actualMove:number[];
    private lastActualMove:number[];

    private playerId:number=-1;
    private lastPlayId:number=-1;
    //todo 用于判断移动模型归哪个用户所有，当有新用户登录，由该用户发送该移动模型的位置信息
    //拥有者离开后，由倒数第二个人负责；
    //存在冲突，若新用户获取位置信息工程中，其他用户发送移动指令了，咋办，先不处理
    private allUsePlayIds:number[]=[];
    private index=-1;

    public resetMove:Array<()=>void>=new Array();
    constructor(len:number,index:number){
        this.moveDiff=new Array(len).fill(0);
        this.showMove=new Array(len).fill(0);
        this.actualMove=new Array(len).fill(0);
        this.lastActualMove=new Array(len).fill(0);
        this.index=index
        MoveModel.allModel[index]=this;
        MonoBehaviourMessageCenter.Instance;
    }

    public destory(){
        this.setMoveInfo=null;
        this.getMoveInfo=null;
    }

    public bindVeryengine(actual:VeryNumber|VeryVector2|VeryVector3|VeryRect,show:VeryNumber|VeryVector2|VeryVector3|VeryRect,
        tag=true){
        if(actual instanceof VeryNumber){
            if(tag)
            this.showMove=this.actualMove=this.lastActualMove=Array.of(actual.value);
            this.setMoveInfo=()=>{
                this.actualMove=Array.of(actual.value);
            }
            this.getMoveInfo=()=>{
                show.value=this.showMove[0];
            }
        }else if(actual instanceof VeryVector2&&show instanceof VeryVector2){
            if(tag)
            this.showMove=this.actualMove=this.lastActualMove=Array.of(actual.value.x,actual.value.y);
            this.setMoveInfo=()=>{
                this.actualMove=Array.of(actual.value.x,actual.value.y);
            }
            this.getMoveInfo=()=>{
                show.value.x=this.showMove[0];
                show.value.y=this.showMove[1];
            }
        }else if(actual instanceof VeryVector3&&show instanceof VeryVector3){
            if(tag)
            this.showMove=this.actualMove=this.lastActualMove=Array.of(actual.value.x,actual.value.y,actual.value.z);
            this.setMoveInfo=()=>{
                this.actualMove=Array.of(actual.value.x,actual.value.y,actual.value.z);
            }
            this.getMoveInfo=()=>{
                show.value.x=this.showMove[0];
                show.value.y=this.showMove[1];
                show.value.z=this.showMove[2];
            }
        }
        else if(actual instanceof VeryRect&&show instanceof VeryRect){
            if(tag)
            this.showMove=this.actualMove=this.lastActualMove=Array.of(actual.value.x,actual.value.y,actual.value.z,actual.value.w);
            this.setMoveInfo=()=>{
                this.actualMove=Array.of(actual.value.x,actual.value.y,actual.value.z,actual.value.w);
            }
            this.getMoveInfo=()=>{
                show.value.x=this.showMove[0];
                show.value.y=this.showMove[1];
                show.value.z=this.showMove[2];
                show.value.w=this.showMove[3];
            }
        }
        this.resetMove.push(()=>{
            // //若操作者为本人，无需复位（可能还在进行位移操作）
            // if(this.playerId!=SocketManager.playerId){
            //     this.getMoveInfo();
            if(actual instanceof VeryNumber&&show instanceof VeryNumber){
                actual.value=show.value;
            }
            else if(actual instanceof VeryVector2&&show instanceof VeryVector2){
                actual.value.x=show.value.x;
                actual.value.y=show.value.y;
            } else if(actual instanceof VeryVector3&&show instanceof VeryVector3){
                actual.value.x=show.value.x;
                actual.value.y=show.value.y;
                actual.value.z=show.value.z;
            }
            else if(actual instanceof VeryRect&&show instanceof VeryRect){
                actual.value.x=show.value.x;
                actual.value.y=show.value.y;
                actual.value.z=show.value.z;
                actual.value.w=show.value.w;
            }
            // }
        })
        this.getMoveInfo();
    }

    
    private setMoveInfo:()=>void;
    private getMoveInfo:()=>void
    public accept(type:number,buf:ByteBuffer){
        if (type == VeryEngineNode.Move)
        {
            let dir=new Array<number>()
            for(let i=0;i<this.showMove.length;i++){
                dir.push(buf.ReadFloat());
            }
            let rtime=buf.ReadInt();
            //结束运动时，需要无视移动时间和距离，发送当前移动信息
            //任何人都可以发送，需要多一个发送id来比对是否合法
            //存在收到最后一个移动信息 和 结束移动信号 有较大时差，此时渲染帧无法执行结束渲染操作,需要将带id移动信号视为结束移动标记
            if(buf.ReadableBytes()>0){
                let playerId=buf.ReadInt();
                if(playerId!=this.playerId){
                    // console.log("收到结束2");
                    return;
                }
                else{
                    if(this._moveState){
                        // console.log("收到结束1");
                        this._moveState=false;
                        this._moveCache=false;
                        this._moveState2=true;
                    }
                    else{
                        // console.log("收到结束3");
                    }
                }
            }
            let tmp={time:rtime,dir:dir};
            this._posInfoHeap.push(tmp);
        }
        else if(type===VeryEngineNode.MoveSate){
            let result=buf.ReadBoolean();
            let playerId=buf.ReadInt();
            if(result){
                //当同一个用户连续移动 可以触发 否则必须等到执行完上一个用户的所有移动指令
                if(this.playerId==playerId||this.playerId==-2||this.playerId==-1){
                    this._moveState=true;
                    this.playerId=playerId;
                    this.lastPlayId=playerId;
                    // let tmpIndex=this.allUsePlayIds.indexOf()
                    // console.log("收到开始");
                    if(this._moveState2)
                        this._moveState2=false;
                }else if(playerId==SocketManager.playerId){
                    console.warn("抱歉！您想操作的物体正在被他人操作，请等他人操作完成后再下达指令。")
                }
            }
            else{
                if(this._moveState&&playerId==this.playerId){
                    this._moveState=false;
                    this._moveCache=false;
                    this._moveState2=true;
                }
            }
        }
        if (type == VeryEngineNode.Pos)
        {
            for(let i=0;i<this.showMove.length;i++){
                this.showMove[i]=buf.ReadFloat();
            }
            if(this.getMoveInfo)
            this.getMoveInfo();
            //他人发送的位置信息，需要将引擎的actual位置更新为插件的showMove
            for(let func of this.resetMove){
                if(this.playerId!=SocketManager.playerId)
                    func();
            }
        }
    }

    public sendCurrent(playerId:number){
        if(SocketManager.playerId==this.lastPlayId){
            this.justLogin.push(playerId);
        }
    }

    public sendMoveState(active:boolean){
        if(active){
            // console.log("发送开始:"+this.playerId)
            if(this.playerId==-1||this.playerId==SocketManager.playerId||this.playerId==-2){
                let buf =ByteBuffer.Allocate(16);
                buf.WriteByte(SocketHandle.GameTurn);
                buf.WriteInt(VerySendMode.All);
                buf.WriteByte(VeryEngineNode.MoveSate);
                buf.WriteInt(this.index);
                buf.WriteBoolean(active);
                buf.WriteInt(SocketManager.playerId);
                if(this.playerId==-1){
                    //防止用户连续点击，不断刷新初始移动位置
                    this.playerId=-2;
                    this.rTime=new Date().getTime();
                    //若同一个用户点击无需重置位置和时间，否则存在上一个开始结束移动指令还未到达，但上上一个移动指令完全执行完成，此时位置进行位置重置
                    //，但上一个结束移动指令会后续到达，此时物体会进行额外位移
                    if(this.lastPlayId==-1||this.lastPlayId!=SocketManager.playerId){
                        this.lastActualMove=new Array().concat(this.showMove);
                        for(let func of this.resetMove){
                            func();
                        }
                    }
                }
                else{
                }
                SocketManager.Instance.PoolSendMsg(buf);
            }
            this._localMoveInfo=true;
        }
        else{
            this._localMoveInfo=false;
            this.setMoveInfo();
            let lastMove =ByteBuffer.Allocate(50);
            let nowTime=new Date().getTime();
            let timeDiff=nowTime-this.rTime;
            this.rTime=nowTime;
            let dirDiff=new Array();
            for(let i=0;i<this.actualMove.length;i++){
                dirDiff.push((this.actualMove[i]-this.lastActualMove[i])/timeDiff);
            }
            this.lastActualMove=new Array().concat(this.actualMove);
            lastMove.WriteByte(SocketHandle.GameTurn);
            lastMove.WriteInt(VerySendMode.All);
            lastMove.WriteByte(VeryEngineNode.Move);
            lastMove.WriteInt(this.index);
            for(let val of dirDiff){
                lastMove.WriteFloat(val);
            }
            lastMove.WriteInt(timeDiff);
            lastMove.WriteInt(SocketManager.playerId)
            SocketManager.Instance.PoolSendMsg(lastMove);
            // console.log("发送结束");
        }
    }

    private equalsWithEpsilon(num1:Array<number>,num2:Array<number>){
        for(let i=0;i<num1.length;i++){
            if(Math.abs(num1[i]-num2[i])>0.01){
                return false
            }
        }
        return true;
    }
    public sendVec3Info(){
        if(SocketManager.playerId==this.playerId&&this._localMoveInfo){
            this.setMoveInfo();
            if(!this.equalsWithEpsilon(this.lastActualMove,this.actualMove))
            {
                let nowTime=new Date().getTime();
                let timeDiff=nowTime-this.rTime;
                if(timeDiff>20){
                    this.rTime=nowTime;
                    let dirDiff=new Array();
                    for(let i=0;i<this.actualMove.length;i++){
                        dirDiff.push((this.actualMove[i]-this.lastActualMove[i])/timeDiff);
                    }
                    this.lastActualMove=new Array().concat(this.actualMove);
                    let buf =ByteBuffer.Allocate(29);
                    buf.WriteByte(SocketHandle.GameTurn);
                    buf.WriteInt(VerySendMode.All);
                    buf.WriteByte(VeryEngineNode.Move);
                    buf.WriteInt(this.index);
                    for(let val of dirDiff){
                        buf.WriteFloat(val);
                    }
                    buf.WriteInt(timeDiff);
                    SocketManager.Instance.PoolSendMsg(buf);
                }
            }
        }

        if(this.justLogin.length!=0){
            let buf =ByteBuffer.Allocate(29);
            for(let i=0;i<this.justLogin.length;i++){
                buf.WriteByte(SocketHandle.GameTurn);
                buf.WriteInt(this.justLogin[i]);
                buf.WriteByte(VeryEngineNode.Pos);
                buf.WriteInt(this.index);
                for(let val of this.actualMove){
                    buf.WriteFloat(val);
                }
                SocketManager.Instance.PoolSendMsg(buf);
            }
            this.justLogin=[];
        }
    }

    public update(){
        let nowTime=new Date().getTime();
        if(this._moveState||this._moveState2){
            if (this._posInfoHeap.length >0 && this._currentTarget === undefined) {
                this._moveCache=true;
                this.nextTarget();
            }
            let timeDiff2=nowTime-this.mTime;
            if (this._currentTarget) {
                //若之前做过预测处理，需要和实际移动轨迹进行比对修改
                if(this._lastTarget&&this._lastTarget.time!=0){
                    let vec3Diff=new Array();
                    for(let i=0;i<this._currentTarget.dir.length;i++){
                        vec3Diff.push(this._currentTarget.dir[i]*this._currentTarget.time-this._lastTarget.dir[i]*this._lastTarget.time);
                    }
                    let timeRevise=this._currentTarget.time-this._lastTarget.time;
                    this._lastTarget.time=0;
                    this.timesRevise=timeRevise+this.timesRevise;
                    for(let i=0;i<vec3Diff.length;i++){
                        this.moveDiff[i]=this.moveDiff[i]+vec3Diff[i];
                    }
                    while(this.timesRevise<=0)
                    {
                        this.nextTarget();
                        if(!this._currentTarget)
                            break;
                        for(let i=0;i<this.moveDiff.length;i++){
                            this.moveDiff[i]=this.moveDiff[i]+this._currentTarget.dir[i]*this._currentTarget.time;
                        }
                        this.timesRevise=this.timesRevise+this._currentTarget.time;
                    }
                    if(this._currentTarget!=null){
                        for(let i=0;i<this._currentTarget.dir.length;i++){
                            this._currentTarget.dir[i]=this.moveDiff[i]/this.timesRevise;
                        }
                        this._currentTarget.time=this.timesRevise;
                        this.moveDiff=new Array(this.moveDiff.length).fill(0);
                        this.timesRevise=0;
                    }
                }
                if(this._currentTarget){
                    let targetTime=this._currentTarget.time-timeDiff2;
                    //当渲染时间间隔超出两帧即以上逻辑帧时长，需跨过去渲染
                    while(targetTime<=0&&this._currentTarget!=null){
                        for(let i=0;i<this.showMove.length;i++){
                            this.showMove[i]=(this.showMove[i]+this._currentTarget.dir[i]*this._currentTarget.time);
                        }
                        timeDiff2=-targetTime;
                        this.nextTarget();
                        if(this._currentTarget!=null)
                            targetTime=this._currentTarget.time-timeDiff2;

                    }
                    if(this._currentTarget!=null){
                        for(let i=0;i<this.showMove.length;i++){
                            this.showMove[i]=(this.showMove[i]+this._currentTarget.dir[i]*timeDiff2);
                        }
                        this._currentTarget.time=targetTime;
                    }
                }
            }
            //逻辑帧还未到达，渲染需要预测，进行预测，直接连续上一帧的移动方向和速度
            if(!this._currentTarget&&this._moveCache&&this._lastTarget!=null){
                for(let i=0;i<this.showMove.length;i++){
                    this.showMove[i]=(this.showMove[i]+this._lastTarget.dir[i]*timeDiff2);
                }
                this._lastTarget.time+=timeDiff2;
            }
            this.getMoveInfo();
        }
        this.mTime=nowTime;
    }

    private nextTarget(){
        if(this._posInfoHeap.length>0){
            if(this._currentTarget!=null){
                this._lastTarget=this._recordTarget;
                this._lastTarget.time=0;
            }
            this._currentTarget=this._posInfoHeap.shift();
            this._recordTarget={time:this._currentTarget.time,dir:this._currentTarget.dir};
        }
        else{
            if(this._moveState2){
                this._moveState2=false;
                if(this.timesRevise!=0){
                    for(let i=0;i<this.showMove.length;i++){
                        this.showMove[i]=(this.showMove[i]+this.moveDiff[i]);
                    }
                    this.moveDiff=new Array(this.moveDiff.length).fill(0);
                    this.timesRevise=0;
                }
                // console.log("-------结束-----------")
                // console.log(this.showMove);
                // console.log(this.actualMove);
                this.playerId=-1;
                this._lastTarget=undefined;
            }
            this._currentTarget=undefined;
        }
    }
}