export class Action_Math_Round extends VE_ActionBehaviour {

    public get ID(): string {
        return "Math_Round|圆整";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '圆整，*number1，*result，2';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=633';
    }
    public get className(): string {
        return "Action_Math_Round";
    }

    public get type(): ActionType {
        return ActionType.Animation;
    }

    private _blueNumber: VeryNumber = new VeryNumber();
    private _decimalNumber: VeryNumber = new VeryNumber();
    private _blueNumber2: VeryNumber = new VeryNumber();

    public active(): void {

    }

    public onUpdate(): void {
        var tmpValue = this._blueNumber.value;
        var tmpDivide = 1;
        for (var i = 0; i < this._decimalNumber.value; i++) {
            tmpValue = tmpValue * 10;
            tmpDivide = tmpDivide * 10;
        }
        tmpValue = Math.round(tmpValue);
        this._blueNumber2.value = tmpValue / tmpDivide;
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2, 3)) {
            return false;
        } else {
            // 参数1：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._blueNumber = para1.number;

            // 参数2：
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaOnlyVar(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._blueNumber2 = para2.number;

            // 参数3：
            this._decimalNumber = new VeryNumber();
            this._decimalNumber.setValue(0);
            if (para_array.length > 2) {
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                    return false;
                }
                this._decimalNumber = para3.number;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}
