export class Action_Net_Move extends VE_ActionBehaviour {

    public get ID(): string {
        return "Net_Move|网络移动";
    }

    public get className(): string {
        return "Action_Net_Move";
    }

    private _actual: VeryVector3 = new VeryVector3();
    private _show: VeryVector3 = new VeryVector3();
    private _id: VeryNumber;
    private runing: VeryBool = new VeryBool();
    private series: MoveModel;
    public active(): void {
        this.series = new MoveModel(3, this._id.value + 9999);
        this.series.bindVeryengine(this._actual, this._show);
        if (this.runing.value)
            this.series.sendMoveState(true);
        else
            this.series.sendMoveState(false);
    }

    public onUpdate(): void {
    }

    public onDisable(): void {
        this.series.sendMoveState(false);
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 4)) {
            return false;
        } else {
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._id = para0.number;
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3Para(this.objectID, this.ID, ParaType.Action, para1, para_array[1])) {
                return false;
            }
            this._actual = para1.vector3;

            if (!ParaParserUtility.Vector3Para(this.objectID, this.ID, ParaType.Action, para1, para_array[2])) {
                return false;
            }
            this._show = para1.vector3;
            if (!ParaParserUtility.BoolPara(this.objectID, this.ID, ParaType.Action, para1, para_array[3])) {
                return false;
            }
            this.runing = para1.bool;
            return true;
        }
    }


    public destroy(): void {

    }
}

export class Action_Net_GetIdentity extends VE_ActionBehaviour {
    public get ID(): string {
        return "Net_GetIdentity|获取身份";
    }

    public get className(): string {
        return "Action_Net_GetIdentity";
    }

    private _id: VeryNumber;
    private _customAction: (() => void) | null = null;

    public active(): void {
        if (SocketManager.playerId != -1) {
            this.sendBack();
        }
        else {
            SocketManager.playIdAct.push(this.sendBack.bind(this))
        }
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2)) {
            return false;
        } else {
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaOnlyVar(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._id = para1.number;

            let triggerArray: string[] = para_array[1].split(/,|，/);
            for (let i: number = 0; i < triggerArray.length; i++) {
                VE_CustomTriggerManager.ConnectCustomTrigger(this.objectID, triggerArray[i].trim(), this.setCallback.bind(this));
            }
            return true;
        }
    }

    private setCallback(callback: () => void): void {
        this._customAction = callback;
    }
    private sendBack() {
        this._id.value = SocketManager.playerId % 2;
        if (this._customAction != null) {
            this._customAction();
        }
    }
    public destroy(): void {

    }
}

