export class Action_Have_Login extends VE_ActionBehaviour {
    private _result = new VeryBool();

    public get ID(): string {
        return '是否登录';
    }

    public get className(): string {
        return 'Have_Login';
    }

    private _customAction: (() => void) | null = null;

    public async active() {
        let that = this;
        let xhr = new XMLHttpRequest();
        xhr.open('post', 'https://utp.veryengine.cn/User/HasLogin');
        xhr.withCredentials = true;
        xhr.setRequestHeader("Content-type", "application/x-www-form-urlencoded");
        //发送请求
        xhr.send('softwareId=' + GameGlobal.projectID);
        xhr.onreadystatechange = function () {
            // 这步为判断服务器是否正确响应
            if (xhr.readyState == 4 && xhr.status == 200) {

                let result = JSON.parse(xhr.responseText);
                if (result.code === '00000') {
                    Action_Login.userInfo = result.data;
                    that.sendBack(true);
                }
                else {
                    that.sendBack(false);
                }
            }
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 0, 2)) {
            return false;
        } else {
            if (para_array.length > 0) {
                let triggerArray: string[] = para_array[0].split(/,|，/);
                for (let i: number = 0; i < triggerArray.length; i++) {
                    VE_CustomTriggerManager.ConnectCustomTrigger(this.objectID, triggerArray[i].trim(), this.setCallback.bind(this));
                }
                let para4: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaOnlyVar(this.objectID, this.ID, ParaType.Action, para4, para_array[1])) {
                    return false;
                }
                this._result = para4.bool;
            }
            return true;
        }
    }

    private setCallback(callback: () => void): void {
        this._customAction = callback;
    }

    private sendBack(result: boolean) {
        if (this._customAction != null) {
            this._result.value = result;
            this._customAction();
        }
    }

    public destroy(): void {

    }

}

export class Action_Login extends VE_ActionBehaviour {
    private _result = new VeryBool();


    public get ID(): string {
        return '登录';
    }

    public get className(): string {
        return 'Login';
    }

    public static userInfo: any = {};
    private _customAction: (() => void) | null = null;
    private account: VeryString;
    private password: VeryString;
    public async active() {
        let that = this;
        let xhr = new XMLHttpRequest();
        xhr.open('post', 'https://utp.veryengine.cn/User/Login');
        xhr.withCredentials = true;
        xhr.setRequestHeader("Content-type", "application/x-www-form-urlencoded");
        //发送请求
        xhr.send('softwareId=' + GameGlobal.projectID + '&account=' + this.account.value + '&password=' + this.password.value);
        xhr.onreadystatechange = function () {
            // 这步为判断服务器是否正确响应
            if (xhr.readyState == 4 && xhr.status == 200) {

                let result = JSON.parse(xhr.responseText);
                if (result.code === '00000') {
                    Action_Login.userInfo = result.data;
                    that.sendBack(true);
                }
                else {
                    that.sendBack(false);
                }
            }
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2, 4)) {
            return false;
        } else {
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this.account = para1.string;

            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringPara(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this.password = para2.string;

            if (para_array.length > 2) {
                let triggerArray: string[] = para_array[2].split(/,|，/);
                for (let i: number = 0; i < triggerArray.length; i++) {
                    VE_CustomTriggerManager.ConnectCustomTrigger(this.objectID, triggerArray[i].trim(), this.setCallback.bind(this));
                }
                let para4: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaOnlyVar(this.objectID, this.ID, ParaType.Action, para4, para_array[3])) {
                    return false;
                }
                this._result = para4.bool;
            }
            return true;
        }
    }

    private setCallback(callback: () => void): void {
        this._customAction = callback;
    }

    private sendBack(result: boolean) {
        if (this._customAction != null) {
            this._result.value = result;
            this._customAction();
        }
    }

    public destroy(): void {

    }
}

export class Action_Judge_Tag extends VE_ActionBehaviour {


    public get ID(): string {
        return 'Judge_Tag|判断标签';
    }

    public get className(): string {
        return 'Action_Judge_Tag';
    }

    private _isActive: VeryBool;  // 定义bool变量
    private _tagName: VeryString;


    /**
     * 响应激活时运行此函数，此处表示传入变量为true时，激活物体；fasle时，使物体失效；
     */
    public active(): void {
        let tags = Action_Login.userInfo.tags;
        if (tags && tags.indexOf(this._tagName.value) >= 0) {
            this._isActive.setValue(true);
        }
        else {
            this._isActive.setValue(false);
        }
    }


    /**
     * 响应初始化时运行此函数，解析传入参数；
     * @param para_array 表格参数按逗号解析一个字符串数组传入；
     * @returns true为解析正确，false为错误；
     */
    public paraParser(para_array: string[]): boolean {
        // 传入参数个数确定，此处表示必须为2个或3个传入参数；
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2)) {
            return false;
        } else {
            // 参数1：是否激活
            let para1: VeryParas = new VeryParas(); // 因为要导出整个变量，js也没有类似out的关键字，包裹成一个对象传入以获取变量
            if (!ParaParserUtility.StringPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._tagName = para1.string;  // 获取变量

            // 参数2：物体
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaOnlyVar(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._isActive = para2.bool;
            return true;
        }
    }

    public destroy(): void {

    }
}

export class Action_Net_Roaming extends VE_ActionBehaviour {
    private cam: BABYLON.UniversalCamera;
    private person: VeryGameObject;
    private _id: VeryNumber;
    private _isVec3: boolean = false;
    private _sizeVec: VeryVector3 = new VeryVector3();
    private _sizeX: VeryNumber = new VeryNumber();
    private _sizeY: VeryNumber = new VeryNumber();
    private _sizeZ: VeryNumber = new VeryNumber();
    private _virtual: BABYLON.Mesh;

    //旋转速度
    private rotateSpeed: VeryNumber = new VeryNumber();
    //移动速度
    private moveSpeed: VeryNumber = new VeryNumber();
    private moveModel: MoveModel;
    private actual: VeryVector2 = new VeryVector2();
    private show: VeryVector2 = new VeryVector2();
    private time3: number;
    private runing: VeryBool = new VeryBool();
    public get ID(): string {
        return 'Net_Roaming|网络漫游';
    }

    public get className(): string {
        return 'Action_Net_Roaming';
    }
    private _dirMoveDic = { "up": false, "down": false, "left": false, "right": false, 'rot': false };

    private IsNotMove(tag: boolean) {
        let result = !this._dirMoveDic["up"] && !this._dirMoveDic["down"] && !this._dirMoveDic["left"] && !this._dirMoveDic["right"]
            && !this._dirMoveDic['rot'];
        if (tag) {
            if (result) {
                this.time3 = new Date().getTime();
                this.moveModel.sendMoveState(true);
            }
        }
        else {
            if (result) {
                this.actual.value.x = this._virtual.position.x;
                this.actual.value.y = this._virtual.position.z;
                this.moveModel.sendMoveState(false);
            }
        }

    }
    private observe;
    private observe2;
    public active(): void {
        let tag = true;
        if (!MoveModel.allModel[this._id.value]) {
            this.moveModel = new MoveModel(2, this._id.value);
        } else {
            tag = false;
            this.moveModel = MoveModel.allModel[this._id.value];
        }
        if (this.runing.value) {
            this.moveModel.resetMove.push(() => {
                this._virtual.position.x = this.show.value.x;
                this._virtual.position.z = this.show.value.y;
            })
        }

        this.moveModel.bindVeryengine(this.actual, this.show, tag);
        if (this.runing.value) {
            this.cam = this.getCamera(this.person.value.transform.transformNode);
            this._virtual = BABYLON.MeshBuilder.CreateSphere("角色", { diameter: 1, diameterY: 1 }, this.scene);
            this._virtual.position = this.person.value.mesh.position.clone();
            this.actual.value = new BABYLON.Vector2(this._virtual.position.x, this._virtual.position.z);
            this.show.value = this.actual.value.clone();
            this._virtual.checkCollisions = true;
            this._virtual.isVisible = false;
            var tmpSize = this._sizeVec.value;
            if (!this._isVec3) {
                tmpSize = new BABYLON.Vector3(this._sizeX.value, this._sizeY.value, this._sizeZ.value);
            }
            this._virtual.ellipsoid = tmpSize;
            this.cam.angularSensibility = 2000 / this.rotateSpeed.value;
            this.cam.attachControl(BabylonEngine.Canvas, true);
            this.cam.inputs.addMouse();
            if (this.cam == null) {
                console.error("网络漫游的父物体下面必须存在相机," + this.person.name + "子物体无相机");
                return;
            }
            this.observe = this.scene.onKeyboardObservable.add((kbInfo) => {
                if (kbInfo.type === BABYLON.KeyboardEventTypes.KEYDOWN) {
                    if (kbInfo.event.keyCode === 87 || kbInfo.event.keyCode === 38) {
                        this.IsNotMove(true);
                        this._dirMoveDic["up"] = true;
                    }
                    else if (kbInfo.event.keyCode === 83 || kbInfo.event.keyCode === 40) {
                        this.IsNotMove(true);
                        this._dirMoveDic["down"] = true;
                    }
                    if (kbInfo.event.keyCode === 65 || kbInfo.event.keyCode === 37) {
                        this.IsNotMove(true);
                        this._dirMoveDic["left"] = true;
                    }
                    else if (kbInfo.event.keyCode === 68 || kbInfo.event.keyCode === 39) {
                        this.IsNotMove(true);
                        this._dirMoveDic["right"] = true;
                    }
                }
                if (kbInfo.type === BABYLON.KeyboardEventTypes.KEYUP) {
                    if (kbInfo.event.keyCode === 87 || kbInfo.event.keyCode === 38) {
                        this._dirMoveDic["up"] = false;
                        this.IsNotMove(false);
                    }
                    else if (kbInfo.event.keyCode === 83 || kbInfo.event.keyCode === 40) {
                        this._dirMoveDic["down"] = false;
                        this.IsNotMove(false);
                    }
                    if (kbInfo.event.keyCode === 65 || kbInfo.event.keyCode === 37) {
                        this._dirMoveDic["left"] = false;
                        this.IsNotMove(false);
                    }
                    else if (kbInfo.event.keyCode === 68 || kbInfo.event.keyCode === 39) {
                        this._dirMoveDic["right"] = false;
                        this.IsNotMove(false);
                    }

                }
            });
            this.observe2 = this.scene.onBeforeRenderObservable.add(() => {
                let t = new Date().getTime();
                let tmp = this.cam.rotation;
                tmp = this.person.value.transform.rotation.add(tmp)
                let tmpV3 = new BABYLON.Vector3(0, 0, 0)
                if (this._dirMoveDic["up"]) {
                    tmpV3 = tmpV3.add(new BABYLON.Vector3(Math.sin(tmp.y), 0, Math.cos(tmp.y)));
                }
                if (this._dirMoveDic["down"]) {
                    tmpV3 = tmpV3.add(new BABYLON.Vector3(-Math.sin(tmp.y), 0, -Math.cos(tmp.y)));
                }
                if (this._dirMoveDic["left"]) {
                    tmpV3 = tmpV3.add(new BABYLON.Vector3(-Math.cos(tmp.y), 0, Math.sin(tmp.y)));
                }
                if (this._dirMoveDic["right"]) {
                    tmpV3 = tmpV3.add(new BABYLON.Vector3(Math.cos(tmp.y), 0, -Math.sin(tmp.y)));
                }
                if (tmpV3.length() != 0) {
                    let tmpSpeed = (t - this.time3) / 20 * this.moveSpeed.value;
                    tmpV3 = tmpV3.normalize().multiplyByFloats(tmpSpeed, 0, tmpSpeed);
                    // tmpV3.y = -9.8;
                    this._virtual.moveWithCollisions(tmpV3);
                }
                this.actual.value.x = this._virtual.position.x;
                this.actual.value.y = this._virtual.position.z;
                this.time3 = t;

                this.person.value.transform.position = new BABYLON.Vector3(this.show.value.x, this.person.value.transform.position.y, this.show.value.y);
            });
        } else {
            if (this.observe)
                this.scene.onKeyboardObservable.remove(this.observe);
            this.observe2 = this.scene.onBeforeRenderObservable.add(() => {
                this.person.value.transform.position = new BABYLON.Vector3(this.show.value.x, this.person.value.transform.position.y, this.show.value.y);
            })
        }
    }

    private getCamera(node: BABYLON.Node) {
        for (let obj of node.getChildren()) {
            if (obj instanceof BABYLON.UniversalCamera) {
                return obj;
            }
            if (obj.getChildren().length > 0) {
                let tmp = this.getCamera(obj);
                if (tmp)
                    return tmp;
            }
        }
        return null;
    }
    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 6)) {
            return false;
        }
        // 参数0：角色id ，全局唯一，由服务器分配
        let para0: VeryParas = new VeryParas();
        if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
            return false;
        }
        this._id = para0.number;
        // 参数1：相机父物体，VeryCamera结构
        let para1: VeryParas = new VeryParas();
        if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para1, para_array[1], this.nodeID)) {
            return false;
        }
        this.person = para1.gameObject;
        let para2 = new VeryParas();
        if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[2])) {
            return false;
        }
        this._isVec3 = para2.isVec;
        this._sizeVec = para2.vector3;
        this._sizeX = para2.vecNumbers[0];
        this._sizeY = para2.vecNumbers[1];
        this._sizeZ = para2.vecNumbers[2];

        // 参数3: 旋转速度
        let para3 = new VeryParas();
        if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para3, para_array[3])) {
            return false;
        }
        this.rotateSpeed = para3.number;

        // 参数4: 平移速度
        let para4 = new VeryParas();
        if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para4, para_array[4])) {
            return false;
        }
        this.moveSpeed = para4.number;
        let para5 = new VeryParas();
        if (!ParaParserUtility.BoolPara(this.objectID, this.ID, ParaType.Action, para5, para_array[5])) {
            return false;
        }
        this.runing = para5.bool;
        return true;
    }

    public destroy(): void {
        if (this.observe)
            this.scene.onKeyboardObservable.remove(this.observe);
        if (this.observe2)
            this.scene.onBeforeRenderObservable.remove(this.observe2);
    }
}

export class Action_Net_Vioce extends VE_ActionBehaviour {
    public get ID(): string {
        return 'Net_Vioce|网络语音';
    }

    public get className(): string {
        return 'Action_Net_Vioce';
    }

    private rec: VeryBool;

    /**
     * 响应激活时运行此函数，此处表示传入变量为true时，激活物体；fasle时，使物体失效；
     */
    public active(): void {
        if (this.rec.value) {
            recStart();
        } else {
            recStop();
        }
    }

    /**
     * 响应初始化时运行此函数，解析传入参数；
     * @param para_array 表格参数按逗号解析一个字符串数组传入；
     * @returns true为解析正确，false为错误；
     */
    public paraParser(para_array: string[]): boolean {
        // 传入参数个数确定，此处表示必须为2个或3个传入参数；
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 1)) {
            return false;
        }
        let para1: VeryParas = new VeryParas(); // 因为要导出整个变量，js也没有类似out的关键字，包裹成一个对象传入以获取变量
        if (!ParaParserUtility.BoolPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
            return false;
        }
        this.rec = para1.bool;  // 获取变量
        bindUpload(this.uploadAudio.bind(this));
        MonoBehaviourMessageCenter.Instance;
        return true;
    }

    private uploadAudio(array: ArrayBuffer) {
        let buf = ByteBuffer.Allocate(2);
        buf.WriteByte(SocketHandle.Vioce);
        buf.WriteArrayBuffer(array);
        SocketManager.Instance.SendMsg(buf);
    }

    public destroy(): void {

    }
}

