import { VeryTable } from "../../verytable";
import { ErrorInfo, VE_StringFormat } from '../utility';
import { VE_ErrorManager, VE_Error } from '../global';
import { VE_Variables, VeryVarManager, IVeryVar, VeryList } from '../variables';
import { VE_Expressions, IExpression } from "../expression";
import { VerySceneVariables } from '../scene';


export class SceneVarLoad {

    private _table!: VeryTable;

    private _projectName: string = '';



    public constructor() {

    }

    // 1、一个个表格解析；
    // 2、多表格不允许重名；
    // 3、后边的表格可以引用前边表格的变量，反之则不行；
    public load(project_name: string, table: VeryTable): boolean {
        this._projectName = project_name;
        this._table = table;

        if (table) {
            let globalVars = new VE_Variables();

            for (let i: number = 1; i < table.RowCount; i++) {
                // console.log(`行号：${i+1}，内容：${table.getData(i, 0)}`);
                // 注释行，直接跳过
                if (table.getData(i, 0).startsWith('//')) {
                    continue;
                }
                // 空行
                if (table.getRow(i)!.isEmpty()) {
                    // console.log('空行：' + (i + 1));
                    // TODO：空行直接分隔状态；
                    continue;
                }
                // 变量提取
                if (table.getData(i, 5) !== '') {
                    let paraData: string = table.getData(i, 5);
                    // 字符串加法公式咋办？双引号先不移除
                    let varArray: string[] = VE_StringFormat.paraSegment(paraData);
                    if (varArray.length === 2 || varArray.length === 3) {
                        let varID: string = varArray[0].trim();
                        if (!VE_StringFormat.isIDLegal(varID)) {
                            VE_ErrorManager.Add(VE_Error.error(table.pos(i, 5), "全局变量：" + table.getData(i, 5) + "，当前变量名不合法，包含非法字符，请检查！", table.ID))
                            return false;
                        }
                        let paraArray: string[] = [varArray[1].trim()];
                        if (varArray.length === 2) {
                            paraArray[1] = '';
                        } else {
                            paraArray[1] = varArray[2].trim();
                        }
                        if (!VerySceneVariables.Variables.varData.isCreatedVariable(varID)) {
                            VerySceneVariables.Variables.varData.addVariable(varID, paraArray, table.pos(i, 5));
                            globalVars.varData.addVariable(varID, paraArray, table.pos(i, 5));
                        } else {
                            VE_ErrorManager.Add(VE_Error.error(table.pos(i, 5), "全局变量：" + table.getData(i, 5) + "，当前全局变量名已创建，请检查！", table.ID))
                            return false;
                        }
                    } else {
                        VE_ErrorManager.Add(VE_Error.error(table.pos(i, 5), "全局变量：" + table.getData(i, 5) + "，当前全局变量格式不正确，请检查！", table.ID))
                        return false;
                    }
                }


            }

            // 2. 场景变量——创建
            // (1).先初始化普通变量
            for (let i = 0; i < globalVars.varData.count; i++) {
                let varID: string = globalVars.varData.getVariableID(i);
                let varPara: string[] = globalVars.varData.getVariableParas(varID);
                // 判断，1.普通变量；2.公式；3.模板变量；
                // 1）公式
                if (varPara[0] === "公式" || varPara[0].toLowerCase() === "expression") {
                    continue;
                }
                // 2）普通IVeryVar变量
                else if (VeryVarManager.hasVarType(varPara[0])) {
                    let errorInfo: ErrorInfo = new ErrorInfo();
                    let newVar: Nullable<IVeryVar> = VeryVarManager.createVariable(
                        varID,
                        varPara[0],
                        varPara[1],
                        errorInfo
                    );
                    // TODO: List或者Dictionary处理
                    //TODO_20210125:List多种方式定义
                    //console.log(varID + "--" + newVar);
                    if (errorInfo.isRight && newVar !== null && newVar.varType === "List") {
                        (<VeryList>newVar).SetChildValue("", errorInfo, '');
                    }
                    if (!errorInfo.isRight || newVar === null) {
                        VE_ErrorManager.Add(
                            VE_Error.error(
                                globalVars.varData.getPos(varID),
                                "表格名：" +
                                project_name +
                                "，全局变量：" +
                                varID +
                                "，" +
                                varPara[0] +
                                "，" +
                                varPara[1] +
                                "，全局变量创建失败，失败原因：" +
                                errorInfo.message +
                                "，请检查！",
                                ""
                            )
                        );
                        return false;
                    } else {
                        VerySceneVariables.Variables.addVariable(varID, newVar);
                        globalVars.addVariable(varID, newVar);
                    }
                }
                //未知错误
                else {
                    VE_ErrorManager.Add(
                        VE_Error.error(
                            globalVars.varData.getPos(varID),
                            "表格名：" +
                            project_name +
                            "，全局变量：" +
                            varID +
                            "，" +
                            varPara[0] +
                            "，" +
                            varPara[1] +
                            "，全局变量创建失败，当前变量不存在，请检查！",
                            ""
                        )
                    );
                    return false;
                }
            }
            // (2).再初始化公式
            for (let i = 0; i < globalVars.varData.count; i++) {
                let varID: string = globalVars.varData.getVariableID(i);
                let varPara: string[] = globalVars.varData.getVariableParas(varID);
                //判断，公式；
                //1.公式
                if (varPara[0] === "公式" || varPara[0].toLowerCase() === "expression") {
                    // 公式之间以从前到后的解析顺序变异，若前面的公式引用了后面的公式，会直接报错
                    let errorInfo: ErrorInfo = new ErrorInfo();
                    let globalExp: IExpression = VE_Expressions.createSceneExpression(
                        varID,
                        varPara[1],
                        errorInfo
                    );
                    if (!errorInfo.isRight || globalExp === null || globalExp === undefined) {
                        VE_ErrorManager.Add(
                            VE_Error.error(
                                globalVars.varData.getPos(varID),
                                "表格名：" +
                                project_name +
                                "，全局变量：" +
                                varID +
                                "," +
                                varPara[0] +
                                "," +
                                varPara[1] +
                                "，全局变量创建失败，公式创建错误：\n" +
                                errorInfo.message,
                                ""
                            )
                        );
                        return false;
                    }
                    globalVars.addExpression(varID, globalExp);
                    VerySceneVariables.Variables.addExpression(varID, globalExp);
                }
                else {
                    continue;
                }
            }
        }


        return true;
    }

}