import {ByteBuffer} from "./ByteBuffer";
import { SocketHandle } from "./SocketBusiness";
import {Dictionary} from "./../utility/dictionary";
import {VeryEngineNode} from "./SocketBusiness";
import {VE_ActionBehaviour} from "../action/actionBehaviour";
import {VE_TriggerBehaviour} from "../trigger/triggerBehaviour";
import {IVeryVar} from "../variables/IVeryVar";
import { SocketManager } from "./SocketManager";
import { MoveModel } from "./MoveModel";
import { VeryNettyPara } from "./VeryNettyPara";

export enum VerySendMode
{
  All = 255, Other = 254, Diff=253
}

export class VeryEngineMessage
{
    public index!:number;
    public frame!:number;
    public value!:ByteBuffer;
}

export class CallbackNetMessage
{
    public type!:SocketHandle;
    public value!:ByteBuffer ;
}

export class MonoBehaviourMessageCenter
{
    private static sInstance:MonoBehaviourMessageCenter;
    private static IsCreate = false;

    public static get Instance():MonoBehaviourMessageCenter
    {
        MonoBehaviourMessageCenter.CreateInstance();
        return MonoBehaviourMessageCenter!.sInstance;
    }

    public static CreateInstance()
    {
        if (MonoBehaviourMessageCenter.IsCreate == true)
            return;

        MonoBehaviourMessageCenter.IsCreate = true;
        this.sInstance=new MonoBehaviourMessageCenter();
        SocketManager.Instance;

    }
    private constructor()
    {
    }

    //自身的网络信息接受激活部分

    private _upDate=new Array<()=>void>()
    public NextTurn()
    {
        if (this._upDate.length != 0)
        {
            for(let func of this._upDate)
                func();
        }
        for(let vec3 in MoveModel.allModel){
            MoveModel.allModel[vec3].sendVec3Info();
        }
    }

    private _netMessageEventList:Dictionary<SocketHandle,Array<(buf:ByteBuffer)=>void>>  = new Dictionary<SocketHandle,Array<(buf:ByteBuffer)=>void>>();
    public  NetMessageData = new Array<CallbackNetMessage>();

    //和二代对接的网络信息部分  void代理 主要用于二代触发
    private  _veryEngineVoidEvent = new Dictionary<number,Array<()=>void>>();

    //bool bool代理 主要用于二代响应
    private _veryEngineBoolEvent = new Dictionary<number, Array<(b1:boolean,b2:boolean)=>void>>();
    //buffer代理，主要用于变量转换
    private _veryEngineBufEvent = new Dictionary<number, Array<(buf:ByteBuffer)=>void>>();
    //记录所有二代有关网络部分触发响应发送的模式：全局发送、除自己以外发送、指定对象发送
    private _recordSendMode = new Dictionary<number, number>();
    //记录所有二代有关网络部分触发响应变量
    private _recordVeryEngine = new Dictionary<VE_ActionBehaviour|VE_TriggerBehaviour|IVeryVar, number>();
    private _recordVeryEngineLast=new Dictionary<number,number>();
    private count = 0;
    //为了保证触发和响应综合的激活顺序一致，以结构的方式记录
    //如果分开写，则必会发送先激活一遍所有触发或者先激活一遍所有响应
    private VeryEngineData = new Array<VeryEngineMessage>();


    public GetVeryEngineIndex (target:VE_ActionBehaviour|VE_TriggerBehaviour|IVeryVar):number
    {
        if (this._recordVeryEngine.ContainsKey(target))
        {
            return this._recordVeryEngine.GetValue(target)!;
        }
        else
        {
            return -1;
        }
    }

    public GetSendMode(index:number):number
    {
        if (this._recordSendMode.ContainsKey(index))
        {
            return this._recordSendMode.GetValue(index)!;
        }
        else
        {
            return VerySendMode.All;
        }
    }

    public GetVeryEngineVar(index:number):IVeryVar|null
    {
        let keys=this._recordVeryEngine.GetKeys();
        for(let i=0;i<keys.length;i++)
        {
            let key=keys[i];
            if(this._recordVeryEngine.GetValue(key) === index)
                return (key as IVeryVar);
        }
        return null;
    }

    //添加变量网络传递事件
    public AddVeryEngineVeryVarEvent(obj:IVeryVar, handle:(buf:ByteBuffer)=>void):number
    {
        if (!this._recordVeryEngine.ContainsKey(obj))
        {
            let index =this.count++ + 100;
            this._recordVeryEngine.Add(obj, index);
            this._veryEngineBufEvent.Add(index, new Array<(buf:ByteBuffer)=>void>());
            this._veryEngineBufEvent.GetValue(index)!.push(handle);
        }
        return this._recordVeryEngine.GetValue(obj)!;
    }

    //添加关联引擎触发事件
    public AddVeryEngineTriggerEvent(obj:VE_TriggerBehaviour, handle:()=>void, mode:VerySendMode)
    {
        if (!this._recordVeryEngine.ContainsKey(obj))
        {
            let index = this.count++ + 100;
            this._recordVeryEngine.Add(obj, index);
            this._veryEngineVoidEvent.Add(index,new Array<()=>void>());
            this._veryEngineVoidEvent.GetValue(index)!.push(handle);
            this._recordSendMode.Add(index, mode);
        }
    }

    //特殊类型的关联触发事件
    public AddVeryEngineTriggerSpecial(obj:VeryEngineNode , handle:()=>void)
    {
        if(!this._veryEngineVoidEvent.ContainsKey(obj))
            this._veryEngineVoidEvent.Add(obj,new Array<()=>void>());
        this._veryEngineVoidEvent.GetValue(obj)!.push(handle);
    }

    //添加关联引擎响应事件
    public AddVeryEngineActionEvent(obj:VE_ActionBehaviour, handle:(b1:boolean,b2:boolean)=>void, mode:VerySendMode)
    {
        if (!this._recordVeryEngine.ContainsKey(obj))
        {
            let index =this.count++ + 100;
            this._recordVeryEngine.Add(obj, index);
            this._veryEngineBoolEvent.Add(index, new Array<(b1:boolean,b2:boolean)=>void>());
            this._veryEngineBoolEvent.GetValue(index)!.push(handle);
            this._recordSendMode.Add(index, mode);
        }
    }

    //添加网络事件观察者
    public AddObserverEvent( handle_type:SocketHandle,  call_back:(action:ByteBuffer)=>void)
    {
        if (!this._netMessageEventList.ContainsKey(handle_type))
        {
            this._netMessageEventList.Add(handle_type, new Array<(action:ByteBuffer)=>void>());
        }
        this._netMessageEventList.GetValue(handle_type)!.push(call_back);
    }

    //删除网络事件观察者
    public removeObserver( handle_type:SocketHandle,  call_back:(buf:ByteBuffer)=>void)
    {
        if (this._netMessageEventList.ContainsKey(handle_type))
        {
            let index=this._netMessageEventList.GetValue(handle_type).indexOf(call_back);
            if(index>=0)
                this._netMessageEventList.GetValue(handle_type)!.splice(index,1);
            if (this._netMessageEventList.GetValue(handle_type)!.length)
            {
                this._netMessageEventList.Remove(handle_type);
            }
        }
    }
    
    //接收触发信号
    public AddTriggerMessage(index:number,frame:number)
    {
        let tmpMessage = new VeryEngineMessage();
        tmpMessage.index = index;
        tmpMessage.frame=frame;
        tmpMessage.value=ByteBuffer.Allocate(0);
        this.VeryEngineData.push(tmpMessage);
    }

    //接收特殊类型触发信号
    public AddTriggerSpecial(node:VeryEngineNode)
    {
        let tmpMessage = new VeryEngineMessage();
        tmpMessage.index = node;
        tmpMessage.value=ByteBuffer.Allocate(0);
        this.VeryEngineData.push(tmpMessage);
    }

    //接收响应信号
    public AddActionMessage(index:number,frame:number, buf: ByteBuffer)
    {
        let tmpMessage = new VeryEngineMessage();
        tmpMessage.index = index;
        tmpMessage.frame=frame;
        tmpMessage.value = buf;
        this.VeryEngineData.push(tmpMessage);
    }

    //接收变量信号
    public AddValMessage(index:number,frame:number,buf:ByteBuffer)
    {
        let tmpMessage = new VeryEngineMessage();
        tmpMessage.index = index;
        tmpMessage.frame=frame;
        tmpMessage.value = buf;
        this.VeryEngineData.push(tmpMessage);
    }


    //接收普通信号（无需帧同步的信号）
    public AddObseverMessage(handle_type:SocketHandle,  buf?:ByteBuffer)
    {
        let callbackNetMessage = new CallbackNetMessage();
        callbackNetMessage.type = handle_type;
        if(buf!=undefined)
            callbackNetMessage.value = buf;
        else
            callbackNetMessage.value=ByteBuffer.Allocate(0);
        this.NetMessageData.push(callbackNetMessage);
    }


    public  AddUpdateEvent(update:()=>void)
    {
        if(this._upDate!=undefined)
            this._upDate.push(update);
    }


    public update()
    {
        if(MonoBehaviourMessageCenter.IsCreate)
        {
            while (this.NetMessageData.length > 0)
            {
                let tmpNetMessageData = this.NetMessageData.shift()!;
                if (this._netMessageEventList.ContainsKey(tmpNetMessageData.type))
                {
                    let obj=this._netMessageEventList.GetValue(tmpNetMessageData.type);
                    for(let func of obj){
                        func(tmpNetMessageData.value)
                    }
                }
            }
            while (this.VeryEngineData.length > 0)
            {
                let tmpVeryEngineMessage = this.VeryEngineData.shift()!;
                let tmpIndex = tmpVeryEngineMessage.index;
                let frame=tmpVeryEngineMessage.frame;
                //记录每一个触发响应最后一次的激活帧数，若接收到的帧
                if(!this._recordVeryEngineLast.ContainsKey(frame)){
                    this._recordVeryEngineLast.Add(tmpIndex,frame);
                }else if(this._recordVeryEngineLast.GetValue(tmpIndex)<frame){
                    this._recordVeryEngineLast.SetValue(tmpIndex,frame)
                }else{
                    continue;
                }
                if (this._veryEngineVoidEvent.ContainsKey(tmpIndex))
                {
                    let obj=this._veryEngineVoidEvent.GetValue(tmpIndex)!;
                    for(let func of obj){
                        func()
                    }
                }
                else if (this._veryEngineBoolEvent.ContainsKey(tmpIndex))
                {
                    for(let func of this._veryEngineBoolEvent.GetValue(tmpIndex)!){
                        func(tmpVeryEngineMessage.value.ReadBoolean(),tmpVeryEngineMessage.value.ReadBoolean());
                    }
                }
                else if (this._veryEngineBufEvent.ContainsKey(tmpIndex))
                {
                    for(let func of this._veryEngineBufEvent.GetValue(tmpIndex)!){
                        func(tmpVeryEngineMessage.value);
                    }
                }
                else
                {
                    //Debug.LogWarning(tmpIndex);
                }
            }

            for(let vec3 in MoveModel.allModel){
                MoveModel.allModel[vec3].update();
            }
        }
    }

    public PoolSendTriggerMsg(send_mode:number,index:number)
    {
        let Value = ByteBuffer.Allocate(255);
        Value.WriteByte(SocketHandle.GameTurn);//发送信息主标识
        Value.WriteInt(send_mode);
        Value.WriteByte(VeryEngineNode.Trigger); //发送引擎信息的标识
        Value.WriteInt(index); //发送对应的响应(触发、变量)个体实例序号
        Value.WriteInt(VeryNettyPara.lockStepTurnID);//帧序号
        SocketManager.Instance.PoolSendMsg(Value);
    }

    public PoolSendVarMsg(send_mode:number,index:number,buff:ByteBuffer)
    {
        let Value = ByteBuffer.Allocate(255);
        Value.WriteByte(SocketHandle.GameTurn);
        Value.WriteInt(send_mode);
        Value.WriteByte(VeryEngineNode.Var);
        Value.WriteInt(index); //发送对应的响应(触发、变量)个体实例序号
        Value.WriteInt(VeryNettyPara.lockStepTurnID);//帧序号
        Value.Write(buff);
        SocketManager.Instance.PoolSendMsg(Value);
    }

    public PoolSendActionMsg(send_mode:number,index:number,action_val:boolean, every_frame:boolean)
    {
        let Value = ByteBuffer.Allocate(255);
        Value.WriteByte(SocketHandle.GameTurn);
        Value.WriteInt(send_mode);
        Value.WriteByte(VeryEngineNode.Action);
        Value.WriteInt(index);
        Value.WriteInt(VeryNettyPara.lockStepTurnID);//帧序号
        Value.WriteBoolean(action_val);
        Value.WriteBoolean(every_frame);
        SocketManager.Instance.PoolSendMsg(Value);
    }
}