import { VE_ActionBehaviour, VE_Actions } from "../../action";
import { ActionType, ParaType, Severity } from "../../enum";
import { ParaParserUtility, VeryParas, FloatUitlity } from "../../utility";
import { VeryNumber, VeryBool, VeryVector3, VeryGameObject } from "../../variables";
// import { VE_ErrorManager, VE_Error } from "../../global";

export class Action_Phone_GetOrientation extends VE_ActionBehaviour {

    public get ID(): string {
        return "Phone_GetOrientation|获取手机设备姿态";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '获取手机设备姿态，*变量1，*变量2，*变量3，*变量4，*变量5';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=912';
    }
    public get className(): string {
        return "Action_Phone_GetOrientation";
    }

    // alpha: 在Z轴上的角度
    private _blueNumber_alpha: VeryNumber = new VeryNumber();
    // gamma: 从左到右
    private _blueNumber_gamma: VeryNumber = new VeryNumber();
    // beta: 从前到后的运动
    private _blueNumber_beta: VeryNumber = new VeryNumber();

    //设备的加速度
    private _blueVec3_acceleration: VeryVector3 = new VeryVector3();
    //设备围绕其每个轴（x、y、z）旋转的速率
    private _blueVec3_rotationRate: VeryVector3 = new VeryVector3();

    public active(): void {

        let tmp = this;
        let tmpBtn;
        //iphone手机处理
        if (typeof (DeviceOrientationEvent) !== "undefined" && typeof ((DeviceOrientationEvent as any).requestPermission) === "function") {
            tmpBtn = document.createElement("BUTTON");
            tmpBtn.style.position = 'absolute';
            tmpBtn.style.left = (window.innerWidth - 200) / 2 + 'px';
            tmpBtn.style.top = (window.innerHeight - 30) / 2 + 'px';
            tmpBtn.style.width = 200 + 'px';
            tmpBtn.style.height = 30 + 'px';
            tmpBtn.addEventListener("click", permission);
            var t = document.createTextNode("权限申请");
            tmpBtn.appendChild(t);
            document.body.append(tmpBtn);
        }
        //android手机处理
        else {
            //姿态信息
            window.addEventListener("deviceorientation", (e) => {
                // alpha: 在Z轴上的角度
                var rotateDegrees = e.alpha;
                // beta: 从前到后的运动
                var frontToBack = e.beta;
                // gamma: 从左到右
                var leftToRight = e.gamma;

                if (rotateDegrees !== null && leftToRight !== null && frontToBack !== null) {
                    tmp._blueNumber_alpha.value = rotateDegrees;
                    tmp._blueNumber_beta.value = frontToBack;
                    tmp._blueNumber_gamma.value = leftToRight;
                }
                else {
                    alert("当前设备和浏览器不支持获取手机设备姿态:DeviceOrientationEvent is not defined");
                }
            });
            //加速度信息
            window.addEventListener("devicemotion", (e) => {
                var acceleration = e.acceleration;
                var rotationRate = e.rotationRate;

                if (acceleration !== null && rotationRate !== null) {
                    tmp._blueVec3_acceleration.value = new BABYLON.Vector3(acceleration.x, acceleration.y, acceleration.z);
                    tmp._blueVec3_rotationRate.value = new BABYLON.Vector3(rotationRate.alpha, rotationRate.beta, rotationRate.gamma);
                }
                else {
                    alert("当前设备和浏览器不支持获取手机设备姿态:DeviceMotionEvent is not defined");
                }
            });
        }

        //iphone权限申请
        function permission() {
            //隐藏
            tmpBtn.style.display = 'none';
            // (optional) Do something before API request prompt.
            (DeviceOrientationEvent as any).requestPermission().then(response => {
                // (optional) Do something after API prompt dismissed.
                if (response == "granted") {

                    //姿态信息
                    window.addEventListener("deviceorientation", (e) => {
                        // alpha: 在Z轴上的角度
                        var rotateDegrees = e.alpha;
                        // beta: 从前到后的运动
                        var frontToBack = e.beta;
                        // gamma: 从左到右
                        var leftToRight = e.gamma;

                        if (rotateDegrees !== null && leftToRight !== null && frontToBack !== null) {
                            tmp._blueNumber_alpha.value = rotateDegrees;
                            tmp._blueNumber_beta.value = frontToBack;
                            tmp._blueNumber_gamma.value = leftToRight;
                        }
                        else {
                            alert("当前设备和浏览器不支持获取手机设备姿态:DeviceOrientationEvent is not defined");
                        }
                    })

                    //加速度信息
                    window.addEventListener("devicemotion", (e) => {
                        var acceleration = e.acceleration;
                        var rotationRate = e.rotationRate;

                        if (acceleration !== null && rotationRate !== null) {
                            tmp._blueVec3_acceleration.value = new BABYLON.Vector3(acceleration.x, acceleration.y, acceleration.z);
                            tmp._blueVec3_rotationRate.value = new BABYLON.Vector3(rotationRate.alpha, rotationRate.beta, rotationRate.gamma);
                        }
                        else {
                            alert("当前设备和浏览器不支持获取手机设备姿态:DeviceMotionEvent is not defined");
                        }
                    });
                }
            }).catch(console.error)
        }
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 5)) {
            return false;
        } else {
            // 参数1：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._blueNumber_alpha = para1.number;

            // 参数2：
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaOnlyVar(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._blueNumber_beta = para2.number;

            // 参数3：
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaOnlyVar(this.objectID, this.ID, ParaType.Action, para3, para_array[2])) {
                return false;
            }
            this._blueNumber_gamma = para3.number;

            // 参数4：
            let para4: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3Para(this.objectID, this.ID, ParaType.Action, para4, para_array[3])) {
                return false;
            }
            this._blueVec3_acceleration = para4.vector3;

            // 参数5：
            let para5: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3Para(this.objectID, this.ID, ParaType.Action, para5, para_array[4])) {
                return false;
            }
            this._blueVec3_rotationRate = para5.vector3;

            return true;
        }
    }
    public destroy(): void {

    }
}

export class Action_Phone_ControlOrientation extends VE_ActionBehaviour {

    public get ID(): string {
        return "Phone_ControlOrientation|手机控制物体姿态";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '手机控制物体姿态，立方体';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=915';
    }
    public get className(): string {
        return "Action_Phone_ControlOrientation";
    }

    //控制物体
    private _blueObj: VeryGameObject = new VeryGameObject();

    //初始化
    private _initialed: boolean = false;
    //控制开启和关闭
    private _active: VeryBool = new VeryBool();
    //辅助参数
    private _tmpBtn: any = null;
    private _screenOrientationAngle: number = 0;
    private _constantTranform: BABYLON.Quaternion = new BABYLON.Quaternion(-Math.sqrt(0.5), 0, 0, Math.sqrt(0.5));
    private _screenQuaternion: BABYLON.Quaternion = new BABYLON.Quaternion(0, 0, 0, 1);
    private _initQuaternion: BABYLON.Nullable<BABYLON.Quaternion> = null;
    private _androidAlpha: number = -1;

    private _orientationChanged = () => {
        this._screenOrientationAngle = <any>window.orientation !== undefined ? +(<any>window.orientation) : (<any>window.screen).orientation && (<any>window.screen).orientation["angle"] ? (<any>window.screen).orientation.angle : 0;
        this._screenOrientationAngle = -BABYLON.Tools.ToRadians(this._screenOrientationAngle / 2);
        this._screenQuaternion.copyFromFloats(0, Math.sin(this._screenOrientationAngle), 0, Math.cos(this._screenOrientationAngle));
    };

    public active(): void {
        let tmp = this;
        this._active.value = true;

        //iphone权限申请
        function permission() {
            //隐藏
            tmp._tmpBtn.style.display = 'none';
            // (optional) Do something before API request prompt.
            (DeviceOrientationEvent as any).requestPermission().then(response => {
                // (optional) Do something after API prompt dismissed.
                if (response == "granted") {
                    //姿态信息
                    window.addEventListener("deviceorientation", (e) => {
                        // alpha: 在Z轴上的角度
                        var rotateDegrees = e.alpha;
                        // beta: X轴从前到后的运动
                        var frontToBack = e.beta;
                        // gamma: Y轴从左到右
                        var leftToRight = e.gamma;

                        if (tmp._active.value) {

                            //DO_20220314:获取手机设备姿态,手机控制物体姿态
                            if (rotateDegrees !== null && leftToRight !== null && frontToBack !== null) {
                                if (tmp._blueObj.value.transform.transformNode.rotationQuaternion === null || tmp._blueObj.value.transform.transformNode.rotationQuaternion === undefined) {
                                    tmp._blueObj.value.transform.transformNode.rotationQuaternion = new BABYLON.Quaternion(0, 0, 0, 1);
                                }
                                var newQuaternion = new BABYLON.Quaternion(0, 0, 0, 1);
                                BABYLON.Quaternion.RotationYawPitchRollToRef(BABYLON.Tools.ToRadians(rotateDegrees), BABYLON.Tools.ToRadians(frontToBack), -BABYLON.Tools.ToRadians(leftToRight), newQuaternion);
                                newQuaternion.multiplyInPlace(tmp._screenQuaternion);
                                newQuaternion.multiplyInPlace(tmp._constantTranform);
                                //Mirror on XY Plane
                                newQuaternion.z *= -1;
                                newQuaternion.w *= -1;

                                if (tmp._initQuaternion === null) {
                                    tmp._initQuaternion = new BABYLON.Quaternion(0, 0, 0, 1);
                                    tmp._initQuaternion.copyFrom(newQuaternion);
                                }
                                var tmpQ = newQuaternion.multiply(tmp._initQuaternion.conjugate());
                                //tmp._blueObj.value.transform.transformNode.rotationQuaternion.copyFrom(tmpQ);
                                tmp._blueObj.value.transform.transformNode.rotationQuaternion.copyFrom(newQuaternion);
                            }
                            else {
                                alert("当前设备和浏览器不支持获取手机设备姿态:DeviceOrientationEvent is not defined");
                            }
                        }
                    })
                }
            }).catch(console.error)
        }

        if (!this._initialed) {
            this._initialed = true;
            //横屏竖屏处理
            this._orientationChanged();
            //监听屏幕方向处理
            window.onorientationchange = function () {
                tmp._orientationChanged();
            }

            //iphone手机处理
            if (typeof (DeviceOrientationEvent) !== "undefined" && typeof ((DeviceOrientationEvent as any).requestPermission) === "function") {
                this._tmpBtn = document.createElement("BUTTON");
                this._tmpBtn.style.position = 'absolute';
                this._tmpBtn.style.left = (window.innerWidth - 200) / 2 + 'px';
                this._tmpBtn.style.top = (window.innerHeight - 30) / 2 + 'px';
                this._tmpBtn.style.width = 200 + 'px';
                this._tmpBtn.style.height = 30 + 'px';
                this._tmpBtn.addEventListener("click", permission);
                var t = document.createTextNode("权限申请");
                this._tmpBtn.appendChild(t);
                document.body.append(this._tmpBtn);
            }
            //android手机处理
            else {
                //姿态信息
                window.addEventListener("deviceorientation", (e) => {
                    // alpha: 在Z轴上的角度
                    var rotateDegrees = e.alpha;
                    // beta: 从前到后的运动
                    var frontToBack = e.beta;
                    // gamma: 从左到右
                    var leftToRight = e.gamma;

                    if (tmp._active.value) {
                        //DO_20220314:获取手机设备姿态,手机控制物体姿态
                        if (rotateDegrees !== null && leftToRight !== null && frontToBack !== null) {
                            if (tmp._blueObj.value.transform.transformNode.rotationQuaternion === null || tmp._blueObj.value.transform.transformNode.rotationQuaternion === undefined) {
                                tmp._blueObj.value.transform.transformNode.rotationQuaternion = new BABYLON.Quaternion(0, 0, 0, 1);
                            }

                            //android获取初始化alpha
                            if (tmp._androidAlpha === -1 && (rotateDegrees !== 0)) {
                                tmp._androidAlpha = rotateDegrees;
                                //alert(rotateDegrees + '--' + leftToRight + '--' + frontToBack);
                            }
                            //android处理alpha
                            rotateDegrees = rotateDegrees - tmp._androidAlpha;

                            var newQuaternion = new BABYLON.Quaternion(0, 0, 0, 1);
                            BABYLON.Quaternion.RotationYawPitchRollToRef(BABYLON.Tools.ToRadians(rotateDegrees), BABYLON.Tools.ToRadians(frontToBack), -BABYLON.Tools.ToRadians(leftToRight), newQuaternion);
                            newQuaternion.multiplyInPlace(tmp._screenQuaternion);
                            newQuaternion.multiplyInPlace(tmp._constantTranform);
                            //Mirror on XY Plane
                            newQuaternion.z *= -1;
                            newQuaternion.w *= -1;

                            if (tmp._initQuaternion === null) {
                                tmp._initQuaternion = new BABYLON.Quaternion(0, 0, 0, 1);
                                tmp._initQuaternion.copyFrom(newQuaternion);
                            }
                            var tmpQ = newQuaternion.multiply(tmp._initQuaternion.conjugate());
                            //tmp._blueObj.value.transform.transformNode.rotationQuaternion.copyFrom(tmpQ);
                            tmp._blueObj.value.transform.transformNode.rotationQuaternion.copyFrom(newQuaternion);
                        }
                        else {
                            alert("当前设备和浏览器不支持获取手机设备姿态:DeviceOrientationEvent is not defined");
                        }
                    }
                });
            }
        }
    }

    public onDisable(): void {
        this._active.value = false;
        this._initQuaternion = null;
        this._androidAlpha = -1;
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 1)) {
            return false;
        } else {
            // 参数1：物体
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0], this.nodeID)) {
                return false;
            }
            this._blueObj = para1.gameObject;

            return true;
        }
    }
    public destroy(): void {

    }
}

//DO_20220314:获取手机设备姿态,手机控制物体姿态
VE_Actions.addAction(Action_Phone_GetOrientation);
VE_Actions.addAction(Action_Phone_ControlOrientation);