import { VE_ActionBehaviour, VE_Actions } from "../../action";
import { ParaParserUtility, VE_KeyboardMap, VeryParas } from '../../utility';
import { ParaType, Severity } from '../../enum';
import { VeryGameObject, VeryBool, VeryNumber, VeryString, VeryRect, VeryVector3, VeryVector2, VeryMaterial } from "../../variables";
import { Action_AudioPlay } from './action-audio';

declare var MediaRecorder: any;

export class Action_RecordVideo_Start extends VE_ActionBehaviour {

    public get ID(): string {
        return 'RecordVideo_Start|开始录制视频';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '开始录制视频';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=843';
    }
    public get className(): string {
        return 'Action_RecordVideo_Start';
    }

    public static mediaRecorder;
    public static recordedBlobs;
    public static canvas;
    public static stream;

    public active(): void {
        Action_RecordVideo_Start.canvas = document.querySelector('canvas');
        Action_RecordVideo_Start.stream = Action_RecordVideo_Start.canvas.captureStream(); // frames per second

        var audio = document.querySelector('audio');
        //console.log('audio--' + audio);
        //console.log('audioContext--' + BABYLON.Engine.audioEngine.audioContext);
        if (audio) {
            var audioCtx = new AudioContext();
            // create a stream from our AudioContext
            var dest = audioCtx.createMediaStreamDestination();
            var audioStream = dest.stream;
            // connect our audio element's output to the stream
            var sourceNode = audioCtx.createMediaElementSource(audio);
            sourceNode.connect(dest)
            sourceNode.connect(audioCtx.destination);
            Action_RecordVideo_Start.stream.addTrack(audioStream.getAudioTracks()[0]);
        }
        else if (BABYLON.Engine.audioEngine.audioContext) {
            if (Action_AudioPlay._soundSource) {
                var dest = BABYLON.Engine.audioEngine.audioContext.createMediaStreamDestination();
                var audioStream = dest.stream;
                Action_AudioPlay._soundSource.connect(dest);
                Action_RecordVideo_Start.stream.addTrack(audioStream.getAudioTracks()[0]);
            }
        }

        //let options = {mimeType: 'audio/webm'};
        let options = { mimeType: 'video/webm\;codecs=vp8' };
        Action_RecordVideo_Start.recordedBlobs = [];
        try {
            //mediaRecorder = new MediaRecorder(stream, options);
            Action_RecordVideo_Start.mediaRecorder = new MediaRecorder(Action_RecordVideo_Start.stream);
        } catch (e0) {
            console.log('Unable to create MediaRecorder with options Object: ', e0);
            try {
                options = {
                    mimeType: 'video/webm,codecs=vp9'
                };
                Action_RecordVideo_Start.mediaRecorder = new MediaRecorder(Action_RecordVideo_Start.stream, options);
            } catch (e1) {
                console.log('Unable to create MediaRecorder with options Object: ', e1);
                try {
                    options = {
                        mimeType: 'video/vp8'
                    };; // Chrome 47
                    Action_RecordVideo_Start.mediaRecorder = new MediaRecorder(Action_RecordVideo_Start.stream, options);
                } catch (e2) {
                    console.error('Exception while creating MediaRecorder:', e2);
                    return;
                }
            }
        }
        Action_RecordVideo_Start.mediaRecorder.onstop = this.handleStop;
        Action_RecordVideo_Start.mediaRecorder.ondataavailable = this.handleDataAvailable;
        Action_RecordVideo_Start.mediaRecorder.start(100); // collect 100ms of data
        //console.log('MediaRecorder started');
    }
    private handleDataAvailable(event) {
        if (event.data && event.data.size > 0) {
            Action_RecordVideo_Start.recordedBlobs.push(event.data);
        }
    }
    private handleStop(event) {
        //console.log('Recorder stopped: ', event);
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 0)) {
            return false;
        } else {
            return true;
        }

    }
    public destroy(): void {

    }
}
export class Action_RecordVideo_Stop extends VE_ActionBehaviour {

    public get ID(): string {
        return 'RecordVideo_Stop|结束录制视频';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '结束录制视频';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=844';
    }
    public get className(): string {
        return 'Action_RecordVideo_Stop';
    }

    public active(): void {
        //console.log("WebGLRecoder: Stopping recording");
        Action_RecordVideo_Start.mediaRecorder.stop();
    }


    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 0)) {
            return false;
        } else {
            return true;
        }

    }
    public destroy(): void {

    }
}
export class Action_RecordVideo_Download extends VE_ActionBehaviour {

    public get ID(): string {
        return 'RecordVideo_Download|下载录制视频';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '下载录制视，测试';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=845';
    }
    public get className(): string {
        return 'Action_RecordVideo_Download';
    }

    //文件名
    private _fileNameString: VeryString = new VeryString();

    public active(): void {
        const blob = new Blob(Action_RecordVideo_Start.recordedBlobs, {
            type: 'video/webm'
        });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.style.display = 'none';
        a.href = url;
        //a.download = 'test.webm';
        a.download = this._fileNameString.value;
        document.body.appendChild(a);
        a.click();
        setTimeout(() => {
            document.body.removeChild(a);
            window.URL.revokeObjectURL(url);
        }, 100);
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 1)) {
            return false;
        } else {

            //参数1
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._fileNameString = para1.string;

            return true;
        }

    }
    public destroy(): void {

    }
}

