export enum SocketHandle
{
  JoinGame = 1, GameTurn = 2, NextTurn = 3, CreatRoom = 4, GameStart = 5, GetRoomID = 8, Exit = 9, CallBack = 10,
  Vioce=18, Empty = 99,Valid=127
}

//和引擎对接的接口
export enum VeryEngineNode
{
  VeryGameObject = 2, VeryString = 3, Var = 97, Action = 98, Trigger = 99,Move=100,Character=101,Exit=102,GetIdentity =103,Pos=104,MoveSate=105
}

export const messageHandlers={};
messageHandlers[SocketHandle.GameTurn]=(buf:ByteBuffer)=>{
  let self=buf.ReadInt();
  let type = buf.ReadByte();
  if(type==VeryEngineNode.GetIdentity){
    let index = buf.ReadInt();
    if(self==index){
      SocketManager.setPlayerId(index);
    }
    else{
      for(let vec3 in MoveModel.allModel){
        MoveModel.allModel[vec3].sendCurrent(index);
      }
    }
    if(SocketManager.playJoin){
      SocketManager.playJoin(self==index,index);
    }
  }
  else if(type==VeryEngineNode.Move||type==VeryEngineNode.MoveSate){
    let index = buf.ReadInt();
    if(MoveModel.allModel[index]){
      MoveModel.allModel[index].accept(type,buf);
    }
  }
  else if(type==VeryEngineNode.Pos){
    let index = buf.ReadInt();
    if(MoveModel.allModel[index]){
      MoveModel.allModel[index].accept(type,buf);
    }else{
      let len=buf.ReadableBytes()/4;
      new MoveModel(len,index).accept(type,buf);
    }
  }
  else if(type==VeryEngineNode.Exit){
    let index = buf.ReadInt();
    delete MoveModel.allModel[index]
    for(let exit of SocketManager.playExit){
      exit(index);
    }
  }
  else{
    if (type == VeryEngineNode.Action)
    {
        let index = buf.ReadInt();
        let frame=buf.ReadInt();
        MonoBehaviourMessageCenter.Instance.AddActionMessage(index,frame, buf.ReadRetainedSlice());
    }
    else if (type == VeryEngineNode.Trigger)
    {
        let index = buf.ReadInt();
        let frame=buf.ReadInt();
        MonoBehaviourMessageCenter.Instance.AddTriggerMessage(index,frame);
    }
    else if(type==VeryEngineNode.Var)
    {
        let index =buf.ReadInt();
        let frame=buf.ReadInt();
        MonoBehaviourMessageCenter.Instance.AddValMessage(index,frame, buf.ReadRetainedSlice());
    }
  }
}

