import { VE_ActionBehaviour, VE_Actions } from "../../action";
import { ParaType, Severity } from "../../enum";
import { ParaParserUtility, VeryParas } from "../../utility";
import { VeryNumber, VeryBool, VeryString, VeryVector3 } from "../../variables";
import { VE_ErrorManager, VE_Error } from "../../global";
// import { BabylonEngine } from "../../../veryengine/babylon";
import { BabylonLoader } from "../../../veryengine/loader";

export class Action_360Photo extends VE_ActionBehaviour {

    public get ID(): string {
        return "360Photo|360图片";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '360图片，*360图片显示控制，1640317036-8b2c13c4，32，10000，0，(0，1000，0)';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=886';
    }
    public get className(): string {
        return "Action_360Photo";
    }

    //控制显示
    private _control: VeryBool = new VeryBool();
    //url
    private _photoURL: VeryString = new VeryString();
    //分辨率
    private _resolution: VeryNumber = new VeryNumber();
    //物体半径
    private _size: VeryNumber = new VeryNumber();
    //image类型
    private _imageType: VeryNumber = new VeryNumber();
    //DO_20211224:添加位置参数
    //位置
    private _posVec: VeryVector3 = new VeryVector3();
    private _isVec: boolean = false;
    private _x: VeryNumber = new VeryNumber();
    private _y: VeryNumber = new VeryNumber();
    private _z: VeryNumber = new VeryNumber();

    private _dome: BABYLON.Nullable<BABYLON.PhotoDome> = null;

    public active(): void {
        //创建360图片
        if (this._dome === null) {
            this._dome = new BABYLON.PhotoDome(
                "photoDome",
                this._photoURL.value,
                {
                    resolution: this._resolution.value,
                    size: this._size.value,
                    useDirectMapping: true
                },
                this.scene
            );
        }
        //设置图片模式和激活
        this._dome.imageMode = this._imageType.value;
        this._dome.setEnabled(this._control.value);
        //DO_20211224:添加位置参数
        if (this._isVec) {
            this._dome.position = this._posVec.value;
        }
        else {
            this._dome.position = new BABYLON.Vector3(this._x.value, this._y.value, this._z.value);
        }
    }

    public onUpdate(): void {

    }
    private async initPhoto() {
        let self = this;
        self._photoURL.value = await BabylonLoader.getAssetUrl(self._photoURL.value);
        if (self._photoURL.value === '') {
            console.error('360图片 初始化失败，asset_id：' + self._photoURL.value + '，无法在当前场景中查找到该ID，请检查！');
        }
    }

    public paraParser(para_array: string[]): boolean {
        //DO_20211224:添加位置参数
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 4, 5, 6)) {
            return false;
        } else {

            // 参数0：
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._control = para0.bool;

            // 参数1：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[1])) {
                return false;
            }
            this._photoURL = para1.string;
            setTimeout(this.initPhoto.bind(this), 0);

            // 参数2：
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[2])) {
                return false;
            }
            this._resolution = para2.number;

            // 参数3：
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[3])) {
                return false;
            }
            this._size = para3.number;

            // 参数4：
            this._imageType.value = BABYLON.PhotoDome.MODE_MONOSCOPIC;
            if (para_array.length > 4) {
                if (para_array[4] === '0') {
                    this._imageType.value = BABYLON.PhotoDome.MODE_MONOSCOPIC;
                }
                else if (para_array[4] === '1') {
                    this._imageType.value = BABYLON.PhotoDome.MODE_TOPBOTTOM;
                }
                else if (para_array[4] === '2') {
                    this._imageType.value = BABYLON.PhotoDome.MODE_SIDEBYSIDE;
                }
                else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[4] + "，{{360图片响应中图片类型填写错误}}，{{应为012中的一种}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }

            //DO_20211224:添加位置参数
            //参数5
            this._isVec = true;
            this._posVec.value = new BABYLON.Vector3(0, 0, 0);
            if (para_array.length > 5) {
                let para5: VeryParas = new VeryParas();
                if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para5, para_array[5])) {
                    return false;
                }
                this._isVec = para5.isVec;
                this._posVec = para5.vector3;
                this._x = para5.vecNumbers[0];
                this._y = para5.vecNumbers[1];
                this._z = para5.vecNumbers[2];
            }

            return true;
        }
    }
    public destroy(): void {
        if (this._dome) {
            this._dome.dispose();
        }
        this._dome = null;
    }
}
export class Action_360Vedio extends VE_ActionBehaviour {

    public get ID(): string {
        return "360Vedio|360视频";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '360视频，*360视频显示控制，1640328240-b8cff384，32，10000，*360视频播放控制，true，1，0，(0，1000，0)';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=887';
    }
    public get className(): string {
        return "Action_360Vedio";
    }

    //控制显示
    private _control: VeryBool = new VeryBool();
    //url
    private _vedioURL: VeryString = new VeryString();
    //分辨率
    private _resolution: VeryNumber = new VeryNumber();
    //物体半径
    private _size: VeryNumber = new VeryNumber();
    //是否播放
    private _switch: VeryBool = new VeryBool();
    //视频循环
    private _musicLoop: VeryBool = new VeryBool();
    //视频音乐大小
    private _musicVolume: VeryNumber = new VeryNumber();
    //vedio类型
    private _vedioType: VeryNumber = new VeryNumber();
    //DO_20211224:添加位置参数
    //位置
    private _posVec: VeryVector3 = new VeryVector3();
    private _isVec: boolean = false;
    private _x: VeryNumber = new VeryNumber();
    private _y: VeryNumber = new VeryNumber();
    private _z: VeryNumber = new VeryNumber();

    private _dome: BABYLON.Nullable<BABYLON.VideoDome> = null;

    public active(): void {
        //创建360视频
        if (this._dome === null) {
            this._dome = new BABYLON.VideoDome(
                "videoDome",
                this._vedioURL.value,
                {
                    resolution: this._resolution.value,
                    size: this._size.value,
                    useDirectMapping: true
                },
                this.scene
            );
        }
        //播放控制
        if (this._switch.value) {
            this._dome.videoTexture.video.loop = this._musicLoop.value;
            this._dome.videoTexture.video.volume = (this._musicVolume.value);

            this._dome.videoTexture.video.play();
        } else {
            this._dome.videoTexture.video.loop = this._musicLoop.value;
            this._dome.videoTexture.video.volume = (this._musicVolume.value);
            this._dome.videoTexture.video.pause();
        }
        //设置vedio类型和激活
        this._dome.videoMode = this._vedioType.value;
        this._dome.setEnabled(this._control.value);
        //DO_20211224:添加位置参数
        if (this._isVec) {
            this._dome.position = this._posVec.value;
        }
        else {
            this._dome.position = new BABYLON.Vector3(this._x.value, this._y.value, this._z.value);
        }
    }

    public onUpdate(): void {

    }
    private async initVideo() {
        let self = this;
        self._vedioURL.value = await BabylonLoader.getAssetUrl(self._vedioURL.value);
        if (self._vedioURL.value === '') {
            console.error('360视频 初始化失败，asset_id：' + self._vedioURL.value + '，无法在当前场景中查找到该ID，请检查！');
        }
    }

    public paraParser(para_array: string[]): boolean {
        //DO_20211224:添加位置参数
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 7, 8, 9)) {
            return false;
        } else {
            // 参数0：
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._control = para0.bool;

            // 参数1：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[1])) {
                return false;
            }
            this._vedioURL = para1.string;
            setTimeout(this.initVideo.bind(this), 0);

            // 参数2：
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[2])) {
                return false;
            }
            this._resolution = para2.number;

            // 参数3：
            let para3: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[3])) {
                return false;
            }
            this._size = para3.number;

            // 第4个参数：
            let para4: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para4, para_array[4])) {
                return false;
            }
            this._switch = para4.bool;

            //第5个参数：
            let para5: VeryParas = new VeryParas();
            if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para5, para_array[5])) {
                return false;
            }
            this._musicLoop = para5.bool;

            //第6个参数：
            let para6: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para6, para_array[6])) {
                return false;
            }
            this._musicVolume = para6.number;

            // 参数7：
            this._vedioType.value = BABYLON.VideoDome.MODE_MONOSCOPIC;
            if (para_array.length > 7) {
                if (para_array[7] === '0') {
                    this._vedioType.value = BABYLON.VideoDome.MODE_MONOSCOPIC;
                }
                else if (para_array[7] === '1') {
                    this._vedioType.value = BABYLON.VideoDome.MODE_TOPBOTTOM;
                }
                else if (para_array[7] === '2') {
                    this._vedioType.value = BABYLON.VideoDome.MODE_SIDEBYSIDE;
                }
                else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[7] + "，{{360视频响应中图片类型填写错误}}，{{应为012中的一种}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }

            //DO_20211224:添加位置参数
            //参数8
            this._isVec = true;
            this._posVec.value = new BABYLON.Vector3(0, 0, 0);
            if (para_array.length > 8) {
                let para8: VeryParas = new VeryParas();
                if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para8, para_array[8])) {
                    return false;
                }
                this._isVec = para8.isVec;
                this._posVec = para8.vector3;
                this._x = para8.vecNumbers[0];
                this._y = para8.vecNumbers[1];
                this._z = para8.vecNumbers[2];
            }

            return true;
        }
    }
    public destroy(): void {
        if (this._dome) {
            this._dome.dispose();
        }
        this._dome = null;
    }
}

//DO_20211223:360
VE_Actions.addAction(Action_360Photo);
VE_Actions.addAction(Action_360Vedio);