import { VEObject, VEObjects } from "../object";
import { GameObject } from "../babylon";
import { Compiler } from "../compiler";

export class VEClone {

    public varId: string;

    public parent: VEObject;

    public instance: Nullable<VEObject> = null;

    public clones: VEObject[] = [];

    private _idx: number = 0;

    public constructor(var_id: string, obj: VEObject) {
        this.varId = var_id;
        this.parent = obj;
    }


    public async create(destory_on_create_new: boolean, withChild: boolean, params?: any): Promise<Nullable<VEObject>> {
        this._idx++;

        // 是否删除上一个实例
        if (destory_on_create_new && this.instance !== null) {
            const index = this.clones.indexOf(this.instance);
            if (index > -1) {
                this.clones.splice(index);
            }

            this.instance.clearClone();
        }

        if (this.parent) {
            const cloneEntity = await this.parent.entity.clone(withChild, params);

            if (cloneEntity) {
                let gameObject: GameObject = null;
                if (cloneEntity.sceneObj && cloneEntity.sceneObj instanceof BABYLON.Node) {
                    gameObject = new GameObject(cloneEntity.name, cloneEntity.sceneObj);
                } else {
                    gameObject = new GameObject(cloneEntity.name);
                    gameObject.setNull();
                    gameObject.id = cloneEntity.id;
                }
                gameObject.entity = cloneEntity;

                // const newNode = GameObject.CreateInstance(this.parent.gameObject);
                // newNode.name = this.parent.NodeName + `-clone-uniqueId-${newNode.uniqueId}`;
                // newNode.id = this.parent.NodeID + `-clone-uniqueId-${newNode.uniqueId}`;

                const newClone = this.parent.clone(gameObject.id, gameObject.name, gameObject);
                newClone.entity = cloneEntity;
                VEObjects.addClone(gameObject.id, newClone);
                Compiler.center.clone(newClone);

                // console.error(newClone);

                if (newClone) {
                    this.instance = newClone;
                    this.clones.push(this.instance);
                }

                return newClone;
            }

        }

        return null;
    }



    public update(): void {
        if (this.clones) {
            for (let i = 0; i < this.clones.length; i++) {
                this.clones[i].update();
            }
        }
    }

    public unload(unload_all_instance: boolean = false): void {
        if (unload_all_instance) {
            for (let i = 0; i < this.clones.length; i++) {
                this.clones[i].clearClone();
                VEObjects.unloadById(this.clones[i].NodeID);
            }
            this.clones = [];
        } else {
            if (this.instance) {
                const index = this.clones.indexOf(this.instance);
                if (index > -1) {
                    this.clones.splice(index);
                }
                this.instance.clearClone();
                VEObjects.unloadById(this.instance.NodeID);
            }
        }
        this.instance = null;
    }


    public clear(): void {

    }


}