import { ParaParserUtility } from "../../utility";
import { VE_TriggerBehaviour, VE_Triggers } from "../../trigger";
import { ParaType } from "../../enum";

export class Trigger_Start extends VE_TriggerBehaviour {

    public get ID(): string {
        return 'Start|开始';
    };

    public get className(): string {
        return 'Trigger_Start';
    };
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '开始';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=452';
    }

    private _observer: Nullable<BABYLON.Observer<BABYLON.Scene>> = null;


    public paraParser(para_array: string[]): boolean {
        // this._observer = this.scene.onReadyObservable.add(() => {
        //     this.sendEvent();
        //     this.destroy();
        // });
        // onReadyObservable触发时间可能先于Observable事件创建
        this._observer = this.scene.onAfterRenderObservable.addOnce(() => {
            this.sendEvent();
            this.destroy();
        });
        return true;
    }


    public destroy(): void {
        if (this._observer) {
            // this.scene.onReadyObservable.remove(this._observer);
            this.scene.onAfterRenderObservable.remove(this._observer);
        }
        this._observer = null;
    }


}

export class Trigger_Continuous extends VE_TriggerBehaviour {

    public get ID(): string {
        return 'Continuous|连续|循环|Update';
    };

    public get className(): string {
        return 'Trigger_Continuous';
    };
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '连续';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=451';
    }

    private _observer: Nullable<BABYLON.Observer<BABYLON.Scene>> = null;


    public paraParser(para_array: string[]): boolean {
        this._observer = this.scene.onBeforeRenderObservable.add(() => {
            this.sendEvent();
        });
        return true;
    }


    public destroy(): void {
        if (this._observer) {
            this.scene.onBeforeRenderObservable.remove(this._observer);
        }
        this._observer = null;
    }


}

