export class Trigger_Broadcast extends VE_TriggerBehaviour {
    public get ID(): string {
        return '接收广播|Broadcast';
    };
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '接收广播,启动';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=450';
    }
    public get className(): string {
        return 'Trigger_Broadcast';
    };

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 1)) {
            return false;
        } else {
            if(!window["Trigger_Broadcast"]){
                window["Trigger_Broadcast"]={};
            }
            window["Trigger_Broadcast"][para_array[0]]=this.sendEvent.bind(this);
        }
        return true;
    }

    public destroy(): void {
    }
}


VE_Triggers.addTrigger(Trigger_Start);
VE_Triggers.addTrigger(Trigger_Continuous);
VE_Triggers.addTrigger(Trigger_Custom);
VE_Triggers.addTrigger(Trigger_Broadcast)