export class GameGlobal {


    public static PlatformLoaded: boolean = false;

    public static projectID: string = '';
    public static projectName: string = '';

    public static assetsData: any = {};

    public static scenesData: any = {};
    public static sceneIndex: number = 0;
    public static sceneName: string = '';

    public static babylonCacheData: { [key: string]: any } = {};
    public static babylonParsedData: { [key: string]: any } = {};

    //TODO_20210311
    public static minimapTextureData: { [key: string]: any } = {};

    public static cameras: any[] = [];
    public static cameraDic: { [key: string]: any } = {};
    public static getCamera(camera: BABYLON.Camera): Nullable<any> {
        if (camera.parent) {
            if (camera.parent.id in GameGlobal.cameraDic) {
                return GameGlobal.cameraDic[camera.parent.id];
            } else {
                return null;
            }
        } else {
            for (let i = 0, len = GameGlobal.cameras.length; i < len; i++) {
                if (GameGlobal.cameras[i].camera === camera) {
                    return GameGlobal.cameras[i];
                }
            }
        }
        return null;
    }

    //DO_20210928:漫游相机封装成VeryCamera
    public static sceneCameraDic: { [key: string]: any } = {};

    //DO_20211102:sprite
    static sceneSpriteDic: { [key: string]: any } = {};

    //DO_20220301:3D引出线,记录信息
    static _linkSprite: { [key: string]: any } = {};
    static _linkMesh: { [key: string]: any } = {};
    static _linkLines: { [key: string]: any } = {};

    //DO_20211116:gif
    static addImageGif: { [key: string]: BABYLON.GUI.Image[] } = {};
    static removeImageGif: BABYLON.GUI.Image[] = [];
    static addMaterialGif: { [key: string]: { [key: string]: BABYLON.Material } } = {};

    //DO_20220412:拖拽Slider,阻止鼠标事件传递，以免同时操作相机
    static operatingUI: boolean = false;

    //DO_20220420:骨骼动画,glb文件导出babylon文件解析
    //多动画之间过渡
    static meshAnimatables: { [key: string]: BABYLON.Animatable[] } = {};

    //DO_20220509:方形画中画,显示时不影响主相机操作
    public static cameraClearcolors: { [key: string]: BABYLON.Nullable<BABYLON.Color4> } = {};
    //DO_20221202:UI方式圆形画中画和方形画中画,效率优化
    public static cameraviewport: boolean = false;
}