import { GameObject } from "../babylon";
import { VEClone } from "../template";
import { VE_DataSource, VE_VariableData } from "../dataSource";
import { IExpression } from "../expression";
import { VE_Fsm } from "../state";
import { VE_ActionBehaviour } from "../action";
import { VE_TriggerBehaviour } from "../trigger";
import { IVeryVar } from "../variables";
import { VEFinder } from "../utility";
import { VeryTable } from "../../verytable";

export class VEObject {

    public get NodeID(): string {
        return this._nodeID;
    }
    private _nodeID: string = '';

    public get ObjectName(): string {
        return this._nodeName;
    }
    public get NodeName(): string {
        return this._nodeName;
    }
    private _nodeName: string = '';

    public gameObject: Nullable<GameObject> = null;

    public entity: Nullable<VREdit.IEDEntity> = null;

    public get table(): VeryTable {
        return this._table;
    }
    private _table: VeryTable;

    public dataSource: VE_DataSource;

    public varData: VE_VariableData;

    public _variables: { [key: string]: IVeryVar } = {};
    private _expressions: { [key: string]: IExpression } = {};
    private _actions: { [key: string]: VE_ActionBehaviour } = {};
    private _triggers: { [key: string]: VE_TriggerBehaviour } = {};
    private _fsms: { [key: string]: VE_Fsm } = {};

    private _unloadCallback: ((object_id: string) => void) | null = null;


    private _cloneInstance: { [key: string]: VEClone } = {};


    // public sample: VEClone = new VEClone();
    // public instance: VEInstance;


    public constructor(node_id: string, node_name: string, game_object: GameObject, table: VeryTable) {
        this._nodeID = node_id;
        this._nodeName = node_name;

        this.gameObject = game_object;

        this._table = table;

        // TODO
        this.dataSource = new VE_DataSource(node_name, false);
        this.varData = new VE_VariableData();
    }




    public isCreatedFsm(fsm_id: string): boolean {
        if (this._fsms[fsm_id]) {
            return true;
        } else {
            return false;
        }
    }

    public addFsm(fsm_id: string, fsm: VE_Fsm): void {
        this._fsms[fsm_id] = fsm;
    }

    public getFsm(fsm_id: string): VE_Fsm {
        return this._fsms[fsm_id];
    }

    public isCreatedTrigger(trigger_id: string): boolean {
        if (this._triggers[trigger_id]) {
            return true;
        } else {
            return false;
        }
    }

    public addTrigger(trigger_id: string, trigger: VE_TriggerBehaviour): void {
        this._triggers[trigger_id] = trigger;
    }

    public getTrigger(trigger_id: string): VE_TriggerBehaviour {
        return this._triggers[trigger_id];
    }

    public isCreatedAction(action_id: string): boolean {
        if (this._actions[action_id]) {
            return true;
        } else {
            return false;
        }
    }

    public addAction(action_id: string, action: VE_ActionBehaviour): void {
        this._actions[action_id] = action;
    }

    public getAction(action_id: string): VE_ActionBehaviour {
        return this._actions[action_id];
    }

    public isCreatedVariable(var_id: string): boolean {
        if (this._variables[var_id]) {
            return true;
        } else {
            return false;
        }
    }

    public addVariable(var_id: string, variable: IVeryVar): void {
        this._variables[var_id] = variable;
    }

    public getVariable(var_id: string): IVeryVar {
        return this._variables[var_id];
    }

    public isCreatedExpression(exp_id: string): boolean {
        if (this._expressions[exp_id]) {
            return true;
        } else {
            return false;
        }
    }

    public addExpression(exp_id: string, expression: IExpression): void {
        this._expressions[exp_id] = expression;
    }

    public getExpression(exp_id: string): IExpression {
        return this._expressions[exp_id];
    }


    public isCreatedVar(var_id: string): boolean {
        // if (this._variables[var_id] || this._expressions[var_id] || this._templates[var_id]) {
        //     return true;
        // } else {
        //     return false;
        // }

        if (this._variables[var_id] || this._expressions[var_id]) {
            return true;
        } else {
            return false;
        }
    }


    public addClone(var_id: string, ve_object: VEObject): void {
        // const parent = VEObjects

        const clone = new VEClone(var_id, ve_object);

        this._cloneInstance[var_id] = clone;

        // console.error(clone);

    }

    public isCreatedClone(var_id: string): boolean {
        if (this._cloneInstance[var_id]) {
            return true;
        } else {
            return false;
        }
    }

    public getClone(var_id: string): VEClone {
        return this._cloneInstance[var_id];
    }


    public update(): void {
        // triggers update
        Object.keys(this._triggers).forEach(key => {
            if (this._triggers[key]) {
                this._triggers[key].update();
            }
        })

        // action update
        // console.log('actions update');
        Object.keys(this._actions).forEach(key => {
            // console.warn(key);
            if (this._actions[key]) {
                this._actions[key].update();
            }
        })

        // clones
        Object.keys(this._cloneInstance).forEach(key => {
            if (this._cloneInstance[key]) {
                this._cloneInstance[key].update();
            }
        })

    }

    // getState(fsm_id: string, index: number): VE_State {

    // }


    public unload(delete_object: boolean = true): void {
        if (this._unloadCallback != null) {
            this._unloadCallback(this._nodeName);
        }

        this.clear();

        if (delete_object && this.entity) {
            this.entity.destroy();
            this.entity = null;
        }

        if (delete_object && this.gameObject) {
            GameObject.Destroy(this.gameObject);
            this.gameObject = null;
        }

    }

    public setUnloadCallback(callback: (id: string) => void): void {
        this._unloadCallback = callback;
    }

    public clone(node_id: string, node_name: string, game_object: GameObject): VEObject {
        const newObject = new VEObject(node_id, node_name, game_object, this.table);

        newObject.entity = VEFinder.FindEntity(node_id);

        newObject.dataSource = this.dataSource;
        newObject.varData = this.varData;

        // if (this._cloneInstance) {
        //     Object.keys(this._cloneInstance).forEach(key => {
        //         newObject.addClone(key, this._cloneInstance[key].parent);
        //     })
        // }

        return newObject;
    }

    public clear(): void {

        if (this.dataSource) {
            this.dataSource.clear();
        }
        if (this.varData) {
            this.varData.clear();
        }
        this._variables = {};
        this._expressions = {};

        if (this._cloneInstance) {
            Object.keys(this._cloneInstance).forEach(key => {
                this._cloneInstance[key].clear();
            })
            this._cloneInstance = {};
        }

        this._fsms = {};
        // this.template = null;

        if (this._actions) {
            Object.keys(this._actions).forEach(key => {
                this._actions[key].destroy();
                this._actions[key] = null;
            })
            this._actions = {};
        }

        if (this._triggers) {
            Object.keys(this._triggers).forEach(key => {
                this._triggers[key].destroy();
                this._triggers[key] = null;
            })
            this._triggers = {};
        }

    }

    public clearClone(): void {

        // if (this.dataSource) {
        //     this.dataSource.clear();
        // }
        // if (this.varData) {
        //     this.varData.clear();
        // }
        this._variables = {};
        this._expressions = {};

        // if (this._cloneInstance) {
        //     Object.keys(this._cloneInstance).forEach(key => {
        //         this._cloneInstance[key].clear();
        //     })
        //     this._cloneInstance = {};
        // }

        this._fsms = {};

        if (this._actions) {
            Object.keys(this._actions).forEach(key => {
                this._actions[key].destroy();
                this._actions[key] = null;
            })
            this._actions = {};
        }

        if (this._triggers) {
            Object.keys(this._triggers).forEach(key => {
                this._triggers[key].destroy();
                this._triggers[key] = null;
            })
            this._triggers = {};
        }

        if (this.entity) {
            this.entity.destroy();
        }
        this.entity = null;

        if (this.gameObject) {
            GameObject.Destroy(this.gameObject);
        }
        this.gameObject = null;
    }
}