export class Action_XR_Enable extends VE_ActionBehaviour {

    public get ID(): string {
        return "VR模式开启|XR_Enable";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return 'VR模式开启，(1，2，1)，1，1000';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=890';
    }
    public get className(): string {
        return "Action_XR_Enable";
    }

    public static _xrHelper: BABYLON.Nullable<BABYLON.WebXRDefaultExperience> = null;
    //相机的椭圆体大小
    private _isVec3: boolean = false;
    private _sizeVec: VeryVector3 = new VeryVector3();
    private _sizeX: VeryNumber = new VeryNumber();
    private _sizeY: VeryNumber = new VeryNumber();
    private _sizeZ: VeryNumber = new VeryNumber();
    //DO_20220517:设置VR相机近远平面
    private _minZ: VeryNumber = new VeryNumber();
    private _maxZ: VeryNumber = new VeryNumber();

    //DO_20220606:VR修改,VR相机初始化位置
    private _initialWebXRCameraPos: boolean = false;
    private _oldCamera: BABYLON.Nullable<BABYLON.Camera> = null;

    public active(): void {
        if (Action_XR_Enable._xrHelper === null) {
            //相机处理
            var currentCamera = this.scene.activeCamera;
            if (this.scene.activeCameras.length > 0) {
                currentCamera = this.scene.activeCameras[this.scene.activeCameras.length - 1];
            }
            this.scene.activeCamera = currentCamera;
            this.scene.activeCameras = [];
            this.CreateXR();

            //DO_20220606:VR修改,VR相机初始化位置
            this._oldCamera = currentCamera;
            let that = this;
            this.scene.beforeRender = function () {
                if (Action_XR_Enable._xrHelper !== null) {
                    if (Action_XR_Enable._xrHelper.baseExperience.state == BABYLON.WebXRState.IN_XR) {
                        if (!that._initialWebXRCameraPos) {
                            Action_XR_Enable._xrHelper.baseExperience.camera.position = (that._oldCamera.globalPosition);
                            console.log('初始化webxr相机位置--');
                            that._initialWebXRCameraPos = true;
                        }
                    }
                }
            };

            /*
            this.scene.onPointerObservable.add((pointInfo: BABYLON.PointerInfo) => {
                if (pointInfo.type === BABYLON.PointerEventTypes.POINTERDOWN) {
                    if (pointInfo.pickInfo !== null) {
                        console.log('点击--');
                        console.log(pointInfo.pickInfo);
                    }
                    if (pointInfo.pickInfo !== null && pointInfo.pickInfo.pickedMesh !== null) {
                        console.log('点击mesh--' + pointInfo.pickInfo.pickedMesh.name);
                    }
                }
            });
            */
        }
    }

    private async CreateXR() {
        //创建默认VR
        Action_XR_Enable._xrHelper = await this.scene.createDefaultXRExperienceAsync();
        console.warn('VR模式开启--');
        var xr = Action_XR_Enable._xrHelper;
        const featuresManager = xr.baseExperience.featuresManager; // or any other way to get a features manager
        //VR相机:重力和碰撞
        xr.baseExperience.camera.checkCollisions = true;
        xr.baseExperience.camera.applyGravity = true;
        //碰撞体积
        var tmpSize = this._sizeVec.value;
        if (!this._isVec3) {
            tmpSize = new BABYLON.Vector3(this._sizeX.value, this._sizeY.value, this._sizeZ.value);
        }
        xr.baseExperience.camera.ellipsoid = tmpSize;
        //DO_20220517:设置VR相机近远平面
        xr.baseExperience.camera.minZ = this._minZ.value;
        xr.baseExperience.camera.maxZ = this._maxZ.value;

        //DO_20220210:VR相机位置和角度处理
        //将主相机下面子物体移到VR相机下面(3D画布,可能有多个画布)
        if (this.scene.activeCamera) {
            var tmpParent = this.scene.activeCamera.parent;
            console.log('主相机处理子物体中3D画布,可能有多个画布--');

            //DO_20220901:VR相机下多个3D画布处理
            var tmpNodes: BABYLON.TransformNode[] = [];
            for (var i = 0; i < tmpParent.getChildren().length; i++) {
                var childeNode = tmpParent.getChildren()[i];
                if (childeNode !== this.scene.activeCamera) {
                    var tmpTransformNode = <BABYLON.TransformNode>childeNode;
                    if (tmpTransformNode) {
                        tmpNodes[tmpNodes.length] = tmpTransformNode;
                        //console.log(tmpTransformNode.name);
                    }
                }
            }
            for (var i = 0; i < tmpNodes.length; i++) {
                var tmpTransformNode = tmpNodes[i];
                if (tmpTransformNode) {
                    var tmpPosition = tmpTransformNode.position.clone();
                    var tmpRotation = tmpTransformNode.rotation.clone();
                    tmpTransformNode.parent = xr.baseExperience.camera;
                    tmpTransformNode.position.copyFrom(tmpPosition);
                    tmpTransformNode.rotation.copyFrom(tmpRotation);
                    if (tmpTransformNode.rotationQuaternion) {
                        var rotationQuaternion = tmpTransformNode.rotationQuaternion.clone();
                        tmpTransformNode.rotationQuaternion.copyFrom(rotationQuaternion);
                    }
                }
            }
        }
        //射线选中:WebXRControllerPointerSelection
        xr.pointerSelection.dispose();
        //DO_20220606:VR修改,手柄射线长度
        xr.pointerSelection = <BABYLON.WebXRControllerPointerSelection>xr.baseExperience.featuresManager.enableFeature(BABYLON.WebXRFeatureName.POINTER_SELECTION, "latest", {
            xrInput: xr.input,
            //disableSwitchOnClick: false,
            maxPointerDistance: this._maxZ.value
        });
        xr.pointerSelection.laserPointerDefaultColor = new BABYLON.Color3(0.5, 0.1, 0.1);
        xr.pointerSelection.laserPointerPickedColor = new BABYLON.Color3(0.1, 0.5, 0.1);
        xr.pointerSelection.displayLaserPointer = true;
        xr.pointerSelection.displaySelectionMesh = true;
        // console.log(xr.pointerSelection);


        //DO_20220606:VR修改,轮廓高亮轨迹
        if (Action_XR_Enable._xrHelper !== null) {
            Action_XR_Enable._xrHelper.baseExperience.sessionManager.onXRFrameObservable.addOnce(() => {
                Action_XR_Enable._xrHelper.baseExperience.camera.rigCameras[0].outputRenderTarget.skipInitialClear = false;
            });
        }

        /*
        //walking
        xr.baseExperience.featuresManager.enableFeature(BABYLON.WebXRFeatureName.WALKING_LOCOMOTION, this._mode, {
            locomotionTarget: xr.baseExperience.camera.parent
        });
        */
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        //DO_20220517:设置VR相机近远平面
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 1, 3)) {
            return false;
        } else {
            // 参数1: 椭圆体大小
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.Vector3OrNumberParaWithExpression(this.objectID, this.ID, ParaType.Trigger, para0, para_array[0])) {
                return false;
            }
            this._isVec3 = para0.isVec;
            this._sizeVec = para0.vector3;
            this._sizeX = para0.vecNumbers[0];
            this._sizeY = para0.vecNumbers[1];
            this._sizeZ = para0.vecNumbers[2];

            //DO_20220517:设置VR相机近远平面
            this._minZ.value = 1;
            this._maxZ.value = 10000;
            if (para_array.length > 2) {
                // 参数1: 相机近平面
                let para1: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Trigger, para1, para_array[1])) {
                    return false;
                }
                this._minZ = para1.number;

                // 参数2: 相机远平面
                let para2: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Trigger, para2, para_array[2])) {
                    return false;
                }
                this._maxZ = para2.number;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}

export class Action_XR_Teleportation extends VE_ActionBehaviour {

    public get ID(): string {
        return "VR传送模式|XR_Teleportation";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return 'VR传送模式，latest，平面，50';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=891';
    }
    public get className(): string {
        return "Action_XR_Teleportation";
    }

    public static _xrHelper: BABYLON.Nullable<BABYLON.WebXRDefaultExperience> = null;
    //模式
    private _mode: string = 'stable';
    //传送:地面物体
    private _floorGameobject: VeryGameObject = new VeryGameObject();
    //传送：后退距离
    private _backwardsTeleportationDistance: VeryNumber = new VeryNumber();

    public active(): void {
        console.warn('VR传送模式初始化--' + (Action_XR_Enable._xrHelper !== null));
        if (Action_XR_Enable._xrHelper !== null) {
            var xr = Action_XR_Enable._xrHelper;
            const featuresManager = xr.baseExperience.featuresManager; // or any other way to get a features manager
            featuresManager.disableFeature(BABYLON.WebXRFeatureName.MOVEMENT);
            //传送:WebXRMotionControllerTeleportation
            if (this._floorGameobject.value && this._floorGameobject.value.mesh) {
                console.log('传送地面--' + this._floorGameobject.value.mesh.name);
                var ground = this._floorGameobject.value.mesh;
                //地面物体，模式
                const teleportation = <BABYLON.WebXRMotionControllerTeleportation>featuresManager.enableFeature(BABYLON.WebXRFeatureName.TELEPORTATION, this._mode, {
                    xrInput: xr.input,
                    // add options here
                    floorMeshes: [ground],
                });
                //后退距离
                teleportation.backwardsTeleportationDistance = this._backwardsTeleportationDistance.value;
                //取消旋转
                teleportation.rotationEnabled = false;
                teleportation.rotationAngle = 0;
            }
        }
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 0, 1, 2, 3)) {
            return false;
        } else {
            //参数1:模式
            if (para_array[0].toLowerCase() === 'stable') {
                this._mode = 'stable';
            }
            else if (para_array[0].toLowerCase() === 'latest') {
                this._mode = 'latest';
            }
            else {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[0] + "，{{应该为stable或者latest中一种}}，{{请检查}}！", '', Severity.Error));
                return false;
            }

            //参数2:地面
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Trigger, para1, para_array[1], this.nodeID)) {
                return false;
            }
            this._floorGameobject = para1.gameObject;

            //参数3:后退距离
            this._backwardsTeleportationDistance.value = 10;
            if (para_array.length > 2) {
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Trigger, para3, para_array[2])) {
                    return false;
                }
                this._backwardsTeleportationDistance = para3.number;
            }

            return true;
        }
    }
    public destroy(): void {

    }
}
