export class Action_XR_Grab extends VE_ActionBehaviour {

    public get ID(): string {
        return "XR_Grab|VR射线抓取";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return 'VR射线抓取，物体名~包括，(立方体6)';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=894';
    }
    public get className(): string {
        return "Action_XR_Grab";
    }

    //过滤条件
    private _filter = false;
    private _include = true;
    private _filterName: string[] = [];

    //拖拽
    private _currentMesh: BABYLON.Nullable<BABYLON.AbstractMesh> = null;
    private _oldParent: BABYLON.Nullable<BABYLON.Node> = null;

    private _observer: Nullable<BABYLON.Observer<BABYLON.PointerInfo>> = null;

    public active(): void {
        console.warn('VR射线抓取初始化--' + (Action_XR_Enable._xrHelper !== null));
        let self = this;
        this._observer = this.scene.onPointerObservable.add((pointerInfo) => {
            //鼠标拖拽控制关闭
            if (!self.enabled) {
                return;
            }
            switch (pointerInfo.type) {
                case BABYLON.PointerEventTypes.POINTERDOWN:
                    if (pointerInfo.pickInfo && pointerInfo.pickInfo.pickedMesh) {
                        if (!this._filter) {
                            this.pointerDown(pointerInfo)
                        }
                        else {
                            if (this._include) {
                                if (this._filterName.indexOf(pointerInfo.pickInfo.pickedMesh.name) != -1) {
                                    this.pointerDown(pointerInfo)
                                }
                            }
                            else {
                                if (this._filterName.indexOf(pointerInfo.pickInfo.pickedMesh.name) == -1) {
                                    this.pointerDown(pointerInfo)
                                }
                            }
                        }
                    }
                    break;
                case BABYLON.PointerEventTypes.POINTERUP:
                    this.pointerUp();
                    break;
            }
        });

    }
    private pointerDown(pointerInfo: BABYLON.PointerInfo) {
        this._currentMesh = pointerInfo.pickInfo.pickedMesh;

        if (Action_XR_Enable._xrHelper) {
            var xrHelper = Action_XR_Enable._xrHelper;
            console.warn('VR射线抓取--开始');
            console.log(this._currentMesh.name);
            let xrInput = xrHelper.pointerSelection.getXRControllerByPointerId((<BABYLON.IPointerEvent>pointerInfo.event).pointerId);
            if (xrInput && xrInput.motionController) {
                this._oldParent = this._currentMesh.parent;
                this._currentMesh.setParent(xrInput.motionController.rootMesh)
            }
            if (xrInput === null) {
                for (var i = 0; i < xrHelper.input.controllers.length; i++) {
                    for (var j = 0; j < xrHelper.input.controllers[i].pointer.getChildMeshes().length; j++) {
                        var tmpMesh = xrHelper.input.controllers[i].pointer.getChildMeshes()[j];
                        if (tmpMesh.name === 'laserPointer' && tmpMesh.isVisible) {
                            this._oldParent = this._currentMesh.parent;
                            this._currentMesh.setParent(xrHelper.input.controllers[i].motionController.rootMesh);
                            break;
                        }
                    }
                }
            }
        }
    }
    private pointerUp() {
        if (this._currentMesh) {
            console.warn('VR射线抓取--结束');
            console.log(this._currentMesh.name);
            this._currentMesh.setParent(this._oldParent);
            this._currentMesh = null;
        }
    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 0, 2)) {
            return false;
        } else {

            //参数1
            if (para_array.length > 0) {
                var tagArray = para_array[0].split('~');
                if (tagArray.length !== 2) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[0] + "，{{第4个参数应为}}“物体名~包括”|“Name~Include”、“物体名~排除”|“Name~Exclude”，{{表示过滤条件}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
                //物体名或者标签判断
                if (tagArray[0].trim() === "物体名" || tagArray[0].trim().toLowerCase() === "name") {
                }
                else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[0] + "，{{第4个参数应为}}“物体名~包括”|“Name~Include”、“物体名~排除”|“Name~Exclude”，{{表示过滤条件}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
                //排除或者包括判断
                if (tagArray[1].trim() === "包括" || tagArray[1].trim().toLowerCase() === "include") {
                    this._include = true;
                }
                else if (tagArray[1].trim() === "排除" || tagArray[1].trim().toLowerCase() === "exclude") {
                    this._include = false;
                }
                else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[0] + "，{{第4个参数应为}}“物体名~包括”|“Name~Include”、“物体名~排除”|“Name~Exclude”，{{表示过滤条件}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }
            else {
                this._filter = false;
                this._filterName = [];
            }

            //参数2
            if (para_array.length > 1) {
                var nameArray = para_array[1].split(/,|，/);
                for (var i = 0; i < nameArray.length; i++) {
                    nameArray[i] = nameArray[i].trim();
                    if (VarTools.IsVarID(nameArray[i])) {
                        var tempStr = new VeryString();
                        let para1 = new VeryParas();
                        if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, nameArray[i])) {
                            return false;
                        }
                        tempStr = para1.string;
                        if (tempStr.value !== "" && (this._filterName.indexOf(tempStr.value) == -1)) {
                            this._filterName[this._filterName.length] = (nameArray[i]);
                        }
                    }
                    else {
                        if (nameArray[i] !== "" && (this._filterName.indexOf(nameArray[i]) == -1)) {
                            this._filterName[this._filterName.length] = (nameArray[i]);
                        }
                    }
                }
                if (this._filterName.length > 0) {
                    this._filter = true;
                }
            }
            else {
                this._filter = false;
                this._filterName = [];
            }
            return true;
        }
    }
    public destroy(): void {
        if (this._observer) {
            this.scene.onPointerObservable.remove(this._observer);
        }
        this._observer = null;
    }
}
export class Action_XR_Drag extends VE_ActionBehaviour {

    public get ID(): string {
        return "XR_Drag|VR射线拖拽";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return 'VR射线拖拽，自由，2，X，物体名~包括，(立方体7)';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=895';
    }
    public get className(): string {
        return "Action_XR_Drag";
    }

    //拖拽方式
    private _choose = "";
    private _moveRef: BABYLON.Nullable<Transform> = null;
    //速度
    private _moveSpeed: VeryNumber = new VeryNumber();
    //拖拽轴
    private _isPlane = false;
    private _move = "";
    //过滤条件
    private _filter = false;
    private _include = true;
    private _filterName: string[] = [];

    //拖拽
    private _currentController: BABYLON.Nullable<BABYLON.WebXRInputSource> = null;
    private _currentControllerMesh: BABYLON.Nullable<BABYLON.AbstractMesh> = null;
    private _controllerStartPos: BABYLON.Vector3 = new BABYLON.Vector3(0, 0, 0);
    private _currentMesh: BABYLON.Nullable<BABYLON.AbstractMesh> = null;
    private _currentMeshStartPos: BABYLON.Vector3 = new BABYLON.Vector3(0, 0, 0);
    private _currentMeshStartLocalPos: BABYLON.Vector3 = new BABYLON.Vector3(0, 0, 0);

    private _observer: Nullable<BABYLON.Observer<BABYLON.PointerInfo>> = null;

    public active(): void {
        console.warn('VR射线拖拽初始化--' + (Action_XR_Enable._xrHelper !== null));
        let self = this;
        this._observer = this.scene.onPointerObservable.add((pointerInfo) => {
            //鼠标拖拽控制关闭
            if (!self.enabled) {
                return;
            }
            switch (pointerInfo.type) {
                case BABYLON.PointerEventTypes.POINTERDOWN:
                    if (pointerInfo.pickInfo && pointerInfo.pickInfo.pickedMesh) {
                        if (!this._filter) {
                            this.pointerDown(pointerInfo)
                        }
                        else {
                            if (this._include) {
                                if (this._filterName.indexOf(pointerInfo.pickInfo.pickedMesh.name) != -1) {
                                    this.pointerDown(pointerInfo)
                                }
                            }
                            else {
                                if (this._filterName.indexOf(pointerInfo.pickInfo.pickedMesh.name) == -1) {
                                    this.pointerDown(pointerInfo)
                                }
                            }
                        }
                    }
                    break;
                case BABYLON.PointerEventTypes.POINTERUP:
                    this.pointerUp();
                    break;
                case BABYLON.PointerEventTypes.POINTERMOVE:
                    this.pointerMove(pointerInfo);
                    break;
            }
        });
    }
    private pointerDown(pointerInfo: BABYLON.PointerInfo) {
        this._currentMesh = pointerInfo.pickInfo.pickedMesh;
        let tmpCamera = this.scene.activeCamera;

        if (Action_XR_Enable._xrHelper) {
            var xrHelper = Action_XR_Enable._xrHelper;
            console.warn('VR射线拖拽--开始');
            console.log(this._currentMesh.name);
            let xrInput = xrHelper.pointerSelection.getXRControllerByPointerId((<BABYLON.IPointerEvent>pointerInfo.event).pointerId);
            if (xrInput) {
                this._currentController = xrInput;
                this._currentControllerMesh = xrInput.motionController.rootMesh;
            }
            if (xrInput === null) {
                for (var i = 0; i < xrHelper.input.controllers.length; i++) {
                    for (var j = 0; j < xrHelper.input.controllers[i].pointer.getChildMeshes().length; j++) {
                        var tmpMesh = xrHelper.input.controllers[i].pointer.getChildMeshes()[j];
                        if (tmpMesh.name === 'laserPointer' && tmpMesh.isVisible) {
                            this._currentController = xrHelper.input.controllers[i];
                            //this._currentControllerMesh = tmpMesh;
                            //this._currentControllerMesh = xrHelper.input.controllers[i].pointer;
                            this._currentControllerMesh = xrHelper.input.controllers[i].motionController.rootMesh;
                            break;
                        }
                    }
                }
            }
            if (this._currentController) {
                this._currentMeshStartPos = this._currentMesh.getAbsolutePosition().clone();
                this._currentMeshStartLocalPos = this._currentMesh.getPositionExpressedInLocalSpace().clone();
                this._controllerStartPos = this._currentControllerMesh.getAbsolutePosition().clone();
            }
        }
    }

    private pointerUp() {
        if (this._currentMesh) {
            console.warn('VR射线拖拽--结束');
            this._currentMesh = null;
            return;
        }
    }
    private pointerMove(pointerInfo: BABYLON.PointerInfo) {
        if (this._currentController && this._currentControllerMesh) {
            var currentPos = this._currentControllerMesh.getAbsolutePosition().clone();
            //物体拖拽移动
            if (this._currentMesh) {
                //console.warn('VR射线拖拽--移动中');
                //console.log(this._currentController.pointer.getAbsolutePosition().clone());
                //console.log(this._currentController.motionController.rootMesh.getAbsolutePosition().clone());
                //console.log(this._currentController.grip.getAbsolutePosition().clone());
                if (this._choose === 'free') {
                    this._currentMesh.setAbsolutePosition(this._currentMeshStartPos.add(currentPos.subtract(this._controllerStartPos).scale(1000 * this._moveSpeed.value)));
                }
                else if (this._choose === 'world') {
                    if (!this._isPlane)  //轴移动
                    {
                        var newPos = this._currentMeshStartPos.add(currentPos.subtract(this._controllerStartPos).scale(1000 * this._moveSpeed.value));
                        if (this._move === 'x') {
                            this._currentMesh.setAbsolutePosition(new BABYLON.Vector3(newPos.x, this._currentMeshStartPos.y, this._currentMeshStartPos.z));
                        }
                        else if (this._move === 'y') {
                            this._currentMesh.setAbsolutePosition(new BABYLON.Vector3(this._currentMeshStartPos.x, newPos.y, this._currentMeshStartPos.z));
                        }
                        else if (this._move === 'z') {
                            this._currentMesh.setAbsolutePosition(new BABYLON.Vector3(this._currentMeshStartPos.x, this._currentMeshStartPos.y, newPos.z));

                        }
                    }
                    else {
                        var newPos = this._currentMeshStartPos.add(currentPos.subtract(this._controllerStartPos).scale(1000 * this._moveSpeed.value));
                        if (this._move === 'xy' || this._move === 'yx') //求直线与z = 常量 平面的交点
                        {
                            this._currentMesh.setAbsolutePosition(new BABYLON.Vector3(newPos.x, newPos.y, this._currentMeshStartPos.z));
                        }
                        else if (this._move === 'xz' || this._move === 'zx') //求直线与y = 常量 平面的交点
                        {
                            this._currentMesh.setAbsolutePosition(new BABYLON.Vector3(newPos.x, this._currentMeshStartPos.y, newPos.z));
                        }
                        else //求直线与x = 常量 平面的交点
                        {
                            this._currentMesh.setAbsolutePosition(new BABYLON.Vector3(this._currentMeshStartPos.x, newPos.y, newPos.z));
                        }
                    }
                }
                else if (this._choose === 'self') {
                    if (!this._isPlane)  //轴移动
                    {
                        this._currentMesh.setAbsolutePosition(this._currentMeshStartPos.add(currentPos.subtract(this._controllerStartPos).scale(1000 * this._moveSpeed.value)));
                        var tmpLocalPos = this._currentMesh.getPositionExpressedInLocalSpace().clone();
                        if (this._move === 'x') {
                            this._currentMesh.setPositionWithLocalVector(new BABYLON.Vector3(tmpLocalPos.x, this._currentMeshStartLocalPos.y, this._currentMeshStartLocalPos.z));

                        }
                        else if (this._move === 'y') {
                            this._currentMesh.setPositionWithLocalVector(new BABYLON.Vector3(this._currentMeshStartLocalPos.x, tmpLocalPos.y, this._currentMeshStartLocalPos.z));

                        }
                        else if (this._move === 'z') {
                            this._currentMesh.setPositionWithLocalVector(new BABYLON.Vector3(this._currentMeshStartLocalPos.x, this._currentMeshStartLocalPos.y, tmpLocalPos.z));

                        }
                    }
                    else {
                        this._currentMesh.setAbsolutePosition(this._currentMeshStartPos.add(currentPos.subtract(this._controllerStartPos).scale(1000 * this._moveSpeed.value)));
                        var tmpLocalPos = this._currentMesh.getPositionExpressedInLocalSpace().clone();
                        if (this._move === 'xy' || this._move === 'yx') //求直线与z = 常量 平面的交点
                        {
                            this._currentMesh.setPositionWithLocalVector(new BABYLON.Vector3(tmpLocalPos.x, tmpLocalPos.y, this._currentMeshStartLocalPos.z));
                        }
                        else if (this._move === 'xz' || this._move === 'zx') //求直线与y = 常量 平面的交点
                        {
                            this._currentMesh.setPositionWithLocalVector(new BABYLON.Vector3(tmpLocalPos.x, this._currentMeshStartLocalPos.y, tmpLocalPos.z));

                        }
                        else if (this._move === 'yz' || this._move === 'zy') //求直线与x = 常量 平面的交点
                        {
                            this._currentMesh.setPositionWithLocalVector(new BABYLON.Vector3(this._currentMeshStartLocalPos.x, tmpLocalPos.y, tmpLocalPos.z));
                        }
                    }
                }
                //TODO:物体模式未实现;x,y,z,xy,xz,yz轴6种模式未实现
                else if (this._choose == 'someObject') {

                }
            }
        }

    }

    public onUpdate(): void {

    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 3, 5)) {
            return false;
        } else {
            //参数1
            var firstStr = para_array[0].toLowerCase();
            if (firstStr === 'world' || firstStr === '世界') {
                this._choose = 'world';
            }
            else if (firstStr === 'self' || firstStr === '相对' || firstStr === '自身') {
                this._choose = 'self';
            }
            else if (firstStr === 'free' || firstStr === '自由') {
                this._choose = 'free';
            }
            else {
                var tempObj = new VeryGameObject();
                let para1 = new VeryParas();
                if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0], this.nodeID)) {
                    return false;
                }
                tempObj = para1.gameObject;
                //DO_20221228:表格编辑器,自动检测
                if (!VeryEngine.enableLuckySheet) {
                    if (tempObj.value === null) {
                        //DO_20221228:表格编辑器,自动检测,中英文
                        VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[0] + "，{{无法在场景中查找到该物体}}，{{请检查}}！", '', Severity.Error));
                        return false;
                    }
                    this._moveRef = tempObj.value.transform;
                    this._choose = "someObject";
                }
            }

            //参数2
            let para2 = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                return false;
            }
            this._moveSpeed = para2.number;

            //参数3
            var thirdStr = para_array[2].toLowerCase();
            if (thirdStr === 'x' || thirdStr === 'y' || thirdStr === 'z' || thirdStr === 'xy' || thirdStr === 'yx' || thirdStr === 'xz' || thirdStr === 'zx' || thirdStr === 'yz' || thirdStr === 'zy') {
                this._move = thirdStr;
                if (thirdStr === 'xy' || thirdStr === 'yx' || thirdStr === 'xz' || thirdStr === 'zx' || thirdStr === 'yz' || thirdStr === 'zy') {
                    this._isPlane = true;
                }
            }
            else {
                if (this._choose !== 'free') {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[2] + "，{{轴应该填“X”、“Y”、“Z”、“XY”、“XZ”、“YZ”}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }

            //参数4
            if (para_array.length > 3) {
                var tagArray = para_array[3].split('~');
                if (tagArray.length !== 2) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[3] + "，{{第4个参数应为}}“物体名~包括”|“Name~Include”、“物体名~排除”|“Name~Exclude”，{{表示过滤条件}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
                //物体名或者标签判断
                if (tagArray[0].trim() === "物体名" || tagArray[0].trim().toLowerCase() === "name") {
                }
                else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[3] + "，{{第4个参数应为}}“物体名~包括”|“Name~Include”、“物体名~排除”|“Name~Exclude”，{{表示过滤条件}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
                //排除或者包括判断
                if (tagArray[1].trim() === "包括" || tagArray[1].trim().toLowerCase() === "include") {
                    this._include = true;
                }
                else if (tagArray[1].trim() === "排除" || tagArray[1].trim().toLowerCase() === "exclude") {
                    this._include = false;
                }
                else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[3] + "，{{第4个参数应为}}“物体名~包括”|“Name~Include”、“物体名~排除”|“Name~Exclude”，{{表示过滤条件}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }
            else {
                this._filter = false;
                this._filterName = [];
            }

            //参数5
            if (para_array.length > 4) {
                var nameArray = para_array[4].split(/,|，/);
                for (var i = 0; i < nameArray.length; i++) {
                    nameArray[i] = nameArray[i].trim();
                    if (VarTools.IsVarID(nameArray[i])) {
                        var tempStr = new VeryString();
                        let para1 = new VeryParas();
                        if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, nameArray[i])) {
                            return false;
                        }
                        tempStr = para1.string;
                        if (tempStr.value !== "" && (this._filterName.indexOf(tempStr.value) == -1)) {
                            this._filterName[this._filterName.length] = (nameArray[i]);
                        }
                    }
                    else {
                        if (nameArray[i] !== "" && (this._filterName.indexOf(nameArray[i]) == -1)) {
                            this._filterName[this._filterName.length] = (nameArray[i]);
                        }
                    }
                }
                if (this._filterName.length > 0) {
                    this._filter = true;
                }
            }
            else {
                this._filter = false;
                this._filterName = [];
            }
            return true;
        }
    }
    public destroy(): void {
        if (this._observer) {
            this.scene.onPointerObservable.remove(this._observer);
        }
        this._observer = null;
    }
}

