    public static GetUI(scene: BABYLON.Scene, gui_fullname: string, host_node_id: string): Nullable<VREdit.GUI> {

        const array: string[] = gui_fullname.split(StateConst.STATE_SEPARATOR);
        // console.error(VREdit.shareBox.id2Entity[host_node_id]);

        const hostEntity = VREdit.shareBox.id2Entity[host_node_id];
        if (hostEntity && (<string>hostEntity.type).toLowerCase() === 'gui') {
            // 查询当前gui entity是否符合部分或全部gui name

            const fullnameData = { name: '' };
            const canvasEntity = ParaParserUtility.getRootCanvas(hostEntity, fullnameData);

            if (gui_fullname === fullnameData.name) {
                return hostEntity;
            } else if (gui_fullname.startsWith(fullnameData.name)) {
                const leftName = gui_fullname.substring(fullnameData.name.length + 1);
                const leftArray = leftName.split(StateConst.STATE_SEPARATOR);
                const childEntity = ParaParserUtility.getUIFromChild(hostEntity.childIds, leftArray, 0);
                if (childEntity) {
                    return childEntity;
                }
            }
            // console.error(`ori fullname: ${gui_fullname}, host fullname: ${fullnameData.name}`);

            if (canvasEntity && canvasEntity.name === array[0]) {
                if (array.length == 1)
                    return canvasEntity;
                else {
                    return ParaParserUtility.getUIFromChild(canvasEntity.childIds, array, 1);
                }
            }
        }

        for (let key in VREdit.shareBox.id2Entity) {
            let entity = VREdit.shareBox.id2Entity[key];
            if (entity && entity.type.toLowerCase() === 'gui' && entity.name === array[0]) {
                if (array.length == 1)
                    return entity;
                else {
                    return ParaParserUtility.getUIFromChild(entity.childIds, array, 1);
                }
            }
        }
        return null;

    }

    private static getUIFromChild(children: string[], array: string[], index: number) {
        let tmp = [];
        for (let child of children) {
            let entity = VREdit.shareBox.id2Entity[child];
            if (entity) {
                if (entity.name == array[index]) {
                    index++;
                    if (index == array.length) {
                        return entity;
                    } else {
                        return ParaParserUtility.getUIFromChild(entity.childIds, array, index);
                    }
                } else {
                    tmp.push(...entity.childIds)
                }
            }
        }
        if (tmp.length == 0) {
            return null;
        } else {
            return ParaParserUtility.getUIFromChild(tmp, array, index);
        }
    }

    private static getRootCanvas(entity: VREdit.GUI, fullname_data: { name: string; }): Nullable<VREdit.GUI> {
        if (fullname_data.name) {
            fullname_data.name = entity.name + StateConst.STATE_SEPARATOR + fullname_data.name;
        } else {
            fullname_data.name = entity.name
        }
        if (entity.subtype.toLowerCase().match('canvas')) {
            return entity;
        } else {
            if (entity.parent && entity.parent.type.toLowerCase() === 'gui') {
                return ParaParserUtility.getRootCanvas(<VREdit.GUI>entity.parent, fullname_data);
            } else {
                return null;
            }
        }
    }

