import { BabylonEngine } from "./babylon";
import { VeryTable } from "../verytable/index";
import { LoadCenter } from "./loader/load-center";
import { GameGlobal, VE_ErrorManager } from "./global";
import { VEObject, VEObjects } from "./object";
import { VEFinder } from "./utility";

// 导出entrance
export * from "./index";

export class Compiler {


    public static center: LoadCenter = new LoadCenter();

    private static _successful: boolean = true;

    /**
     * 加载表格，有多个表格时，按先后顺序调用此函数进行加载，全部加载完毕，再调用loadEnd函数，告知编译器；
     * @param node_id 场景物体id；
     * @param table_name 表格名，不带后缀；
     * @param data 表格数据，二维字符串数组；
     */
    public static loadTable(node_id: string, table_name: string, data: Array<Array<string>>): void {

        if (!BabylonEngine.Scene) {
            console.error(`请先初始化'VR.BabylonEngine.Scene'参数，再进行表格编译！`);
            return;
        }

        // const node = BabylonEngine.Scene.getNodeById(node_id);
        const entity = VEFinder.FindEntity(node_id);
        // console.warn(entity);

        if (!entity) {
            console.error(`物体ID：${node_id}，表格名：${table_name}，当前表格解析失败，无法在场景中找到该物体！`);
            return;
        }

        const nodeName = entity.name;

        // console.log(`load table: ${node_id}, table ${table_name}, ${nodeName}`);

        // check if table of this node has been loaded
        if (Compiler.center.hasLoaded(node_id)) {
            console.error(`物体ID：${node_id}，表格名：${table_name}，当前ID物体已加载表格，请勿重复加载！`);
            return;
        }

        const tableData: VeryTable = new VeryTable(data, table_name);

        // 加载及初始化，语法分析
        if (!Compiler.center.loadTable(node_id, table_name, nodeName, tableData, entity)) {
            Compiler._successful = false;
        }


        // 平台第一次加载，响应类型、触发类型、变量类型初始化
        GameGlobal.PlatformLoaded = true;
    }

    /**
     * 1个或多个表格加载完毕后，调用此函数，进行编译；
     * 后续动态加载时，同样加载1个或N个后，调用此函数；
     */
    public static loadEnd(): void {
        // console.log(`load end`);

        // 实例化加载
        if (!Compiler.center.loadEnd()) {
            Compiler._successful = false;
        }
        console.log(`表格解析结果：${Compiler._successful}`);
        VE_ErrorManager.Print();
        Compiler._successful = true;
    }

    /**
     * 通过场景物体id，卸载表格；
     * @param node_id 场景物体id；
     * @param delete_object 是否删除对象在场景中关联的物体，默认true；
     */
    public static unloadTableById(node_id: string, delete_object: boolean = true): void {
        Compiler.center.unloadTableById(node_id, delete_object);
    }

    /**
    * 通过场景物体名，卸载表格；
    * @param node_name 场景物体名；
    * @param host_node_id 所属对象场景物体id；
    * @param delete_object 是否删除对象在场景中关联的物体，默认true；
    */
    public static unloadTableByName(node_name: string, host_node_id: string, delete_object: boolean = true): void {
        Compiler.center.unloadTableByName(node_name, host_node_id, delete_object);
    }

    /**
     * 克隆对象，通过对象变量克隆对象；
     * @param node_id 具体对象ID；
     * @param clone_var_id 对象变量名；
     * @param destory_on_create_new 是否销毁旧实例；
     * @param withChild 是否克隆子物体；
     * @param params 参数；
     */
    public static cloneObject(node_id: string, clone_var_id: string, destory_on_create_new: boolean, withChild: boolean, params?: any): Promise<Nullable<VEObject>> {
        if (VEObjects.isNodeIdLoaded(node_id)) {
            const ve_object = VEObjects.getByNodeId(node_id);
            if (ve_object.isCreatedClone(clone_var_id)) {
                const cloneVar = ve_object.getClone(clone_var_id);
                return cloneVar.create(destory_on_create_new, withChild, params);
            }
        }
        return null;
    }

    /**
     * 响应和触发update入口，需要通过babylon的engine.runRenderLoop每一帧调用；
     */
    public static update(): void {
        VEObjects.update();
    }

    /**
     * 待定；
     */
    public static dispose(): void {

    }


}