import { VE_ActionBehaviour, VE_Actions } from "../../action";
import { ParaType, Severity } from "../../enum";
import { ParaParserUtility } from "../../utility";
import { VE_ErrorManager, VE_Error } from "../../global";
import { VEClone } from '../../template';
import { VE_State, VE_Fsm, StateConst } from "../../state";
import { AssociatedFsmType } from "../../enum";
import { VEObjects, VEObject } from "../../object";

enum SequenceActionControl { Pause, Resume, Stop }

export class Action_AnimationActionControl extends VE_ActionBehaviour {

    public get ID(): string {
        return "AnimationActionControl|动画响应控制";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '动画响应控制，某某状态，暂停,动画响应控制，某某对象.某某状态=2，停止';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=913';
    }
    public get className(): string {
        return "Action_AnimationActionControl";
    }

    private _type: AssociatedFsmType = AssociatedFsmType.Object;
    private _state: VE_State = null;
    private _fsm: VE_Fsm = null;
    private _template: VEClone = null;
    private _templateFsmID: string = "";
    private _stateIndex: number = StateConst.STATE_INDEX;
    private _oriStateStr: string = "";

    private _controlFlag: SequenceActionControl = SequenceActionControl.Pause;

    public active(): void {

        if (this._type == AssociatedFsmType.Object) {
            if (this._fsm == null) {
                console.error(this.ID + " 响应 运行错误，当前要控制的目标状态为空，请检查响应！");
                return;
            }
            //DO_20220323:动画响应控制
            this._state = this._fsm.getStateByIndex(this._stateIndex);
            if (this._state == null) {
                console.error(this.ID + " 响应 运行错误，当前要控制的目标状态为空，请检查响应！");
                return;
            }
            if (this._state._sequenceActions == null) {
                console.warn(this.ID + " 响应，待控制目标状态：" + this._oriStateStr + "，当前状态响应未运行，无法进行控制！");
                return;
            }
            if (this._controlFlag == SequenceActionControl.Pause) {
                this._state._sequenceActions.pause();
            }
            else if (this._controlFlag == SequenceActionControl.Resume) {
                this._state._sequenceActions.resume();
            }
            else {
                this._state._sequenceActions.stop();
            }
        }
        else {
            if (this._template && this._template.instance != null) {
                if (this._template.instance.isCreatedFsm(this._templateFsmID)) {
                    var fsm: VE_Fsm = this._template.instance.getFsm(this._templateFsmID);
                    //DO_20220323:动画响应控制
                    this._state = fsm.getStateByIndex(this._stateIndex);
                    if (this._state != null) {
                        if (this._controlFlag == SequenceActionControl.Pause) {
                            this._state._sequenceActions.pause();
                        }
                        else if (this._controlFlag == SequenceActionControl.Resume) {
                            this._state._sequenceActions.resume();
                        }
                        else {
                            this._state._sequenceActions.stop();
                        }
                    }
                    else {
                        console.warn(this.ID + " 响应，待控制目标状态：" + this._oriStateStr + "，在目标模板变量的目标状态中，关联状态序号超出范围，无法进行控制，请检查！");
                        return;
                    }
                }
                else {
                    console.warn(this.ID + " 响应，待控制目标状态：" + this._oriStateStr + "，在目标模板变量中无法查找到该目标状态名，无法进行控制，请检查！");
                    return;
                }
            }
            else {
                console.warn(this.ID + " 响应，待控制目标状态：" + this._oriStateStr + "，当前模板变量未实例化创建，无法进行控制，请检查！");
                return;
            }
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 2)) {
            return false;
        } else {
            //第1个参数转化  状态
            //1.状态名；2.对象名.状态名；3.*模板变量.状态名；4.对象名.*局部模板变量.状态名
            if (!this.StateParser(para_array[0])) {
                return false;
            }

            //第2个参数转化  控制标志
            if (para_array[1].toLowerCase() == "暂停" || para_array[1].toLowerCase() == "pause") {
                this._controlFlag = SequenceActionControl.Pause;
            }
            else if (para_array[1].toLowerCase() == "恢复" || para_array[1].toLowerCase() == "resume") {
                this._controlFlag = SequenceActionControl.Resume;
            }
            else if (para_array[1].toLowerCase() == "停止" || para_array[1].toLowerCase() == "stop") {
                this._controlFlag = SequenceActionControl.Stop;
            }
            else {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{顺序运行响应控制参数}}：" + para_array[1] + "，{{应为}}“暂停|Pause、恢复|Resume、停止|Stop”{{的形式}}，{{当前格式错误}}，{{请检查}}！", '', Severity.Error));
                return false;
            }
            return true;
        }
    }
    public destroy(): void {

    }

    private StateParser(state_info: string): boolean {
        this._oriStateStr = state_info;
        var strArray: string[] = state_info.split('=');
        //状态序号
        if (strArray.length == 1) {
            this._stateIndex = StateConst.STATE_INDEX;
        }
        else if (strArray.length == 2) {
            try {
                this._stateIndex = Number(strArray[1].trim());
            }
            catch
            {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{状态名}}：" + state_info + "，{{应为“状态名=子状态ID（int整数）”的形式}}，{{当前状态序号格式错误}}，{{请检查}}！", '', Severity.Error));
                return false;
            }
        }
        else {
            //DO_20221228:表格编辑器,自动检测,中英文
            VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{状态名}}：" + state_info + "，{{应为“状态名=子状态ID（int整数）”的形式}}，{{当前格式错误}}，{{请检查}}！", '', Severity.Error));
            return false;
        }
        //--this._stateIndex;

        //1. 状态名
        //2. 对象名.状态名
        //3. *模板变量.状态名
        //4. 对象名.*局部模板变量.状态名
        // var objects: VE_Objects = VE_Manager.objects(this.projectName);
        var veryObject: VEObject = VEObjects.getByName(this.objectID, this.nodeID);
        // var globalVars: VE_Variables = VE_Manager.variables(this.projectName);

        var aFsmID = strArray[0].trim();
        if (aFsmID.indexOf(StateConst.STATE_SEPARATOR) !== -1) {
            var stateArray: string[] = aFsmID.split(StateConst.STATE_SEPARATOR[0]);
            for (var q = 0; q < stateArray.length; q++) {
                stateArray[q] = stateArray[q].trim();
            }
            //对象名.*局部模板变量.状态名
            if (stateArray.length == 3) {
                if (VEObjects.isNodeNameLoaded(stateArray[0], this.nodeID)) {
                    var aObject: VEObject = VEObjects.getByName(stateArray[0], this.nodeID);
                    if (stateArray[1].startsWith(StateConst.VARIABLE_SYMBOL)) {
                        var varID = stateArray[1].substring(1);
                        if (aObject.isCreatedClone(varID)) {
                            var template: VEClone = aObject.getClone(varID);
                            if (template.parent.dataSource.isCreatedFsm(stateArray[2])) {
                                this._type = AssociatedFsmType.Template;
                                this._template = template;
                                this._templateFsmID = stateArray[2];
                            }
                            else {
                                //DO_20221228:表格编辑器,自动检测,中英文
                                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{状态名}}：" + state_info + "，{{当前顺序响应目标状态填写格式为“对象名.*模板变量.状态名”}}，{{在当前对象的该模板变量中无法查找到对应状态名}}，{{请检查}}！", '', Severity.Error));
                                return false;
                            }
                        }
                        else {
                            //DO_20221228:表格编辑器,自动检测,中英文
                            VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{状态名}}：" + state_info + " {{响应参数错误}}，{{状态名}}：" + state_info + "，{{当前顺序响应目标状态填写格式为“对象名.*模板变量.状态名”}}，{{在当前对象中无法查找到该模板变量}}，{{请检查}}！", '', Severity.Error));
                            return false;
                        }
                    }
                    else {
                        //DO_20221228:表格编辑器,自动检测,中英文
                        VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{状态名}}：" + state_info + "，{{当前顺序响应目标状态填写格式为“对象名.*模板变量.状态名”}}，{{模板变量填写格式不正确}}，{{请检查}}！", '', Severity.Error));
                        return false;
                    }
                }
                else {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{状态名}}：" + state_info + "，{{当前顺序响应目标状态填写格式为“对象名.*模板变量.状态名”}}，{{无法查找到该对象}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }
            else if (stateArray.length == 2) {
                var aObjectID: string = stateArray[0].trim();
                aFsmID = stateArray[1].trim();
                //*模板变量.状态名
                if (aObjectID.startsWith(StateConst.VARIABLE_SYMBOL)) {
                    aObjectID = aObjectID.substring(1);
                    if (veryObject.isCreatedClone(aObjectID)) {
                        var template: VEClone = veryObject.getClone(aObjectID);
                        if (template.parent.dataSource.isCreatedFsm(stateArray[1])) {
                            this._type = AssociatedFsmType.Template;
                            this._template = template;
                            this._templateFsmID = stateArray[1];
                        }
                        else {
                            //DO_20221228:表格编辑器,自动检测,中英文
                            VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{状态名}}：" + state_info + "，{{当前顺序响应目标状态填写格式为“*模板变量.状态名”}}，{{在当前模板变量中无法查找到对应状态名}}，{{请检查}}！", '', Severity.Error));
                            return false;
                        }
                    }
                    else {
                        //DO_20221228:表格编辑器,自动检测,中英文
                        VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{状态名}}：" + state_info + "，{{当前顺序响应目标状态填写格式为“*模板变量.状态名”}}，{{在当前系统中无法查找到该模板变量}}，{{请检查}}！", '', Severity.Error));
                        return false;
                    }
                }
                //对象名.状态名
                else {
                    var aObject: VEObject = VEObjects.getByName(aObjectID, this.nodeID);
                    if (aObject == null) {
                        //DO_20221228:表格编辑器,自动检测,中英文
                        VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{状态名}}：" + state_info + "，{{当前顺序响应目标状态填写格式为“对象名.状态名”}}，{{当前系统中无法查找到该对象名}}，{{请检查}}！", '', Severity.Error));
                        return false;
                    }
                    var aFsm: VE_Fsm = aObject.getFsm(aFsmID);
                    if (aFsm == null) {
                        //DO_20221228:表格编辑器,自动检测,中英文
                        VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{状态名}}：" + state_info + "，{{当前顺序响应目标状态填写格式为“对象名.状态名”}}，{{当前对象名所对应的对象中无法查找到该状态名}}，{{请检查}}！", '', Severity.Error));
                        return false;
                    }
                    //VE_State toState = aFsm[this._stateIndex];
                    //if (toState == null)
                    //{
                    //    Debug.LogError(this.ID + " 响应参数错误，状态名：" + state_info + "，当前顺序响应目标状态填写格式为“对象名.状态名”，当前关联状态序号超出对应状态序号范围，请检查！");
                    //    return false;
                    //}
                    this._type = AssociatedFsmType.Object;
                    //this._state = toState;
                    this._fsm = aFsm;
                }
            }
            else {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{状态名}}：" + state_info + "，{{当前顺序响应目标状态填写格式为“1.状态名；2.对象名.状态名；3.*模板变量.状态名；4.对象名.*局部模板变量.状态名”}}，{{当前都不符合}}，{{请检查}}！", '', Severity.Error));
                return false;
            }
        }
        //状态名
        else {
            var aFsm: VE_Fsm = veryObject.getFsm(aFsmID);
            if (aFsm == null) {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应参数错误}}，{{状态名}}：" + state_info + "，{{当前顺序响应目标状态填写格式为“状态名”}}，{{状态名填写错误}}，{{可以查找到对象}}，{{但是对象上无法查找到该状态}}，{{请检查}}！", '', Severity.Error));
                return false;
            }
            //VE_State toState = aFsm[this._stateIndex];
            //if (toState == null)
            //{
            //    Debug.LogError(this.ID + " 响应参数错误，状态名：" + state_info + "，当前顺序响应目标状态填写格式为“状态名”，可以查找到对象和状态，当前关联状态序号超出对应状态序号范围，请检查！");
            //    return false;
            //}
            this._type = AssociatedFsmType.Object;
            this._fsm = aFsm;
            //this._state = toState;
        }

        return true;
    }

}
//DO_20220323:动画响应控制
VE_Actions.addAction(Action_AnimationActionControl);