import { VE_TriggerBehaviour } from "../../trigger";
import { VE_Triggers } from '../../trigger';
import { ParaParserUtility, VE_KeyboardMap, VeryParas } from '../../utility';
import { ParaType, Severity } from '../../enum';
import { VE_ErrorManager, VE_Error } from '../../global';

export class Trigger_Phone_OrientationChange extends VE_TriggerBehaviour {

    public get ID(): string {
        return 'Phone_OrientationChange|手机横屏竖屏切换';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '手机横屏竖屏切换，横屏,手机横屏竖屏切换，竖屏';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=942';
    }
    public get className(): string {
        return 'Trigger_Phone_OrientationChange';
    }

    //屏幕方想
    private _diviceOritation: string = '';

    //触发初始化
    private _initialed: boolean = false;

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 1)) {
            return false;
        } else {
            //DO_20220830:触发响应中参数支持中英文
            if (para_array[0] === '横屏' || para_array[0].toLowerCase() == 'landscape') {
                this._diviceOritation = '横屏';
            }
            else if (para_array[0] === '竖屏' || para_array[0].toLowerCase() == 'portrait') {
                this._diviceOritation = '竖屏';
            }
            else {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{触发}} {{传入参数格式错误}}：" + para_array[0] + "，{{参数应为}}横屏|landscape、竖屏|portrait，{{此处填写错误}}，{{请检查}}！", '', Severity.Error));
                return false;
            }

            return true;
        }

    }

    public onUpdate(): void {
        if (!this._initialed) {

            let self = this;
            if (window.orientation === 90 || window.orientation === -90) {
                if (self._diviceOritation === '横屏') {
                    //横屏
                    self.sendEvent();
                }
            }
            else if (window.orientation === 0 || window.orientation === 180) {
                if (self._diviceOritation === '竖屏') {
                    //竖屏
                    self.sendEvent();
                }
            }
            window.addEventListener("orientationchange", function () {
                if (window.orientation === 90 || window.orientation === -90) {
                    if (self._diviceOritation === '横屏') {
                        //横屏
                        self.sendEvent();
                    }
                }
                else if (window.orientation === 0 || window.orientation === 180) {
                    if (self._diviceOritation === '竖屏') {
                        //竖屏
                        self.sendEvent();
                    }
                }
            }, false);
            /*
            window.addEventListener("resize", function () {
                if (window.orientation === 90 || window.orientation === -90) {
                    if (self._diviceOritation === '横屏') {
                        //横屏
                        self.sendEvent();
                    }
                }
                else if (window.orientation === 0 || window.orientation === 180) {
                    if (self._diviceOritation === '竖屏') {
                        //竖屏
                        self.sendEvent();
                    }
                }

            });
            */

            this._initialed = true;
        }
    }

    public destroy(): void {

    }

}

//DO_20220606:手机修改,横屏竖屏切换
VE_Triggers.addTrigger(Trigger_Phone_OrientationChange);