export class Trigger_MousePickUI extends VE_TriggerBehaviour {

    public get ID(): string {
        return 'MousePickUI|鼠标点选UI';
    };

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '鼠标点选UI，2D画布.容器.按钮1，null';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=924';
    }
    public get className(): string {
        return 'Trigger_MousePickUI';
    };

    private _controlVar: VeryUI = new VeryUI();

    //点击时间,根据点击时间差获取实际点击UI
    private _pickTime: number = 0;

    public paraParser(para_array: string[]): boolean {

        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 2)) {
            return false;
        }
        else {
            //第一个参数:Mesh的isPickable为true才能点选被检测到
            var tmpArray: string[] = para_array[0].split(/,|，/);
            for (var i = 0; i < tmpArray.length; i++) {
                tmpArray[i] = tmpArray[i].trim();
                var newUI = new VeryUI();
                let para1: VeryParas = new VeryParas();
                if (!ParaParserUtility.UIControlPara(this.objectID, this.ID, ParaType.Trigger, para1, tmpArray[i])) {
                    return false;
                }
                newUI = para1.uiControl;
                //DO_5代ui修改
                let tmpControl = newUI.value;
                //DO_20221228:表格编辑器,自动检测
                if (!VeryEngine.enableLuckySheet) {
                    if (tmpControl.sceneObj instanceof BABYLON.GUI.Control) {
                        tmpControl.sceneObj.onPointerDownObservable.add(() => {
                            var myDateTime = new Date().getTime();
                            if (this._pickTime === 0) {
                                this._pickTime = myDateTime;
                                this._controlVar.setValue(tmpControl);
                                this.sendEvent();
                            }
                            else {
                                //根据点击时间差获取实际点击UI
                                if ((myDateTime - this._pickTime) > 100) {
                                    this._pickTime = myDateTime;
                                    this._controlVar.setValue(tmpControl);
                                    this.sendEvent();
                                }
                            }
                        })
                    }
                    else
                        tmpControl.sceneObj.addEventListener("mousedown", () => {
                            var myDateTime = new Date().getTime();
                            if (this._pickTime === 0) {
                                this._pickTime = myDateTime;
                                this._controlVar.setValue(tmpControl);
                                this.sendEvent();
                            }
                            else {
                                //根据点击时间差获取实际点击UI
                                if ((myDateTime - this._pickTime) > 100) {
                                    this._pickTime = myDateTime;
                                    this._controlVar.setValue(tmpControl);
                                    this.sendEvent();
                                }
                            }
                        })
                }
            }

            //第2个参数:
            if (para_array[1].toLowerCase() == "null" || para_array[1].toLowerCase() == "none") {

            }
            else {
                let para2: VeryParas = new VeryParas();
                if (!ParaParserUtility.UIControlParaOnlyVar(this.objectID, this.ID, ParaType.Trigger, para2, para_array[1])) {
                    return false;
                }
                this._controlVar = para2.uiControl;
            }

            return true;
        }
    }

    public destroy(): void {

    }
}

