import { VE_ActionBehaviour, VE_Actions } from "../../action";
import { ParaParserUtility, VeryParas } from '../../utility';
import { ParaType, Severity } from '../../enum';
import { VE_ErrorManager, VE_Error, GameGlobal } from '../../global';
import { VeryGameObject, VeryString, VeryMaterial } from "../../variables";
import { BabylonLoader } from "../../../veryengine/loader";

//DO_20221228:表格编辑器,自动检测
import { VeryEngine } from "../../veryEngine";

export class Action_Get_Material extends VE_ActionBehaviour {

    public get ID(): string {
        return 'Get_Material|获取材质球';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '获取材质球，立方体，*材质球变量';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=707';
    }
    public get className(): string {
        return 'Action_Get_Material';
    }


    private _blueGameobject: VeryGameObject = new VeryGameObject();
    private _blueMaterial: VeryMaterial = new VeryMaterial();


    public active(): void {

    }

    public onUpdate(): void {
        var tmpMesh = this._blueGameobject.value?.mesh;
        if (tmpMesh != null && tmpMesh != undefined) {
            this._blueMaterial.value = tmpMesh.material;
        }
    }


    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 2)) {
            return false;
        } else {
            // 第1个参数：
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0], this.nodeID)) {
                return false;
            }
            this._blueGameobject = para0.gameObject;
            //DO_20221228:表格编辑器,自动检测
            if (!VeryEngine.enableLuckySheet) {
                var tmpMesh = this._blueGameobject.value?.mesh;
                if (tmpMesh == null || tmpMesh == undefined) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[0] + "，{{该物体不具有Mesh}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }

            //参数2
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.MaterialParaOnlyVar(this.objectID, this.ID, ParaType.Action, para1, para_array[1])) {
                return false;
            }
            this._blueMaterial = para1.material;

            return true;
        }

    }
    public destroy(): void {

    }
}

export class Action_Set_Material extends VE_ActionBehaviour {

    public get ID(): string {
        return 'Set_Material|设置材质球';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '设置材质球，立方体，1601112126-3a9aa95a';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=709';
    }
    public get className(): string {
        return 'Action_Set_Material';
    }


    private _blueGameobject: VeryGameObject = new VeryGameObject();
    private _isMaterialVar: boolean = false;
    private _blueMaterial: VeryMaterial = new VeryMaterial();
    private _materialString: VeryString = new VeryString();

    public active(): void {
        if (this._blueGameobject.value.mesh) {
            // if(this._isMaterialVar) {
            //     this._blueGameobject.value.mesh.material = this._blueMaterial.value;
            // } else {
            //     this._blueGameobject.value.mesh.material = this._blueMaterial.value;
            // }

            //DO_20211116:gif,模型贴图初始化设置Gif
            let tmpMat = this._blueMaterial.value;
            if (tmpMat instanceof BABYLON.StandardMaterial) {
                //DO_20211207:gif支持blob格式
                //DO_20211220:diffuseTexture可能为空
                if (GameGlobal.assetsData.assets[this._materialString.value].data.diffuseTexture) {
                    var assetID = GameGlobal.assetsData.assets[this._materialString.value].data.diffuseTexture.texture_id;
                    //console.warn(GameGlobal.assetsData.assets[assetID]);
                    if (GameGlobal.assetsData.assets[assetID] && GameGlobal.assetsData.assets[assetID].name.endsWith('.gif')) {
                        ossfile.getUrl(GameGlobal.projectID, assetID, GameGlobal.assetsData.assets[assetID].name, GameGlobal.assetsData.assets[assetID].file.hash).then(response => {
                            //console.log('newMat.diffuseTexture.name--' + response);
                            if (GameGlobal.addMaterialGif[response] == undefined) {
                                GameGlobal.addMaterialGif[response] = {};
                            }
                            //设置gif
                            if (GameGlobal.addMaterialGif[response][tmpMat.uniqueId + '~' + 'diffuseTexture'] === undefined) {
                                GameGlobal.addMaterialGif[response][tmpMat.uniqueId + '~' + 'diffuseTexture'] = tmpMat;
                            }
                        });
                    }
                }
            }

            this._blueGameobject.value.mesh.material = this._blueMaterial.value;
        }
    }

    private async getMaterial() {
        let self = this;
        this._blueMaterial.value = await BabylonLoader.getMaterial(self._materialString.value);
        if (!this._blueMaterial.value) {
            console.warn('响应：' + this.ID + '，当前材质ID（' + this._materialString.value + '）无法实例化，请检查！');
        }
    }

    public onUpdate(): void {
        // var tmpMesh = this._blueGameobject.value?.mesh;
        // if (tmpMesh != null && tmpMesh != undefined) {
        //     tmpMesh.material = this._blueMaterial.value;
        // }
    }


    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 2)) {
            return false;
        } else {
            // 参数1 待设置物体
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0], this.nodeID)) {
                return false;
            }
            this._blueGameobject = para0.gameObject;
            //DO_20221228:表格编辑器,自动检测
            if (!VeryEngine.enableLuckySheet) {
                var tmpMesh = this._blueGameobject.value.mesh;
                if (!tmpMesh) {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[0] + "，{{该物体不具有Mesh}}，{{请检查}}！", '', Severity.Error));
                    return false;
                }
            }

            // 参数2 材质变量或者材质ID
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.MaterialParaOnlyVar(this.objectID, this.ID, ParaType.Action, para1, para_array[1], false)) {
                if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[1])) {
                    return false;
                } else {
                    this._isMaterialVar = false;
                    this._materialString = para1.string;
                    setTimeout(this.getMaterial.bind(this), 0);
                }
            } else {
                this._isMaterialVar = true;
                this._blueMaterial = para1.material;
            }

            return true;
        }

    }

    public destroy(): void {

    }
}

//TODO:20200807
VE_Actions.addAction(Action_Get_Material);
VE_Actions.addAction(Action_Set_Material);