export class VEFinder {


    public static FindEntity(node_id: string): Nullable<VREdit.IEDEntity> {
        if (VREdit.shareBox.id2Entity[node_id]) {
            return VREdit.shareBox.id2Entity[node_id];
        } else {
            return null;
        }
    }

    public static FindNode(node_name: string, host_node_id: string): Nullable<BABYLON.Node> {
        let assetId = null;
        if (VREdit.shareBox.id2Entity[host_node_id]) {
            assetId = VREdit.shareBox.id2Entity[host_node_id].originAsset;
            if (VREdit.shareBox.id2Entity[host_node_id].name === node_name) {
                return VREdit.shareBox.id2Entity[host_node_id].sceneObj;
            }
        }
        let recordEntity = null;
        // console.warn(`FindNode --- name: ${node_name}, asset id: ${assetId}`);
        for (let entity of Object.values(VREdit.shareBox.id2Entity)) {
            if (entity.type !== 'logic') {
                if (entity.name == node_name) {
                    // 若来自同一个.babylon
                    if (assetId == null || assetId == entity.originAsset) {
                        return entity.sceneObj;
                    } else if (!recordEntity) {
                        recordEntity = entity;
                    }
                }
            }
        }
        return recordEntity ? recordEntity.sceneObj : null;
    }

    public static FindNodeEntity(node_name: string, host_node_id: string): Nullable<VREdit.IEDEntity> {

        let assetId = null;
        if (VREdit.shareBox.id2Entity[host_node_id]) {
            assetId = VREdit.shareBox.id2Entity[host_node_id].originAsset;
            if (VREdit.shareBox.id2Entity[host_node_id].name === node_name) {
                return VREdit.shareBox.id2Entity[host_node_id];
            }
        }
        let recordEntity = null;
        // console.warn(`FindNode --- name: ${node_name}, asset id: ${assetId}`);
        for (let entity of Object.values(VREdit.shareBox.id2Entity)) {
            if (entity.type !== 'logic') {
                if (entity.name == node_name) {
                    // 若来自同一个.babylon
                    if (assetId == null || assetId == entity.originAsset) {
                        return entity;
                    } else if (!recordEntity) {
                        recordEntity = entity;
                    }
                }
            }
        }
        return recordEntity ? recordEntity : null;
    }

    public static FindMesh(node_name: string, host_node_id: string): Nullable<BABYLON.AbstractMesh> {
        const node = VEFinder.FindNode(node_name, host_node_id);
        if (!node) {
            return null;
        } else if (node instanceof BABYLON.AbstractMesh) {
            return node;
        } else {
            return null;
        }
    }


    // public static


}