function isMobile() {
    var userAgentInfo = navigator.userAgent;

    var mobileAgents = ["Android", "iPhone", "SymbianOS", "Windows Phone", "iPad", "iPod"];

    var mobile_flag = false;

    //根据userAgent判断是否是手机
    for (var v = 0; v < mobileAgents.length; v++) {
        if (userAgentInfo.indexOf(mobileAgents[v]) > 0) {
            mobile_flag = true;
            break;
        }
    }
    return mobile_flag;
}
export class Trigger_UGUI_Button extends VE_TriggerBehaviour {

    public get ID(): string {
        return 'GUI_Button|按钮 ';
    };
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '按钮，2D画布.容器.按钮';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=518';
    }
    public get className(): string {
        return 'Trigger_UGUI_Button';
    };

    private _button: BABYLON.GUI.Control | HTMLElement;

    private _observer: any = null;
    private tag = false;

    public paraParser(para_array: string[]): boolean {

        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 1)) {
            return false;
        }
        else {
            //第一个参数
            this.tag = isMobile();
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.UIControlPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            
            //DO_20221228:表格编辑器,自动检测
            if (!VeryEngine.enableLuckySheet) {
                this._button = para0.uiControl.value.sceneObj;
                if (this._button instanceof BABYLON.GUI.Control) {
                    this._button.isPointerBlocker = true;
                    this._observer = this._button.onPointerDownObservable.add(() => {
                        this.sendEvent();
                    });
                } else {
                    this._observer = this.sendEvent.bind(this);
                    if (this.tag) {
                        this._button.addEventListener("touchstart", this._observer);
                    } else
                        this._button.addEventListener("mousedown", this._observer);
                }
            }

            return true;
        }
    }
    public destroy(): void {
        if (this._observer) {
            if (this._button instanceof BABYLON.GUI.Control)
                this._button.onPointerDownObservable.remove(this._observer);
            else {
                this._button.removeEventListener("mousedown", this._observer);
                this._button.removeEventListener("touchstart", this._observer);
            }

        }
        this._observer = null;
    }
}

export class Trigger_Slider_Button extends VE_TriggerBehaviour {

    public get ID(): string {
        return 'Slider_Button|滑块按钮';
    };
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '滑块按钮，2D画布.容器.滑动条,按下';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=518';
    }
    public get className(): string {
        return 'Trigger_Slider_Button';
    };

    private _control: HTMLElement;
    private _eventType: string;

    private _moveObserver: any = null;
    private _outObserver: any = null;
    private _downObserver: any = null;
    private _upObserver: any = null;
    private _clickObserver: any = null;
    private _enterObserver: any = null;
    private tag = false;

    public paraParser(para_array: string[]): boolean {

        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 2)) {
            return false;
        }
        else {
            //第一个参数
            this.tag = isMobile();
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.UIControlPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            //DO_20221228:表格编辑器,自动检测
            let tmp;
            if (!VeryEngine.enableLuckySheet) {
                tmp = para0.uiControl.value.sceneObj;
            }
            let thum: HTMLElement;
            if (tmp instanceof BABYLON.GUI.Control) {
                console.error(para_array[0] + ",该物体为3dgui，暂不支持");
                return false;
            } else if (tmp) {
                this._control = tmp;
                thum = this._control.querySelector(".sliderThumb");
                if (!thum) {
                    console.error(para_array[0] + ",该物体非滑动条类型，暂不支持");
                    return false;
                }
            }
            //DO_20220830:触发响应中参数支持中英文
            //第2个参数
            this._eventType = para_array[1];
            if (this._eventType == '移动' || this._eventType.toLowerCase() == 'mousemove') {
                //DO_20221228:表格编辑器,自动检测
                if (!VeryEngine.enableLuckySheet) {
                    this._moveObserver = this.sendEvent.bind(this);
                    if (this.tag)
                        thum.addEventListener("touchmove", this._moveObserver);
                    else
                        thum.addEventListener("mousemove", this._moveObserver);
                }
            }
            else if (this._eventType == '移出' || this._eventType.toLowerCase() == 'mouseexist') {
                //DO_20221228:表格编辑器,自动检测
                if (!VeryEngine.enableLuckySheet) {
                    this._outObserver = this.sendEvent.bind(this);
                    thum.addEventListener("mouseout", this._outObserver);
                }
            }
            else if (this._eventType == '按下' || this._eventType.toLowerCase() == 'mousedown') {
                //DO_20221228:表格编辑器,自动检测
                if (!VeryEngine.enableLuckySheet) {
                    this._downObserver = this.sendEvent.bind(this);
                    if (this.tag)
                        thum.addEventListener("touchstart", this._downObserver)
                    else
                        thum.addEventListener("mousedown", this._downObserver);
                }
            }
            else if (this._eventType == '抬起' || this._eventType.toLowerCase() == 'mouseup') {
                //DO_20221228:表格编辑器,自动检测
                if (!VeryEngine.enableLuckySheet) {
                    this._upObserver = this.sendEvent.bind(this);
                    if (this.tag)
                        thum.addEventListener("touchend", this._upObserver)
                    else
                        thum.addEventListener("mouseup", this._upObserver);
                }
            }
            else if (this._eventType == '点击' || this._eventType.toLowerCase() == 'mouseclick') {
                //DO_20221228:表格编辑器,自动检测
                if (!VeryEngine.enableLuckySheet) {
                    this._clickObserver = this.sendEvent.bind(this);
                    thum.addEventListener("click", this._clickObserver);
                }
            }
            else if (this._eventType == '移入' || this._eventType.toLowerCase() == 'mouseenter') {
                //DO_20221228:表格编辑器,自动检测
                if (!VeryEngine.enableLuckySheet) {
                    this._enterObserver = this.sendEvent.bind(this);
                    thum.addEventListener("mouseenter", this._enterObserver);
                }
            }
            else {
                //DO_20221228:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{触发}} {{传入参数格式可能有误}}，{{传入参数}}：" + para_array[1] + "，{{事件类型填写错误}}，{{请检查}}！", '', Severity.Error));
                return false;
            }

            return true;
        }
    }
    public destroy(): void {
        if (this._moveObserver) {
            this._control.removeEventListener("mousemove", this._moveObserver)
        }
        if (this._outObserver) {
            this._control.removeEventListener("mouseout", this._outObserver)
        }
        if (this._downObserver) {
            this._control.removeEventListener("mousedown", this._downObserver)
        }
        if (this._upObserver) {
            this._control.removeEventListener("mouseup", this._upObserver);
        }
        if (this._clickObserver) {
            this._control.removeEventListener("click", this._clickObserver)
        }
        if (this._enterObserver) {
            this._control.removeEventListener("mouseenter", this._enterObserver)
        }
    }
}

