export class Trigger_UGUI_Repeat_Button extends VE_TriggerBehaviour {

    public get ID(): string {
        return 'GUI_Repeat_Button|按钮持续';
    };
    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '按钮持续，2D画布.容器.按钮';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=870';
    }
    public get className(): string {
        return 'Trigger_UGUI_Repeat_Button';
    };

    private _button: BABYLON.GUI.Control | HTMLElement;
    private _isTrigger: boolean = false;

    private _outObserver: any = null;
    private _downObserver: any = null;
    private _upObserver: any = null;

    public paraParser(para_array: string[]): boolean {

        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 1)) {
            return false;
        }
        else {
            //第一个参数
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.UIControlPara(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            //DO_20221228:表格编辑器,自动检测
            if (!VeryEngine.enableLuckySheet)
                this._button = para0.uiControl.value.sceneObj;
            //DO_20221228:表格编辑器,自动检测
            if (!VeryEngine.enableLuckySheet) {
                if (this._button instanceof BABYLON.GUI.Button) {
                    this._button.isPointerBlocker = true;
                    this._downObserver = this._button.onPointerDownObservable.add(() => {
                        this._isTrigger = true;
                    });
                    this._upObserver = this._button.onPointerUpObservable.add(() => {
                        this._isTrigger = false;
                    });
                    this._outObserver = this._button.onPointerOutObservable.add(() => {
                        this._isTrigger = false;
                    });
                } else {
                    this._downObserver = () => {
                        this._isTrigger = true;
                    };
                    this._upObserver = () => {
                        this._isTrigger = false;
                    }
                    this._outObserver = () => {
                        this._isTrigger = false;
                    }
                    (this._button as HTMLElement).addEventListener("mousedown", this._downObserver);
                    (this._button as HTMLElement).addEventListener("mouseup", this._upObserver);
                    (this._button as HTMLElement).addEventListener("mouseout", this._outObserver);
                }
            }

            return true;
        }
    }

    public onUpdate(): void {
        if (this.enabled) {
            if (this._isTrigger) {
                this.sendEvent();
            }
        }
    }

    public destroy(): void {
        if (this._button instanceof BABYLON.GUI.Button) {
            if (this._outObserver) {
                this._button.onPointerOutObservable.remove(this._outObserver);
            }
            if (this._downObserver) {
                this._button.onPointerDownObservable.remove(this._downObserver);
            }
            if (this._upObserver) {
                this._button.onPointerUpObservable.remove(this._upObserver);
            }
        } else {
            if (this._outObserver)
                (this._button as HTMLElement).removeEventListener("mouseout", this._outObserver);
            if (this._downObserver)
                (this._button as HTMLElement).removeEventListener("mousedown", this._downObserver);
            if (this._upObserver)
                (this._button as HTMLElement).removeEventListener("mouseup", this._upObserver);
        }
        this._outObserver = null;
        this._downObserver = null;
        this._upObserver = null;
    }
}

export class UGUI_Tools {

    public static GetUI(scene: BABYLON.Scene, buttonName: string, id: string): BABYLON.Nullable<BABYLON.GUI.Control> {
        // scene = BabylonEngine.GUIScene;
        var array: string[] = buttonName.split('.');
        var tmpTexture: BABYLON.GUI.AdvancedDynamicTexture;

        // 2D GUI在单独的GUI scene中，但是3D GUI依然在普通场景中
        let allTexture: BABYLON.BaseTexture[] = [];
        if (BabylonEngine.GUIScene !== BabylonEngine.Scene) {
            for (var i = 0; i < BabylonEngine.GUIScene.textures.length; i++) {
                allTexture.push(BabylonEngine.GUIScene.textures[i]);
            }

            for (var i = 0; i < BabylonEngine.Scene.textures.length; i++) {
                allTexture.push(BabylonEngine.Scene.textures[i]);
            }
        } else {
            allTexture = BabylonEngine.Scene.textures;
        }

        for (var i = 0; i < allTexture.length; i++) {
            if (allTexture[i] instanceof BABYLON.GUI.AdvancedDynamicTexture && array[0] === allTexture[i].name) {
                tmpTexture = <BABYLON.GUI.AdvancedDynamicTexture>allTexture[i];
                var tmpContainer = tmpTexture.rootContainer;
                if (array.length === 1) {
                    return tmpContainer;
                }

                for (var k = 1; k < array.length; k++) {
                    var tmpControl = tmpContainer.getChildByName(array[k]);
                    if (tmpControl === null) {
                        break;
                    }
                    else {
                        if (k !== (array.length - 1)) {
                            tmpContainer = <BABYLON.GUI.Container>tmpControl;
                        }
                        else {
                            return tmpControl;
                        }
                    }
                }
            }
        }
        // console.error(id + '--响应参数出错--' + buttonName);
        return null;
    }

    //RGB转成#FFFFFF格式
    public static RGBToHexColor(r: number, g: number, b: number): string {
        var str = "#";
        var tmpStr = new Number((r * 255).toFixed()).toString(16);
        if (tmpStr.length == 1) {
            tmpStr = "0" + tmpStr;
        }
        str += tmpStr;
        var tmpStr = new Number((g * 255).toFixed()).toString(16);
        if (tmpStr.length == 1) {
            tmpStr = "0" + tmpStr;
        }
        str += tmpStr;
        var tmpStr = new Number((b * 255).toFixed()).toString(16);
        if (tmpStr.length == 1) {
            tmpStr = "0" + tmpStr;
        }
        str += tmpStr;
        return str;
    }
    //TODO_20210625:GUI动画
    //#FFFFFF格式转成RGB
    public static HexColorToRGB(hsv: string): number[] {
        var colorChange = [];
        for (var i = 1; i < hsv.length; i += 2) {
            colorChange.push(parseInt('0x' + hsv.slice(i, i + 2)) / 255.0);
        }
        return colorChange;
    }
}

