import { IExpression, VE_Expressions } from "../expression";
import { VE_AssignmentTypeJudge } from "../action/assignmentTypeJudge";
import { VEClone } from "../template";
import { AssignType } from "../enum";
import { IVeryVar, VeryExpression } from "../variables";
import { StateConst, VE_State, VE_StateAction } from "../state";
import { VEObject, VEObjects } from "../object";
import { VE_Assignment } from "../action";
import { ErrorInfo, VE_StringFormat } from "../utility";
import { VE_Error, VE_ErrorManager } from "../global";
import { VE_StateActionData } from "../dataSource";

export class AssignmentParser {



    public assignmentAction(
        object_id: string,
        fsm_id: string,
        very_object: VEObject,
        action_data: VE_StateActionData,
        state: VE_State
    ): boolean {

        let successful: boolean = true;

        // 赋值
        const assignment: VE_Assignment = new VE_Assignment(
            state,
            action_data.totalString
        );
        let varID: string = action_data.varID;
        // Debug.LogWarning("赋值响应：" + action_data.TotalString);
        // 1. 等号左侧： 变量必须为普通变量，允许格式：
        //（1）*变量；（2）对象名.*变量；（3）*模板变量.*变量；（4）对象名.*模板变量.*变量；
        if (varID.indexOf(StateConst.VARIABLE_SYMBOL) > -1) {
            // 变量或者公式
            if (varID.indexOf(StateConst.STATE_SEPARATOR) > -1) {
                const valArray: string[] = varID.split(StateConst.STATE_SEPARATOR);
                for (let q: number = 0; q < valArray.length; q++) {
                    valArray[q] = valArray[q].trim();
                }
                // 对象名.*变量 or *模板变量.*变量
                if (valArray.length === 2) {
                    // *模板变量.*变量，当前未实例化，只做前期语法检测，然后记录参数到状态，状态使用时，动态读取
                    if (valArray[0].startsWith(StateConst.VARIABLE_SYMBOL)) {
                        const templateVarID: string = valArray[0].substring(1);
                        varID = valArray[1].substring(1);
                        if (very_object.isCreatedClone(templateVarID)) {
                            const clone: VEClone = very_object.getClone(templateVarID);
                            // console.warn(clone);
                            if (clone.parent && clone.parent.varData.isCreatedVariable(varID)) {
                                const varPara: string[] = clone.parent.varData.getVariableParas(varID);
                                if (
                                    varPara[1].toLowerCase() === "expression" ||
                                    varPara[1].toLowerCase() === "公式"
                                ) {
                                    VE_ErrorManager.Add(
                                        VE_Error.error(
                                            "",
                                            "{{对象}}：" +
                                            object_id +
                                            "，{{状态}}：" +
                                            fsm_id +
                                            "，{{赋值响应}}：" +
                                            action_data.totalString +
                                            "，{{当前赋值响应等号左侧格式“*模板变量.*变量”}}，{{该变量不能为“公式”}}，{{请检查}}！",
                                            "",
                                            object_id
                                        )
                                    );
                                    successful = false;
                                } else {
                                    assignment.setLeftCloneVar(clone, varID);
                                }
                            } else if (clone.parent && clone.parent.dataSource.isCreatedFsm(varID)) {
                                assignment.setLeftCloneVar(clone, varID);
                            } else {
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        "",
                                        "{{对象}}：" +
                                        object_id +
                                        "，{{状态}}：" +
                                        fsm_id +
                                        "，{{赋值响应}}：" +
                                        action_data.totalString +
                                        "，{{当前赋值响应等号左侧格式“*模板变量.*变量”}}，{{当前“*模板变量”可以查找到}}，{{但是无法查到对应“*变量”}}，{{请检查}}！",
                                        "",
                                        object_id
                                    )
                                );
                                successful = false;
                            }
                        } else {
                            VE_ErrorManager.Add(
                                VE_Error.error(
                                    "",
                                    "{{对象}}：" +
                                    object_id +
                                    "，{{状态}}：" +
                                    fsm_id +
                                    "，{{赋值响应}}：" +
                                    action_data.totalString +
                                    "，{{当前赋值响应等号左侧格式“*模板变量.*变量”}}，{{当前“*模板变量”无法在系统中查找到}}，{{请检查}}！",
                                    "",
                                    object_id
                                )
                            );
                            successful = false;
                        }
                    }
                    // 对象名.*变量
                    else {
                        if (VEObjects.isNodeNameLoaded(valArray[0], very_object.NodeID)) {
                            const aObject: VEObject = VEObjects.getByName(valArray[0], very_object.NodeID);
                            //DO_20221102:测试赋值响应,对象名.*变量
                            //varID = varID.substring(1);
                            varID = valArray[1].substring(1);
                            if (aObject.isCreatedExpression(varID)) {
                                //DO_20221228:表格编辑器,自动检测,中英文
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        "",
                                        "{{对象}}：" +
                                        object_id +
                                        "，{{状态}}：" +
                                        fsm_id +
                                        "，{{赋值响应}}：" +
                                        action_data.totalString +
                                        "，{{当前赋值响应等号左侧格式“对象名.*变量”}}，{{该变量不能为“公式”}}，{{请检查}}！",
                                        "",
                                        object_id
                                    )
                                );
                                successful = false;
                            } else if (aObject.isCreatedFsm(varID)) {
                                const v: IVeryVar = aObject.getFsm(varID).fsmVar;
                                assignment.setLeftVariable(v);
                            } else if (aObject.isCreatedVariable(varID)) {
                                const v: IVeryVar = aObject.getVariable(varID);
                                assignment.setLeftVariable(v);
                            }
                            // TOODO
                            else if (aObject.isCreatedClone(varID)) {
                                const clone: VEClone = aObject.getClone(varID);
                                assignment.setLeftClone(clone);
                            }
                            else {
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        "",
                                        "{{对象}}：" +
                                        object_id +
                                        "，{{状态}}：" +
                                        fsm_id +
                                        "，{{赋值响应}}：" +
                                        action_data.totalString +
                                        "，{{当前赋值响应等号左侧格式“对象名.*变量”}}，{{无法在当前对象名中查找到该变量}}，{{请检查}}！",
                                        "",
                                        object_id
                                    )
                                );
                                successful = false;
                            }
                        } else {
                            VE_ErrorManager.Add(
                                VE_Error.error(
                                    "",
                                    "{{对象}}：" +
                                    object_id +
                                    "，{{状态}}：" +
                                    fsm_id +
                                    "，{{赋值响应}}：" +
                                    action_data.totalString +
                                    "，{{赋值响应等号左侧变量格式“对象名.*变量”}}，{{当前“对象名”无法在系统中查找到}}，{{请检查}}！",
                                    "",
                                    object_id
                                )
                            );
                            successful = false;
                        }
                    }
                } else if (valArray.length === 3) {
                    // 对象名.*模板变量.*变量
                    // 对象名.*模板变量.*变量，当前未实例化，只做前期语法检测，然后记录参数到状态，状态使用时，动态读取
                    if (
                        valArray[0].startsWith(StateConst.VARIABLE_SYMBOL) ||
                        !valArray[1].startsWith(StateConst.VARIABLE_SYMBOL) ||
                        !valArray[2].startsWith(StateConst.VARIABLE_SYMBOL)
                    ) {
                        VE_ErrorManager.Add(
                            VE_Error.error(
                                "",
                                "{{对象}}：" +
                                object_id +
                                "，{{状态}}：" +
                                fsm_id +
                                "，{{赋值响应}}：" +
                                action_data.totalString +
                                "，{{赋值响应等号左侧变量格式错误}}，{{应为“（1）*变量；（2）对象名.*变量；（3）*模板变量.*变量；（4）对象名.*模板变量.*变量”几种形式}}，{{当前不符合}}，{{无法解析}}，{{请检查}}！",
                                "",
                                object_id
                            )
                        );
                        successful = false;
                    } else {
                        const templateVarID: string = valArray[1].substring(1);
                        varID = valArray[2].substring(1);
                        if (VEObjects.isNodeNameLoaded(valArray[0], very_object.NodeID)) {
                            const tObject: VEObject = VEObjects.getByName(valArray[0], very_object.NodeID);
                            if (tObject.isCreatedClone(templateVarID)) {
                                const clone: VEClone = tObject.getClone(templateVarID);
                                if (clone.parent && clone.parent.dataSource.isCreatedFsm(varID)) {
                                    assignment.setLeftCloneVar(clone, varID);
                                } else if (clone.parent && clone.parent.varData.isCreatedVariable(varID)) {
                                    const varParas: string[] = clone.parent.varData.getVariableParas(
                                        varID
                                    );
                                    if (
                                        varParas[1].toLowerCase() === "expression" ||
                                        varParas[1].toLowerCase() === "公式"
                                    ) {
                                        VE_ErrorManager.Add(
                                            VE_Error.error(
                                                "",
                                                "{{对象}}：" +
                                                object_id +
                                                "，{{状态}}：" +
                                                fsm_id +
                                                "，{{赋值响应}}：" +
                                                action_data.totalString +
                                                "，{{赋值响应等号左侧变量格式“对象名.*模板变量.*变量”}}，{{当前“对象名.*模板变量.*变量”为公式变量}}，{{公式变量不可直接赋值}}，{{请检查}}！",
                                                "",
                                                object_id
                                            )
                                        );
                                        successful = false;
                                    } else {
                                        assignment.setLeftCloneVar(clone, varID);
                                    }
                                } else {
                                    VE_ErrorManager.Add(
                                        VE_Error.error(
                                            "",
                                            "{{对象}}：" +
                                            object_id +
                                            "，{{状态}}：" +
                                            fsm_id +
                                            "，{{赋值响应}}：" +
                                            action_data.totalString +
                                            "，{{赋值响应等号左侧变量格式“对象名.*模板变量.*变量”}}，{{当前“对象名.*模板变量”可以查找到}}，{{但是无法查到对应“*变量”}}，{{请检查}}！",
                                            "",
                                            object_id
                                        )
                                    );
                                    successful = false;
                                }
                            } else {
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        "",
                                        "{{对象}}：" +
                                        object_id +
                                        "，{{状态}}：" +
                                        fsm_id +
                                        "，{{赋值响应}}：" +
                                        action_data.totalString +
                                        "，{{赋值响应等号左侧变量格式“对象名.*模板变量.*变量”}}，{{当前“对象名”的对象中无法查找到该“*模板变量”}}，{{请检查}}！",
                                        "",
                                        object_id
                                    )
                                );
                                successful = false;
                            }
                        } else {
                            VE_ErrorManager.Add(
                                VE_Error.error(
                                    "",
                                    "{{对象}}：" +
                                    object_id +
                                    "，{{状态}}：" +
                                    fsm_id +
                                    "，{{赋值响应}}：" +
                                    action_data.totalString +
                                    "，{{赋值响应等号左侧变量格式“对象名.*模板变量.*变量”}}，{{当前“对象名”无法在系统中查找到}}，{{请检查}}！",
                                    "",
                                    object_id
                                )
                            );
                            successful = false;
                        }
                    }
                } else {
                    VE_ErrorManager.Add(
                        VE_Error.error(
                            "",
                            "{{对象}}：" +
                            object_id +
                            "，{{状态}}：" +
                            fsm_id +
                            "，{{赋值响应}}：" +
                            action_data.totalString +
                            "，{{赋值响应等号左侧变量格式错误}}，{{应为“（1）*变量；（2）对象名.*变量；（3）*模板变量.*变量；（4）对象名.*模板变量.*变量”几种形式}}，{{当前不符合}}，{{无法解析}}，{{请检查}}！",
                            "",
                            object_id
                        )
                    );
                    successful = false;
                }
            } // *变量
            else {
                varID = varID.substring(1);
                if (very_object.isCreatedExpression(varID)) {
                    VE_ErrorManager.Add(
                        VE_Error.error(
                            "",
                            "，{{对象}}：" +
                            object_id +
                            "，{{状态}}：" +
                            fsm_id +
                            "，{{赋值响应}}：" +
                            action_data.totalString +
                            "，{{当前赋值响应等号左侧格式“*变量”}}，{{该变量不能为“公式”}}，{{请检查}}！",
                            "",
                            object_id
                        )
                    );
                    successful = false;
                } else if (very_object.isCreatedFsm(varID)) {
                    const v: IVeryVar = very_object.getFsm(varID).fsmVar;
                    assignment.setLeftVariable(v);
                } else if (very_object.isCreatedVariable(varID)) {
                    const v: IVeryVar = very_object.getVariable(varID);
                    assignment.setLeftVariable(v);
                }
                // TOODO
                else if (very_object.isCreatedClone(varID)) {
                    const clone: VEClone = very_object.getClone(varID);
                    assignment.setLeftClone(clone);
                }
                else {
                    VE_ErrorManager.Add(
                        VE_Error.error(
                            "",
                            "{{对象}}：" +
                            object_id +
                            "，{{状态}}：" +
                            fsm_id +
                            "，{{赋值响应}}：" +
                            action_data.totalString +
                            "，{{当前赋值响应等号左侧格式“*变量”}}，{{无法在当前系统中查找到该变量}}，{{请检查}}！",
                            "",
                            object_id
                        )
                    );
                    successful = false;
                }
            }
        } else {
            VE_ErrorManager.Add(
                VE_Error.error(
                    "",
                    "{{对象}}：" +
                    object_id +
                    "，{{状态}}：" +
                    fsm_id +
                    "，{{赋值响应}}：" +
                    action_data.totalString +
                    "，{{赋值响应等号左边必须为变量}}，{{请检查}}！",
                    "",
                    object_id
                )
            );
            successful = false;
        }

        // （2）等号右侧： 变量必须为普通变量，允许格式：（1）*变量；（2）对象名.*变量；（3）*模板变量.*变量；（4）对象名.*模板变量.*变量；（5）常量；
        varID = action_data.varValue.trim();

        // 字符串特殊处理
        if (
            varID.startsWith('"') ||
            varID.startsWith("'") ||
            varID.startsWith("“") ||
            varID.startsWith("‘")
        ) {
            assignment.setRightConst(varID.substring(1, varID.length - 1));
        } else if (VE_StringFormat.isFormulaString(varID)) {
            // 公式处理
            // Debug.LogError(varID);
            const errorInfo: ErrorInfo = new ErrorInfo();
            StateConst.AssignmentFormulaCount++;
            // TOODO
            const localExp: IExpression = VE_Expressions.createLocalExpression(
                StateConst.AssignmentPrefix +
                StateConst.AssignmentFormulaCount.toString(),
                varID,
                object_id,
                errorInfo,
                very_object.NodeID
            );
            if (!errorInfo.isRight || localExp === null || localExp === undefined) {
                // errorInfo = "模板对象实例化失败���局部变量创建失败，公式创建错误：\n" + errorInfo + "，请检查！" + errorPos;
                // return null;
                VE_ErrorManager.Add(
                    VE_Error.error(
                        "",
                        "{{对象}}：" +
                        object_id +
                        "，{{状态}}：" +
                        fsm_id +
                        "，{{赋值响应}}：" +
                        action_data.totalString +
                        "，{{当前赋值响应等号右侧格式“公式”}}，{{公式解析错误}}，{{请检查}}！{{错误信息}}：" +
                        errorInfo.message,
                        "",
                        object_id
                    )
                );
                successful = false;
            }
            assignment.setRightVariable(new VeryExpression(localExp));
        } else {
            if (varID.indexOf(StateConst.VARIABLE_SYMBOL) > -1) {
                // 变量或者公式
                if (varID.indexOf(StateConst.STATE_SEPARATOR) > -1) {
                    const valArray: string[] = varID.split(StateConst.STATE_SEPARATOR);
                    for (let q: number = 0; q < valArray.length; q++) {
                        valArray[q] = valArray[q].trim();
                    }
                    // 对象名.*变量 or *模板变量.*变量
                    if (valArray.length === 2) {
                        // *模板变量.*变量，当前未实例化，只做前期语法检测，然后记录参数到状态，状态使用时，动态读取
                        if (valArray[0].startsWith(StateConst.VARIABLE_SYMBOL)) {
                            const templateVarID: string = valArray[0].substring(1);
                            varID = valArray[1].substring(1);
                            // TOODO
                            if (very_object.isCreatedClone(templateVarID)) {
                                const clone: VEClone = very_object.getClone(templateVarID);
                                if (clone.parent && (clone.parent.varData.isCreatedVariable(varID) || clone.parent.dataSource.isCreatedFsm(varID))) {
                                    // 不确定类型，需要在赋值时判断
                                    assignment.setRightCloneVariable(clone, varID);
                                } else {
                                    VE_ErrorManager.Add(
                                        VE_Error.error(
                                            "",
                                            "{{对象}}：" +
                                            object_id +
                                            "，{{状态}}：" +
                                            fsm_id +
                                            "，{{赋值响应}}：" +
                                            action_data.totalString +
                                            "，{{当前赋值响应等号右侧格式“*模板变量.*变量”}}，{{当前“*模板变量”可以查找到}}，{{但是无法查到对应“*变量”}}，{{请检查}}！",
                                            "",
                                            object_id
                                        )
                                    );
                                    successful = false;
                                }
                            } else {
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        "",
                                        "{{对象}}：" +
                                        object_id +
                                        "，{{状态}}：" +
                                        fsm_id +
                                        "，{{赋值响应}}：" +
                                        action_data.totalString +
                                        "，{{当前赋值响应等号右侧格式“*模板变量.*变量”}}，{{当前“*模板变量”无法在系统中查找到}}，{{请检查}}！",
                                        "",
                                        object_id
                                    )
                                );
                                successful = false;
                            }
                        }
                        // 对象名.*变量
                        else {
                            if (VEObjects.isNodeNameLoaded(valArray[0], very_object.NodeID)) {
                                let aObject: VEObject = VEObjects.getByName(valArray[0], very_object.NodeID);
                                //DO_20221114:赋值响应,对象名.*变量
                                //varID = varID.substring(1);
                                varID = valArray[1].substring(1);
                                // TOODO
                                let rightVar: Nullable<IVeryVar> = null;
                                let rightClone: Nullable<VEClone> = null;
                                if (aObject.isCreatedExpression(varID)) {
                                    rightVar = new VeryExpression(aObject.getExpression(varID));
                                } else if (aObject.isCreatedFsm(varID)) {
                                    rightVar = aObject.getFsm(varID).fsmVar;
                                } else if (aObject.isCreatedVariable(varID)) {
                                    rightVar = aObject.getVariable(varID);
                                } else if (aObject.isCreatedClone(varID)) {
                                    rightClone = aObject.getClone(varID);
                                } else {
                                    VE_ErrorManager.Add(
                                        VE_Error.error(
                                            "",
                                            "{{对象}}：" +
                                            object_id +
                                            "，{{状态}}：" +
                                            fsm_id +
                                            "，{{赋值响应}}：" +
                                            action_data.totalString +
                                            "，{{当前赋值响应等号右侧格式“对象名.*变量”}}，{{无法在当前系统中查找到该变量}}，{{请检查}}！",
                                            "",
                                            object_id
                                        )
                                    );
                                    successful = false;
                                }
                                // 赋值合理性判断
                                if (rightVar !== null && rightVar !== undefined) {
                                    if (assignment.leftType === AssignType.Template) {
                                        VE_ErrorManager.Add(
                                            VE_Error.error(
                                                "",
                                                "{{对象}}：" +
                                                object_id +
                                                "，{{状态}}：" +
                                                fsm_id +
                                                "，{{赋值响应}}：" +
                                                action_data.totalString +
                                                "，{{当前赋值响应等号左侧为“模板变量”类型}}，{{右侧为“普通变量”类型}}，{{无法赋值}}，{{请检查}}！",
                                                "",
                                                object_id
                                            )
                                        );
                                        successful = false;
                                    } else if (assignment.leftType === AssignType.Variable) {
                                        if (
                                            VE_AssignmentTypeJudge.allow(
                                                assignment.leftVariable!,
                                                rightVar
                                            )
                                        ) {
                                            assignment.setRightVariable(rightVar);
                                        } else {
                                            VE_ErrorManager.Add(
                                                VE_Error.error(
                                                    "",
                                                    "{{对象}}：" +
                                                    object_id +
                                                    "，{{状态}}：" +
                                                    fsm_id +
                                                    "，{{赋值响应}}：" +
                                                    action_data.totalString +
                                                    "，{{当前赋值响应等号左侧和右侧类型不匹配}}，{{无法赋值}}，{{请检查}}！",
                                                    "",
                                                    object_id
                                                )
                                            );
                                            successful = false;
                                        }
                                    } else {
                                        // 模板变量，不确定类型
                                        assignment.setRightVariable(rightVar);
                                    }
                                } else if (rightClone != null && rightClone != undefined) {
                                    if (assignment.leftType === AssignType.Template) {
                                        assignment.setRightClone(rightClone);
                                    } else {
                                        VE_ErrorManager.Add(
                                            VE_Error.error(
                                                "",
                                                "{{对象}}：" +
                                                object_id +
                                                "，{{状态}}：" +
                                                fsm_id +
                                                "，{{赋值响应}}：" +
                                                action_data.totalString +
                                                "，{{当前赋值响应等号左侧为“模板变量”}}，{{右侧为“普通变量”}}，{{无法赋值}}，{{请检查}}！",
                                                "",
                                                object_id
                                            )
                                        );
                                        successful = false;
                                    }
                                } else {
                                    VE_ErrorManager.Add(
                                        VE_Error.error(
                                            "",
                                            "{{对象}}：" +
                                            object_id +
                                            "，{{状态}}：" +
                                            fsm_id +
                                            "，{{赋值响应}}：" +
                                            action_data.totalString +
                                            "，{{当前赋值响应等号右侧数据无法识别}}，{{请检查}}！",
                                            "",
                                            object_id
                                        )
                                    );
                                    successful = false;
                                }
                            } else {
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        "",
                                        "{{对象}}：" +
                                        object_id +
                                        "，{{状态}}：" +
                                        fsm_id +
                                        "，{{赋值响应}}：" +
                                        action_data.totalString +
                                        "，{{赋值响应等号右侧变量格式“对象名.*变量”}}，{{当前“对象名”无法在系统中查找到}}，{{请检查}}！",
                                        "",
                                        object_id
                                    )
                                );
                                successful = false;
                            }
                        }
                    } else if (valArray.length === 3) {
                        // 对象名.*模板变量.*变量
                        // 对象名.*模板变量.*变量，当前未实例化，只做前期语法检测，然后记录参数到状态，状态使用时，动态读取
                        if (
                            valArray[0].startsWith(StateConst.STATE_SEPARATOR) ||
                            !valArray[1].startsWith(StateConst.STATE_SEPARATOR) ||
                            !valArray[2].startsWith(StateConst.STATE_SEPARATOR)
                        ) {
                            VE_ErrorManager.Add(
                                VE_Error.error(
                                    "",
                                    "{{对象}}：" +
                                    object_id +
                                    "，{{状态}}：" +
                                    fsm_id +
                                    "，{{赋值响应}}：" +
                                    action_data.totalString +
                                    "，{{赋值响应等号右侧变量格式错误}}，{{应为“（1）*变量；（2）对象名.*变量；（3）*模板变量.*变量；（4）对象名.*模板变量.*变量”几种形式}}，{{当前不符合}}，{{无法解析}}，{{请检查}}！",
                                    "",
                                    object_id
                                )
                            );
                            successful = false;
                        } else {
                            const templateVarID: string = valArray[1].substring(1);
                            varID = valArray[2].substring(1);
                            if (VEObjects.isNodeNameLoaded(valArray[0], very_object.NodeID)) {
                                const tObject: VEObject = VEObjects.getByName(valArray[0], very_object.NodeID);
                                // TOODO
                                if (tObject.isCreatedClone(templateVarID)) {
                                    const clone: VEClone = tObject.getClone(templateVarID);
                                    // 无法判断是否为公式，需在运行条件下判断
                                    if (clone.parent && 
                                        (clone.parent.dataSource.isCreatedFsm(varID) ||
                                        clone.parent.varData.isCreatedVariable(varID))
                                    ) {
                                        // 不确定格式是否合理，运行时判断
                                        assignment.setRightCloneVariable(clone, varID);
                                    } else {
                                        VE_ErrorManager.Add(
                                            VE_Error.error(
                                                "",
                                                "{{对象}}：" +
                                                object_id +
                                                "，{{状态}}：" +
                                                fsm_id +
                                                "，{{赋值响应}}：" +
                                                action_data.totalString +
                                                "，{{赋值响应等号右侧变量格式“对象名.*模板变量.*变量”}}，{{当前“对象名.*模板变量”可以查找到}}，{{但是无法查到对应“*变量”}}，{{请检查}}！",
                                                "",
                                                object_id
                                            )
                                        );
                                        successful = false;
                                    }
                                } else {
                                    VE_ErrorManager.Add(
                                        VE_Error.error(
                                            "",
                                            "{{对象}}：" +
                                            object_id +
                                            "，{{状态}}：" +
                                            fsm_id +
                                            "，{{赋值响应}}：" +
                                            action_data.totalString +
                                            "，{{赋值响应等号右侧变量格式“对象名.*模板变量.*变量”}}，{{当前“对象名”的对象中无法查找到该“*模板变量”}}，{{请检查}}！",
                                            "",
                                            object_id
                                        )
                                    );
                                    successful = false;
                                }
                            } else {
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        "",
                                        "{{对象}}：" +
                                        object_id +
                                        "，{{状态}}：" +
                                        fsm_id +
                                        "，{{赋值响应}}：" +
                                        action_data.totalString +
                                        "，{{赋值响应等号右侧变量格式“对象名.*模板变量.*变量”}}，{{当前“对象名”无法在系统中查找到}}，{{请检查}}！",
                                        "",
                                        object_id
                                    )
                                );
                                successful = false;
                            }
                        }
                    } else {
                        VE_ErrorManager.Add(
                            VE_Error.error(
                                "",
                                "{{对象}}：" +
                                object_id +
                                "，{{状态}}：" +
                                fsm_id +
                                "，{{赋值响应}}：" +
                                action_data.totalString +
                                "，{{赋值响应等号右侧变量格式错误}}，{{应为“（1）*变量；（2）对象名.*变量；（3）*模板变量.*变量；（4）对象名.*模板变量.*变量”几种形式}}，{{当前不符合}}，{{无法解析}}，{{请检查}}！",
                                "",
                                object_id
                            )
                        );
                        successful = false;
                    }
                } // *变量
                else {
                    varID = varID.substring(1);
                    // TOODO
                    let rightVar: Nullable<IVeryVar> = null;
                    let rightClone: Nullable<VEClone> = null;
                    if (very_object.isCreatedExpression(varID)) {
                        rightVar = new VeryExpression(very_object.getExpression(varID));
                    } else if (very_object.isCreatedFsm(varID)) {
                        rightVar = very_object.getFsm(varID).fsmVar;
                    } else if (very_object.isCreatedVariable(varID)) {
                        rightVar = very_object.getVariable(varID);
                    } else if (very_object.isCreatedClone(varID)) {
                        rightClone = very_object.getClone(varID);
                    } else {
                        VE_ErrorManager.Add(
                            VE_Error.error(
                                "",
                                "{{对象}}：" +
                                object_id +
                                "，{{状态}}：" +
                                fsm_id +
                                "，{{赋值响应}}：" +
                                action_data.totalString +
                                "，{{当前赋值响应等号右侧格式“*变量”}}，{{无法在当前系统中查找到该变量}}，{{请检查}}！",
                                "",
                                object_id
                            )
                        );
                        successful = false;
                    }
                    // 赋值合理性判断
                    if (rightVar !== null && rightVar !== undefined) {
                        if (assignment.leftType === AssignType.Template) {
                            VE_ErrorManager.Add(
                                VE_Error.error(
                                    "",
                                    "{{对象}}：" +
                                    object_id +
                                    "，{{状态}}：" +
                                    fsm_id +
                                    "，{{赋值响应}}：" +
                                    action_data.totalString +
                                    "，{{当前赋值响应等号左侧为“模板变量”类型}}，{{右侧为“普通变量”类型}}，{{无法赋值}}，{{请检查}}！",
                                    "",
                                    object_id
                                )
                            );
                            successful = false;
                        } else if (assignment.leftType === AssignType.Variable) {
                            if (
                                VE_AssignmentTypeJudge.allow(assignment.leftVariable!, rightVar)
                            ) {
                                assignment.setRightVariable(rightVar);
                            } else {
                                VE_ErrorManager.Add(
                                    VE_Error.error(
                                        "",
                                        "{{对象}}：" +
                                        object_id +
                                        "，{{状态}}：" +
                                        fsm_id +
                                        "，{{赋值响应}}：" +
                                        action_data.totalString +
                                        "，{{当前赋值响应等号左侧和右侧类型不匹配}}，{{无法赋值}}，{{请检查}}！",
                                        "",
                                        object_id
                                    )
                                );
                                successful = false;
                            }
                        } else {
                            // 模板变量，不确定类型
                            assignment.setRightVariable(rightVar);
                        }
                    } else if (rightClone !== null && rightClone !== undefined) {
                        if (assignment.leftType === AssignType.Template) {
                            assignment.setRightClone(rightClone);
                        } else {
                            VE_ErrorManager.Add(
                                VE_Error.error(
                                    "",
                                    "{{对象}}：" +
                                    object_id +
                                    "，{{状态}}：" +
                                    fsm_id +
                                    "，{{赋值响应}}：" +
                                    action_data.totalString +
                                    "，{{当前赋值响应等号左侧为“模板变量”}}，{{右侧为“普通变量”}}，{{无法赋值}}，{{请检查}}！",
                                    "",
                                    object_id
                                )
                            );
                            successful = false;
                        }
                    } else {
                        VE_ErrorManager.Add(
                            VE_Error.error(
                                "",
                                "{{对象}}：" +
                                object_id +
                                "，{{状态}}：" +
                                fsm_id +
                                "，{{赋值响应}}：" +
                                action_data.totalString +
                                "，{{当前赋值响应等号右侧数据无法识别}}，{{请检查}}！",
                                "",
                                object_id
                            )
                        );
                        successful = false;
                    }
                }
            } // 常量
            else {
                if (assignment.leftType === AssignType.Template) {
                    if (varID.trim().toLowerCase() === "null") {
                        assignment.setRightNull();
                    } else {
                        VE_ErrorManager.Add(
                            VE_Error.error(
                                "",
                                "{{对象}}：" +
                                object_id +
                                "，{{状态}}：" +
                                fsm_id +
                                "，{{赋值响应}}：" +
                                action_data.totalString +
                                "，{{当前赋值响应等号左侧为模板变量}}，{{右侧赋值为常量时只能填“null”}}，{{表示销毁模板变量}}，{{当前格式错误}}，{{请检查}}！",
                                "",
                                object_id
                            )
                        );
                        successful = false;
                    }
                } else if (assignment.leftType === AssignType.TemplateVariable) {
                    assignment.setRightConst(varID);
                } else {
                    if (assignment.leftVariable !== null && assignment.leftVariable !== undefined) {
                        const errorInfo: ErrorInfo = new ErrorInfo();
                        const newValue: any = assignment.leftVariable.initValue(
                            varID,
                            errorInfo
                        );
                        if (!errorInfo.isRight || newValue === null || newValue === undefined) {
                            //DO_20221228:表格编辑器,自动检测,中英文
                            VE_ErrorManager.Add(
                                VE_Error.error(
                                    "",
                                    "{{对象}}：" +
                                    object_id +
                                    "，{{状态}}：" +
                                    fsm_id +
                                    "，{{赋值响应}}：" +
                                    action_data.totalString +
                                    "，{{当前赋值响应等号左侧变量类型与右侧常量值不匹配}}，{{错误信息}}：" +
                                    errorInfo.message +
                                    "，{{请检查}}！",
                                    "",
                                    object_id
                                )
                            );
                            successful = false;
                        } else {
                            assignment.setRightConstValue(newValue);
                        }
                    } else {
                        VE_ErrorManager.Add(
                            VE_Error.error(
                                "",
                                "{{对象}}：" +
                                object_id +
                                "，{{状态}}：" +
                                fsm_id +
                                "，{{赋值响应}}：" +
                                action_data.totalString +
                                "，{{当前赋值响应等号左侧变量获取为空}}，{{请检查}}！",
                                "",
                                object_id
                            )
                        );
                        successful = false;
                    }
                }
            }
        }

        const stateAction: VE_StateAction = new VE_StateAction();
        stateAction.setAssignment(assignment);
        state.addAction(stateAction);

        return successful;
    }




}