import { VarTools, IVeryVar, VeryExpression } from "../variables";
import { ErrorInfo } from "../utility";
// import { VE_Manager } from "../manager";
// import { VE_Reset } from "../manager";

// DO_5代ui绑定逻辑
// DO_20221228:表格编辑器,自动检测
import { VeryEngine } from "../veryEngine";
import { StateConst } from "../state";
import { VEObject, VEObjects } from "../object";

export class UIManager {

    //{项目:{UI全名变量:控制脚本}}
    // private static _update: { [key: string]: { ied: VREdit.GUI, attr: string, value: IVeryVar, old: any }[] } = {};
    private static _update: { [key: string]: { ied: VREdit.GUI, attr: string, value: IVeryVar, old: any } } = {};

    constructor() {
        //清空关联
        // VE_Reset.addClear(UIManager.Clear);
        // VE_Reset.addProjectClear(UIManager.ClearProject);
    }


    //清空所有
    public static Clear(): void {

        for (let key in UIManager._update) {
            if (UIManager._update[key].ied && UIManager._update[key].ied.unwatch) {
                UIManager._update[key].ied.unwatch('group id');
            }
        }
        UIManager._update = {};
    }

    //清空项目
    public static ClearProject(project_name: string): void {
        // this._update[project_name] = [];
    }

    //初始化
    public static init(): void {
        //DO_20221228:表格编辑器,自动检测
        if (!VeryEngine.enableLuckySheet) {
            //遍历场景UI
            for (let key in VREdit.shareBox.id2Entity) {
                let entity = VREdit.shareBox.id2Entity[key];
                if (entity instanceof VREdit.IEDGUI) {
                    // console.log(`entity.name: ${entity.name}, entity.id: ${entity.id} `);
                    // console.error(entity.veryVar);
                    if (entity && entity.veryVar.length != 0) {
                        if (!UIManager._update[entity.id]) {
                            for (let tmp of entity.veryVar) {
                                const varArray: string[] = tmp.valName.split(StateConst.STATE_SEPARATOR);

                                if (varArray.length !== 2) {
                                    console.error(`GUI变量关联错误，GUI名：${entity.name}，变量ID：${tmp.valName}，当前变量格式应为“对象名.*变量”，当前变量ID不符合，请检查！`);
                                    continue;
                                }

                                for (let i: number = 0; i < varArray.length; i++) {
                                    varArray[i] = varArray[i].trim();
                                }

                                if (!varArray[1].startsWith(StateConst.VARIABLE_SYMBOL)) {
                                    console.error(`GUI变量关联错误，GUI名：${entity.name}，变量ID：${tmp.valName}，当前变量格式应为“对象名.*变量”，当前变量ID不符合，请检查！`);
                                    continue;
                                }

                                // 不支持对象变量的引用，只支持“对象名.*变量名”
                                let guiVar = UIManager.getGUIVar(entity, varArray[0], varArray[1].substring(1));
                                if (!guiVar) {
                                    const errorInfo: ErrorInfo = new ErrorInfo();
                                    guiVar = VarTools.GetVeryVarWithExpression('', tmp.valName, errorInfo, '');
                                }

                                // console.error(entity);
                                // console.error(entity.veryVar);
                                // let veryVar = VarTools.GetVeryVarWithExpression('', tmp.valName, errorInfo, '');
                                if (guiVar) {
                                    let text = guiVar.getValue();
                                    entity.set(tmp.attr, text);
                                    if (entity.subtype == "input") {
                                        entity.watch(tmp.attr, (val) => {
                                            if (guiVar) {
                                                if (guiVar.varType == "number")
                                                    val = +val;
                                                if (val != guiVar.getValue())
                                                    guiVar.setValue(val);
                                            }
                                        }, 'group id');
                                    }
                                    UIManager._update[entity.id] = { ied: entity, attr: tmp.attr, value: guiVar, old: text };
                                    // this._update[project_name].push({ ied: entity, attr: tmp.attr, value: guiVar, old: text })
                                }
                            }
                        } 
                        // else {
                        //     console.warn(`相同了`);
                        //     console.warn(entity);
                        //     console.warn(entity.veryVar);
                        // }
                    }
                }
            }
        }
    }

    public static Update(): void {
        for (let key in UIManager._update) {
            if (UIManager._update[key] && UIManager._update[key].ied && UIManager._update[key].value) {
                if (UIManager._update[key].value.getValue() !== UIManager._update[key].old) {
                    UIManager._update[key].old = UIManager._update[key].value.getValue();
                    UIManager._update[key].ied.set(UIManager._update[key].attr, UIManager._update[key].old);
                }
            }
        }
    }

    private static _canvasToObjects: Map<string, string[]> = new Map<string, string[]>();
    private static _objectToCanvas: Map<string, string> = new Map<string, string>();

    public static addGUIObject(entity: VREdit.IEDEntity): void {
        if (entity && entity.type.toLowerCase() === 'gui') {
            const nodeID = entity.id;
            const root = UIManager.getRootCanvas(<any>entity);
            if (root) {
                const canvasID = root.id;
                if (!UIManager._canvasToObjects.has(canvasID)) {
                    UIManager._canvasToObjects.set(canvasID, []);
                }
                const idx = UIManager._canvasToObjects.get(canvasID).indexOf(nodeID);
                if (idx < 0) {
                    UIManager._canvasToObjects.get(canvasID).push(nodeID);
                }

                UIManager._objectToCanvas.set(nodeID, canvasID);
            }
        }
    }

    public static removeGUIObject(entity: VREdit.IEDEntity): void {
        if (entity && entity.type.toLowerCase() === 'gui') {
            const nodeID = entity.id;
            const root = UIManager.getRootCanvas(<any>entity);
            if (root) {
                const canvasID = root.id;
                if (UIManager._canvasToObjects.has(canvasID)) {
                    const idx = UIManager._canvasToObjects.get(canvasID).indexOf(nodeID);
                    if (idx > -1) {
                        UIManager._canvasToObjects.get(canvasID).splice(idx, 1);
                    }
                }

                UIManager._objectToCanvas.delete(nodeID);
            }
        }
    }

    private static getRootCanvas(entity: VREdit.GUI, fullname_data?: { name: string; }): Nullable<VREdit.GUI> {
        if (fullname_data) {
            if (fullname_data.name) {
                fullname_data.name = entity.name + StateConst.STATE_SEPARATOR + fullname_data.name;
            } else {
                fullname_data.name = entity.name
            }
        }
        if (entity.subtype.toLowerCase().match('canvas')) {
            return entity;
        } else {
            if (entity.parent && entity.parent.type.toLowerCase() === 'gui') {
                return UIManager.getRootCanvas(<VREdit.GUI>entity.parent, fullname_data);
            } else {
                return null;
            }
        }
    }


    private static getGUIVar(entity: VREdit.IEDGUI, node_name: string, var_id: string): Nullable<IVeryVar> {
        // 由当前GUI元素开始往上找，若id有对应object，则进行判断
        // console.warn(entity);
        // console.log(`entity.name: ${entity.name}, node_name: ${node_name}, var_id: ${var_id}`);
        const parentVar = UIManager.getVarFromParent(entity, node_name, var_id, entity.name);
        if (parentVar) {
            // console.warn(parentVar);
            return parentVar;
        }

        // 通过当前parent canvas所包含的object开始查找
        const fullnameData = { name: '' };
        const root = UIManager.getRootCanvas(entity, fullnameData);
        if (root) {
            if (UIManager._canvasToObjects.has(root.id)) {
                const nodeIDs = UIManager._canvasToObjects.get(root.id);
                // 倒序

                for (let node_id of nodeIDs) {
                    let object = VEObjects.getByNodeId(node_id);
                    if (object) {
                        const tempVar = UIManager.getSubVar(object, node_name, var_id, entity.name);
                        if (tempVar) {
                            return tempVar;
                        }
                    }
                }
            }
        }

        return null;
    }

    private static getVarFromParent(entity: VREdit.GUI, node_name: string, var_id: string, ori_entity_name: string): Nullable<IVeryVar> {
        if (entity) {
            if (UIManager._objectToCanvas.has(entity.id)) {
                const object = VEObjects.getByNodeId(entity.id);
                if (object) {
                    const tempVar = UIManager.getSubVar(object, node_name, var_id, ori_entity_name);
                    if (tempVar) {
                        return tempVar;
                    }
                }
            }
            if (entity.parent && entity.parent.type.toLowerCase() === 'gui') {
                return UIManager.getVarFromParent(<VREdit.GUI>entity.parent, node_name, var_id, ori_entity_name);
            }
        }

        return null;
    }


    private static getSubVar(object: VEObject, node_name: string, var_id: string, ori_entity_name: string): Nullable<IVeryVar> {
        if (object) {
            if (object.NodeName === node_name) {
                if (object.isCreatedVariable(var_id)) {
                    return object.getVariable(var_id);
                }
                else if (object.isCreatedFsm(var_id)) {
                    return object.getFsm(var_id).fsmVar;
                }
                else if (object.isCreatedExpression(var_id)) {
                    return new VeryExpression(object.getExpression(var_id));
                }
                else if (object.isCreatedClone(var_id)) {
                    console.error(`GUI变量关联错误，GUI名：${ori_entity_name}，变量ID：${node_name}.*${var_id} ，GUI关联变量不能引用对象变量，请检查！`);
                    return null;
                }
            }
        }
        return null;
    }


}

