export class Action_AudioPlay extends VE_ActionBehaviour {

    public get ID(): string {
        return 'AudioPlay|声音播放';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '声音播放，*播放控制，1613833951-6e940bca，true';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=742';
    }
    public get className(): string {
        return 'Action_AudioPlay';
    }

    // 是否开启
    private _switchControl: VeryString = new VeryString();
    // 播放音乐
    private _musicString: VeryString = new VeryString();
    // 音乐循环
    private _musicLoop: VeryBool = new VeryBool();
    // 音乐大小
    private _musicVolume: VeryNumber = new VeryNumber();
    private _url: string = '';

    // 声音
    private _music: BABYLON.Nullable<BABYLON.Sound> = null;

    // 声音记录
    private _source: Nullable<AudioBufferSourceNode> = null;
    public static _soundSource: Nullable<AudioBufferSourceNode>;
    private _started: boolean = false;

    //DO_20220527:声音播放,支持音频ID为变量
    public static _audioURLDic: { [key: string]: string } = {};

    public active(): void {

        //DO_20220527:声音播放,支持音频ID为变量
        if (Action_AudioPlay._audioURLDic[this._musicString.value] === undefined) {
            setTimeout(this.AddNewAudio.bind(this), 0);
            return;
        }
        else {
            //先关闭当前播放声音
            if (this._music !== null) {
                this._music.dispose();
            }
            this._music = new BABYLON.Sound('AudioPlayAction', Action_AudioPlay._audioURLDic[this._musicString.value], this.scene, null, {
                loop: this._musicLoop.value,
                autoplay: (this._switchControl.value === '播放' || this._switchControl.value.toLowerCase() === 'play') ? true : false
            });
        }
        if (this._music !== null) {
            this._music.loop = this._musicLoop.value;
            this._music.setVolume(this._musicVolume.value);
            if (this._switchControl.value === '播放' || this._switchControl.value.toLowerCase() === 'play') {
                if (!this._music.isPlaying) {
                    this._music.play();
                    // console.log('播放');
                }
                // console.warn(this._music.isPlaying);
                // if (!this._started) {
                //     this._source.start();
                //     this._started = true;
                // }
                // Action_AudioPlay._soundSource = this._source;
            } else if (this._switchControl.value === '暂停' || this._switchControl.value.toLowerCase() === 'pause') {
                if (this._music.isPlaying) {
                    this._music.pause();
                    // console.log('暂停');
                }
                // Action_AudioPlay._soundSource = null;
            }
            else if (this._switchControl.value === '停止' || this._switchControl.value.toLowerCase() === 'stop') {
                this._music.stop();
                // console.log('停止');
                // Action_AudioPlay._soundSource = null;
            }
        }

    }

    //DO_20220527:声音播放,支持音频ID为变量
    private async AddNewAudio() {
        let self = this;
        self._url = await BabylonLoader.getAssetUrl(self._musicString.value);
        if (self._url === '') {
            console.error('声音播放响应 初始化失败，asset_id：' + self._musicString.value + '，无法在当前场景中查找到该ID，请检查！');
        }
        else {
            Action_AudioPlay._audioURLDic[self._musicString.value] = self._url;

            //先关闭当前播放声音
            if (self._music !== null) {
                self._music.dispose();
            }
            self._music = new BABYLON.Sound('AudioPlayAction', self._url, this.scene, null, {
                loop: self._musicLoop.value,
                autoplay: (self._switchControl.value === '播放' || self._switchControl.value.toLowerCase() === 'play') ? true : false
            });
            self._music.loop = self._musicLoop.value;
            self._music.setVolume(self._musicVolume.value);
            if (self._switchControl.value === '播放' || self._switchControl.value.toLowerCase() === 'play') {
                if (!self._music.isPlaying) {
                    self._music.play();
                    // console.log('播放');
                }
            } else if (self._switchControl.value === '暂停' || self._switchControl.value.toLowerCase() === 'pause') {
                if (self._music.isPlaying) {
                    self._music.pause();
                    // console.log('暂停');
                }
            }
            else if (self._switchControl.value === '停止' || self._switchControl.value.toLowerCase() === 'stop') {
                self._music.stop();
                // console.log('停止');
            }
        }
    }

    //DO_20220527:声音播放,支持音频ID为变量
    private async initAudio() {
        let self = this;
        self._url = await BabylonLoader.getAssetUrl(self._musicString.value);
        if (self._url === '') {
            console.error('声音播放响应 初始化失败，asset_id：' + self._musicString.value + '，无法在当前场景中查找到该ID，请检查！');
        }
        else {
            Action_AudioPlay._audioURLDic[self._musicString.value] = self._url;
        }
    }

    private getBuffer(url: string) {
        const request = new XMLHttpRequest();
        return new Promise((resolve, reject) => {
            request.open('GET', url, true);
            request.responseType = 'arraybuffer';
            request.onload = () => {
                BABYLON.Engine.audioEngine.audioContext.decodeAudioData(request.response, buffer => buffer ? resolve(buffer) : reject('decoding error'));
            };
            request.onerror = error => reject(error);
            request.send();
        });
    };

    public onUpdate(): void {

    }


    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 2, 3, 4)) {
            return false;
        } else {
            // 第1个参数：
            let para0: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para0, para_array[0])) {
                return false;
            }
            this._switchControl = para0.string;

            //参数2
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringPara(this.objectID, this.ID, ParaType.Action, para1, para_array[1])) {
                return false;
            }
            this._musicString = para1.string;
            setTimeout(this.initAudio.bind(this), 0);
            //console.log("_musicString--" + this._musicString.value);

            //参数3
            this._musicLoop.value = true;
            if (para_array.length > 2) {
                let para2: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[2])) {
                    return false;
                }
                this._musicLoop = para2.bool;
            }

            //参数4
            this._musicVolume.value = 1;
            if (para_array.length > 3) {
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para3, para_array[3])) {
                    return false;
                }
                this._musicVolume = para3.number;
            }

            return true;
        }

    }
    public destroy(): void {

    }
}

export class Action_WindowsVoice extends VE_ActionBehaviour {

    public get ID(): string {
        return 'WindowsVoice|语音';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '语音，今天天气真不错';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=741';
    }
    public get className(): string {
        return 'Action_WindowsVoice';
    }

    //播放文本
    private _musicString: VeryString = new VeryString();
    //DO_20221021:语音添加音量参数
    private _musicVolume: VeryNumber = new VeryNumber();

    //DO_20211027:语音改成动画类型
    public get type(): ActionType {
        return ActionType.Animation;
    }
    private _switch: boolean = false;
    public pause(): void {
        this._switch = false;
        window.speechSynthesis.pause();
        super.pause();
    }
    public resume(): void {
        this._switch = true;
        window.speechSynthesis.resume();
        super.resume();
    }
    public stop(): void {
        window.speechSynthesis.cancel();
        this.timesUp();
        super.stop();
    }
    private timesUp(): void {
        this._switch = false;
        this.finish();
    }

    public active(): void {
        // 默认设置每帧运行
        if (!this.everyFrame) {
            this.setEveryFrame(true);
        }

        //TODO_20210624:先清空队列中所有播放的语音
        window.speechSynthesis.cancel();
        var utterThis = new window.SpeechSynthesisUtterance(this._musicString.value);
        //DO_20221021:语音添加音量参数
        utterThis.volume = this._musicVolume.value;
        for (var i = 0; i < window.speechSynthesis.getVoices().length; i++) {
            if (window.speechSynthesis.getVoices()[i].localService === true && window.speechSynthesis.getVoices()[i].lang === "zh-CN") {
                //console.log(window.speechSynthesis.getVoices()[i]);
                utterThis.voice = window.speechSynthesis.getVoices()[i];
                break;
            }
        }
        window.speechSynthesis.speak(utterThis);
        //console.log(window.speechSynthesis.getVoices());
        //DO_20211027:语音改成动画类型
        this._switch = true;
    }

    public onUpdate(): void {
        if (this.type === ActionType.Animation) {
            //DO_20211027:语音改成动画类型
            if (!window.speechSynthesis.speaking && this._switch) {
                this.timesUp();
            }
        }
    }


    public paraParser(para_array: string[]): boolean {
        //DO_20221021:语音添加音量参数
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 1, 2)) {
            return false;
        } else {
            //参数1
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._musicString = para1.string;

            //DO_20221021:语音添加音量参数
            this._musicVolume.value = 1;
            if (para_array.length > 1) {
                //参数2
                let para2: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, para_array[1])) {
                    return false;
                }
                this._musicVolume = para2.number;
            }

            return true;
        }


    }
    public destroy(): void {

    }
}

export class Action_BaiduVoice extends VE_ActionBehaviour {

    public get ID(): string {
        return 'BaiduVoice|百度语音';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '百度语音，今天天气真不错';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=822';
    }
    public get className(): string {
        return 'Action_BaiduVoice';
    }

    //播放文本
    private _musicString: VeryString = new VeryString();

    //TODO_20210624:先停止正在播放的声音
    private static _source: BABYLON.Nullable<HTMLSourceElement> = null;

    //DO_20220301:百度语音更新调用方式,存储token
    private static _token: string = '';

    //DO_20220329:百度语音改成动画类型
    public get type(): ActionType {
        return ActionType.Animation;
    }
    private _switch: boolean = false;
    public pause(): void {
        this._switch = false;
        (<HTMLAudioElement>Action_BaiduVoice._source.parentNode).pause();
        super.pause();
    }
    public resume(): void {
        this._switch = true;
        (<HTMLAudioElement>Action_BaiduVoice._source.parentNode).play();
        super.resume();
    }
    public stop(): void {
        this.timesUp();
        (<HTMLAudioElement>Action_BaiduVoice._source.parentNode).pause();
        super.stop();
    }
    private timesUp(): void {
        this._switch = false;
        this.finish();
    }

    public active(): void {
        // 默认设置每帧运行
        if (!this.everyFrame) {
            this.setEveryFrame(true);
        }

        //DO_20220301:百度语音更新调用方式,调用方式修改
        //TODO_20210624:先停止正在播放的声音
        //var url = "http://tts.baidu.com/text2audio/text2audio?lan=zh&ie=UTF-8&spd=8&text=";
        var url = "https://tsn.baidu.com/text2audio?lan=zh&ctp=1&cuid=abcdxxx&tok=" + Action_BaiduVoice._token + "&vol=9&per=0&spd=5&pit=5&aue=3&tex=";
        if (Action_BaiduVoice._source === null) {
            try {
                //添加audio标签
                var f = document.createDocumentFragment();
                var audio = document.createElement("audio");
                audio.controls = true;
                audio.autoplay = true;

                var source = document.createElement("source");
                source.id = "tts_source";
                source.type = "audio/mpeg";
                source.src = url;
                audio.appendChild(source);
                f.appendChild(audio);
                document.body.appendChild(f);

                //播放
                source.src = url + this._musicString.value;
                if (source.parentNode != null) {
                    (<HTMLAudioElement>source.parentNode).load();
                }
                //记录
                Action_BaiduVoice._source = source;
            }
            catch (error) {
                console.error(error);
            }

        }
        else {
            //先暂停
            (<HTMLAudioElement>Action_BaiduVoice._source.parentNode).pause();
            //播放
            Action_BaiduVoice._source.src = url + this._musicString.value;
            if (Action_BaiduVoice._source.parentNode != null) {
                (<HTMLAudioElement>Action_BaiduVoice._source.parentNode).load();
            }
        }
        //DO_20220329:百度语音改成动画类型
        this._switch = true;
    }

    public onUpdate(): void {
        if (this.type === ActionType.Animation) {
            //DO_20220329:百度语音改成动画类型
            if ((<HTMLAudioElement>Action_BaiduVoice._source.parentNode).ended && this._switch) {
                this.timesUp();
            }
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Trigger, para_array.length, 1)) {
            return false;
        } else {
            //参数1
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.StringParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, para_array[0])) {
                return false;
            }
            this._musicString = para1.string;

            //DO_20220301:百度语音更新调用方式,向服务器请求token
            if (Action_BaiduVoice._token === '') {
                var url = 'https://bigdata.veryengine.cn/baidubce';
                axios.get(url).then(response => {
                    let message: any = response.data;
                    //console.log(message);
                    if (message['data']['token'] !== undefined) {
                        Action_BaiduVoice._token = message['data']['token'];
                        // console.log('Action_BaiduVoice._token--' + Action_BaiduVoice._token);
                    }
                }).catch(error => {
                    //DO_20221228:表格编辑器,自动检测,中英文
                    VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}} {{百度语音获取Token失败}},{{请联系平台开发者}}", '', Severity.Error));
                    return false;
                })
            }

            return true;
        }

    }
    public destroy(): void {

    }
}

