export class Action_Add_Step extends VE_ActionBehaviour {

    private paraArray: string[];

    public get ID(): string {
        return "Add_Step|添加成绩";
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '添加成绩，1，第一步，30，50，10，2';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=860';
    }
    public get className(): string {
        return 'Action_Add_Step';
    }

    public paraParser(para_array: string[]): boolean {
        if (para_array.length == 0) {
            console.error(this.ID + " 响应 至少需要" + 2 + "个传入参数，请检查！");
            return false;
        }
        this.paraArray = para_array;
        return true;
    }

    public active(): void {
        if (!ossfile.xuebei.IsSuccess) {
            return;
        }
        if (!XueBeiNet.upload.result.count(this.paraArray.length)) {
            let err = this.ID + "响应，和学呗定义列数不一致，当前行的值为：";
            for (let i = 0; i < this.paraArray.length; i++) {
                err = err + this.paraArray[i];
                if (i != this.paraArray.length - 1)
                    err = err + ",";
            }
            console.error(err);
            return;
        }
        let obj = new Array<any>();
        for (let i = 0; i < this.paraArray.length; i++) {
            if (XueBeiNet.upload.result.getType(i) == "string") {
                let para1: VeryParas = new VeryParas();
                if (!ParaParserUtility.StringPara(this.objectID, this.ID, ParaType.Action, para1, this.paraArray[i])) {
                    return;
                }
                obj.push(para1.string.getValue());
            }
            else if (XueBeiNet.upload.result.getType(i) == "number") {
                let para2: VeryParas = new VeryParas();
                if (!ParaParserUtility.NumberPara(this.objectID, this.ID, ParaType.Action, para2, this.paraArray[i])) {
                    return;
                }
                obj.push(para2.number.getValue());
            }

            else if (XueBeiNet.upload.result.getType(i) == "bool") {
                let para3: VeryParas = new VeryParas();
                if (!ParaParserUtility.BoolPara(this.objectID, this.ID, ParaType.Action, para3, this.paraArray[i])) {
                    return;
                }
                obj.push(para3.bool.getValue());
            }
        }
        XueBeiNet.upload.Add(obj);
    }

    public destroy(): void {

    }
}

