export class XueBeiNet {

    // public static Score = 0;

    // public static START_TIME: number = 0;
    // public static END_TIME: number = 0;
    public static upload: uploadClass;
    private static GetJsonHeader(headers, json: string) {
        let timeStamp = new Date().getTime();
        json = json + "&accessKey=" + ossfile.xuebei.accessKey + "&timestamp=" + timeStamp;
        let signatureArray = CryptoJS.HmacSHA256(json, ossfile.xuebei.accessSecret);
        let signature = CryptoJS.enc.Base64.stringify(signatureArray);

        headers["accessKey"] = ossfile.xuebei.accessKey;
        headers["timestamp"] = timeStamp;
        headers["signature"] = signature;
    }

    private static GetFormHeader(headers, param: string[]) {
        for (let i = 0; i < param.length; i++) {
            let tmp = param[i].split('=');
            param[i] = tmp[0] + "=" + decodeURIComponent(tmp[1]);
        }

        let timeStamp = new Date().getTime();
        param.push("timestamp=" + timeStamp);
        param.push("accessKey=" + ossfile.xuebei.accessKey);
        param.sort();
        let signature = param[0];
        for (let i = 1; i < param.length; i++) {
            signature += ("&" + param[i]);
        }
        signature = CryptoJS.enc.Base64.stringify(CryptoJS.HmacSHA256(signature, ossfile.xuebei.accessSecret));
        headers["accessKey"] = ossfile.xuebei.accessKey;
        headers["timestamp"] = timeStamp.toString();
        headers["signature"] = signature;
    }

    public static FormGet(url: string, content: string, act_bool: (bool: boolean) => void) {
        if (content != null)
            url = url + "?" + content;
        axios.defaults.withCredentials = true;
        let headers = {};
        XueBeiNet.GetFormHeader(headers, content.split('&'));
        axios.get(url, { headers: headers }).then(response => {
            let back = response.data;
            if (back.success) {
                act_bool(true);
            }
            else {
                console.error(back.errorMsg);
                act_bool(false);
            }
        })
            .catch(error => {
                console.error(error);
                act_bool(false);
            })

    }

    public static JsonPost(url: string, jsonParam: string, act_bool: (bool: boolean) => void) {
        axios.defaults.withCredentials = true;
        let headers = { 'Content-Type': 'application/json' };
        XueBeiNet.GetJsonHeader(headers, jsonParam);
        axios.post(url, jsonParam, { headers: headers })
            .then(function (response) {
                let back = response.data;
                if (back.success) {
                    act_bool(true);
                }
                else {
                    console.error(back.errorMsg);
                    act_bool(false);
                }
            })
            .catch(function (error) {
                console.error(error);
                act_bool(false);
            });
    }

    public static GetQuestion(url: string, content: string, cont: VeryList, optionList: VeryList, answer: VeryList, testType: VeryList, points: VeryList, act_bool: (bool: boolean) => void) {
        if (content != null)
            url = url + "?" + content;
        axios.defaults.withCredentials = true;
        let headers = {};
        XueBeiNet.GetFormHeader(headers, content.split('&'));
        axios.get(url, { headers: headers }).then(response => {
            let message: BackQuestion = response.data;
            // console.log(message);
            if (message.success) {
                cont.Clear(); optionList.Clear(); answer.Clear(); testType.Clear(); points.Clear();
                for (let i = 0; i < message.questions.length; i++) {
                    let tmpCont = new VeryString();
                    tmpCont.setValue(message.questions[i].content.replace("<p>", "").replace("</p>", ""));
                    cont.Add(tmpCont);
                    let tmpList = new VeryList();
                    if (message.questions[i].optionList != null) {
                        for (let j = 0; j < message.questions[i].optionList.length; j++) {
                            let tmpContent = new VeryString();
                            tmpContent.setValue(message.questions[i].optionList[j].content.replace("<p>", "").replace("</p>", ""))
                            tmpList.Add(tmpContent);
                        }
                    }
                    optionList.Add(tmpList);
                    let tmpAnswer = new VeryString();
                    tmpAnswer.setValue(message.questions[i].answer);
                    answer.Add(tmpAnswer);
                    let tmpType = new VeryString();
                    tmpType.setValue(message.questions[i].testType);
                    testType.Add(tmpType);
                    let tmpPoint = new VeryNumber();
                    tmpPoint.setValue(message.questions[i].points);
                    points.Add(tmpPoint);
                }
                act_bool(true);
            }
            else {
                console.error(message.errorMsg);
                act_bool(false);
            }
        })
            .catch(error => {
                console.error(error);
                act_bool(false);
            })

    }

    private static GetPoint(key: KeyPoints, nodeId: VeryList, nodeName: VeryList, levels: VeryList, current_level: number) {
        let tmpNode = new VeryNumber();
        tmpNode.setValue(key.nodeId);
        nodeId.Add(tmpNode);
        let tmpNodeName = new VeryString();
        tmpNodeName.setValue(key.nodeName);
        nodeName.Add(tmpNodeName);
        if (levels != null) {
            let tmpLevel = new VeryNumber();
            tmpLevel.setValue(current_level);
            levels.Add(tmpLevel);
        }
        if (key.childNodes != null && key.childNodes.length != 0) {
            current_level++;
            for (let i = 0; i < key.childNodes.length; i++) {
                XueBeiNet.GetPoint(key.childNodes[i], nodeId, nodeName, levels, current_level);
            }
        }
    }

    public static GetKeyPoints(url: string, content: string, nodeId: VeryList, nodeName: VeryList, levels: VeryList, act_bool: (bool: boolean) => void) {
        if (content != null)
            url = url + "?" + content;
        axios.defaults.withCredentials = true;
        let headers = {};
        XueBeiNet.GetFormHeader(headers, content.split('&'));
        axios.get(url, { headers: headers }).then(response => {
            let message: BackKeyPoints = response.data;
            if (message.success) {
                nodeId.Clear(); nodeName.Clear();
                if (levels != null)
                    levels.Clear();
                for (let i = 0; i < message.keyPoints.length; i++) {
                    XueBeiNet.GetPoint(message.keyPoints[i], nodeId, nodeName, levels, 0);
                }
                act_bool(true);
            }
            else {
                console.error(message.errorMsg);
                act_bool(false);
            }
        })
            .catch(error => {
                console.error(error);
                act_bool(false);
            })
    }

}
