export class Action_SetRandomPosition extends VE_ActionBehaviour {

    public get ID(): string {
        return 'Set_Random_Position|设置随机位置';
    }

    //DO_20221228:表格编辑器,自动填充
    public get Example(): string {
        return '设置随机位置，立方体，world，(2，*number变量)，(-3.4，5.7)，old';
    }
    //DO_20221228:表格编辑器,触发响应说明文档链接
    public get Document(): string {
        return 'https://showdoc.cool360.com/web/#/12?page_id=538';
    }
    public get className(): string {
        return 'Action_SetRandomPosition';
    }

    private _obj: VeryGameObject = new VeryGameObject();
    private _space: BABYLON.Space = BABYLON.Space.LOCAL;
    private _xRange = new VE_RandomRange();
    private _yRange = new VE_RandomRange();
    private _zRange = new VE_RandomRange();

    private _axisChoose: boolean[] = [false, false, false];
    private _xyzRange: VE_RandomRange[] = [];

    private _posVector3Value: BABYLON.Vector3 = new BABYLON.Vector3();

    public active(): void {
    }

    public onUpdate(): void {
        if (this._obj.value != null) {
            if (this._space == BABYLON.Space.LOCAL) {
                if (this._axisChoose[0]) {
                    this._posVector3Value.x = this._xRange.GetValue();
                }
                else {
                    this._posVector3Value.x = this._obj.value.transform.localPosition.x;
                }
                if (this._axisChoose[1]) {
                    this._posVector3Value.y = this._yRange.GetValue();
                }
                else {
                    this._posVector3Value.y = this._obj.value.transform.localPosition.y;
                }
                if (this._axisChoose[2]) {
                    this._posVector3Value.z = this._zRange.GetValue();
                }
                else {
                    this._posVector3Value.z = this._obj.value.transform.localPosition.z;
                }
                this._obj.value.transform.localPosition = this._posVector3Value;
            }
            else {
                if (this._axisChoose[0]) {
                    this._posVector3Value.x = this._xRange.GetValue();
                }
                else {
                    this._posVector3Value.x = this._obj.value.transform.position.x;
                }
                if (this._axisChoose[1]) {
                    this._posVector3Value.y = this._yRange.GetValue();
                }
                else {
                    this._posVector3Value.y = this._obj.value.transform.position.y;
                }
                if (this._axisChoose[2]) {
                    this._posVector3Value.z = this._zRange.GetValue();
                }
                else {
                    this._posVector3Value.z = this._obj.value.transform.position.z;
                }
                this._obj.value.transform.position = this._posVector3Value;
            }
        }
    }

    public paraParser(para_array: string[]): boolean {
        if (!ParaParserUtility.ParaNumbers(this.ID, ParaType.Action, para_array.length, 5)) {
            return false;
        } else {
            // 参数1：
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.GameObjectPara(this.objectID, this.ID, ParaType.Action, para1, para_array[0], this.nodeID)) {
                return false;
            }
            this._obj = para1.gameObject;

            // 参数2：
            if (para_array[1].toLowerCase() == "self" || para_array[1] == "自身") {
                this._space = BABYLON.Space.LOCAL;
            }
            else if (para_array[1].toLowerCase() == "world" || para_array[1] == "世界") {
                this._space = BABYLON.Space.WORLD;
            }
            else {
                //DO_20230613:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}}，{{错误原因}}：" + "{{应填}}" + "world|世界" + "{{或者}}" + "self|自身", '', Severity.Error));
                return false;
            }

            //X轴随机参数设置
            if (!this.AxisParaParser(para_array[2], 0)) {
                return false;
            }
            //Y轴随机参数设置
            if (!this.AxisParaParser(para_array[3], 1)) {
                return false;
            }
            //Y轴随机参数设置
            if (!this.AxisParaParser(para_array[4], 2)) {
                return false;
            }

            return true;
        }
    }
    private AxisParaParser(para: string, index: number,) {
        if (para.toLowerCase() == "old") {
            this._axisChoose[index] = false;
        }
        else {
            this._axisChoose[index] = true;
            var rangeArray = para.split(/,|，/);
            if (rangeArray.length != 2) {
                //DO_20230613:表格编辑器,自动检测,中英文
                VE_ErrorManager.Add(new VE_Error('', this.ID + " {{响应}}，{{错误原因}}：" + "{{应填}}" + "old" + "{{或者}}" + "(number,number)", '', Severity.Error));
                //console.error(this.ID + " 响应参数格式错误，轴参数应为old或者（float1，float2）格式，当前为：" + para + "，请检查！");
                return false;
            }
            //第一个参数
            let para1: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para1, rangeArray[0].trim())) {
                return false;
            }
            var very_range = new VE_RandomRange();
            very_range.AddFirstVar(para1.number);

            //第二个参数
            let para2: VeryParas = new VeryParas();
            if (!ParaParserUtility.NumberParaWithExpression(this.objectID, this.ID, ParaType.Action, para2, rangeArray[1].trim())) {
                return false;
            }
            very_range.AddSecondVar(para2.number);
            this._xyzRange[index] = very_range;
            if (index == 0) {
                this._xRange = very_range;
            }
            if (index == 1) {
                this._yRange = very_range;
            }
            if (index == 2) {
                this._zRange = very_range;
            }
        }
        return true;
    }

    public destroy(): void {
        // 
    }

}

