export class Events {

    private static _events: { [key: string]: Function } = {};

    public static method(name: string, callback: Function): void {
        Events._events[name] = callback;
    }

    public static call(name: string,
        arg0?: any,
        arg1?: any,
        arg2?: any,
        arg3?: any,
        arg4?: any,
        arg5?: any,
        arg6?: any,
        arg7?: any): void {
        if (Events._events[name]) {
            try {
                Events._events[name].call(this, arg0, arg1, arg2, arg3, arg4, arg5, arg6, arg7);
            } catch (ex) {
                console.info("%c%s %c(event error)", "color: #06f", name, "color: #f00");
                console.log(ex.stack);
            }
        }
    }

}