import { CustomFunctions, IExpression, IFunction } from "../expression";
import { ShowError } from "../html";
import { VEObjects } from "../object";
import { ErrorInfo } from "../utility";
import { VEVarDynamic, VarTools } from "../variables";

export class Created implements IFunction {

    public get expType(): string {
        return 'bool';
    }

    public get className(): string {
        return 'created';
    }

    public parameterNumber(): number {
        return 1;
    }

    public evaluate(args: IExpression[]): any {
        // console.warn('created: Fucntion');
        // console.warn(args[0].evaluate());

        let value = args[0].evaluate();
        if (value === null || value === undefined || value === '') {
            ShowError.showError(`表达式编译错误：'created'函数参数错误，参数值：${value}，应为对象名，请检查！`);
            return undefined;
        } else {
            value = value.toString();

            // 对象名 | *模板对象 | 对象名.*模板对象
            if (VEObjects.isNodeNameLoaded(value, VEVarDynamic.HOST_NODE_ID)) {
                return true;
            } else {
                if (VarTools.IsTemplateID(value)) {
                    if (VarTools.GetClone(value, value, new ErrorInfo(), VEVarDynamic.HOST_NODE_ID)) {
                        return true;
                    } else {
                        return false;
                    }
                } else {
                    return false;
                }
            }
        }
    }
}

